function act(obs, mem) {
  const D = Math.PI / 180;

  const isNum = v => typeof v === "number" && isFinite(v);
  const clamp = (v, a, b) => {
    v = +v;
    if (!isFinite(v)) return a;
    return v < a ? a : (v > b ? b : v);
  };
  const wrap180 = a => {
    a = +a;
    if (!isFinite(a)) return 0;
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  };
  const dist = (x1, y1, x2, y2) => {
    const dx = x2 - x1;
    const dy = y2 - y1;
    return Math.sqrt(dx * dx + dy * dy);
  };

  if (!mem || typeof mem !== "object") mem = {};

  const now = isNum(obs.t) ? obs.t : ((isNum(mem.lastT) ? mem.lastT : 0) + 0.1);
  let dt = isNum(mem.lastT) ? now - mem.lastT : 0.1;
  if (!(dt > 0.01) || dt > 0.5) dt = 0.1;

  const mi = obs.mission || {};

  if (!mem.init) {
    mem.init = true;

    mem.size = isNum(mi.size) && mi.size > 50 ? mi.size : 400;
    const b = mi.base || {};
    mem.baseX = isNum(b.x) ? b.x : (isNum(obs.x) ? obs.x : mem.size / 2);
    mem.baseY = isNum(b.y) ? b.y : (isNum(obs.y) ? obs.y : mem.size / 2);
    mem.capacity = isNum(mi.capacity) && mi.capacity > 0 ? Math.floor(mi.capacity) : 5;
    mem.maxTime = isNum(mi.seconds) && mi.seconds > 0 ? mi.seconds : 1200;

    const hintList = Array.isArray(mi.hints) ? mi.hints : [];
    mem.targets = [];
    for (let i = 0; i < hintList.length; i++) {
      const q = hintList[i] || {};
      if (!isNum(q.x) || !isNum(q.y)) continue;
      const id = mem.targets.length;
      mem.targets.push({
        id: id,
        x: clamp(q.x, 12, mem.size - 12),
        y: clamp(q.y, 12, mem.size - 12),
        est: Math.max(0.1, isNum(q.estimate) ? q.estimate : 1),
        state: "unvisited",
        pts: null,
        searchIdx: 0,
        searchArrivedAt: null,
        sawScience: false,
        start: 0
      });
    }

    mem.maxEst = 1;
    for (const t of mem.targets) {
      if (t.est > mem.maxEst) mem.maxEst = t.est;
    }

    mem.state = "plan";
    mem.targetId = null;
    mem.searchIdx = 0;
    mem.searchArrivedAt = null;
    mem.dockTime = 0;
    mem.recoverStart = null;
    mem.recoverSide = null;
    mem.stuckTime = 0;
    mem.lastTurn = 0;
    mem.trim = 0;
    mem.speedEMA = 0;
    mem.vSignedEMA = 0;
    mem.lastGoalDist = null;
    mem.ignoreSiteUntil = -1;
    mem.wpts = null;
    mem.wanderIdx = 0;
    mem.energy = {
      perDist: 0.00035,
      perSec: 0.0015
    };

    mem.lastB = isNum(obs.battery) ? obs.battery : 1;
    mem.lastX = isNum(obs.x) ? obs.x : mem.baseX;
    mem.lastY = isNum(obs.y) ? obs.y : mem.baseY;
    mem.lastT = now;
    mem.lastHeading = isNum(obs.heading) ? obs.heading : 0;
    mem.lastCarried = isNum(obs.carried) ? obs.carried : 0;
    mem.lastDelivered = isNum(obs.delivered) ? obs.delivered : 0;
    mem.lastScience = isNum(obs.science) ? obs.science : 0;
  }

  if (!mem.energy) {
    mem.energy = { perDist: 0.00035, perSec: 0.0015 };
  }
  if (!mem.targets) mem.targets = [];
  if (!isNum(mem.size)) mem.size = 400;
  if (!isNum(mem.baseX)) mem.baseX = mem.size / 2;
  if (!isNum(mem.baseY)) mem.baseY = mem.size / 2;
  if (!isNum(mem.capacity)) mem.capacity = 5;

  const x = isNum(obs.x) ? obs.x : (isNum(mem.lastX) ? mem.lastX : mem.baseX);
  const y = isNum(obs.y) ? obs.y : (isNum(mem.lastY) ? mem.lastY : mem.baseY);
  const lastX = isNum(mem.lastX) ? mem.lastX : x;
  const lastY = isNum(mem.lastY) ? mem.lastY : y;
  const dx = x - lastX;
  const dy = y - lastY;
  const moveDist = Math.sqrt(dx * dx + dy * dy);

  const rawHeading = isNum(obs.heading) ? obs.heading : (isNum(mem.lastHeading) ? mem.lastHeading : 0);
  const wheelLeft = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wheelRight = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  const wheelAvg = (wheelLeft + wheelRight) / 2;

  let speed = clamp(moveDist / dt, 0, 6);
  if (speed < 0.08 && Math.abs(wheelAvg) > 0.12) {
    speed = clamp(Math.abs(wheelAvg), 0, 5);
  }
  mem.speedEMA = clamp((isNum(mem.speedEMA) ? mem.speedEMA : 0) * 0.82 + speed * 0.18, 0, 6);

  let heading = wrap180(rawHeading);
  if (isNum(mem.lastHeading)) {
    const dh = wrap180(rawHeading - mem.lastHeading);
    if (Math.abs(dh) > 35 && speed < 0.35) {
      heading = wrap180(mem.lastHeading + clamp(dh, -5, 5));
    }
  }

  const ux = Math.cos(heading * D);
  const uy = Math.sin(heading * D);
  const vSigned = clamp((dx * ux + dy * uy) / dt, -6, 6);
  mem.vSignedEMA = clamp((isNum(mem.vSignedEMA) ? mem.vSignedEMA : 0) * 0.72 + vSigned * 0.28, -6, 6);

  const solar = isNum(obs.solar) ? Math.max(0, obs.solar) : 0;
  const battery = isNum(obs.battery) ? obs.battery : (isNum(mem.lastB) ? mem.lastB : 1);

  if (isNum(mem.lastB)) {
    const consumed = Math.max(0, mem.lastB - battery + solar * dt);
    if (moveDist > 0.2) {
      mem.energy.perDist = clamp(consumed / moveDist, 0.00001, 0.02);
    }
    if (moveDist < 0.05 && dt > 0) {
      mem.energy.perSec = clamp(consumed / dt, 0.00005, 0.08);
    }
  }

  const timeLeft = isNum(obs.timeLeft) ? Math.max(0, obs.timeLeft) : Math.max(0, mem.maxTime - now);
  const baseDist = dist(x, y, mem.baseX, mem.baseY);
  const carried = isNum(obs.carried) ? obs.carried : 0;
  const carriedUp = isNum(mem.lastCarried) && carried > mem.lastCarried + 0.5;
  const carriedDown = isNum(mem.lastCarried) && carried < mem.lastCarried - 0.5;

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const rayAng = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

  function rayAt(rel) {
    rel = wrap180(rel);
    if (rel < -88 || rel > 88) return 15;
    let best = 15;
    let bestD = 999;
    for (let i = 0; i < 9; i++) {
      const r = rays[i];
      if (!isNum(r) || r < 0) continue;
      const d = Math.abs(wrap180(rel - rayAng[i]));
      if (d < bestD) {
        bestD = d;
        best = r;
      }
    }
    return best;
  }

  function rayAvg(list) {
    let s = 0;
    let n = 0;
    for (const a of list) {
      const r = rayAt(a);
      if (isNum(r)) {
        s += r;
        n++;
      }
    }
    return n ? s / n : 15;
  }

  function targetById(id) {
    if (!isNum(id)) return null;
    for (const t of mem.targets) {
      if (t.id === id) return t;
    }
    return null;
  }

  function nearestTarget(radius) {
    let best = null;
    let bestD = radius;
    for (const t of mem.targets) {
      if (t.state === "sampled" || t.state === "dead") continue;
      const d = dist(x, y, t.x, t.y);
      if (d < bestD) {
        bestD = d;
        best = t;
      }
    }
    return best;
  }

  function completeSample() {
    let t = targetById(mem.targetId);
    if (!t) t = nearestTarget(45);
    if (t) t.state = "sampled";
    mem.targetId = null;
    mem.state = "plan";
    mem.searchIdx = 0;
    mem.searchArrivedAt = null;
    mem.ignoreSiteUntil = now + 1.2;
    mem.lastDrill = 0;
  }

  function markDead(t) {
    if (!t) return;
    t.state = "dead";
    if (mem.targetId === t.id) mem.targetId = null;
  }

  function getSearchPts(t) {
    if (t.pts && t.pts.length) return t.pts;
    const pts = [{ x: t.x, y: t.y }];
    const rings = [
      { r: 10, n: 12 },
      { r: 20, n: 16 }
    ];
    for (const ring of rings) {
      for (let k = 0; k < ring.n; k++) {
        const a = (k * 360 / ring.n + (t.id * 29) % 360) * D;
        pts.push({
          x: clamp(t.x + Math.cos(a) * ring.r, 15, mem.size - 15),
          y: clamp(t.y + Math.sin(a) * ring.r, 15, mem.size - 15)
        });
      }
    }
    t.pts = pts;
    return pts;
  }

  function chooseNext() {
    let best = null;
    let bestScore = -1;
    for (const t of mem.targets) {
      if (t.state === "sampled" || t.state === "dead") continue;
      if (mem.targetId === t.id && (mem.state === "toTarget" || mem.state === "search")) continue;

      const dc = dist(x, y, t.x, t.y);
      const db = dist(t.x, t.y, mem.baseX, mem.baseY);
      const v = Math.max(0.1, t.est || 1);
      let score = v / (dc + 0.72 * db + 24);

      if (t.state === "searching") score *= 1.25;
      if (db < 85) score *= 1.16;
      if (mem.maxEst && v < 0.18 * mem.maxEst && db > 225) score *= 0.52;

      if (score > bestScore) {
        bestScore = score;
        best = t;
      }
    }
    return best;
  }

  function sitePoint() {
    const s = obs.site || {};
    const br = isNum(s.bearing) ? wrap180(heading + s.bearing) : heading;
    const d = clamp(isNum(s.distance) ? s.distance : 1.5, 0, 20);
    return {
      x: x + Math.cos(br * D) * d,
      y: y + Math.sin(br * D) * d
    };
  }

  function basePoint() {
    const bq = obs.beacon;
    if (bq && isNum(bq.distance) && isNum(bq.bearing)) {
      const br = wrap180(heading + bq.bearing);
      const d = clamp(bq.distance, 0, 25);
      return {
        x: x + Math.cos(br * D) * d,
        y: y + Math.sin(br * D) * d
      };
    }
    return { x: mem.baseX, y: mem.baseY };
  }

  function isStill() {
    const wheel = Math.abs((wheelLeft + wheelRight) / 2);
    return wheel < 0.28 && (moveDist < 0.028 || Math.abs(mem.vSignedEMA || 0) < 0.18);
  }

  function holdStation() {
    const v = isNum(mem.vSignedEMA) ? mem.vSignedEMA : 0;
    const wheel = (wheelLeft + wheelRight) / 2;
    let cmd = 0;

    if (v > 0.15 || wheel > 0.28) {
      cmd = -clamp(0.22 + 0.58 * Math.abs(v || wheel), 0.22, 0.72);
    } else if (v < -0.15 || wheel < -0.28) {
      cmd = clamp(0.22 + 0.58 * Math.abs(v || wheel), 0.22, 0.72);
    } else if (isNum(obs.pitch) && obs.pitch > 2.5) {
      cmd = clamp(0.07 + 0.010 * obs.pitch, 0, 0.34);
    } else if (isNum(obs.pitch) && obs.pitch < -2.5) {
      cmd = -clamp(0.07 - 0.010 * obs.pitch, 0, 0.34);
    }

    return {
      left: clamp(cmd, -1, 1),
      right: clamp(cmd, -1, 1)
    };
  }

  function steer(rel, distTo, slow) {
    rel = wrap180(rel);

    let pathR = rayAt(rel);
    let rep = 0;
    let minAhead = 15;
    let valid = 0;

    for (let i = 0; i < 9; i++) {
      const r = rays[i];
      if (!isNum(r) || r < 0) continue;
      valid++;
      const a = rayAng[i];
      if (r < 9) {
        rep += -Math.sin(a * D) * ((9 - r) / 9) * 1.7;
      }
      if (Math.abs(a) < 35 && r < minAhead) minAhead = r;
    }

    const leftC = rayAvg([20, 40, 60, 80]);
    const rightC = rayAvg([-20, -40, -60, -80]);

    if (obs.bumped) {
      mem.stuckTime = Math.max(mem.stuckTime || 0, 6);
    }

    if ((mem.stuckTime || 0) > 5.5 && distTo > 2.5) {
      if (mem.recoverStart == null) {
        mem.recoverStart = now;
        mem.recoverSide = leftC >= rightC ? 1 : -1;
      }
      const rec = now - mem.recoverStart;
      if (rec < 2.4) {
        const side = mem.recoverSide || 1;
        return { left: -0.52 * side, right: 0.52 * side };
      }
      if (rec < 4.0) {
        return { left: 0.34, right: 0.34 };
      }
      mem.recoverStart = null;
      mem.recoverSide = null;
      mem.stuckTime = 0;
    }

    let turn;
    if (pathR < 4.2) {
      const urgency = clamp((4.2 - pathR) / 4.2, 0, 1);
      const away = leftC >= rightC ? 1 : -1;
      turn = clamp(away * urgency * 1.2 + 0.22 * (rel >= 0 ? 1 : -1), -1, 1);
    } else {
      turn = clamp(0.88 * rel / 55 + rep * 0.58, -1, 1);
    }

    const prevTurn = isNum(mem.lastTurn) ? mem.lastTurn : 0;
    turn = clamp(turn, prevTurn - 0.16, prevTurn + 0.16);
    mem.lastTurn = turn;

    let base = slow ? 0.34 : 0.62;

    if (pathR < 6) {
      base = Math.min(base, 0.27 + 0.34 * clamp(pathR / 6, 0, 1));
    }
    if (distTo < 3) {
      base = Math.min(base, 0.18 + 0.15 * clamp(distTo / 3, 0, 1));
    }
    if (minAhead < 1.7) {
      base = Math.min(base, 0.17);
    }
    if (valid < 3) {
      base *= 0.64;
    }
    if (isNum(obs.pitch) && obs.pitch > 12) {
      base *= 0.78;
    }

    if (Math.abs(rel) < 12 && base > 0.25 && isNum(obs.wheelLeft) && isNum(obs.wheelRight)) {
      const diff = obs.wheelLeft - obs.wheelRight;
      mem.trim = clamp((isNum(mem.trim) ? mem.trim : 0) + clamp(-diff * 0.0015, -0.008, 0.008), -0.22, 0.22);
    }

    const trim = isNum(mem.trim) ? mem.trim : 0;
    return {
      left: clamp(base - turn * 0.72 - trim, -1, 1),
      right: clamp(base + turn * 0.72 + trim, -1, 1)
    };
  }

  function driveToWorld(tx, ty, slow) {
    const lo = 18;
    const hi = Math.max(28, mem.size - 18);
    tx = clamp(tx, lo, hi);
    ty = clamp(ty, lo, hi);
    const rel = wrap180(Math.atan2(ty - y, tx - x) / D - heading);
    return steer(rel, dist(x, y, tx, ty), !!slow);
  }

  function driveToSite() {
    const s = obs.site;
    if (s && isNum(s.bearing) && isNum(s.distance)) {
      return steer(wrap180(s.bearing), clamp(s.distance, 0, 20), s.distance < 3.2);
    }
    const p = sitePoint();
    return driveToWorld(p.x, p.y, true);
  }

  function driveToBase() {
    const bq = obs.beacon;
    if (bq && isNum(bq.bearing) && isNum(bq.distance)) {
      return steer(wrap180(bq.bearing), clamp(bq.distance, 0, 25), bq.distance < 4.5);
    }
    return driveToWorld(mem.baseX, mem.baseY, false);
  }

  function needReturnNow() {
    if (mem.state === "toBase" || mem.state === "dock") return true;
    if (carried >= mem.capacity) return true;

    const speedRef = clamp(mem.speedEMA || 1.5, 0.75, 2.8);
    const timeToBase = baseDist / speedRef + 15;

    if (carried > 0 && timeLeft < timeToBase + 25) return true;

    const eDist = Math.max(0.00001, mem.energy.perDist || 0.00035);
    const eSec = Math.max(0.00005, mem.energy.perSec || 0.0015);
    const returnEnergy =
      baseDist * eDist * (1 + 0.08 * carried) +
      22 * eSec +
      0.05 +
      0.018 * carried;

    if (battery < returnEnergy * 1.28) return true;
    if (battery < 0.19) return true;
    if (carried > 0 && battery < 0.42 && baseDist < 280) return true;

    return false;
  }

  function finish(cmd) {
    mem.lastT = now;
    mem.lastX = x;
    mem.lastY = y;
    mem.lastHeading = heading;
    mem.lastB = battery;
    mem.lastCarried = carried;
    mem.lastDelivered = isNum(obs.delivered) ? obs.delivered : mem.lastDelivered;
    mem.lastScience = isNum(obs.science) ? obs.science : mem.lastScience;

    return {
      left: clamp(cmd && isNum(cmd.left) ? cmd.left : 0, -1, 1),
      right: clamp(cmd && isNum(cmd.right) ? cmd.right : 0, -1, 1),
      drill: !!(cmd && cmd.drill)
    };
  }

  const drillingDone = isNum(obs.drilling) && obs.drilling >= 5.85;

  if (mem.state === "sampling" && (carriedUp || drillingDone)) {
    completeSample();
  }

  if (carriedDown && baseDist < 6) {
    mem.state = "dock";
    mem.dockTime = 0;
  }

  const nr = needReturnNow();

  if (
    obs.site &&
    isNum(obs.site.distance) &&
    obs.site.distance <= 8.5 &&
    carried < mem.capacity &&
    now >= (mem.ignoreSiteUntil || -1) &&
    (!nr || (obs.site.distance < 1.5 && battery > 0.3))
  ) {
    if (mem.state !== "sampling") {
      mem.state = "sampling";
      mem.sampleStart = now;
      mem.searchArrivedAt = null;
      if (mem.targetId == null) {
        const near = nearestTarget(42);
        if (near) mem.targetId = near.id;
      }
    }
  }

  if (mem.state === "sampling") {
    if (nr && !(obs.site && isNum(obs.site.distance) && obs.site.distance < 1.5 && battery > 0.3)) {
      mem.state = "toBase";
    } else if (!obs.site) {
      if (carriedUp || drillingDone) {
        completeSample();
      } else if (mem.targetId != null) {
        mem.state = "search";
        mem.searchIdx = 0;
        mem.searchArrivedAt = null;
      } else {
        mem.state = "plan";
      }
    } else {
      const sdist = clamp(obs.site.distance, 0, 20);
      if (sdist > 1.36) {
        return finish(driveToSite());
      }

      const hold = holdStation();
      const still = isStill();
      const drill = still && sdist <= 1.5 && !(nr && battery < 0.28);

      if (isNum(obs.drilling) && obs.drilling > 0.2) {
        mem.lastDrill = obs.drilling;
      }

      return finish({
        left: hold.left,
        right: hold.right,
        drill: drill
      });
    }
  }

  if (nr) {
    mem.state = "toBase";
    return finish(driveToBase());
  }

  if (mem.state === "dock") {
    mem.dockTime = (isNum(mem.dockTime) ? mem.dockTime : 0) + dt;

    if (carried > 0 && !obs.docked && mem.dockTime > 2.5) {
      mem.state = "toBase";
      return finish(driveToBase());
    }

    if (
      (battery >= 0.9 && mem.dockTime > 5) ||
      mem.dockTime > 55 ||
      (timeLeft < 35 && carried === 0)
    ) {
      mem.state = "plan";
    } else {
      return finish(holdStation());
    }
  }

  if (mem.state === "toBase") {
    const bp = basePoint();
    const bd = dist(x, y, bp.x, bp.y);
    if (bd < 3 && isStill()) {
      mem.state = "dock";
      mem.dockTime = 0;
      return finish(holdStation());
    }
    return finish(driveToBase());
  }

  if (mem.state === "toTarget") {
    const t = targetById(mem.targetId);
    if (!t || t.state === "sampled" || t.state === "dead") {
      mem.state = "plan";
    } else {
      if (!t.start) t.start = now;
      if (isNum(obs.science) && obs.science > 0) t.sawScience = true;

      const limit = t.sawScience ? 190 : 105;
      if (now - t.start > limit) {
        markDead(t);
        mem.state = "plan";
      } else {
        const d = dist(x, y, t.x, t.y);
        if (d < 5 && !obs.site) {
          mem.state = "search";
          t.state = "searching";
          mem.searchIdx = 0;
          mem.searchArrivedAt = null;
        } else {
          return finish(driveToWorld(t.x, t.y, !obs.site && isNum(obs.science) && obs.science > 0));
        }
      }
    }
  }

  if (mem.state === "search") {
    const t = targetById(mem.targetId);
    if (!t || t.state === "sampled" || t.state === "dead") {
      mem.state = "plan";
    } else {
      if (!t.start) t.start = now;
      if (isNum(obs.science) && obs.science > 0) t.sawScience = true;

      const limit = t.sawScience ? 190 : 105;
      if (now - t.start > limit) {
        markDead(t);
        mem.state = "plan";
      } else {
        const pts = getSearchPts(t);
        if (mem.searchIdx >= pts.length) {
          markDead(t);
          mem.state = "plan";
        } else {
          const p = pts[mem.searchIdx];
          const d = dist(x, y, p.x, p.y);

          if (d < 2.3) {
            if (mem.searchArrivedAt == null) mem.searchArrivedAt = now;
            if (now - mem.searchArrivedAt > 1.25) {
              mem.searchIdx++;
              mem.searchArrivedAt = null;
            }
            return finish(driveToWorld(p.x, p.y, true));
          }

          mem.searchArrivedAt = null;
          return finish(driveToWorld(p.x, p.y, isNum(obs.science) && obs.science > 0));
        }
      }
    }
  }

  if (mem.state === "plan" || mem.state === "postSample") {
    if (needReturnNow()) {
      mem.state = "toBase";
      return finish(driveToBase());
    }

    const t = chooseNext();
    if (t) {
      mem.state = "toTarget";
      mem.targetId = t.id;
      t.state = "searching";
      t.start = now;
      mem.searchIdx = 0;
      mem.searchArrivedAt = null;
      return finish(driveToWorld(t.x, t.y, false));
    }

    mem.state = "wander";
  }

  if (mem.state === "wander") {
    if (!mem.wpts || !mem.wpts.length) {
      mem.wpts = [];
      const margin = 38;
      const step = 66;
      const rows = Math.max(3, Math.floor((mem.size - 2 * margin) / step) + 1);
      const cols = rows;
      for (let r = 0; r < rows; r++) {
        const yy = margin + r * step;
        for (let c = 0; c < cols; c++) {
          const xx = (r % 2 === 0) ? margin + c * step : mem.size - margin - c * step;
          mem.wpts.push({
            x: clamp(xx, 25, mem.size - 25),
            y: clamp(yy, 25, mem.size - 25)
          });
        }
      }
      mem.wanderIdx = 0;
    }

    if (mem.wanderIdx >= mem.wpts.length) mem.wanderIdx = 0;
    let p = mem.wpts[mem.wanderIdx];
    if (dist(x, y, p.x, p.y) < 9) {
