    mem.missionSecs = num(mission.seconds, 1200);
    mem.capacity = Math.max(1, num(mission.capacity, 5));

    const base = mission.base || {};
    mem.baseX = num(base.x, rawX);
    mem.baseY = num(base.y, rawY);

    mem.hints = [];
    if (Array.isArray(mission.hints)) {
      for (let i = 0; i < mission.hints.length; i++) {
        const q = mission.hints[i] || {};
        if (typeof q.x === "number" && typeof q.y === "number") {
          mem.hints.push({
            id: i,
            x: clamp(q.x, 2, Math.max(2, w - 2)),
            y: clamp(q.y, 2, Math.max(2, h - 2)),
            val: Math.max(0.05, num(q.estimate, 1)),
            status: 0,
            idx: 0,
            pts: null,
            sampled: false,
            maxSci: 0,
            outerChecked: false
          });
        }
      }
    }

    mem.grid = [];
    for (let gy = 20; gy <= h - 20; gy += 45) {
      for (let gx = 20; gx <= w - 20; gx += 45) {
        mem.grid.push({ x: gx, y: gy, done: false });
      }
    }
    mem.gridTarget = -1;

    mem.px = rawX;
    mem.py = rawY;
    mem.hEst = rawHeading;
    mem.bias = 0;
    mem.lastRawH = rawHeading;
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.gpsFrozen = false;
    mem.odoX = 0;
    mem.odoY = 0;
    mem.odoDist = 0;

    mem.calX = 0;
    mem.calY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calT = 0;

    mem.eMeter = 0.0007;
    mem.energyCost = 0;
    mem.energyDist = 0;
    mem.energyReady = false;
    mem.prevBat = battery;
    mem.prevSolar = solar;
    mem.prevDock = docked;

    mem.lastCarried = carried;
    mem.lastDelivered = num(obs.delivered, 0);
    mem.activeHint = null;
    mem.returning = false;
    mem.sampleTarget = null;
    mem.sampling = false;
    mem.sampleStart = 0;

    mem.sigSamples = [];
    mem.sigLastX = null;
    mem.sigLastY = null;
    mem.sigLastT = 0;
    mem.gradRegion = null;
    mem.gradTarget = null;
    mem.gradSteps = 0;
    mem.gradCooldown = 0;

    mem.rayLast = new Array(9);
    mem.raySame = new Array(9);
    mem.rayStale = new Array(9);
    mem.rayStartX = new Array(9);
    mem.rayStartY = new Array(9);
    mem.rayStartH = new Array(9);
    mem.raysClean = new Array(9);
    for (let i = 0; i < 9; i++) {
      mem.rayLast[i] = null;
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = rawX;
      mem.rayStartY[i] = rawY;
      mem.rayStartH[i] = rawHeading;
      mem.raysClean[i] = 15;
    }

    mem.avoidSide = 0;
    mem.clearTicks = 0;
    mem.bumpTicks = 0;
    mem.bumpSide = 1;
    mem.prevBumped = false;
    mem.prevNavBearing = null;

    mem.navHas = false;
    mem.navStuck = 0;
    mem.stuckUntil = 0;
    mem.stuckSide = 0;
    mem.iL = 0;
    mem.iR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;
    mem.lastTL = 0;
    mem.lastTR = 0;

    mem.tick = 0;
    mem.initialized = true;
  }

  mem.tick = (mem.tick || 0) + 1;
  const now = mem.tick * dt;
  const timeLeft = Math.max(
    0,
    num(obs.timeLeft, Math.max(0, mem.missionSecs - now))
  );
  const capacity = Math.max(1, num(
    obs.mission && obs.mission.capacity,
    mem.capacity || 5
  ));

  const oldH = mem.hEst;
  const yawDeg = ((wr - wl) / 0.6) * dt * deg;
  const rawHeadingChange = wrap(rawHeading - mem.lastRawH);
  let compassJump = false;
  if (Math.abs(rawHeadingChange) > 50 && Math.abs(yawDeg) < 32) {
    mem.bias = wrap(mem.bias - rawHeadingChange);
    compassJump = true;
    mem.calX = 0;
    mem.calY = 0;
    mem.calSin = 0;
    mem.calCos = 0;
    mem.calT = 0;
  }

  const rawDx = rawX - mem.lastRawX;
  const rawDy = rawY - mem.lastRawY;
  const rawStep = Math.hypot(rawDx, rawDy);
  const gpsJump = rawStep > 8 && !mem.gpsFrozen;

  if (!gpsJump && !mem.gpsFrozen && !docked) {
    const straight = (wl + wr) * 0.5 > 0.25 &&
                     Math.abs(wl - wr) < 0.28 &&
                     Math.abs(rawHeadingChange) < 15;
    if (straight) {
      mem.calX += rawDx;
      mem.calY += rawDy;
      mem.calSin += Math.sin(rawHeading * rad) * dt;
      mem.calCos += Math.cos(rawHeading * rad) * dt;
      mem.calT += dt;
      if (Math.hypot(mem.calX, mem.calY) > 4 &&
          mem.calT > 2.5 &&
          Math.hypot(mem.calX, mem.calY) < mem.calT * 2.5) {
        const course = Math.atan2(mem.calY, mem.calX) * deg;
        const meanHeading = Math.atan2(mem.calSin, mem.calCos) * deg;
        const measuredBias = wrap(course - meanHeading);
        const err = wrap(measuredBias - mem.bias);
        mem.bias = wrap(mem.bias + clamp(err, -12, 12) * 0.14);
        mem.calX = 0;
        mem.calY = 0;
        mem.calSin = 0;
        mem.calCos = 0;
        mem.calT = 0;
      }
    } else {
      mem.calX = 0;
      mem.calY = 0;
      mem.calSin = 0;
      mem.calCos = 0;
      mem.calT = 0;
    }
  }

  const heading = compassJump
    ? wrap(oldH + yawDeg)
    : wrap(rawHeading + mem.bias);
  mem.hEst = heading;
  mem.lastRawH = rawHeading;

  const forward = (wl + wr) * 0.5;
  const travel = (Math.abs(wl) + Math.abs(wr)) * 0.5 * dt;
  const midHeading = (oldH + yawDeg * 0.5) * rad;
  const stepX = forward * dt * Math.cos(midHeading);
  const stepY = forward * dt * Math.sin(midHeading);

  mem.odoX += stepX;
  mem.odoY += stepY;
  mem.odoDist += travel;

  const predX = mem.px + stepX;
  const predY = mem.py + stepY;
  let px = predX;
  let py = predY;
  const anchorDist = Math.hypot(rawX - mem.gpsAnchorX, rawY - mem.gpsAnchorY);

  if (docked) {
    px = mem.baseX;
    py = mem.baseY;
    mem.gpsFrozen = false;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.odoX = 0;
    mem.odoY = 0;
    mem.odoDist = 0;
  } else if (gpsJump) {
    px = predX;
    py = predY;
  } else if (mem.gpsFrozen) {
    if (anchorDist > 1.35) {
      px = rawX;
      py = rawY;
      mem.gpsFrozen = false;
      mem.gpsAnchorX = rawX;
      mem.gpsAnchorY = rawY;
      mem.odoX = 0;
      mem.odoY = 0;
      mem.odoDist = 0;
    } else {
      px = predX;
      py = predY;
    }
  } else if (anchorDist > 1.35) {
    px = predX + 0.55 * (rawX - predX);
    py = predY + 0.55 * (rawY - predY);
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
    mem.odoX = 0;
    mem.odoY = 0;
    mem.odoDist = 0;
  } else if (mem.odoDist > 6.5 && anchorDist < 0.8) {
    mem.gpsFrozen = true;
    px = mem.gpsAnchorX + mem.odoX;
    py = mem.gpsAnchorY + mem.odoY;
  } else {
    let alpha = Math.abs(forward) > 0.15 ? 0.48 : 0.25;
    if (Math.hypot(rawX - predX, rawY - predY) > 12) alpha = 0.08;
    px = predX + alpha * (rawX - predX);
    py = predY + alpha * (rawY - predY);
  }

  mem.px = clamp(px, -10, mem.W + 10);
  mem.py = clamp(py, -10, mem.H + 10);
  if (!gpsJump || mem.gpsFrozen) {
    mem.lastRawX = rawX;
    mem.lastRawY = rawY;
  }

  if (mem.energyReady && !docked && !mem.prevDock) {
    const solarAvg = clamp((mem.prevSolar + solar) * 0.5, 0, 0.02);
    const cost = mem.prevBat - battery + solarAvg * dt;
    mem.energyCost += Math.max(0, cost);
    mem.energyDist += travel;
    if (mem.energyDist >= 5) {
      const rate = clamp(mem.energyCost / Math.max(1, mem.energyDist), 0.00005, 0.02);
      const a = rate > mem.eMeter ? 0.55 : 0.20;
      mem.eMeter = clamp(mem.eMeter * (1 - a) + rate * a, 0.00005, 0.02);
      mem.energyCost = 0;
      mem.energyDist = 0;
    }
  }
  if (docked) {
    mem.energyCost = 0;
    mem.energyDist = 0;
  }
  mem.prevBat = battery;
  mem.prevSolar = solar;
  mem.prevDock = docked;
  mem.energyReady = true;

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    const v = clamp(num(rays[i], 15), 0, 15);
    if (mem.rayLast[i] !== null && Math.abs(v - mem.rayLast[i]) < 0.015) {
      mem.raySame[i] += dt;
      const moved = Math.hypot(mem.px - mem.rayStartX[i], mem.py - mem.rayStartY[i]);
      const turned = Math.abs(wrap(heading - mem.rayStartH[i]));
      if (mem.raySame[i] > 7 && (moved > 2.5 || turned > 35)) {
        mem.rayStale[i] = true;
      }
    } else {
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = mem.px;
      mem.rayStartY[i] = mem.py;
      mem.rayStartH[i] = heading;
    }
    mem.rayLast[i] = v;
    mem.raysClean[i] = mem.rayStale[i] ? 15 : v;
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    const f = (a + 80) / 20;
    const i = Math.floor(f);
    if (i >= 8) return mem.raysClean[8];
    const q = f - i;
    return mem.raysClean[i] * (1 - q) + mem.raysClean[i + 1] * q;
  }

  function wallDist(a) {
    const ang = (heading + a) * rad;
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    let d = 1e6;
    if (dx > 0.0001) d = Math.min(d, (mem.W - 1.3 - mem.px) / dx);
    else if (dx < -0.0001) d = Math.min(d, (1.3 - mem.px) / dx);
    if (dy > 0.0001) d = Math.min(d, (mem.H - 1.3 - mem.py) / dy);
    else if (dy < -0.0001) d = Math.min(d, (1.3 - mem.py) / dy);
    return Math.max(0, d);
  }

  function openSide(goalRel) {
    const leftOpen = rayAt(40) + rayAt(70) +
                     Math.min(wallDist(40), wallDist(70));
    const rightOpen = rayAt(-40) + rayAt(-70) +
                      Math.min(wallDist(-40), wallDist(-70));
    if (leftOpen > rightOpen + 0.5) return 1;
    if (rightOpen > leftOpen + 0.5) return -1;
    return goalRel >= 0 ? 1 : -1;
  }

  if (bumped && !mem.prevBumped) {
    mem.bumpSide = openSide(0);
    mem.bumpTicks = 12;
    mem.avoidSide = mem.bumpSide;
  }
  mem.prevBumped = bumped;

  if (!docked) {
    if (mem.sigLastX === null ||
        Math.hypot(mem.px - mem.sigLastX, mem.py - mem.sigLastY) > 3) {
      mem.sigSamples.push({ x: mem.px, y: mem.py, s: science });
      if (mem.sigSamples.length > 24) mem.sigSamples.shift();
      mem.sigLastX = mem.px;
      mem.sigLastY = mem.py;
      mem.sigLastT = now;
    }
  }

  function hintById(id) {
    if (id === null || id === undefined) return null;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].id === id) return mem.hints[i];
    }
    return null;
  }

  function buildHintPoints(h) {
    const pts = [];
    const add = (x, y) => {
      pts.push({
        x: clamp(x, 2, Math.max(2, mem.W - 2)),
        y: clamp(y, 2, Math.max(2, mem.H - 2))
      });
    };
    add(h.x, h.y);
    add(h.x + 8, h.y);
    add(h.x, h.y + 8);
    add(h.x - 8, h.y);
    add(h.x, h.y - 8);
    const r = 18.5;
    const angles = [-90, -45, 0, 45, 90, 135, 180, 225];
    for (let i = 0; i < angles.length; i++) {
      const a = angles[i] * rad;
      add(h.x + r * Math.cos(a), h.y + r * Math.sin(a));
    }
    h.pts = pts;
  }

  function markHintDone(h, sampled) {
    if (!h) return;
    h.status = 2;
    if (sampled) h.sampled = true;
    if (mem.activeHint === h.id) mem.activeHint = null;
  }

  function associateHint(x, y) {
    const active = hintById(mem.activeHint);
    if (active && active.status < 2 &&
        Math.hypot(x - active.x, y - active.y) < 32) return active.id;

    let best = null;
    let bd = 28;
    for (let i = 0; i < mem.hints.length; i++) {
      const q = mem.hints[i];
      if (q.status >= 2) continue;
      const d = Math.hypot(x - q.x, y - q.y);
      if (d < bd) {
        bd = d;
        best = q;
      }
    }
    return best ? best.id : null;
  }

  function markSiteDone(x, y, id) {
    let chosen = null;
    const q = hintById(id);
    if (q && q.status < 2 && Math.hypot(x - q.x, y - q.y) < 32) {
      chosen = q;
    }
    if (!chosen) {
      let bd = 28;
      for (let i = 0; i < mem.hints.length; i++) {
        const c = mem.hints[i];
        if (c.status >= 2) continue;
        const d = Math.hypot(x - c.x, y - c.y);
        if (d < bd) {
          bd = d;
          chosen = c;
        }
      }
    }
    if (chosen) markHintDone(chosen, true);
  }

  const previousCarried = num(mem.lastCarried, carried);
  if (carried > previousCarried) {
    const st = mem.sampleTarget;
    const sx = st ? st.x : mem.px;
    const sy = st ? st.y : mem.py;
    markSiteDone(sx, sy, st ? st.hintId : mem.activeHint);
    mem.sampleTarget = null;
    mem.sampling = false;
    mem.sampleStart = 0;
  } else if (carried < previousCarried && docked) {
    if (mem.sampling && drilling <= 0) {
      mem.sampleTarget = null;
      mem.sampling = false;
      mem.sampleStart = 0;
    }
  }
  mem.lastCarried = carried;
  mem.lastDelivered = num(obs.delivered, mem.lastDelivered || 0);

  function initHint(h) {
    h.status = 1;
    h.idx = 0;
    h.maxSci = science;
    h.outerChecked = false;
    buildHintPoints(h);
    mem.activeHint = h.id;
  }

  function ensureActive() {
    let h = hintById(mem.activeHint);
    if (h && h.status < 2) {
      if (!h.pts) buildHintPoints(h);
      return h;
    }
    mem.activeHint = null;

    let best = null;
    let bestScore = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const q = mem.hints[i];
      if (q.status >= 2) continue;
      const d = Math.hypot(q.x - mem.px, q.y - mem.py);
      const db = Math.hypot(q.x - mem.baseX, q.y - mem.baseY);
      const v = Math.max(0.1, q.val);
      let score = Math.pow(v, 1.35) / (d + 0.72 * db + 28);
      if (q.status === 1) score *= 1.25;
      if (score > bestScore) {
        bestScore = score;
        best = q;
      }
    }
    if (best) {
      if (best.status === 0) initHint(best);
      else {
        mem.activeHint = best.id;
        if (!best.pts) buildHintPoints(best);
      }
    }
    return best;
  }

  function ensureGrid() {
    if (mem.gridTarget >= 0 &&
        mem.gridTarget < mem.grid.length &&
        !mem.grid[mem.gridTarget].done) {
      return mem.gridTarget;
    }
    mem.gridTarget = -1;
    let best = -1;
    let bd = 1e30;
    for (let i = 0; i < mem.grid.length; i++) {
      if (mem.grid[i].done) continue;
      const d = Math.hypot(mem.grid[i].x - mem.px, mem.grid[i].y - mem.py);
      if (d < bd) {
        bd = d;
        best = i;
      }
    }
    mem.gridTarget = best;
    return best;
  }

  function basicPlan() {
    const h = ensureActive();
    if (h) {
      if (!h.pts) buildHintPoints(h);
      const idx = clamp(num(h.idx, 0), 0, h.pts.length - 1);
      return { x: h.pts[idx].x, y: h.pts[idx].y, hint: h, grid: -1 };
    }
    const gi = ensureGrid();
    if (gi >= 0) {
      return { x: mem.grid[gi].x, y: mem.grid[gi].y, hint: null, grid: gi };
    }
    return null;
  }

  function preparePlan() {
    for (let guard = 0; guard < 20; guard++) {
      const h = ensureActive();
      if (!h) break;
      h.maxSci = Math.max(num(h.maxSci, 0), science);
      if (!h.pts) buildHintPoints(h);

      if (h.idx >= 5 && !h.outerChecked) {
        h.outerChecked = true;
        if (h.maxSci <= 0.000001 && h.val < 2.2) {
          markHintDone(h, false);
          continue;
        }
      }
      if (h.idx >= h.pts.length) {
        markHintDone(h, false);
        continue;
      }
      const p = h.pts[h.idx];
      if (Math.hypot(p.x - mem.px, p.y - mem.py) <= 3.0) {
        h.idx++;
        continue;
      }
      return { x: p.x, y: p.y, hint: h, grid: -1 };
    }

    for (let guard = 0; guard < 20; guard++) {
      const gi = ensureGrid();
      if (gi < 0) return null;
      const p = mem.grid[gi];
      if (Math.hypot(p.x - mem.px, p.y - mem.py) <= 5) {
        p.done = true;
        mem.gridTarget = -1;
        continue;
      }
      return { x: p.x, y: p.y, hint: null, grid: gi };
    }
    return null;
  }

  function planExtra(h) {
    if (!h) return 0;
    const idx = num(h.idx, 0);
    if (idx === 0) return 95;
    if (idx <= 4) return 65;
    return 32;
  }

  function planEnergy(x, y, h, load) {
    const d1 = Math.hypot(x - mem.px, y - mem.py);
    const db = Math.hypot(x - mem.baseX, y - mem.baseY);
    const extra = planExtra(h);
    const length = 1.35 * d1 + 1.55 * db + extra + 18;
    return 0.085 + mem.eMeter * length * (1 + 0.13 * load) * 1.25;
  }

  function motorControl(v, omega, hold, drillFlag) {
    v = clamp(v, -1.05, 1.05);
    omega = clamp(omega, -1.3, 1.3);
    const targetL = v - omega * 0.3;
    const targetR = v + omega * 0.3;
    const actualL = wl;
    const actualR = wr;

    if (Math.abs(targetL) < 0.05 && Math.abs(mem.lastTL) > 0.25) mem.iL *= 0.15;
    if (Math.abs(targetR) < 0.05 && Math.abs(mem.lastTR) > 0.25) mem.iR *= 0.15;

    const pitchBias = hold && Math.abs(v) < 0.05
      ? 0.06 * Math.sin(pitch * rad)
      : 0;

    function oneWheel(target, actual, integral, bias) {
      const err = target - actual;
      const oldI = integral;
      let newI = clamp(oldI + 0.08 * err * dt, -0.55, 0.55);
      let raw = target / 3 + 0.07 * err + newI + bias;
      if ((raw > 1 && err > 0) || (raw < -1 && err < 0)) {
        newI = oldI;
        raw = target / 3 + 0.07 * err + newI + bias;
      }
      return { u: clamp(raw, -1, 1), i: newI };
    }

    const l = oneWheel(targetL, actualL, mem.iL, pitchBias);
    const r = oneWheel(targetR, actualR, mem.iR, pitchBias);
    mem.iL = l.i;
    mem.iR = r.i;
    mem.lastTL = targetL;
    mem.lastTR = targetR;
    mem.lastUL = l.u;
    mem.lastUR = r.u;
    return { left: l.u, right: r.u, drill: !!drillFlag };
  }

  function stoppedOutput() {
    mem.iL = 0;
    mem.iR = 0;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;
    return { left: 0, right: 0, drill: false };
  }

  function navDrive(tx, ty, stopRadius, cruise) {
    let dx = tx - mem.px;
    let dy = ty - mem.py;
    let dist = Math.hypot(dx, dy);
    if (!isFinite(dist)) return stoppedOutput();
    if (dist <= stopRadius) return motorControl(0, 0, false, false);

    if (!mem.navHas ||
        Math.hypot(tx - mem.navTX, ty - mem.navTY) > 7) {
      mem.navHas = true;
      mem.navTX = tx;
      mem.navTY = ty;
      mem.navCheckAt = now + 7;
      mem.navCheckDist = dist;
      mem.navCheckX = mem.px;
      mem.navCheckY = mem.py;
      mem.navStuck = 0;
      mem.stuckUntil = 0;
      mem.stuckSide = 0;
    } else if (now >= mem.navCheckAt) {
      const moved = Math.hypot(mem.px - mem.navCheckX, mem.py - mem.navCheckY);
      const progress = mem.navCheckDist - dist;
      const commanded = Math.abs(mem.lastUL) + Math.abs(mem.lastUR);
      if (moved < 1.6 && progress < 1.0 &&
          (Math.abs(wl) + Math.abs(wr) > 0.25 || commanded > 0.25)) {
        mem.navStuck++;
        mem.stuckSide = openSide(wrap(Math.atan2(dy, dx) * deg - heading));
        mem.stuckUntil = now + 8;
        mem.avoidSide = mem.stuckSide;
      } else {
        mem.navStuck = 0;
      }
      mem.navCheckAt = now + 7;
      mem.navCheckDist = dist;
      mem.navCheckX = mem.px;
      mem.navCheckY = mem.py;
    }

    if (mem.bumpTicks > 0) {
      mem.bumpTicks--;
      return motorControl(0, mem.bumpSide * 0.85, false, false);
    }

    dx = tx - mem.px;
    dy = ty - mem.py;
    dist = Math.hypot(dx, dy);
    if (dist <= stopRadius) return motorControl(0, 0, false, false);

    const bearing = Math.atan2(dy, dx) * deg;
    const goalRel = wrap(bearing - heading);
    const directRange = rayAt(goalRel);

    if (Math.abs(goalRel) < 85 && directRange < 5.2) {
      if (!mem.avoidSide) mem.avoidSide = openSide(goalRel);
      mem.clearTicks = 0;
    } else if (directRange > 6.5 || Math.abs(goalRel) >= 85) {
      mem.clearTicks++;
      if (mem.clearTicks > 12) {
        mem.avoidSide = 0;
        mem.clearTicks = 0;
      }
    } else {
      mem.clearTicks = 0;
    }

    let bestA = clamp(goalRel, -100, 100);
    let bestCost = 1e30;
    for (let a = -100; a <= 100; a += 5) {
      const diff = Math.abs(wrap(goalRel - a));
      let cost = 2.6 * (1 - Math.cos(diff * rad));

      const clear = Math.min(rayAt(a), wallDist(a));
      const safe = 3.35;
      if (clear < safe) {
        const q = (safe - clear) / safe;
        cost += 7 * q * q + 2 * q;
        if (clear < 1.25) cost += 4;
      }

      if (mem.avoidSide && Math.abs(a) > 12 &&
          Math.sign(a) !== mem.avoidSide) cost += 0.42;
      if (now < mem.stuckUntil && mem.stuckSide &&
          Math.abs(a) > 10 && Math.sign(a) !== mem.stuckSide) cost += 0.85;

      if (mem.prevNavBearing !== null) {
        const smooth = Math.abs(wrap(heading + a - mem.prevNavBearing));
        cost += 0.035 * (1 - Math.cos(smooth * rad));
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
      }
    }

    mem.prevNavBearing = wrap(heading + bestA);

    const absErr = Math.abs(bestA);
    let speed = cruise;
    if (absErr > 55) speed = 0;
    else if (absErr > 35) speed = Math.min(speed, 0.30);
    else if (absErr > 22) speed = Math.min(speed, 0.56);

    const clearance = Math.min(rayAt(bestA), wallDist(bestA));
    if (clearance < 5) speed = Math.min(speed, 0.65);
    if (clearance < 3.35) speed = Math.min(speed, 0.38);
    if (clearance < 2.35) speed = Math.min(speed, 0.16);
    if (clearance < 1.35) speed = 0;

    const remaining = Math.max(0, dist - stopRadius);
    speed = Math.min(speed, Math.sqrt(0.70 * remaining));
