    return motorControl(speed, omega, false, false);
  }

  function returnOutput() {
    const beacon = obs.beacon;
    if (beacon && typeof beacon === "object" &&
        typeof beacon.distance === "number" &&
        typeof beacon.bearing === "number") {
      const d = Math.max(0, beacon.distance);
      if (d <= 2.65) return motorControl(0, 0, false, false);
      const a = (heading + beacon.bearing) * rad;
      const tx = mem.px + d * Math.cos(a);
      const ty = mem.py + d * Math.sin(a);
      return navDrive(tx, ty, 2.55, 0.92);
    }

    const d = Math.hypot(mem.baseX - mem.px, mem.baseY - mem.py);
