  let active = ensureActive();
  if (active) active.maxSci = Math.max(num(active.maxSci, 0), science);

  const beaconNow = obs.beacon;
  const baseDist = beaconNow && typeof beaconNow.distance === "number"
    ? Math.max(0, beaconNow.distance)
    : Math.hypot(mem.baseX - mem.px, mem.baseY - mem.py);
  const returnNeed = 0.09 +
    mem.eMeter * (1.60 * baseDist + 18) *
    (1 + 0.16 * carried) * 1.25;
  const returnTime = baseDist / 0.78 * 1.45 + 20;

  let pendingHint = false;
  for (let i = 0; i < mem.hints.length; i++) {
    if (mem.hints[i].status < 2) {
      pendingHint = true;
      break;
    }
  }

  let forceReturn = mem.returning ||
                    carried >= capacity ||
                    battery < returnNeed ||
                    battery < 0.065 ||
                    (carried > 0 && timeLeft < returnTime + 16) ||
                    (carried > 0 && !pendingHint && !mem.sampleTarget);

  const drillInProgress = !!mem.sampleTarget &&
    (drilling > 0 ||
     (mem.sampling && now - num(mem.sampleStart, now) < 7.5));

  if (forceReturn && drillInProgress && carried < capacity &&
      battery > 0.04 && timeLeft > returnTime + 5) {
    forceReturn = false;
  }

  if (forceReturn && !docked) mem.returning = true;
  if (!forceReturn && drillInProgress) mem.returning = false;

  if (docked) {
    if (carried > 0) {
      mem.iL = 0;
      mem.iR = 0;
      mem.lastUL = 0;
      mem.lastUR = 0;
      return { left: 0, right: 0, drill: false };
    }
    mem.returning = false;
    const p = basicPlan();
    if (!p) return stoppedOutput();
    const need = planEnergy(p.x, p.y, p.hint, carried);
    const extra = p.hint ? planExtra(p.hint) : 0;
    const d1 = Math.hypot(p.x - mem.px, p.y - mem.py);
    const db = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
    const tripSeconds = (1.45 * d1 + 1.60 * db + extra) / 0.82 + 30;
    if (timeLeft < tripSeconds + 8) return stoppedOutput();
    const chargeTarget = clamp(need + 0.11, 0.46, 0.97);
    if (battery + 0.003 < chargeTarget) return stoppedOutput();
  }

  if (mem.returning && !docked) return returnOutput();

  const site = obs.site && typeof obs.site === "object" ? obs.site : null;
  const siteDistance = site ? num(site.distance, -1) : -1;
  const siteBearing = site ? num(site.bearing, 0) : 0;
  const siteValid = !!site && siteDistance >= 0 && siteDistance <= 8;

  if (siteValid && carried < capacity) {
    const a = (heading + siteBearing) * rad;
    const sx = mem.px + siteDistance * Math.cos(a);
    const sy = mem.py + siteDistance * Math.sin(a);
    let st = mem.sampleTarget;
    if (!st || (!mem.sampling &&
        Math.hypot(sx - st.x, sy - st.y) > 10)) {
      st = {
        x: sx,
        y: sy,
        value: num(site.value, 0),
        hintId: associateHint(sx, sy),
        lastSeen: now
      };
      mem.sampleTarget = st;
      mem.sampling = false;
      mem.sampleStart = 0;
    } else {
      const blend = mem.sampling ? 0.18 : 0.55;
      st.x = st.x * (1 - blend) + sx * blend;
      st.y = st.y * (1 - blend) + sy * blend;
      st.value = num(site.value, st.value);
      st.lastSeen = now;
      if (st.hintId === null || st.hintId === undefined) {
        st.hintId = associateHint(sx, sy);
      }
    }
  }

  if (mem.sampleTarget) {
    const st = mem.sampleTarget;
    const stDist = Math.hypot(st.x - mem.px, st.y - mem.py);
    const age = now - num(st.lastSeen, now);
    if (drilling <= 0 && !mem.sampling &&
        ((age > 13 && stDist > 14) || age > 28 || stDist > 40)) {
      mem.sampleTarget = null;
      mem.sampling = false;
      mem.sampleStart = 0;
    }
  }

  if (mem.sampleTarget && carried < capacity) {
    const st = mem.sampleTarget;
    const stDist = Math.hypot(st.x - mem.px, st.y - mem.py);
    const closeDist = siteValid ? Math.min(stDist, siteDistance) : stDist;
    const activeDrill = drilling > 0 ||
      (mem.sampling && now - num(mem.sampleStart, now) < 7.5);

    if (!activeDrill) {
      const siteBaseDist = Math.hypot(st.x - mem.baseX, st.y - mem.baseY);
      const sampleNeed = 0.085 +
        mem.eMeter * (1.55 * siteBaseDist + 18) *
        (1 + 0.14 * carried) * 1.25;
      const sampleReturnTime = siteBaseDist / 0.82 * 1.45 + 18;
      const enoughTime = siteBaseDist < 3
        ? timeLeft > 7
        : timeLeft > sampleReturnTime + 7;
      if (battery < sampleNeed || !enoughTime) {
        mem.returning = true;
        return returnOutput();
      }
    }

    if (drilling > 0) {
      mem.sampling = true;
      if (!mem.sampleStart) mem.sampleStart = now;
      return motorControl(0, 0, true, true);
    }

    if (mem.sampling && closeDist <= 1.55) {
      return motorControl(0, 0, true, true);
    }
    if (mem.sampling && closeDist > 1.65) {
      mem.sampling = false;
      mem.sampleStart = 0;
    }

    const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
    if (closeDist <= 1.35) {
      if (speedNow < 0.15) {
        mem.sampling = true;
        mem.sampleStart = now;
        return motorControl(0, 0, true, true);
      }
      return motorControl(0, 0, true, false);
    }
    if (closeDist <= 1.60) {
      return motorControl(0, 0, true, false);
    }
    return navDrive(st.x, st.y, 1.10, 0.68);
  }

  if (mem.returning && !docked) return returnOutput();

  const plan = preparePlan();
  if (!plan) {
    if (carried > 0) {
      mem.returning = true;
      return returnOutput();
    }
    return stoppedOutput();
  }

  const region = plan.hint ? "h" + plan.hint.id : "g" + plan.grid;
  if (mem.gradRegion !== region) {
    mem.gradRegion = region;
    mem.gradTarget = null;
    mem.gradSteps = 0;
    mem.gradCooldown = 0;
  }

  function signalGradient() {
    const list = mem.sigSamples || [];
    const pts = [];
    for (let i = Math.max(0, list.length - 14); i < list.length; i++) {
      const q = list[i];
      if (Math.hypot(q.x - mem.px, q.y - mem.py) <= 48) pts.push(q);
    }
    if (pts.length < 4) return null;
    let mx = 0, my = 0, ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let xx = 0, yy = 0, xy = 0, xs = 0, ys = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      xx += dx * dx;
      yy += dy * dy;
      xy += dx * dy;
      xs += dx * ds;
      ys += dy * ds;
    }
    const det = xx * yy - xy * xy;
    if (det < 25) return null;
    const gx = (xs * yy - ys * xy) / det;
    const gy = (ys * xx - xs * xy) / det;
    const norm = Math.hypot(gx, gy);
    if (!isFinite(norm) || norm < 1e-9) return null;
    return { x: gx, y: gy, n: norm };
  }

  if (mem.gradTarget) {
    const gd = Math.hypot(mem.gradTarget.x - mem.px, mem.gradTarget.y - mem.py);
    const startD = Math.hypot(mem.px - mem.gradStartX, mem.py - mem.gradStartY);
    if (gd <= 2.8) {
      if (mem.gradStartSci > 0.000001 &&
          science < mem.gradStartSci * 0.72) {
        mem.gradSteps = 5;
      } else {
        mem.gradSteps++;
      }
      mem.gradTarget = null;
      mem.gradCooldown = now + 1.5;
    } else if (now - mem.gradAt > 20 ||
               (startD > 4 && mem.gradStartSci > 0.000001 &&
                science < mem.gradStartSci * 0.55)) {
      mem.gradSteps++;
      mem.gradTarget = null;
      mem.gradCooldown = now + 2;
    }
  }

  if (!mem.gradTarget && mem.gradSteps < 5 &&
      now >= mem.gradCooldown && science > 0.0000001) {
    const g = signalGradient();
    if (g && g.n * 10 > Math.max(0.00001, science * 0.05)) {
      const tx = clamp(mem.px + g.x / g.n * 10, 2, Math.max(2, mem.W - 2));
      const ty = clamp(mem.py + g.y / g.n * 10, 2, Math.max(2, mem.H - 2));
      if (Math.hypot(tx - mem.px, ty - mem.py) > 4) {
        mem.gradTarget = { x: tx, y: ty };
        mem.gradAt = now;
        mem.gradStartX = mem.px;
        mem.gradStartY = mem.py;
        mem.gradStartSci = science;
      }
    }
  }

  let goalX = plan.x;
  let goalY = plan.y;
  let cruise = plan.hint ? (plan.hint.idx === 0 ? 0.90 : 0.82) : 0.88;
  if (mem.gradTarget) {
    goalX = mem.gradTarget.x;
    goalY = mem.gradTarget.y;
    cruise = Math.min(cruise, 0.78);
  }

  const needForPlan = planEnergy(goalX, goalY, plan.hint, carried);
  if (battery < needForPlan || battery < 0.065) {
    mem.returning = true;
    return returnOutput();
  }

  const d1 = Math.hypot(goalX - mem.px, goalY - mem.py);
  const db = Math.hypot(goalX - mem.baseX, goalY - mem.baseY);
  const extra = planExtra(plan.hint);
  const plannedSeconds = (1.45 * d1 + 1.60 * db + extra) / 0.82 + 28;
  if (carried > 0 && timeLeft < plannedSeconds + 8) {
    mem.returning = true;
    return returnOutput();
  }

  return navDrive(goalX, goalY, plan.hint ? 2.7 : 4.0, cruise);
}

function act(obs, mem) {
  if (!obs || typeof obs !== "object") obs = {};
  if (!mem || typeof mem !== "object") mem = {};

  const dt = 0.1;
  const rad = Math.PI / 180;
  const deg = 180 / Math.PI;

  function num(v, fallback) {
    return (typeof v === "number" && isFinite(v)) ? v : fallback;
  }
  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }
  function wrap(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }

  const rawX0 = num(obs.x, 0);
  const rawY0 = num(obs.y, 0);
  const rawH0 = num(obs.heading, 0);
  const battery0 = Math.max(0, num(obs.battery, 1));
  const solar0 = Math.max(0, num(obs.solar, 0));
  const docked0 = !!obs.docked;

  if (!mem.initialized) {
    const mission = obs.mission || {};
    let w = 400;
    let h = 400;
    if (typeof mission.size === "number" && mission.size > 0) {
      w = mission.size;
      h = mission.size;
    } else if (mission.size && typeof mission.size === "object") {
      w = num(mission.size.width, num(mission.size.x, 400));
      h = num(mission.size.height, num(mission.size.y, 400));
    }

    mem.W = w;
    mem.H = h;
    mem.missionSecs = num(mission.seconds, 1200);
    mem.capacity = Math.max(1, num(mission.capacity, 5));

    const b = mission.base || {};
    mem.baseX = num(b.x, rawX0);
    mem.baseY = num(b.y, rawY0);

    mem.hints = [];
    if (Array.isArray(mission.hints)) {
      for (let i = 0; i < mission.hints.length; i++) {
        const q = mission.hints[i] || {};
        if (typeof q.x === "number" && typeof q.y === "number") {
          mem.hints.push({
            id: i,
            x: clamp(q.x, 2, Math.max(2, w - 2)),
            y: clamp(q.y, 2, Math.max(2, h - 2)),
            val: Math.max(0.05, num(q.estimate, 1)),
            status: 0,
            idx: 0,
            pts: null,
            maxSci: 0,
            sampled: false
          });
        }
      }
    }

    mem.grid = [];
    for (let gy = 35; gy <= h - 35; gy += 65) {
      for (let gx = 35; gx <= w - 35; gx += 65) {
        mem.grid.push({ x: gx, y: gy, done: false });
      }
