    mem.gridTarget = -1;

    mem.px = rawX0;
    mem.py = rawY0;
    mem.hEst = rawH0;
    mem.bias = 0;
    mem.poseReady = true;
    mem.lastRawH = rawH0;
    mem.lastRawX = rawX0;
    mem.lastRawY = rawY0;
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    mem.gpsAnchorX = rawX0;
    mem.gpsAnchorY = rawY0;

    mem.calActive = false;
    mem.calX = rawX0;
    mem.calY = rawY0;
    mem.calT = 0;
    mem.calSin = 0;
    mem.calCos = 0;

    mem.eRate = 0.0008;
    mem.energyCost = 0;
    mem.energyDist = 0;
    mem.energyReady = false;
    mem.prevBat = battery0;
    mem.prevSolar = solar0;
    mem.prevDock = docked0;
    mem.maxBattery = Math.max(0.1, battery0);

    mem.lastCarried = Math.max(0, num(obs.carried, 0));
    mem.lastDelivered = num(obs.delivered, 0);
    mem.activeHint = -1;
    mem.returning = false;
    mem.siteLock = null;
    mem.sampling = false;
