    mem.iR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;
    mem.lastTL = 0;
    mem.lastTR = 0;

    mem.navHas = false;
    mem.navStuck = 0;
    mem.navCheckAt = 0;
    mem.navCheckDist = 0;
    mem.navCheckX = rawX0;
    mem.navCheckY = rawY0;
    mem.navTX = rawX0;
    mem.navTY = rawY0;
    mem.stuckUntil = 0;
    mem.stuckSide = 0;
    mem.prevSteer = 0;

    mem.recovery = 0;
    mem.recoveryUntil = 0;
    mem.bumpSide = 1;
    mem.prevBumped = false;

    mem.tick = 0;
    mem.now = 0;
    mem.initialized = true;
  }

  mem.tick = (mem.tick || 0) + 1;
  const now = Math.max(
    num(obs.t, mem.tick * dt),
    num(mem.now, 0)
