      mem.calX = rawX;
      mem.calY = rawY;
      mem.calT = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
    mem.calT += dt;
    mem.calSin += Math.sin(rawHeading * rad) * dt;
    mem.calCos += Math.cos(rawHeading * rad) * dt;

    const cdx = rawX - mem.calX;
    const cdy = rawY - mem.calY;
    if (Math.hypot(cdx, cdy) > 5.5 && mem.calT > 4.5) {
