  mem.lastRawH = rawHeading;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;

  if (mem.energyReady && !docked && !mem.prevDock) {
    const solarAvg = clamp((mem.prevSolar + solar) * 0.5, 0, 0.2);
    const cost = mem.prevBat - battery + solarAvg * dt;
    if (travel > 0.01 && cost > 0) {
      mem.energyCost += cost;
      mem.energyDist += travel;
    }
    if (mem.energyDist >= 6) {
      const measured = mem.energyCost / Math.max(1, mem.energyDist);
      const mix = measured > mem.eRate ? 0.38 : 0.20;
      mem.eRate = clamp(mem.eRate * (1 - mix) + measured * mix,
                        0.00025, 0.025);
      mem.energyCost = 0;
      mem.energyDist = 0;
    }
  } else if (docked) {
    mem.energyCost = 0;
    mem.energyDist = 0;
  }
  mem.prevBat = battery;
  mem.prevSolar = solar;
  mem.prevDock = docked;
  mem.energyReady = true;
  mem.maxBattery = Math.max(num(mem.maxBattery, battery), battery);

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    const v = clamp(num(rays[i], 15), 0, 15);
    if (mem.rayLast[i] !== null &&
        Math.abs(v - mem.rayLast[i]) < 0.015) {
      mem.raySame[i] += dt;
      const moved = Math.hypot(
        mem.px - mem.rayStartX[i],
        mem.py - mem.rayStartY[i]
      );
      const turned = Math.abs(wrap(heading - mem.rayStartH[i]));
      if (mem.raySame[i] > 6 && (moved > 2.2 || turned > 40)) {
        mem.rayStale[i] = true;
      }
    } else {
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = mem.px;
      mem.rayStartY[i] = mem.py;
      mem.rayStartH[i] = heading;
    }
    mem.rayLast[i] = v;
    mem.raysClean[i] = mem.rayStale[i] ? 15 : v;
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    const f = (a + 80) / 20;
    const i = Math.floor(f);
    if (i >= 8) return mem.raysClean[8];
    const q = f - i;
    return mem.raysClean[i] * (1 - q) + mem.raysClean[i + 1] * q;
  }

  function wallDist(a) {
    const ang = (heading + a) * rad;
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    let d = 1e6;
    if (dx > 0.0001) d = Math.min(d, (mem.W - 1.4 - mem.px) / dx);
    else if (dx < -0.0001) d = Math.min(d, (1.4 - mem.px) / dx);
    if (dy > 0.0001) d = Math.min(d, (mem.H - 1.4 - mem.py) / dy);
    else if (dy < -0.0001) d = Math.min(d, (1.4 - mem.py) / dy);
    return Math.max(0, d);
  }

  function clearAt(a) {
    return Math.min(rayAt(a), wallDist(a));
  }

  function openSide() {
    const left = rayAt(45) + rayAt(70) +
      Math.min(wallDist(45), wallDist(70));
    const right = rayAt(-45) + rayAt(-70) +
      Math.min(wallDist(-45), wallDist(-70));
    if (left > right + 0.3) return 1;
    if (right > left + 0.3) return -1;
    return (mem.bumpSide || 1);
  }

  function wheelOne(target, actual, side, bias) {
    let integral = side === 0 ? num(mem.iL, 0) : num(mem.iR, 0);
    const lastT = side === 0 ? num(mem.lastTL, 0) : num(mem.lastTR, 0);
    const lastU = side === 0 ? num(mem.lastUL, 0) : num(mem.lastUR, 0);

    if (Math.abs(lastT - target) < 0.10 &&
        Math.abs(target) > 0.16 &&
        Math.abs(actual - target) < 0.28 &&
        Math.abs(lastU) > 0.10 &&
        actual * lastU > 0) {
      const gObs = Math.abs(actual / lastU);
      if (gObs > 0.8 && gObs < 5) {
        if (side === 0) {
          mem.gainL = clamp(mem.gainL * 0.98 + gObs * 0.02, 1.1, 5);
        } else {
          mem.gainR = clamp(mem.gainR * 0.98 + gObs * 0.02, 1.1, 5);
        }
      }
    }

    if (target * lastT < -0.02) integral *= 0.25;
    const err = target - actual;
    const oldI = integral;
    let nextI = clamp(oldI + 0.22 * err * dt, -0.42, 0.42);
    if (Math.abs(target) < 0.035 && Math.abs(actual) < 0.07) {
      nextI *= 0.78;
    }

    const gain = side === 0
      ? clamp(num(mem.gainL, 2.5), 1.1, 5)
      : clamp(num(mem.gainR, 2.5), 1.1, 5);
    let feed = 0;
    if (Math.abs(target) > 0.035) {
      feed = target / gain + Math.sign(target) * 0.065;
    }
    let raw = feed + 0.20 * err + nextI + bias;
    if ((raw > 1 && err > 0) || (raw < -1 && err < 0)) {
      nextI = oldI;
      raw = feed + 0.20 * err + nextI + bias;
    }

    if (side === 0) mem.iL = nextI;
    else mem.iR = nextI;
    return clamp(raw, -1, 1);
  }

  function motor(v, omega, drillFlag, hold) {
    v = clamp(v, -1.05, 1.05);
    omega = clamp(omega, -0.8, 0.8);
    const targetL = clamp(v - 0.3 * omega, -1.2, 1.2);
    const targetR = clamp(v + 0.3 * omega, -1.2, 1.2);
    const pitchBias = hold ? 0.34 * Math.sin(pitch * rad) : 0;
    const left = wheelOne(targetL, wl, 0, pitchBias);
    const right = wheelOne(targetR, wr, 1, pitchBias);
    mem.lastTL = targetL;
    mem.lastTR = targetR;
    mem.lastUL = left;
    mem.lastUR = right;
    return { left: left, right: right, drill: !!drillFlag };
  }

  function chooseAngle(goalRel) {
    if (Math.abs(goalRel) > 100) {
      return { a: Math.sign(goalRel) * 90, clear: clearAt(Math.sign(goalRel) * 80) };
    }

    const candidates = [];
    for (let a = -80; a <= 80; a += 10) candidates.push(a);
    candidates.push(clamp(goalRel, -80, 80));

    let bestA = 0;
    let bestCost = 1e30;
    let bestClear = 15;
    for (let i = 0; i < candidates.length; i++) {
      const a = candidates[i];
      const diff = Math.abs(wrap(goalRel - a));
      const clear = clearAt(a);
      let cost = 2.2 * (1 - Math.cos(diff * rad)) + 0.003 * diff;

      if (clear < 4.5) {
        const q = 4.5 - clear;
        cost += 0.22 * q * q;
      }
      if (clear < 2.2) cost += 2.5 + (2.2 - clear) * 3;
      if (clear < 1.2) cost += 7;
      if (clear < 0.75) cost += 10;

      if (now < mem.stuckUntil && Math.abs(a) > 12 &&
          Math.sign(a) !== mem.stuckSide) {
        cost += 0.9;
      }
      if (Math.abs(a) > 8) {
        cost += 0.0015 * Math.abs(a - num(mem.prevSteer, 0));
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestClear = clear;
      }
    }
    mem.prevSteer = bestA;
    return { a: bestA, clear: bestClear };
  }

  function noteNav(tx, ty, dist, stopRadius) {
    if (!mem.navHas || Math.hypot(tx - mem.navTX, ty - mem.navTY) > 7) {
      mem.navHas = true;
      mem.navTX = tx;
      mem.navTY = ty;
      mem.navCheckAt = now + 7;
      mem.navCheckDist = dist;
      mem.navCheckX = mem.px;
      mem.navCheckY = mem.py;
      mem.navStuck = 0;
      mem.stuckUntil = 0;
      return;
    }

    if (now >= mem.navCheckAt) {
      const moved = Math.hypot(
        mem.px - mem.navCheckX,
        mem.py - mem.navCheckY
      );
      const progress = mem.navCheckDist - dist;
      const command = Math.abs(num(mem.lastUL, 0)) +
                      Math.abs(num(mem.lastUR, 0));
      if (dist > stopRadius + 2 &&
          moved < 1.2 && progress < 0.8 && command > 0.25) {
        mem.navStuck = Math.min(6, mem.navStuck + 1);
        mem.stuckSide = openSide();
        mem.stuckUntil = now + 6;
      } else {
        mem.navStuck = 0;
      }
      mem.navCheckAt = now + 7;
      mem.navCheckDist = dist;
      mem.navCheckX = mem.px;
      mem.navCheckY = mem.py;
    }
  }

  function driveBearing(goalRel, dist, stopRadius, cruise) {
    goalRel = wrap(goalRel);
    dist = Math.max(0, num(dist, 0));
    if (dist <= stopRadius) return motor(0, 0, false, true);

    const yaw = clamp((wr - wl) / 0.6, -5, 5);
    if (Math.abs(goalRel) > 100) {
      const omega = clamp(1.10 * goalRel * rad - 0.50 * yaw, -0.68, 0.68);
      return motor(0, omega, false, false);
    }

    const choice = chooseAngle(goalRel);
    const a = choice.a;
    let speed = 0;
    if (Math.abs(a) < 59) {
      speed = cruise * Math.max(0, Math.cos(a * rad));
    }

    const remaining = Math.max(0, dist - stopRadius);
    speed = Math.min(speed, Math.sqrt(0.85 * remaining));

    const clear = choice.clear;
    if (clear < 5) speed = Math.min(speed, 0.58);
    if (clear < 3.5) speed = Math.min(speed, 0.34);
    if (clear < 2.5) speed = Math.min(speed, 0.17);
    if (clear < 1.25) speed = 0;

    const omega = clamp(1.10 * a * rad - 0.50 * yaw, -0.68, 0.68);
    return motor(speed, omega, false, false);
  }

  function navTo(tx, ty, stopRadius, cruise) {
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const dist = Math.hypot(dx, dy);
    if (!isFinite(dist)) return motor(0, 0, false, true);
    if (dist <= stopRadius) return motor(0, 0, false, true);

    noteNav(tx, ty, dist, stopRadius);
    const bearing = Math.atan2(dy, dx) * deg;
    return driveBearing(wrap(bearing - heading), dist, stopRadius, cruise);
  }

  function returnOutput() {
    const beacon = obs.beacon;
    if (beacon && typeof beacon === "object" &&
        typeof beacon.distance === "number" &&
        typeof beacon.bearing === "number" &&
        beacon.distance >= 0 && beacon.distance <= 20.5) {
      const d = beacon.distance;
      if (d <= 2.35) return motor(0, 0, false, true);
      return driveBearing(beacon.bearing, d, 2.30, 0.78);
    }
    const d = Math.hypot(mem.baseX - mem.px, mem.baseY - mem.py);
    if (d <= 2.35) return motor(0, 0, false, true);
    return navTo(mem.baseX, mem.baseY, 2.30, 0.78);
  }

  function recoveryOutput() {
    if (bumped && !mem.prevBumped) {
      mem.bumpSide = openSide();
      mem.recovery = 1;
      mem.recoveryUntil = now + 0.75;
    }
    mem.prevBumped = bumped;

    if (mem.recovery === 1) {
      if (now < mem.recoveryUntil) {
        return motor(-0.22, 0, false, false);
      }
      mem.recovery = 2;
      mem.recoveryUntil = now + 1.0;
    }
    if (mem.recovery === 2) {
      if (now < mem.recoveryUntil) {
        return motor(0, (mem.bumpSide || 1) * 0.48, false, false);
      }
      mem.recovery = 0;
    }
    return null;
  }

  function hintById(id) {
    if (id === null || id === undefined || id < 0) return null;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].id === id) return mem.hints[i];
    }
    return null;
  }

  function buildHintPoints(h) {
    if (h.pts) return;
    const pts = [];
    function add(x, y) {
      x = clamp(x, 2, Math.max(2, mem.W - 2));
      y = clamp(y, 2, Math.max(2, mem.H - 2));
      for (let i = 0; i < pts.length; i++) {
        if (Math.hypot(pts[i].x - x, pts[i].y - y) < 2.5) return;
      }
      pts.push({ x: x, y: y });
    }

    add(h.x, h.y);
    const inner = [0, 90, 180, 270];
    for (let i = 0; i < inner.length; i++) {
      add(h.x + 9 * Math.cos(inner[i] * rad),
          h.y + 9 * Math.sin(inner[i] * rad));
    }
    for (let a = 0; a < 360; a += 45) {
      add(h.x + 18.5 * Math.cos(a * rad),
          h.y + 18.5 * Math.sin(a * rad));
    }
    h.pts = pts;
  }

  function markHintDone(h, sampled) {
    if (!h) return;
    h.status = 2;
    if (sampled) h.sampled = true;
    if (mem.activeHint === h.id) mem.activeHint = -1;
  }

  function associateHint(x, y) {
    const active = hintById(mem.activeHint);
    if (active && active.status < 2 &&
        Math.hypot(x - active.x, y - active.y) < 36) {
      return active.id;
    }
    let best = null;
    let bd = 30;
    for (let i = 0; i < mem.hints.length; i++) {
      const q = mem.hints[i];
      if (q.status >= 2) continue;
      const d = Math.hypot(x - q.x, y - q.y);
      if (d < bd) {
        bd = d;
        best = q;
      }
    }
    return best ? best.id : null;
  }

  function markSiteDone(x, y, id) {
    let chosen = null;
    const q = hintById(id);
    if (q && q.status < 2 && Math.hypot(x - q.x, y - q.y) < 36) {
      chosen = q;
    }
    if (!chosen) {
      let bd = 30;
      for (let i = 0; i < mem.hints.length; i++) {
        const c = mem.hints[i];
        if (c.status >= 2) continue;
        const d = Math.hypot(x - c.x, y - c.y);
        if (d < bd) {
          bd = d;
          chosen = c;
        }
      }
    }
    if (chosen) markHintDone(chosen, true);
  }

  const previousCarried = num(mem.lastCarried, carried);
  if (carried > previousCarried) {
    const st = mem.siteLock;
    if (st) markSiteDone(st.x, st.y, st.hintId);
    else markSiteDone(mem.px, mem.py, mem.activeHint);
    mem.sampleCount = num(mem.sampleCount, 0) + carried - previousCarried;
    mem.siteLock = null;
    mem.sampling = false;
    mem.sampleStart = -1;
  }
  mem.lastCarried = carried;
  mem.lastDelivered = num(obs.delivered, mem.lastDelivered || 0);

  const site = obs.site && typeof obs.site === "object" ? obs.site : null;
  const siteDistance = site ? num(site.distance, -1) : -1;
  const siteBearing = site ? num(site.bearing, 0) : 0;
  const siteValid = !!site && siteDistance >= 0 && siteDistance <= 8.2;

  if (siteValid) {
    const a = (heading + siteBearing) * rad;
    const sx = mem.px + siteDistance * Math.cos(a);
    const sy = mem.py + siteDistance * Math.sin(a);
    let st = mem.siteLock;
    if (!st || now - num(st.lastSeen, now) > 18 ||
        Math.hypot(sx - st.x, sy - st.y) > 13) {
      st = {
        x: sx,
        y: sy,
        value: num(site.value, 0),
        hintId: associateHint(sx, sy),
        lastSeen: now,
        lastDistance: siteDistance
      };
      mem.siteLock = st;
    } else {
      st.x = st.x * 0.62 + sx * 0.38;
      st.y = st.y * 0.62 + sy * 0.38;
      st.value = num(site.value, st.value);
      st.lastSeen = now;
      st.lastDistance = siteDistance;
      if (st.hintId === null || st.hintId === undefined) {
        st.hintId = associateHint(sx, sy);
      }
    }
  } else if (mem.siteLock && drilling <= 0 && !mem.sampling &&
             now - num(mem.siteLock.lastSeen, now) > 25) {
    mem.siteLock = null;
  }

  if (drilling > 0) {
    mem.sampling = true;
    if (mem.sampleStart < 0) mem.sampleStart = now - drilling;
  } else if (mem.sampling && mem.sampleStart >= 0 &&
             now - mem.sampleStart > 8.2) {
    mem.sampling = false;
    mem.sampleStart = -1;
  }

  if (!docked) {
    const movedFromSignal = mem.sigLastX === null
      ? 1e9
      : Math.hypot(mem.px - mem.sigLastX, mem.py - mem.sigLastY);
    if (mem.sigLastX === null ||
        (movedFromSignal > 2.4 && now - mem.sigLastT > 0.2) ||
        (movedFromSignal > 0.8 && now - mem.sigLastT > 3.2)) {
      mem.sigSamples.push({ x: mem.px, y: mem.py, s: science });
      if (mem.sigSamples.length > 24) mem.sigSamples.shift();
      mem.sigLastX = mem.px;
      mem.sigLastY = mem.py;
      mem.sigLastT = now;
    }
  }

  function returnEnergy(distance, load) {
    return 0.11 +
      mem.eRate * (Math.max(0, distance) + 11) *
      (1 + 0.13 * Math.max(0, load)) * 1.75 +
      0.012 * Math.max(0, load);
  }

  function returnTime(distance) {
    return 20 + Math.max(0, distance) * 2.3;
  }

  function baseDistanceNow() {
    const beacon = obs.beacon;
    if (beacon && typeof beacon.distance === "number" &&
        beacon.distance >= 0 && beacon.distance <= 20.5) {
      return beacon.distance;
    }
    return Math.hypot(mem.baseX - mem.px, mem.baseY - mem.py);
  }

  function planMetrics(x, y, hint, idx) {
    const d1 = Math.hypot(x - mem.px, y - mem.py);
    const db = Math.hypot(x - mem.baseX, y - mem.baseY);
    const remaining = hint && hint.pts
      ? Math.max(1, hint.pts.length - idx)
      : 1;
    const searchSeconds = hint ? Math.max(18, remaining * 7.5) : 18;
    const searchDistance = hint ? Math.max(12, remaining * 2.5) : 12;
    const energy = 0.12 +
      mem.eRate * (d1 + db + searchDistance + 8) *
      (1 + 0.11 * (carried + 1)) * 1.60 +
      0.018 * (carried + 1);
    const seconds = 1.65 * d1 + 2.05 * db + searchSeconds + 25;
    return { d1: d1, db: db, energy: energy, seconds: seconds };
  }

  function hintMetrics(hint) {
    buildHintPoints(hint);
    const idx = clamp(Math.floor(num(hint.idx, 0)), 0, hint.pts.length - 1);
    const p = hint.pts[idx];
    return planMetrics(p.x, p.y, hint, idx);
  }

  function ensureHint() {
    let active = hintById(mem.activeHint);
    if (active && active.status < 2) {
      const m = hintMetrics(active);
      if (timeLeft > m.seconds + 4 &&
          m.energy < num(mem.maxBattery, battery) * 1.28) {
        return active;
      }
    }

    let best = null;
    let bestScore = -1;
    for (let i = 0; i < mem.hints.length; i++) {
      const q = mem.hints[i];
      if (q.status >= 2) continue;
      buildHintPoints(q);
      const m = hintMetrics(q);
      if (timeLeft <= m.seconds + 4 ||
          m.energy >= num(mem.maxBattery, battery) * 1.28) {
        continue;
      }
      const remaining = Math.max(1, q.pts.length - q.idx);
      let score = Math.pow(Math.max(0.1, q.val), 1.08) /
        (55 + 0.65 * m.d1 + 0.45 * m.db + remaining * 1.7);
      if (q.status === 1) score *= 1.12;
      if (score > bestScore) {
        bestScore = score;
        best = q;
      }
    }
    if (best) {
      mem.activeHint = best.id;
      best.status = 1;
    } else {
      mem.activeHint = -1;
    }
    return best;
  }

  function gridPlan() {
    if (!Array.isArray(mem.grid) || mem.grid.length === 0) return null;

    let best = null;
    let bestIndex = -1;
    let bestDist = 1e30;

    for (let i = 0; i < mem.grid.length; i++) {
      const g = mem.grid[i];
      if (g.done) continue;
      const m = planMetrics(g.x, g.y, null, 0);
      if (timeLeft <= m.seconds + 4 ||
          m.energy >= num(mem.maxBattery, battery) * 1.28) {
        continue;
      }
      const d = Math.hypot(g.x - mem.px, g.y - mem.py);
      if (i === mem.gridTarget) d *= 0.94;
      if (d < bestDist) {
        bestDist = d;
        best = g;
        bestIndex = i;
      }
    }

    if (!best) {
      mem.gridTarget = -1;
      return null;
    }
    mem.gridTarget = bestIndex;
    return {
      x: best.x,
      y: best.y,
      hint: null,
      grid: bestIndex,
      metrics: planMetrics(best.x, best.y, null, 0)
    };
  }

  function preparePlan() {
    for (let guard = 0; guard < 40; guard++) {
      const h = ensureHint();
      if (!h) break;
      buildHintPoints(h);

      if (h.idx >= 5 && h.maxSci < 0.00001 && h.val < 2.6) {
        markHintDone(h, false);
        continue;
      }
      if (h.idx >= h.pts.length) {
        markHintDone(h, false);
        continue;
      }

      const p = h.pts[h.idx];
      if (Math.hypot(p.x - mem.px, p.y - mem.py) <= 3.2) {
        h.idx++;
        continue;
      }
      const metrics = planMetrics(p.x, p.y, h, h.idx);
      return {
        x: p.x,
        y: p.y,
        hint: h,
        grid: -1,
        metrics: metrics
      };
    }

    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].status < 2) return null;
    }

    for (let guard = 0; guard < 40; guard++) {
      const p = gridPlan();
      if (!p) return null;
      const g = mem.grid[p.grid];
      if (Math.hypot(g.x - mem.px, g.y - mem.py) <= 4.5) {
        g.done = true;
        mem.gridTarget = -1;
        continue;
      }
      return p;
    }
    return null;
  }

  function signalGradient(cx, cy) {
    const list = mem.sigSamples || [];
    const pts = [];
    for (let i = Math.max(0, list.length - 18); i < list.length; i++) {
      const q = list[i];
      if (Math.hypot(q.x - mem.px, q.y - mem.py) <= 48 &&
          Math.hypot(q.x - cx, q.y - cy) <= 55) {
        pts.push(q);
      }
    }
    if (pts.length < 5) return null;

    let mx = 0, my = 0, ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let xx = 0, yy = 0, xy = 0, xs = 0, ys = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      xx += dx * dx;
      yy += dy * dy;
      xy += dx * dy;
      xs += dx * ds;
      ys += dy * ds;
    }
    const det = xx * yy - xy * xy;
    if (det < 28) return null;
    const gx = (xs * yy - ys * xy) / det;
    const gy = (ys * xx - xs * xy) / det;
