    }
  }

  if (mustReturn) {
    mem.returning = true;
    return returnOutput();
  }

  if (mem.siteLock && carried < capacity) {
    const st = mem.siteLock;
    const d = siteValid
      ? siteDistance
      : Math.hypot(st.x - mem.px, st.y - mem.py);
    const age = now - num(st.lastSeen, now);

    if (!canSample && !inProgress) {
      if (docked) return { left: 0, right: 0, drill: false };
