        Math.abs(u) > 0.15 && target * u > 0) {
      const apparent = Math.abs(target) /
        Math.max(0.08, Math.abs(u) - 0.06);
      if (apparent > 0.65 && apparent < 5) {
        if (side === 0) {
          mem.gainL = clamp(mem.gainL * 0.985 + apparent * 0.015, 0.65, 5);
        } else {
          mem.gainR = clamp(mem.gainR * 0.985 + apparent * 0.015, 0.65, 5);
        }
      }
    } else if (Math.abs(err) > 0.45 && Math.abs(u) > 0.85) {
      if (side === 0) mem.gainL = Math.max(0.65, mem.gainL * 0.995);
      else mem.gainR = Math.max(0.65, mem.gainR * 0.995);
    }

    if (side === 0) mem.iL = nextI;
    else mem.iR = nextI;
    return u;
  }

  function motor(v, omega, drillFlag, hold) {
    v = clamp(v, -1.1, 1.1);
    omega = clamp(omega, -1.2, 1.2);
    const targetL = clamp(v - 0.3 * omega, -1.4, 1.4);
    const targetR = clamp(v + 0.3 * omega, -1.4, 1.4);
    const pitchBias = hold
      ? clamp(0.28 * Math.sin(pitch * rad), -0.18, 0.18)
      : 0;
    const left = wheelOne(targetL, wl, 0, pitchBias);
    const right = wheelOne(targetR, wr, 1, pitchBias);
    mem.lastTL = targetL;
    mem.lastTR = targetR;
    mem.lastUL = left;
    mem.lastUR = right;
    return { left: left, right: right, drill: !!drillFlag };
  }

  function idle() {
    mem.iL *= 0.65;
    mem.iR *= 0.65;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;
    return { left: 0, right: 0, drill: false };
  }

  function startRecovery(side) {
    mem.bumpSide = side || 1;
    mem.recoveryPhase = 1;
    mem.recoveryUntil = now + 0.65;
  }

  function recoveryOutput() {
    if (docked) {
      mem.recoveryPhase = 0;
      return null;
    }
    if (mem.recoveryPhase === 1) {
      if (now < mem.recoveryUntil) {
        return motor(-0.20, 0, false, false);
      }
      mem.recoveryPhase = 2;
      mem.recoveryUntil = now + 1.0;
    }
    if (mem.recoveryPhase === 2) {
      if (now < mem.recoveryUntil) {
        return motor(0, (mem.bumpSide || 1) * 0.65, false, false);
      }
      mem.recoveryPhase = 0;
    }
    return null;
  }

  if (bumped && !mem.prevBumped && !docked) {
    mem.bumpSide = openSide(0);
    startRecovery(mem.bumpSide);
  }
  mem.prevBumped = bumped;

  function noteNav(key, tx, ty, dist, stopRadius, rel) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navFails = 0;
      mem.navCheckAt = now + 7;
      mem.navPrevDist = dist;
      mem.navX = mem.px;
      mem.navY = mem.py;
      mem.navProgressAt = now;
      mem.navPrevRel = Math.abs(rel);
      return;
    }

    if (now >= num(mem.navCheckAt, now)) {
      const moved = Math.hypot(mem.px - mem.navX, mem.py - mem.navY);
      const progress = num(mem.navPrevDist, dist) - dist;
      const turnProgress = num(mem.navPrevRel, Math.abs(rel)) -
        Math.abs(rel) > 9;

      if (progress > 0.7 || moved > 1.1 || turnProgress) {
        mem.navProgressAt = now;
        mem.navFails = 0;
      } else if (dist > stopRadius + 3 &&
                 Math.abs(rel) < 68 &&
                 now - num(mem.navProgressAt, now) > 12) {
        mem.navFails = Math.min(6, num(mem.navFails, 0) + 1);
        mem.navProgressAt = now;
        if (mem.navFails < 3 && mem.recoveryPhase === 0) {
          startRecovery(openSide(rel));
        }
      }

      mem.navCheckAt = now + 7;
      mem.navPrevDist = dist;
      mem.navX = mem.px;
      mem.navY = mem.py;
      mem.navPrevRel = Math.abs(rel);
    }
  }

  function navigateRel(goalRel, dist, stopRadius, cruise, key, tx, ty) {
    goalRel = wrap(goalRel);
    dist = Math.max(0, num(dist, 0));
    if (!isFinite(dist) || dist <= stopRadius) {
      return motor(0, 0, false, true);
    }

    if (typeof tx !== "number" || typeof ty !== "number") {
      const a = (heading + goalRel) * rad;
      tx = mem.px + dist * Math.cos(a);
      ty = mem.py + dist * Math.sin(a);
    }
    noteNav(key, tx, ty, dist, stopRadius, goalRel);

    const recovery = recoveryOutput();
    if (recovery) return recovery;

    const yaw = clamp((wr - wl) / 0.6, -5, 5);
    if (Math.abs(goalRel) > 108) {
      const omega = clamp(
        2.0 * goalRel * rad - 0.42 * yaw,
        -1.0,
        1.0
      );
      return motor(0, omega, false, false);
    }

    let bestA = clamp(goalRel, -80, 80);
    let bestCost = 1e30;
    let bestClear = 15;

    for (let a = -80; a <= 80; a += 10) {
      const diff = Math.abs(wrap(goalRel - a));
      const clear = clearAt(a);
      let cost = 0.006 * diff * diff;

      if (clear < 4.5) {
        const q = 4.5 - clear;
        cost += 0.62 * q * q;
      }
      if (clear < 2.4) cost += 4 + (2.4 - clear) * 2;
      if (clear < 1.2) cost += 8;

      if (Math.abs(a) > 8) {
        cost += 0.0015 * Math.abs(a - num(mem.prevSteer, 0));
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestClear = clear;
      }
    }
    mem.prevSteer = bestA;

    let speed = cruise;
    if (Math.abs(bestA) > 57) {
      speed = 0;
    } else {
      speed *= Math.max(0.30, Math.cos(bestA * rad));
    }

    const remaining = Math.max(0, dist - stopRadius);
    speed = Math.min(speed, Math.sqrt(0.82 * remaining));
    if (bestClear < 5) speed = Math.min(speed, 0.58);
    if (bestClear < 3.5) speed = Math.min(speed, 0.34);
    if (bestClear < 2.5) speed = Math.min(speed, 0.16);
    if (bestClear < 1.35) speed = 0;

    const omega = clamp(
      1.8 * bestA * rad - 0.42 * yaw,
      -1.1,
      1.1
    );
    return motor(speed, omega, false, false);
  }

  function navigateAbs(tx, ty, stopRadius, cruise, key) {
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const dist = Math.hypot(dx, dy);
    if (!isFinite(dist) || dist <= stopRadius) {
      return motor(0, 0, false, true);
    }
    const bearing = Math.atan2(dy, dx) * deg;
    return navigateRel(
      wrap(bearing - heading),
      dist,
      stopRadius,
      cruise,
      key,
      tx,
      ty
    );
  }

  function hintById(id) {
    if (id === null || id === undefined || id < 0) return null;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].id === id) return mem.hints[i];
    }
    return null;
  }

  function markHintSampled(st) {
    if (!st) return;
    let chosen = null;
    const h = hintById(st.hintId);
    if (h && h.state < 2 &&
        Math.hypot(st.x - h.x, st.y - h.y) < 40) {
      chosen = h;
    }
    if (!chosen) {
      const active = hintById(mem.activeHint);
      if (active && active.state < 2 &&
          Math.hypot(st.x - active.x, st.y - active.y) < 36) {
        chosen = active;
      }
    }
    if (!chosen) {
      let best = 30;
      for (let i = 0; i < mem.hints.length; i++) {
        const q = mem.hints[i];
        if (q.state >= 2) continue;
        const d = Math.hypot(st.x - q.x, st.y - q.y);
        if (d < best) {
          best = d;
          chosen = q;
        }
      }
    }
    if (chosen) {
      chosen.state = 2;
      chosen.sampled = true;
      if (mem.activeHint === chosen.id) mem.activeHint = -1;
    }
  }

  function isFailedSite(x, y) {
    for (let i = 0; i < mem.failedSites.length; i++) {
      const f = mem.failedSites[i];
      if (f.until > now && f.count >= 2 &&
          Math.hypot(x - f.x, y - f.y) < 3.5) return true;
    }
    return false;
  }

  function addFailedSite(st, amount) {
    if (!st) return;
    let best = null;
    for (let i = 0; i < mem.failedSites.length; i++) {
      const f = mem.failedSites[i];
      if (Math.hypot(st.x - f.x, st.y - f.y) < 3.5) {
        best = f;
        break;
      }
    }
    if (best) {
      best.count += amount || 1;
      best.until = now + 120;
    } else {
      mem.failedSites.push({
        x: st.x,
        y: st.y,
        count: amount || 1,
        until: now + 120
      });
    }
    if (mem.failedSites.length > 16) mem.failedSites.shift();
  }

  function clearFailedSite(st) {
    if (!st) return;
    for (let i = mem.failedSites.length - 1; i >= 0; i--) {
      if (Math.hypot(st.x - mem.failedSites[i].x,
                     st.y - mem.failedSites[i].y) < 4) {
        mem.failedSites.splice(i, 1);
      }
    }
  }

  function returnEnergy(distance, load) {
    distance = Math.max(0, distance);
    load = Math.max(0, load);
    return 0.12 +
      mem.eRate * (distance + 10) * (1 + 0.20 * load) * 2.0 +
      0.02 * load;
  }

  function tripEnergy(d1, d2, load) {
    d1 = Math.max(0, d1);
    d2 = Math.max(0, d2);
    load = Math.max(0, load);
    return 0.13 +
      mem.eRate * (d1 + d2 + 14) * (1 + 0.20 * load) * 2.0 +
      0.025 * (load + 1);
  }

  function returnSeconds(distance) {
    return 22 + Math.max(0, distance) * 2.15;
  }

  function validBeacon() {
    const b = obs.beacon;
    return !!b && typeof b.distance === "number" &&
      typeof b.bearing === "number" &&
      b.distance >= 0 && b.distance <= 20.5;
  }

  function baseDistanceNow() {
    if (validBeacon()) return Math.max(0, obs.beacon.distance);
    return Math.hypot(mem.baseX - mem.px, mem.baseY - mem.py);
  }

  function returnOutput() {
    if (validBeacon()) {
      const d = Math.max(0, obs.beacon.distance);
      if (d <= 2.25) return motor(0, 0, false, true);
      return navigateRel(
        obs.beacon.bearing,
        d,
        2.25,
        0.78,
        "return"
      );
    }

    const dx = mem.baseX - mem.px;
    const dy = mem.baseY - mem.py;
    const d = Math.hypot(dx, dy);
    if (d <= 2.25) return motor(0, 0, false, true);
    return navigateAbs(mem.baseX, mem.baseY, 2.25, 0.78, "return");
  }

  function preparePlan() {
    const hintLimit = mem.hints.length + 3;

    for (let guard = 0; guard < hintLimit; guard++) {
      let h = hintById(mem.activeHint);
      if (!h || h.state >= 2) {
        mem.activeHint = -1;
        h = null;
      }

      if (!h) {
        let best = null;
        let bestScore = -1;
        for (let i = 0; i < mem.hints.length; i++) {
          const q = mem.hints[i];
          if (q.state >= 2 || q.idx >= q.points.length) continue;
          const p = q.points[q.idx];
          const d1 = Math.hypot(p.x - mem.px, p.y - mem.py);
          const db = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
          const energy = tripEnergy(d1, db, carried);
          const time = 2.05 * (d1 + db) + 55 + carried * 8;
          if (energy > mem.maxBattery * 0.985 ||
              time > timeLeft - 5) continue;

          const score = Math.pow(Math.max(0.1, q.val), 1.22) /
            (35 + d1 + 0.72 * db + 7 * q.idx);
          if (score > bestScore) {
            bestScore = score;
            best = q;
          }
        }
        if (!best) break;
        h = best;
        h.state = 1;
        mem.activeHint = h.id;
      }

      h.maxSci = Math.max(num(h.maxSci, 0), science);

      if (h.idx >= h.points.length) {
        h.state = 2;
        if (mem.activeHint === h.id) mem.activeHint = -1;
        continue;
      }
      if (h.idx >= 5 && h.maxSci < 0.00001 && h.val < 2.5) {
        h.state = 2;
        if (mem.activeHint === h.id) mem.activeHint = -1;
        continue;
      }

      const p = h.points[h.idx];
      const d = Math.hypot(p.x - mem.px, p.y - mem.py);
      if (d <= 1.8) {
        h.maxSci = Math.max(h.maxSci, science);
        h.idx++;
        h.wpKey = null;
        mem.navKey = null;
        mem.navFails = 0;
        continue;
      }

      const db = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
      const energy = tripEnergy(d, db, carried);
      const eta = 2.05 * (d + db) + 55 + carried * 8;
      if (energy > mem.maxBattery * 0.985) {
        h.state = 2;
        if (mem.activeHint === h.id) mem.activeHint = -1;
        continue;
      }
      if (eta > timeLeft - 5) {
        h.state = 2;
        if (mem.activeHint === h.id) mem.activeHint = -1;
        continue;
      }

      const key = "h" + h.id + "_" + h.idx;
      if (mem.navKey === key && mem.navFails >= 3) {
        h.idx++;
        h.wpKey = null;
        mem.navKey = null;
        mem.navFails = 0;
        continue;
      }

      if (h.wpKey !== key) {
        h.wpKey = key;
        h.wpAt = now;
        h.wpDist = d;
      } else {
        const timeout = clamp(2.5 * num(h.wpDist, d) + 45, 90, 300);
        if (now - num(h.wpAt, now) > timeout) {
          h.idx++;
          h.wpKey = null;
          mem.navKey = null;
          mem.navFails = 0;
          continue;
        }
      }

      return {
        x: p.x,
        y: p.y,
        key: key,
        energy: energy,
        eta: eta,
        hint: h,
        grid: -1
      };
    }

    let gIndex = mem.gridTarget;
    if (gIndex < 0 || gIndex >= mem.grid.length ||
        mem.grid[gIndex].done) {
      gIndex = -1;
      let bestScore = 1e30;
      for (let i = 0; i < mem.grid.length; i++) {
        const g = mem.grid[i];
        if (g.done) continue;
        const d1 = Math.hypot(g.x - mem.px, g.y - mem.py);
        const db = Math.hypot(g.x - mem.baseX, g.y - mem.baseY);
        const energy = tripEnergy(d1, db, carried);
        const eta = 1.95 * (d1 + db) + 50 + carried * 8;
        if (energy > mem.maxBattery * 0.985 ||
            eta > timeLeft - 5) continue;
        const score = d1 + 0.48 * db;
        if (score < bestScore) {
          bestScore = score;
          gIndex = i;
        }
      }
    }

    if (gIndex < 0) {
      mem.gridTarget = -1;
      return null;
    }

    mem.gridTarget = gIndex;
    const g = mem.grid[gIndex];
    const d = Math.hypot(g.x - mem.px, g.y - mem.py);
    if (d <= 2.3) {
      g.done = true;
      mem.gridTarget = -1;
      mem.navKey = null;
      return preparePlan();
    }

    const key = "g" + gIndex;
    if (mem.navKey === key && mem.navFails >= 3) {
      g.done = true;
      mem.gridTarget = -1;
      mem.navKey = null;
      mem.navFails = 0;
      return preparePlan();
    }

    const db = Math.hypot(g.x - mem.baseX, g.y - mem.baseY);
    const energy = tripEnergy(d, db, carried);
    const eta = 1.95 * (d + db) + 50 + carried * 8;
    if (energy > mem.maxBattery * 0.985 || eta > timeLeft - 5) {
      return null;
    }
    return {
      x: g.x,
      y: g.y,
      key: key,
      energy: energy,
      eta: eta,
      hint: null,
      grid: gIndex
    };
  }

  let sampleSucceeded = false;
  const previousCarried = num(mem.lastCarried, carried);
  if (carried > previousCarried) {
    sampleSucceeded = true;
    markHintSampled(mem.lastSample || mem.siteLock);
    clearFailedSite(mem.lastSample || mem.siteLock);
    mem.siteLock = null;
    mem.lastSample = null;
    mem.sampling = false;
    mem.sampleStart = -1;
  } else if (carried < previousCarried && docked) {
    mem.siteLock = null;
    mem.lastSample = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.returning = false;
  }
  mem.lastCarried = carried;
  mem.lastDelivered = num(obs.delivered, mem.lastDelivered || 0);

  if (!sampleSucceeded && drilling > 0) {
    if (!mem.sampling) mem.sampling = true;
    if (mem.sampleStart < 0) mem.sampleStart = now - drilling;
  }

  if (mem.sampling && mem.sampleStart >= 0 &&
      now - mem.sampleStart > 7.8) {
    addFailedSite(mem.lastSample || mem.siteLock, 1);
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.lastSample = null;
    mem.siteLock = null;
  }

  const site = obs.site && typeof obs.site === "object" ? obs.site : null;
  const siteDistance = site ? num(site.distance, -1) : -1;
  const siteBearing = site ? num(site.bearing, 0) : 0;
  const siteValid = !!site && siteDistance >= 0 &&
    siteDistance <= 8.5 && isFinite(siteBearing);

  if (siteValid && carried < capacity) {
    const a = (heading + siteBearing) * rad;
    const sx = mem.px + siteDistance * Math.cos(a);
    const sy = mem.py + siteDistance * Math.sin(a);

    if (isFailedSite(sx, sy)) {
      if (mem.siteLock &&
          Math.hypot(sx - mem.siteLock.x, sy - mem.siteLock.y) < 4) {
        mem.siteLock = null;
      }
    } else {
      let st = mem.siteLock;
      if (!st || (!mem.sampling &&
          Math.hypot(sx - st.x, sy - st.y) > 12)) {
        let hintId = null;
        const active = hintById(mem.activeHint);
        if (active && active.state < 2 &&
            Math.hypot(sx - active.x, sy - active.y) < 36) {
          hintId = active.id;
        } else {
          let best = 30;
          for (let i = 0; i < mem.hints.length; i++) {
            const q = mem.hints[i];
            if (q.state >= 2) continue;
            const d = Math.hypot(sx - q.x, sy - q.y);
            if (d < best) {
              best = d;
              hintId = q.id;
            }
          }
        }
        st = {
          x: sx,
          y: sy,
          value: num(site.value, 0),
          hintId: hintId,
          lastSeen: now,
          key: "s" + Math.round(sx / 8) + "_" + Math.round(sy / 8)
        };
        mem.siteLock = st;
      } else {
        const blend = mem.sampling ? 0.12 : 0.36;
        st.x = st.x * (1 - blend) + sx * blend;
        st.y = st.y * (1 - blend) + sy * blend;
        st.value = num(site.value, st.value);
        st.lastSeen = now;
      }
    }
  } else if (mem.siteLock && !mem.sampling &&
             now - num(mem.siteLock.lastSeen, now) > 18) {
    mem.siteLock = null;
  }

  if (docked && carried > 0) {
    mem.returning = false;
    return idle();
  }
  if (docked && carried === 0) {
    mem.returning = false;
  }

  const activeSample = mem.sampling && mem.sampleStart >= 0 &&
    now - mem.sampleStart <= 7.8;
  if (activeSample) {
    const baseD = baseDistanceNow();
    const lockD = mem.siteLock
      ? (siteValid
        ? siteDistance
        : Math.hypot(mem.siteLock.x - mem.px, mem.siteLock.y - mem.py))
      : 0;
    const safeFinish =
      carried < capacity &&
      battery > returnEnergy(baseD, carried) + 0.055 &&
      timeLeft > returnSeconds(baseD) + 8 &&
      (!mem.siteLock || lockD <= 2.1);

    if (safeFinish) {
      mem.returning = false;
      return motor(0, 0, true, true);
    }

    mem.sampling = false;
    mem.sampleStart = -1;
    mem.returning = true;
    if (docked) return idle();
    return returnOutput();
  }

  if (!docked && mem.returning) {
    return returnOutput();
  }

  const lock = mem.siteLock;
  if (lock && carried < capacity) {
    const d = siteValid
      ? siteDistance
      : Math.hypot(lock.x - mem.px, lock.y - mem.py);
    const siteBaseD = Math.hypot(lock.x - mem.baseX, lock.y - mem.baseY);
    const approachEnergy =
      mem.eRate * Math.max(0, d - 1.2) * 2.1;
    const sampleNeed =
      returnEnergy(siteBaseD, carried + 1) + approachEnergy + 0.025;
    const sampleTime =
      24 + 2.05 * (siteBaseD + Math.max(0, d - 1.2));

    if (battery <= sampleNeed || timeLeft <= sampleTime) {
      if (docked) return idle();
      mem.returning = true;
      return returnOutput();
    }

    const key = lock.key || "site";
    if (mem.navKey === key && mem.navFails >= 3 && d > 2.5) {
      addFailedSite(lock, 2);
      mem.siteLock = null;
    } else if (d <= 1.5) {
      const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
      if (speedNow < 0.14) {
        if (!mem.sampling) {
          mem.sampling = true;
          mem.sampleStart = now;
          mem.lastSample = {
            x: lock.x,
            y: lock.y,
            hintId: lock.hintId
          };
        }
        return motor(0, 0, true, true);
      }
      return motor(0, 0, false, true);
    } else if (siteValid) {
      const a = (heading + siteBearing) * rad;
      const tx = mem.px + siteDistance * Math.cos(a);
      const ty = mem.py + siteDistance * Math.sin(a);
      return navigateRel(
        siteBearing,
        siteDistance,
        1.05,
        0.50,
        key,
        tx,
        ty
      );
    } else {
      return navigateAbs(lock.x, lock.y, 1.05, 0.42, key);
    }
  }

  const baseD = baseDistanceNow();
  const retNeed = returnEnergy(baseD, carried);
  const retTime = returnSeconds(baseD);

  if (!docked &&
      (carried >= capacity ||
       battery < retNeed + 0.02 ||
       (carried > 0 && timeLeft < retTime + 8))) {
    mem.returning = true;
    return returnOutput();
  }

  const plan = preparePlan();
  if (!plan) {
    if (carried > 0 && !docked) {
      mem.returning = true;
      return returnOutput();
    }
    return docked ? idle() : motor(0, 0, false, true);
  }

  if (docked) {
    if (timeLeft < plan.eta + 5) return idle();
    const launchTarget = Math.min(
      mem.maxBattery * 0.98,
      Math.max(mem.maxBattery * 0.86, plan.energy + 0.035)
    );
    if (battery + 0.004 < launchTarget) return idle();
  } else {
    if (timeLeft < plan.eta) {
      mem.returning = true;
