                   hy + 9 * Math.sin(a * rad));
        }
        for (let a = 0; a < 360; a += 30) {
          addPoint(hx + 19 * Math.cos(a * rad),
                   hy + 19 * Math.sin(a * rad));
        }

        const visited = [];
        for (let k = 0; k < pts.length; k++) visited.push(false);
        mem.hints.push({
          id: i,
          x: hx,
          y: hy,
          val: Math.max(0.05, num(q.estimate, 1)),
