    mem.activeHint = -1;

    mem.px = rawX0;
    mem.py = rawY0;
    mem.hEst = rawH0;
    mem.compassBias = 0;
    mem.lastRawH = rawH0;
    mem.lastRawX = rawX0;
    mem.lastRawY = rawY0;
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    mem.gpsAnchorX = rawX0;
    mem.gpsAnchorY = rawY0;

    mem.calActive = false;
    mem.calX = rawX0;
    mem.calY = rawY0;
    mem.calT = 0;

    mem.energyRate = 0.0012;
    mem.energyCost = 0;
    mem.energyDist = 0;
    mem.energyReady = false;
    mem.prevBat = battery0;
    mem.prevSolar = Math.max(0, num(obs.solar, 0));
    mem.prevDock = !!obs.docked;
    mem.maxBattery = Math.max(0.1, battery0);
    mem.dockStableAt = 0;
    mem.dockPeak = battery0;

    mem.lastCarried = Math.max(0, num(obs.carried, 0));
    mem.lastDelivered = num(obs.delivered, 0);
    mem.returning = false;

    mem.siteLock = null;
    mem.lastSample = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.failedSites = [];

    mem.rayLast = new Array(9);
    mem.raySame = new Array(9);
    mem.rayStale = new Array(9);
    mem.rayStartX = new Array(9);
    mem.rayStartY = new Array(9);
    mem.rayStartH = new Array(9);
    mem.raysClean = new Array(9);
    for (let i = 0; i < 9; i++) {
      mem.rayLast[i] = null;
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = rawX0;
      mem.rayStartY[i] = rawY0;
      mem.rayStartH[i] = rawH0;
      mem.raysClean[i] = 15;
    }

    mem.gainL = 3;
    mem.gainR = 3;
    mem.iL = 0;
    mem.iR = 0;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;

    mem.navKey = null;
    mem.navFails = 0;
    mem.navCheckAt = 0;
    mem.navPrevDist = 0;
    mem.navX = rawX0;
    mem.navY = rawY0;
    mem.navProgressAt = 0;
    mem.navPrevRel = 0;
    mem.prevSteer = 0;

    mem.recoveryPhase = 0;
    mem.recoveryUntil = 0;
    mem.bumpSide = 1;
    mem.prevBumped = false;

    mem.sciSamples = [];
    mem.sciLastX = null;
    mem.sciLastY = null;
    mem.sciLastT = 0;
    mem.scienceSmooth = null;

    mem.gradRegion = null;
    mem.gradTarget = null;
    mem.gradAttempts = 0;
    mem.gradCooldown = 0;
    mem.gradStartSci = 0;
    mem.gradUntil = 0;

