  mem.lastNow = now;

  const timeLeft = Math.max(
    0,
    num(obs.timeLeft, Math.max(0, mem.missionSecs - now))
  );
  const rawX = num(obs.x, mem.px);
  const rawY = num(obs.y, mem.py);
  const rawHeading = num(obs.heading, mem.hEst);
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const forward = (wl + wr) * 0.5;
  const travel = (Math.abs(wl) + Math.abs(wr)) * 0.5 * dt;
  const battery = Math.max(0, num(obs.battery, mem.prevBat));
  const solar = Math.max(0, num(obs.solar, 0));
  const pitch = num(obs.pitch, 0);
  const carried = Math.max(0, num(obs.carried, mem.lastCarried || 0));
  const drilling = Math.max(0, num(obs.drilling, 0));
  const science = Math.max(0, num(obs.science, 0));
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;
  const capacity = Math.max(
    1,
    num(obs.mission && obs.mission.capacity, mem.capacity || 5)
  );

  const oldH = mem.hEst;
  const yawRate = (wr - wl) / 0.6;
  const yawDeg = yawRate * dt * deg;
  const rawHeadingChange = wrap(rawHeading - mem.lastRawH);
  const rawStep = Math.hypot(rawX - mem.lastRawX, rawY - mem.lastRawY);
  const gpsJump = rawStep > 15;

  const predictedH = wrap(oldH + yawDeg);
  const compassJump =
    Math.abs(wrap(rawHeadingChange - yawDeg)) > 48 &&
    Math.abs(yawDeg) < 25;

