    const solarAvg = clamp((mem.prevSolar + solar) * 0.5, 0, 0.2);
    const grossCost = mem.prevBat - battery + solarAvg * dt;
    mem.energyDist += travel;
    if (grossCost > 0) mem.energyCost += grossCost;
    if (mem.energyDist >= 6) {
