    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    let d = 1e6;
    if (dx > 0.0001) d = Math.min(d, (mem.W - 1.5 - mem.px) / dx);
    else if (dx < -0.0001) d = Math.min(d, (1.5 - mem.px) / dx);
    if (dy > 0.0001) d = Math.min(d, (mem.H - 1.5 - mem.py) / dy);
    else if (dy < -0.0001) d = Math.min(d, (1.5 - mem.py) / dy);
    return Math.max(0, d);
  }

  function clearAt(a) {
    return Math.min(rayAt(a), wallDist(a));
  }

