      Math.min(wallDist(45), wallDist(70));
    const right = rayAt(-45) + rayAt(-70) +
      Math.min(wallDist(-45), wallDist(-70));
    if (left > right + 0.2) return 1;
    if (right > left + 0.2) return -1;
    return mem.bumpSide || 1;
  }

  function wheelOne(target, actual, side, bias) {
    let integral = side === 0 ? num(mem.iL, 0) : num(mem.iR, 0);
    const lastTarget = side === 0
      ? num(mem.lastTL, 0)
      : num(mem.lastTR, 0);
    const lastU = side === 0
      ? num(mem.lastUL, 0)
      : num(mem.lastUR, 0);
    const gain = clamp(
      side === 0 ? num(mem.gainL, 3) : num(mem.gainR, 3),
      0.55,
      8
    );

    if (Math.abs(lastTarget - target) < 0.12 &&
        Math.abs(actual - target) < 0.38 &&
        Math.abs(lastU) > 0.20 &&
        actual * lastU > 0) {
      const apparent = Math.abs(actual) /
        Math.max(0.08, Math.abs(lastU) - 0.085);
      if (apparent > 0.55 && apparent < 8) {
        if (side === 0) {
          mem.gainL = clamp(mem.gainL * 0.98 + apparent * 0.02, 0.55, 8);
        } else {
          mem.gainR = clamp(mem.gainR * 0.98 + apparent * 0.02, 0.55, 8);
        }
      }
    }

    if (target * lastTarget < -0.04) integral *= 0.20;
    const err = target - actual;
    const oldI = integral;
    let nextI;

    if (Math.abs(target) < 0.055) {
      nextI = integral * 0.72;
      const raw = -0.52 * actual + nextI + bias;
      if (side === 0) mem.iL = nextI;
      else mem.iR = nextI;
      return clamp(raw, -0.65, 0.65);
    }

    nextI = clamp(integral + 0.18 * err * dt, -0.34, 0.34);
    const dz = 0.085;
    const feed = target / gain + Math.sign(target) * dz;
    let raw = feed + 0.36 * err + nextI + bias;

    if ((raw > 1 && err > 0) || (raw < -1 && err < 0)) {
      nextI = oldI;
      raw = feed + 0.36 * err + nextI + bias;
    }

    if (Math.abs(target) > 0.16 &&
        Math.abs(actual) < Math.abs(target) * 0.65 &&
        Math.abs(raw) < 0.13) {
      raw = Math.sign(target) * 0.13;
    }

    if (side === 0) mem.iL = nextI;
    else mem.iR = nextI;
    return clamp(raw, -1, 1);
