    v = clamp(v, -1.1, 1.1);
    omega = clamp(omega, -1.25, 1.25);
    const targetL = clamp(v - 0.3 * omega, -2.4, 2.4);
    const targetR = clamp(v + 0.3 * omega, -2.4, 2.4);
    const pitchBias = hold
      ? clamp(0.48 * Math.sin(pitch * rad), -0.25, 0.25)
      : 0;

    const left = wheelOne(targetL, wl, 0, pitchBias);
    const right = wheelOne(targetR, wr, 1, pitchBias);
    mem.lastTL = targetL;
    mem.lastTR = targetR;
    mem.lastUL = left;
    mem.lastUR = right;
    return { left: left, right: right, drill: !!drillFlag };
  }

  function idle() {
    mem.iL *= 0.65;
    mem.iR *= 0.65;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;
    return { left: 0, right: 0, drill: false };
  }

  function startRecovery(side) {
    mem.bumpSide = side || 1;
    mem.recoveryPhase = 1;
    mem.recoveryUntil = now + 0.60;
  }

  function recoveryOutput() {
    if (docked) {
      mem.recoveryPhase = 0;
      return null;
    }
    if (mem.recoveryPhase === 1) {
      if (now < mem.recoveryUntil) {
        return motor(-0.22, 0, false, false);
      }
      mem.recoveryPhase = 2;
      mem.recoveryUntil = now + 0.90;
    }
    if (mem.recoveryPhase === 2) {
      if (now < mem.recoveryUntil) {
        return motor(0, (mem.bumpSide || 1) * 0.62, false, false);
      }
      mem.recoveryPhase = 0;
    }
    return null;
  }

  function noteNav(key, dist, stopRadius, rel) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navFails = 0;
      mem.navCheckAt = now + 7;
      mem.navPrevDist = dist;
      mem.navX = mem.px;
      mem.navY = mem.py;
      mem.navProgressAt = now;
      mem.navPrevRel = Math.abs(rel);
      return;
    }

    if (now >= num(mem.navCheckAt, now)) {
      const moved = Math.hypot(mem.px - mem.navX, mem.py - mem.navY);
      const progress = num(mem.navPrevDist, dist) - dist;
      const turned = num(mem.navPrevRel, Math.abs(rel)) -
        Math.abs(rel) > 10;

      if (progress > 0.65 || moved > 1.0 || turned) {
        mem.navProgressAt = now;
        mem.navFails = 0;
      } else if (dist > stopRadius + 3 &&
                 now - num(mem.navProgressAt, now) > 6 &&
                 Math.abs(num(mem.lastUL, 0)) +
                 Math.abs(num(mem.lastUR, 0)) > 0.22) {
        mem.navFails = Math.min(5, num(mem.navFails, 0) + 1);
        mem.navProgressAt = now;
        if (mem.navFails <= 2 && mem.recoveryPhase === 0) {
          startRecovery(openSide());
        }
      }

      mem.navCheckAt = now + 7;
      mem.navPrevDist = dist;
      mem.navX = mem.px;
      mem.navY = mem.py;
      mem.navPrevRel = Math.abs(rel);
    }
  }

  function navigateRel(goalRel, dist, stopRadius, cruise, key, tx, ty) {
    goalRel = wrap(goalRel);
    dist = Math.max(0, num(dist, 0));
    if (!isFinite(dist) || dist <= stopRadius) {
      return motor(0, 0, false, true);
    }

    if (typeof tx !== "number" || typeof ty !== "number") {
      const a = (heading + goalRel) * rad;
      tx = mem.px + dist * Math.cos(a);
      ty = mem.py + dist * Math.sin(a);
    }
    noteNav(key, dist, stopRadius, goalRel);

    const recovery = recoveryOutput();
    if (recovery) return recovery;

    const actualYaw = clamp((wr - wl) / 0.6, -5, 5);
    if (Math.abs(goalRel) > 118) {
      const omega = clamp(
        1.55 * goalRel * rad - 0.50 * actualYaw,
        -1.0,
        1.0
      );
      return motor(0, omega, false, false);
    }

    let bestA = clamp(goalRel, -80, 80);
    let bestCost = 1e30;
    let bestClear = 15;

    for (let a = -80; a <= 80; a += 10) {
      const diff = Math.abs(wrap(goalRel - a));
      const clear = clearAt(a);
      let cost = 0.012 * diff * diff;

      if (clear < 5) {
        const q = 5 - clear;
        cost += 1.35 * q * q;
      }
      if (clear < 2.3) cost += 12 + (2.3 - clear) * 6;
      if (clear < 1.0) cost += 25;
      if (Math.abs(a) > 68) cost += 0.25;
      cost += 0.001 * Math.abs(a - num(mem.prevSteer, 0));

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestClear = clear;
      }
    }
    mem.prevSteer = bestA;

    let speed = 0;
    if (Math.abs(bestA) < 58) {
      speed = cruise * Math.max(0.25, Math.cos(bestA * rad));
    }

    const remaining = Math.max(0, dist - stopRadius);
    speed = Math.min(speed, Math.sqrt(0.82 * remaining));
    if (bestClear < 5) speed = Math.min(speed, 0.58);
    if (bestClear < 3.5) speed = Math.min(speed, 0.34);
    if (bestClear < 2.4) speed = Math.min(speed, 0.17);
    if (bestClear < 1.2) speed = 0;

    const omega = clamp(
      1.7 * bestA * rad - 0.52 * actualYaw,
      -1.1,
      1.1
    );
    return motor(speed, omega, false, false);
  }

  function navigateAbs(tx, ty, stopRadius, cruise, key) {
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const dist = Math.hypot(dx, dy);
    if (!isFinite(dist) || dist <= stopRadius) {
      return motor(0, 0, false, true);
    }
    const bearing = Math.atan2(dy, dx) * deg;
    return navigateRel(
      wrap(bearing - heading),
      dist,
      stopRadius,
      cruise,
      key,
      tx,
      ty
    );
  }

  function hintById(id) {
    if (id === null || id === undefined || id < 0) return null;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].id === id) return mem.hints[i];
    }
    return null;
  }

  function nearestHintId(x, y) {
    let best = null;
    let bestD = 34;
    const active = hintById(mem.activeHint);
    if (active && active.state < 2 &&
        Math.hypot(x - active.x, y - active.y) < 42) {
      return active.id;
    }
    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.state >= 2) continue;
      const d = Math.hypot(x - h.x, y - h.y);
      if (d < bestD) {
        bestD = d;
        best = h.id;
      }
    }
    return best;
  }

  function markHintSampled(st) {
    if (!st) return;
    let chosen = hintById(st.hintId);
    if (!chosen || chosen.state >= 2 ||
        Math.hypot(st.x - chosen.x, st.y - chosen.y) > 42) {
      chosen = null;
      let bestD = 34;
      for (let i = 0; i < mem.hints.length; i++) {
        const h = mem.hints[i];
        if (h.state >= 2) continue;
        const d = Math.hypot(st.x - h.x, st.y - h.y);
        if (d < bestD) {
          bestD = d;
          chosen = h;
        }
      }
    }
    if (chosen) {
      chosen.state = 2;
      chosen.target = -1;
      if (mem.activeHint === chosen.id) mem.activeHint = -1;
    }
  }

  function isFailedSite(x, y) {
    for (let i = 0; i < mem.failedSites.length; i++) {
      const f = mem.failedSites[i];
      if (f.until > now && Math.hypot(x - f.x, y - f.y) < 5) return true;
    }
    return false;
  }

  function addFailedSite(st) {
    if (!st) return;
    for (let i = 0; i < mem.failedSites.length; i++) {
      const f = mem.failedSites[i];
      if (Math.hypot(st.x - f.x, st.y - f.y) < 4) {
        f.until = now + 150;
        f.count += 1;
        return;
      }
    }
    mem.failedSites.push({
      x: st.x,
      y: st.y,
      count: 1,
      until: now + 150
    });
    if (mem.failedSites.length > 18) mem.failedSites.shift();
  }

  const previousCarried = num(mem.lastCarried, carried);
  if (carried > previousCarried) {
    markHintSampled(mem.lastSample || mem.siteLock);
    mem.siteLock = null;
    mem.lastSample = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.gradTarget = null;
  } else if (carried < previousCarried && docked) {
    mem.siteLock = null;
    mem.lastSample = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.returning = false;
  }
  mem.lastCarried = carried;
  mem.lastDelivered = num(obs.delivered, mem.lastDelivered || 0);

  const site = obs.site && typeof obs.site === "object" ? obs.site : null;
  const siteDistance = site ? num(site.distance, -1) : -1;
  const siteBearing = site ? num(site.bearing, 0) : 0;
  const siteValid = !!site &&
    siteDistance >= 0 &&
    siteDistance <= 8.5 &&
    isFinite(siteBearing);

  if (siteValid && carried < capacity) {
    const a = (heading + siteBearing) * rad;
    const sx = mem.px + siteDistance * Math.cos(a);
    const sy = mem.py + siteDistance * Math.sin(a);

    if (isFailedSite(sx, sy)) {
      if (mem.siteLock &&
          Math.hypot(sx - mem.siteLock.x, sy - mem.siteLock.y) < 6) {
        mem.siteLock = null;
      }
    } else {
      let st = mem.siteLock;
      if (!st || now - num(st.lastSeen, now) > 18 ||
          Math.hypot(sx - st.x, sy - st.y) > 12) {
        st = {
          x: sx,
          y: sy,
          value: num(site.value, 0),
          hintId: nearestHintId(sx, sy),
          lastSeen: now,
          lastDistance: siteDistance
        };
        mem.siteLock = st;
      } else {
        const blend = mem.sampling ? 0.10 : 0.30;
        st.x = st.x * (1 - blend) + sx * blend;
        st.y = st.y * (1 - blend) + sy * blend;
        st.value = num(site.value, st.value);
        st.lastSeen = now;
        st.lastDistance = siteDistance;
        if (st.hintId === null || st.hintId === undefined) {
          st.hintId = nearestHintId(sx, sy);
        }
      }
    }
  } else if (mem.siteLock && !mem.sampling &&
             now - num(mem.siteLock.lastSeen, now) > 20) {
    mem.siteLock = null;
  }

  if (drilling > 0) {
    if (!mem.sampling) {
      mem.sampling = true;
      mem.sampleStart = now - drilling;
    } else if (mem.sampleStart < 0) {
      mem.sampleStart = now - drilling;
    }
    if (!mem.lastSample && mem.siteLock) {
      mem.lastSample = {
        x: mem.siteLock.x,
        y: mem.siteLock.y,
        hintId: mem.siteLock.hintId
      };
    }
  }

  if (mem.activeHint >= 0) {
    const active = hintById(mem.activeHint);
    if (active && active.state < 2 &&
        Math.hypot(mem.px - active.x, mem.py - active.y) < 45) {
      active.maxSci = Math.max(
        num(active.maxSci, 0),
        num(mem.scienceSmooth, science)
      );
    }
  }

  function validBeacon() {
    const b = obs.beacon;
    return !!b &&
      typeof b.distance === "number" &&
      typeof b.bearing === "number" &&
      b.distance >= 0 &&
      b.distance <= 20.5;
  }

  function baseDistanceNow() {
    if (validBeacon()) return Math.max(0, obs.beacon.distance);
    return Math.hypot(mem.baseX - mem.px, mem.baseY - mem.py);
  }

  function returnEnergy(distance, load) {
    distance = Math.max(0, distance);
    load = Math.max(0, load);
    return 0.12 +
      mem.energyRate * (distance + 10) *
      (1 + 0.22 * load) * 1.9 +
      0.018 * load;
  }

  function returnTime(distance, load) {
    return 25 + Math.max(0, distance) * 2.3 + 7 * Math.max(0, load);
  }

  function returnOutput() {
    if (validBeacon()) {
      const d = Math.max(0, obs.beacon.distance);
      if (d <= 2.25) return motor(0, 0, false, true);
      return navigateRel(
        obs.beacon.bearing,
        d,
        2.25,
        0.82,
        "return"
      );
    }

    const dx = mem.baseX - mem.px;
    const dy = mem.baseY - mem.py;
    const d = Math.hypot(dx, dy);
    if (d <= 2.25) return motor(0, 0, false, true);
    return navigateAbs(mem.baseX, mem.baseY, 2.25, 0.82, "return");
  }

  function siteBaseDistance(st, d) {
    const direct = st
      ? Math.hypot(st.x - mem.baseX, st.y - mem.baseY)
      : baseDistanceNow();
    const baseNow = baseDistanceNow();
    const lo = Math.max(0, baseNow - Math.max(0, d) - 2);
    const hi = baseNow + Math.max(0, d) + 2;
    return clamp(direct + 2, lo, Math.max(lo, hi));
  }

  function hintTarget(h) {
    if (!h || h.state >= 2) return null;

    if (mem.activeHint === h.id ||
        Math.hypot(mem.px - h.x, mem.py - h.y) < 45) {
      h.maxSci = Math.max(
        num(h.maxSci, 0),
        num(mem.scienceSmooth, science)
      );
    }

    if (h.target >= 0 && h.target < h.points.length &&
        !h.visited[h.target]) {
      const p0 = h.points[h.target];
      const key0 = "h" + h.id + "_" + h.target;
      const d0 = Math.hypot(p0.x - mem.px, p0.y - mem.py);
      if (d0 <= 1.35 ||
          (mem.navKey === key0 && num(mem.navFails, 0) >= 3)) {
        h.visited[h.target] = true;
        h.target = -1;
        if (mem.navKey === key0) {
          mem.navKey = null;
          mem.navFails = 0;
        }
      }
    }

    let count = 0;
    for (let i = 0; i < h.visited.length; i++) {
      if (h.visited[i]) count++;
    }

    if (count >= h.points.length ||
        (count >= 8 && h.maxSci < 0.000001 && h.val < 2.5)) {
      h.state = 2;
      h.target = -1;
      if (mem.activeHint === h.id) mem.activeHint = -1;
      return null;
    }

    if (h.target < 0 || h.visited[h.target]) {
      if (count === 0 && h.points.length > 0) {
        h.target = 0;
      } else {
        let best = -1;
        let bestD = 1e30;
        for (let i = 0; i < h.points.length; i++) {
          if (h.visited[i]) continue;
          const d = Math.hypot(
            h.points[i].x - mem.px,
            h.points[i].y - mem.py
          );
          if (d < bestD) {
            bestD = d;
            best = i;
          }
        }
        h.target = best;
      }
    }

    if (h.target < 0 || h.target >= h.points.length) {
      h.state = 2;
      return null;
    }
    return h.target;
  }

  function tripEnergy(d1, d2, load, extra) {
    return 0.12 +
      mem.energyRate * (Math.max(0, d1) + Math.max(0, d2) +
        Math.max(0, extra) + 12) *
      (1 + 0.20 * (Math.max(0, load) + 1)) * 1.85 +
      0.025 * (Math.max(0, load) + 1);
  }

  function tripEta(d1, d2, load, extra) {
    return 38 + 2.1 * (Math.max(0, d1) + Math.max(0, d2) +
      Math.max(0, extra)) + 10 * Math.max(0, load);
  }

  function preparePlan() {
    let best = null;
    let bestScore = -1;

    for (let i = 0; i < mem.hints.length; i++) {
      const h = mem.hints[i];
      if (h.state >= 2) continue;

      const idx = hintTarget(h);
      if (idx === null || idx < 0) continue;

      const p = h.points[idx];
      const d1 = Math.hypot(p.x - mem.px, p.y - mem.py);
      const db = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
      const need = tripEnergy(d1, db, carried, 18);
      const eta = tripEta(d1, db, carried, 18);

      if (need > num(mem.maxBattery, battery) * 1.04 ||
          eta + 5 > timeLeft) continue;

      let score = Math.pow(Math.max(0.1, h.val), 1.12) /
        (42 + d1 + 0.52 * db + 2.5 * idx);
      if (mem.activeHint === h.id) score *= 1.30;
      if (h.state === 1) score *= 1.05;

      if (score > bestScore) {
        bestScore = score;
        best = {
          x: p.x,
          y: p.y,
          key: "h" + h.id + "_" + idx,
          need: need,
          eta: eta,
          hint: h,
          hintIndex: idx,
          region: "h" + h.id,
          centerX: h.x,
          centerY: h.y
        };
      }
    }

    if (best) {
      mem.activeHint = best.hint.id;
      best.hint.state = 1;
      return best;
    }

    mem.activeHint = -1;

    if (mem.gridTarget >= 0 &&
        mem.gridTarget < mem.grid.length &&
        !mem.grid[mem.gridTarget].done) {
      const g = mem.grid[mem.gridTarget];
      const d = Math.hypot(g.x - mem.px, g.y - mem.py);
      const key = "g" + mem.gridTarget;
      if (d <= 1.45 ||
          (mem.navKey === key && num(mem.navFails, 0) >= 3)) {
        g.done = true;
        mem.gridTarget = -1;
        if (mem.navKey === key) {
          mem.navKey = null;
          mem.navFails = 0;
        }
      }
    }

    let gridBest = null;
    let gridScore = 1e30;
    let gridIndex = -1;
    for (let i = 0; i < mem.grid.length; i++) {
      const g = mem.grid[i];
      if (g.done) continue;
      const d1 = Math.hypot(g.x - mem.px, g.y - mem.py);
      const db = Math.hypot(g.x - mem.baseX, g.y - mem.baseY);
      const need = tripEnergy(d1, db, carried, 14);
      const eta = tripEta(d1, db, carried, 14);
      if (need > num(mem.maxBattery, battery) * 1.04 ||
          eta + 5 > timeLeft) continue;

      let score = d1 + 0.42 * db;
      if (i === mem.gridTarget) score *= 0.88;
      if (score < gridScore) {
        gridScore = score;
        gridBest = g;
        gridIndex = i;
      }
    }

    if (!gridBest) {
      mem.gridTarget = -1;
      return null;
    }

    mem.gridTarget = gridIndex;
    return {
      x: gridBest.x,
      y: gridBest.y,
      key: "g" + gridIndex,
      need: tripEnergy(
        Math.hypot(gridBest.x - mem.px, gridBest.y - mem.py),
        Math.hypot(gridBest.x - mem.baseX, gridBest.y - mem.baseY),
        carried,
        14
      ),
      eta: tripEta(
        Math.hypot(gridBest.x - mem.px, gridBest.y - mem.py),
        Math.hypot(gridBest.x - mem.baseX, gridBest.y - mem.baseY),
        carried,
        14
      ),
      hint: null,
      hintIndex: -1,
      region: "g" + gridIndex,
      centerX: gridBest.x,
      centerY: gridBest.y
    };
  }

  if (bumped && !mem.prevBumped && !docked) {
    mem.bumpSide = openSide();
    startRecovery(mem.bumpSide);
    mem.sampling = false;
    mem.sampleStart = -1;
  }
  mem.prevBumped = bumped;

  if (!docked) {
    const recovery = recoveryOutput();
    if (recovery) return recovery;
  }

  if (docked && carried > 0) {
    mem.returning = true;
    return idle();
  }
  if (docked && carried === 0) {
    mem.returning = false;
  }

  const baseD = baseDistanceNow();

  if (mem.sampling &&
      mem.sampleStart >= 0 &&
      now - mem.sampleStart > 10.5 &&
      carried === previousCarried) {
    addFailedSite(mem.lastSample || mem.siteLock);
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.lastSample = null;
    mem.siteLock = null;
  }

  const activeDrill = drilling > 0 || mem.sampling;
  if (activeDrill) {
    const st = mem.siteLock;
    const d = siteValid
      ? siteDistance
      : (st ? Math.hypot(st.x - mem.px, st.y - mem.py) : 0);
    const stBaseD = siteBaseDistance(st, d);
    const safe =
      carried < capacity &&
      battery > returnEnergy(stBaseD, carried + 1) + 0.045 &&
      timeLeft > returnTime(stBaseD, carried + 1) + 10;

    if (!safe) {
      mem.sampling = false;
      mem.sampleStart = -1;
      mem.returning = true;
      return returnOutput();
    }

    if ((!st && drilling > 0) || d <= 1.55) {
      const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
      if (speedNow < 0.13) {
        mem.sampling = true;
        if (mem.sampleStart < 0) mem.sampleStart = now;
        if (!mem.lastSample && st) {
          mem.lastSample = { x: st.x, y: st.y, hintId: st.hintId };
        }
        return motor(0, 0, true, true);
      }
      mem.sampling = false;
      mem.sampleStart = -1;
      return motor(0, 0, false, true);
    }

    mem.sampling = false;
    mem.sampleStart = -1;
  }

  if (mem.returning && !docked) {
    return returnOutput();
  }

  if (mem.siteLock && carried < capacity) {
    const st = mem.siteLock;
    const d = siteValid
      ? siteDistance
      : Math.hypot(st.x - mem.px, st.y - mem.py);
    const age = now - num(st.lastSeen, now);
    const stBaseD = siteBaseDistance(st, d);
    const approachCost =
      mem.energyRate * (Math.max(0, d - 1.0) + 4) *
      (1 + 0.20 * carried) * 1.85;
    const sampleNeed =
      returnEnergy(stBaseD, carried + 1) + approachCost + 0.04;
    const sampleTime =
      returnTime(stBaseD, carried + 1) + 2.25 * d + 12;

    if (battery <= sampleNeed || timeLeft <= sampleTime) {
      if (docked) return idle();
      mem.returning = true;
      return returnOutput();
    }

    if (d <= 1.40) {
      const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
      if (speedNow < 0.13) {
        mem.sampling = true;
        mem.sampleStart = now;
        mem.lastSample = { x: st.x, y: st.y, hintId: st.hintId };
        return motor(0, 0, true, true);
      }
      return motor(0, 0, false, true);
    }

    if (siteValid) {
      const a = (heading + siteBearing) * rad;
      const tx = mem.px + siteDistance * Math.cos(a);
      const ty = mem.py + siteDistance * Math.sin(a);
      return navigateRel(
        siteBearing,
        siteDistance,
        1.05,
        0.42,
        "site",
        tx,
        ty
      );
    }

    if (age <= 25) {
      return navigateAbs(st.x, st.y, 1.05, 0.38, "site");
    }
    mem.siteLock = null;
  }

  const retNeed = returnEnergy(baseD, carried);
  const retTime = returnTime(baseD, carried);
  if (!docked &&
      (carried >= capacity ||
       battery < retNeed + 0.055 ||
       timeLeft < retTime + 14)) {
    mem.returning = true;
    return returnOutput();
  }

  const plan = preparePlan();
  if (!plan) {
    if (carried > 0 && !docked) {
      mem.returning = true;
      return returnOutput();
    }
    if (!docked && baseD > 3) {
      mem.returning = true;
      return returnOutput();
    }
    return idle();
  }

  if (docked) {
    if (battery < plan.need + 0.035) return idle();
    if (timeLeft < plan.eta + 4) return idle();
  } else {
    if (battery < plan.need + 0.045) {
      mem.returning = true;
      return returnOutput();
    }
    if (timeLeft < plan.eta) {
      if (carried > 0) {
        mem.returning = true;
        return returnOutput();
      }
      return idle();
    }
  }

  if (mem.gradRegion !== plan.region) {
    mem.gradRegion = plan.region;
    mem.gradTarget = null;
    mem.gradAttempts = 0;
    mem.gradCooldown = now + 2;
  }

  if (mem.gradTarget) {
    const gd = Math.hypot(
      mem.gradTarget.x - mem.px,
      mem.gradTarget.y - mem.py
    );
    if (gd <= 2.5 || now > num(mem.gradUntil, now)) {
      const improvement = mem.scienceSmooth - num(mem.gradStartSci, 0);
      if (improvement > Math.max(0.02, num(mem.gradStartSci, 0) * 0.025)) {
        mem.gradCooldown = now + 2;
      } else {
        mem.gradAttempts = 3;
        mem.gradCooldown = now + 10;
      }
      mem.gradTarget = null;
    }
  }

  function signalGradient() {
    const list = mem.sciSamples || [];
    const pts = [];
    const start = Math.max(0, list.length - 20);
    for (let i = start; i < list.length; i++) {
      const q = list[i];
      if (Math.hypot(q.x - mem.px, q.y - mem.py) <= 52) pts.push(q);
    }
    if (pts.length < 5) return null;

    let mx = 0, my = 0, ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let xx = 0, yy = 0, xy = 0, xs = 0, ys = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      xx += dx * dx;
      yy += dy * dy;
      xy += dx * dy;
      xs += dx * ds;
      ys += dy * ds;
    }

    const det = xx * yy - xy * xy;
    if (det < 55) return null;
    const gx = (xs * yy - ys * xy) / det;
    const gy = (ys * xx - xs * xy) / det;
    const norm = Math.hypot(gx, gy);
    if (!isFinite(norm) || norm < 1e-7) return null;
    return { x: gx, y: gy, n: norm };
  }

  if (!mem.gradTarget &&
      num(mem.gradAttempts, 0) < 3 &&
      now >= num(mem.gradCooldown, 0) &&
      science > 0.00005 &&
      !mem.siteLock) {
    const g = signalGradient();
    if (g &&
        g.n * 9 > Math.max(0.025, mem.scienceSmooth * 0.03)) {
      const tx = clamp(
        mem.px + 9 * g.x / g.n,
        3,
        Math.max(3, mem.W - 3)
      );
      const ty = clamp(
        mem.py + 9 * g.y / g.n,
        3,
        Math.max(3, mem.H - 3)
      );
      const nearRegion = Math.hypot(tx - plan.centerX, ty - plan.centerY);
      if (Math.hypot(tx - mem.px, ty - mem.py) > 4 &&
          (!plan.hint || nearRegion < 44)) {
        mem.gradAttempts = num(mem.gradAttempts, 0) + 1;
        mem.gradTarget = { x: tx, y: ty };
        mem.gradStartSci = mem.scienceSmooth;
        mem.gradUntil = now + 28;
      }
    }
  }

  if (mem.gradTarget) {
    const key = "grad:" + plan.region + ":" +
      num(mem.gradAttempts, 0);
    if (mem.navKey === key && num(mem.navFails, 0) >= 3) {
      mem.gradTarget = null;
      mem.gradAttempts = 3;
      mem.gradCooldown = now + 10;
    } else {
      return navigateAbs(
        mem.gradTarget.x,
        mem.gradTarget.y,
        1.35,
        0.66,
        key
      );
    }
  }

  return navigateAbs(
    plan.x,
    plan.y,
    1.25,
    plan.hint ? 0.82 : 0.80,
    plan.key
  );
}

function act(obs, mem) {
  if (!obs || typeof obs !== "object") obs = {};
  if (!mem || typeof mem !== "object") mem = {};

  const rad = Math.PI / 180;
  const deg = 180 / Math.PI;
  const dt0 = 0.1;

  function num(v, fallback) {
    return typeof v === "number" && isFinite(v) ? v : fallback;
  }
  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }
  function wrap(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }

  const rawX0 = num(obs.x, 200);
  const rawY0 = num(obs.y, 200);
  const rawH0 = num(obs.heading, 0);
  const battery0 = Math.max(0, num(obs.battery, 1));

  if (!mem.initialized) {
    const mission = obs.mission || {};
    let w = 400;
    let h = 400;

    if (typeof mission.size === "number" && mission.size > 0) {
      w = mission.size;
      h = mission.size;
    } else if (mission.size && typeof mission.size === "object") {
      w = num(mission.size.width, num(mission.size.x, 400));
      h = num(mission.size.height, num(mission.size.y, 400));
    }

    mem.W = w;
    mem.H = h;
    mem.missionSecs = num(mission.seconds, 1200);
    mem.capacity = Math.max(1, num(mission.capacity, 5));

    const base = mission.base || {};
    mem.baseX = num(base.x, rawX0);
    mem.baseY = num(base.y, rawY0);

    mem.hints = [];
    if (Array.isArray(mission.hints)) {
      for (let i = 0; i < mission.hints.length; i++) {
        const q = mission.hints[i] || {};
        if (typeof q.x !== "number" || typeof q.y !== "number") continue;

        const hx = clamp(q.x, 3, Math.max(3, w - 3));
        const hy = clamp(q.y, 3, Math.max(3, h - 3));
        const points = [];

        function addHintPoint(x, y) {
          x = clamp(x, 3, Math.max(3, w - 3));
          y = clamp(y, 3, Math.max(3, h - 3));
          for (let j = 0; j < points.length; j++) {
            if (Math.hypot(points[j].x - x, points[j].y - y) < 2) return;
          }
          points.push({ x: x, y: y, done: false });
        }

        addHintPoint(hx, hy);
        for (let a = 0; a < 360; a += 45) {
          addHintPoint(
            hx + 8.5 * Math.cos(a * rad),
            hy + 8.5 * Math.sin(a * rad)
          );
        }
        for (let a = 0; a < 360; a += 45) {
          addHintPoint(
            hx + 18.5 * Math.cos(a * rad),
            hy + 18.5 * Math.sin(a * rad)
          );
        }

        mem.hints.push({
          id: i,
          x: hx,
          y: hy,
          value: Math.max(0.05, num(q.estimate, 1)),
          state: 0,
          maxScience: 0,
          points: points
        });
      }
    }

    mem.grid = [];
    for (let gy = 22; gy <= h - 22; gy += 36) {
      for (let gx = 22; gx <= w - 22; gx += 36) {
        mem.grid.push({ x: gx, y: gy, done: false });
      }
    }
    mem.gridRound = 0;
    mem.current = null;

    mem.px = rawX0;
    mem.py = rawY0;
    mem.heading = rawH0;
    mem.headingBias = 0;
    mem.lastRawH = rawH0;
    mem.lastRawX = rawX0;
    mem.lastRawY = rawY0;

    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    mem.gpsAnchorX = rawX0;
    mem.gpsAnchorY = rawY0;

    mem.calActive = false;
    mem.calX = rawX0;
    mem.calY = rawY0;
    mem.calT = 0;
    mem.calSin = 0;
    mem.calCos = 0;

    mem.energyRate = 0.0010;
    mem.energyCost = 0;
    mem.energyDist = 0;
    mem.energyReady = false;
    mem.prevBat = battery0;
    mem.prevSolar = Math.max(0, num(obs.solar, 0));
    mem.prevDock = !!obs.docked;
    mem.maxBattery = Math.max(0.1, battery0);

    mem.lastCarried = Math.max(0, num(obs.carried, 0));
    mem.lastDelivered = num(obs.delivered, 0);
    mem.returning = false;

    mem.siteLock = null;
    mem.lastSample = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.failedSites = [];

    mem.rayLast = new Array(9);
    mem.raySame = new Array(9);
    mem.rayStale = new Array(9);
    mem.rayStartX = new Array(9);
    mem.rayStartY = new Array(9);
    mem.rayStartH = new Array(9);
    mem.raysClean = new Array(9);
    for (let i = 0; i < 9; i++) {
      mem.rayLast[i] = null;
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = rawX0;
      mem.rayStartY[i] = rawY0;
      mem.rayStartH[i] = rawH0;
      mem.raysClean[i] = 15;
    }

    mem.gainL = 2.0;
    mem.gainR = 2.0;
    mem.iL = 0;
    mem.iR = 0;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;

    mem.navKey = null;
    mem.navFails = 0;
    mem.navCheckAt = 0;
    mem.navPrevDist = 0;
    mem.navX = rawX0;
    mem.navY = rawY0;
    mem.navProgressAt = 0;
    mem.navPrevRel = 0;
    mem.prevSteer = 0;

    mem.recoveryPhase = 0;
    mem.recoveryUntil = 0;
    mem.bumpSide = 1;
    mem.prevBumped = false;

    mem.scienceSmooth = null;
    mem.scienceSamples = [];
    mem.sciLastX = null;
    mem.sciLastY = null;
    mem.sciLastT = 0;

    mem.gradTarget = null;
    mem.gradKey = null;
    mem.gradCount = 0;
    mem.gradCooldown = 0;
    mem.gradStartT = 0;

    mem.tick = 0;
    mem.lastNow = 0;
    mem.initialized = true;
  }

  mem.tick = (mem.tick || 0) + 1;
  const now = Math.max(
    num(obs.t, mem.tick * dt0),
    num(mem.lastNow, 0)
  );
  const dt = clamp(now - num(mem.lastNow, now - dt0), 0.04, 0.25);
  mem.lastNow = now;

  const timeLeft = Math.max(
    0,
    num(obs.timeLeft, Math.max(0, mem.missionSecs - now))
  );
  const rawX = num(obs.x, mem.px);
  const rawY = num(obs.y, mem.py);
  const rawHeading = num(obs.heading, mem.heading);
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const forward = (wl + wr) * 0.5;
  const travel = (Math.abs(wl) + Math.abs(wr)) * 0.5 * dt;
  const battery = Math.max(0, num(obs.battery, mem.prevBat));
  const solar = Math.max(0, num(obs.solar, 0));
  const pitch = num(obs.pitch, 0);
  const carried = Math.max(0, num(obs.carried, mem.lastCarried || 0));
  const drilling = Math.max(0, num(obs.drilling, 0));
  const science = Math.max(0, num(obs.science, 0));
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;
  const capacity = Math.max(
    1,
    num(obs.mission && obs.mission.capacity, mem.capacity || 5)
  );

  const oldHeading = mem.heading;
  const yawRate = (wr - wl) / 0.6;
  const yawDeg = yawRate * dt * deg;
  const rawHeadingChange = wrap(rawHeading - mem.lastRawH);
  const rawStep = Math.hypot(rawX - mem.lastRawX, rawY - mem.lastRawY);
  const gpsJump = rawStep > 15;

  let heading = wrap(oldHeading + yawDeg);
  const compassJump =
    Math.abs(wrap(rawHeadingChange - yawDeg)) > 48 &&
    Math.abs(yawDeg) < 26;

  if (compassJump) {
    mem.headingBias = wrap(oldHeading - rawHeading);
  } else {
    const compassTarget = wrap(rawHeading + mem.headingBias);
    const error = wrap(compassTarget - heading);
    heading = wrap(heading + clamp(error, -28, 28) * 0.42);
  }

  if (!docked && !gpsJump && !mem.gpsFrozen &&
      forward > 0.28 && Math.abs(wr - wl) < 0.22) {
    if (!mem.calActive) {
      mem.calActive = true;
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calT = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
    mem.calT += dt;
    mem.calSin += Math.sin(rawHeading * rad) * dt;
    mem.calCos += Math.cos(rawHeading * rad) * dt;

    const dx = rawX - mem.calX;
    const dy = rawY - mem.calY;
    if (Math.hypot(dx, dy) > 4.5 && mem.calT > 2.5) {
      const course = Math.atan2(dy, dx) * deg;
      const meanRaw = Math.atan2(mem.calSin, mem.calCos) * deg;
      const measuredBias = wrap(course - meanRaw);
      const error = wrap(measuredBias - mem.headingBias);
      mem.headingBias = wrap(
        mem.headingBias + clamp(error, -18, 18) * 0.10
      );
      mem.calActive = false;
      mem.calT = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
  } else {
    mem.calActive = false;
    mem.calT = 0;
    mem.calSin = 0;
    mem.calCos = 0;
  }

  if (!docked && travel > 0.015 && rawStep < 0.035) {
    mem.gpsSameTime += dt;
    mem.gpsMoveWhileSame += travel;
  } else if (rawStep > 0.12) {
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
  }

  if (!mem.gpsFrozen &&
      mem.gpsSameTime > 3.2 &&
      mem.gpsMoveWhileSame > 1.7) {
    mem.gpsFrozen = true;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
  }

  let releasedGPS = false;
  if (mem.gpsFrozen &&
      Math.hypot(rawX - mem.gpsAnchorX, rawY - mem.gpsAnchorY) > 1.5) {
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    releasedGPS = true;
  }

  const midHeading = wrap(
    oldHeading + 0.5 * wrap(heading - oldHeading)
  );
  const predX = mem.px + forward * dt * Math.cos(midHeading * rad);
  const predY = mem.py + forward * dt * Math.sin(midHeading * rad);

  let px = predX;
  let py = predY;
  if (docked) {
    px = mem.baseX;
    py = mem.baseY;
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
  } else if (!mem.gpsFrozen && !gpsJump) {
    let alpha = travel > 0.025 ? 0.38 : 0.22;
    if (releasedGPS) alpha = 0.48;
    if (Math.hypot(rawX - predX, rawY - predY) > 10) alpha = 0.025;
    px = predX + alpha * (rawX - predX);
    py = predY + alpha * (rawY - predY);
  }

  mem.px = clamp(px, -5, mem.W + 5);
  mem.py = clamp(py, -5, mem.H + 5);
  mem.heading = heading;
  mem.lastRawH = rawHeading;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;

  if (mem.energyReady && !docked && !mem.prevDock && travel > 0.01) {
    const solarAvg = clamp((mem.prevSolar + solar) * 0.5, 0, 0.20);
    const grossCost = mem.prevBat - battery + solarAvg * dt;
    mem.energyDist += travel;
    if (grossCost > 0) mem.energyCost += grossCost;

    if (mem.energyDist >= 5) {
      const loadFactor = 1 + 0.18 * Math.max(0, carried);
      const measured = clamp(
        mem.energyCost /
          Math.max(1, mem.energyDist * loadFactor),
        0.00035,
        0.020
      );
      const mix = measured > mem.energyRate ? 0.24 : 0.12;
      mem.energyRate = clamp(
        mem.energyRate * (1 - mix) + measured * mix,
        0.00035,
        0.020
      );
      mem.energyCost = 0;
      mem.energyDist = 0;
    }
  } else if (docked) {
    mem.energyCost = 0;
    mem.energyDist = 0;
  }

  mem.prevBat = battery;
  mem.prevSolar = solar;
  mem.prevDock = docked;
  mem.energyReady = true;
  mem.maxBattery = Math.max(num(mem.maxBattery, battery), battery);

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    const v = clamp(num(rays[i], 15), 0, 15);
    if (mem.rayLast[i] !== null &&
        Math.abs(v - mem.rayLast[i]) < 0.015) {
      mem.raySame[i] += dt;
      const moved = Math.hypot(
        mem.px - mem.rayStartX[i],
        mem.py - mem.rayStartY[i]
      );
      const turned = Math.abs(wrap(heading - mem.rayStartH[i]));
      if (mem.raySame[i] > 6 && (moved > 2.2 || turned > 38)) {
        mem.rayStale[i] = true;
      }
    } else {
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = mem.px;
      mem.rayStartY[i] = mem.py;
      mem.rayStartH[i] = heading;
    }
    mem.rayLast[i] = v;
    mem.raysClean[i] = mem.rayStale[i] ? 15 : v;
  }

  if (mem.scienceSmooth === null || mem.scienceSmooth === undefined) {
    mem.scienceSmooth = science;
  } else {
    mem.scienceSmooth = mem.scienceSmooth * 0.82 + science * 0.18;
  }

  const movedSinceScience = mem.sciLastX === null
    ? 1e9
    : Math.hypot(mem.px - mem.sciLastX, mem.py - mem.sciLastY);
  if (mem.sciLastX === null ||
      (movedSinceScience > 2.6 && now - mem.sciLastT > 1) ||
      now - mem.sciLastT > 22) {
    mem.scienceSamples.push({
      x: mem.px,
      y: mem.py,
      s: mem.scienceSmooth,
      t: now
    });
    if (mem.scienceSamples.length > 30) mem.scienceSamples.shift();
    mem.sciLastX = mem.px;
    mem.sciLastY = mem.py;
    mem.sciLastT = now;
  }

  function validBeacon() {
    const b = obs.beacon;
    return !!b &&
      typeof b.distance === "number" &&
      typeof b.bearing === "number" &&
      isFinite(b.distance) &&
      isFinite(b.bearing) &&
      b.distance >= 0 &&
      b.distance <= 20.5;
  }

  function baseDistanceNow() {
    if (validBeacon()) return Math.max(0, obs.beacon.distance);
    return Math.hypot(mem.baseX - mem.px, mem.baseY - mem.py);
  }

  function returnEnergy(distance, load) {
    distance = Math.max(0, distance);
    load = Math.max(0, load);
    return 0.08 +
      mem.energyRate * (distance + 12) *
        (1 + 0.18 * load) * 1.65 +
      0.02 * load;
  }

  function returnTime(distance, load) {
    return 34 + Math.max(0, distance) * 2.0 + 10 * Math.max(0, load);
  }

  function tripNeed(d1, d2, load) {
    d1 = Math.max(0, d1);
    d2 = Math.max(0, d2);
    load = Math.max(0, load);
    return 0.09 +
      mem.energyRate *
        (d1 * (1 + 0.18 * load) +
         d2 * (1 + 0.18 * (load + 1)) +
         15) * 1.50 +
      0.025 * (load + 1);
  }

  function tripTime(d1, d2, load) {
    return 45 + 2.15 * (Math.max(0, d1) + Math.max(0, d2)) +
      14 * Math.max(0, load);
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    const f = (a + 80) / 20;
    const i = Math.floor(f);
    if (i >= 8) return mem.raysClean[8];
    const q = f - i;
    return mem.raysClean[i] * (1 - q) + mem.raysClean[i + 1] * q;
  }

  function wallDist(a) {
    const ang = (heading + a) * rad;
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    let d = 1e6;
    if (dx > 0.0001) d = Math.min(d, (mem.W - 1.5 - mem.px) / dx);
    else if (dx < -0.0001) d = Math.min(d, (1.5 - mem.px) / dx);
    if (dy > 0.0001) d = Math.min(d, (mem.H - 1.5 - mem.py) / dy);
    else if (dy < -0.0001) d = Math.min(d, (1.5 - mem.py) / dy);
    return Math.max(0, d);
  }

  function clearAt(a) {
    return Math.min(rayAt(a), wallDist(a));
  }

  function openSide() {
    const left = rayAt(45) + rayAt(70) +
      Math.min(wallDist(45), wallDist(70));
    const right = rayAt(-45) + rayAt(-70) +
      Math.min(wallDist(-45), wallDist(-70));
    if (left > right + 0.2) return 1;
    if (right > left + 0.2) return -1;
    return -(mem.bumpSide || 1);
  }

  function wheelOne(target, actual, side, bias) {
    let integral = side === 0 ? num(mem.iL, 0) : num(mem.iR, 0);
    const lastTarget = side === 0
      ? num(mem.lastTL, 0)
      : num(mem.lastTR, 0);
    const lastCommand = side === 0
      ? num(mem.lastUL, 0)
      : num(mem.lastUR, 0);
    const gain = clamp(
      side === 0 ? num(mem.gainL, 2) : num(mem.gainR, 2),
      0.55,
      5
    );

    if (Math.abs(lastTarget - target) < 0.13 &&
        Math.abs(lastCommand) > 0.18 &&
        actual * lastCommand > 0 &&
        Math.abs(actual) < 2.8) {
      const apparent = Math.abs(actual) /
        Math.max(0.12, Math.abs(lastCommand) - 0.065);
      if (apparent > 0.55 && apparent < 5) {
        if (side === 0) {
          mem.gainL = clamp(mem.gainL * 0.98 + apparent * 0.02, 0.55, 5);
        } else {
          mem.gainR = clamp(mem.gainR * 0.98 + apparent * 0.02, 0.55, 5);
        }
      }
    }

    if (target * lastTarget < -0.04) integral *= 0.2;

    if (Math.abs(target) < 0.045) {
      integral *= 0.68;
      const raw = -0.72 * actual + 0.35 * integral + bias;
      if (side === 0) mem.iL = integral;
      else mem.iR = integral;
      return clamp(raw, -0.72, 0.72);
    }

    const err = target - actual;
    const oldIntegral = integral;
    let nextIntegral = clamp(
      integral + 0.16 * err * dt,
      -0.38,
      0.38
    );
    const currentGain = clamp(
      side === 0 ? num(mem.gainL, 2) : num(mem.gainR, 2),
      0.55,
      5
    );
    const feed = target / currentGain + Math.sign(target) * 0.075;
    let raw = feed + 0.34 * err + nextIntegral + bias;

    if ((raw > 1 && err > 0) || (raw < -1 && err < 0)) {
      nextIntegral = oldIntegral;
      raw = feed + 0.34 * err + nextIntegral + bias;
    }

    if (Math.abs(target) > 0.12 &&
        Math.abs(raw) < 0.105 &&
        target * raw >= 0) {
      raw = Math.sign(target) * 0.105;
    }

    if (side === 0) mem.iL = nextIntegral;
    else mem.iR = nextIntegral;
    return clamp(raw, -1, 1);
  }

  function motor(v, omega, drillFlag, hold) {
    v = clamp(v, -1.05, 1.05);
    omega = clamp(omega, -1.45, 1.45);
    const targetL = clamp(v - 0.3 * omega, -1.55, 1.55);
    const targetR = clamp(v + 0.3 * omega, -1.55, 1.55);
    const pitchBias = hold
      ? clamp(0.34 * Math.sin(pitch * rad), -0.22, 0.22)
      : 0;
    const left = wheelOne(targetL, wl, 0, pitchBias);
    const right = wheelOne(targetR, wr, 1, pitchBias);
    mem.lastTL = targetL;
    mem.lastTR = targetR;
    mem.lastUL = left;
    mem.lastUR = right;
    return { left: left, right: right, drill: !!drillFlag };
  }

  function idle() {
    mem.iL *= 0.65;
    mem.iR *= 0.65;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;
    return { left: 0, right: 0, drill: false };
  }

  function startRecovery(side) {
    mem.bumpSide = side || 1;
    mem.recoveryPhase = 1;
    mem.recoveryUntil = now + 0.55;
  }

  function recoveryOutput() {
    if (docked) {
      mem.recoveryPhase = 0;
      return null;
    }
    if (mem.recoveryPhase === 1) {
      if (now < mem.recoveryUntil) {
        return motor(-0.22, 0, false, false);
      }
      mem.recoveryPhase = 2;
      mem.recoveryUntil = now + 0.85;
    }
    if (mem.recoveryPhase === 2) {
      if (now < mem.recoveryUntil) {
        return motor(0, (mem.bumpSide || 1) * 0.78, false, false);
      }
      mem.recoveryPhase = 0;
    }
    return null;
  }

  function noteNav(key, dist, stopRadius, rel) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navFails = 0;
      mem.navCheckAt = now + 6;
      mem.navPrevDist = dist;
      mem.navX = mem.px;
      mem.navY = mem.py;
      mem.navProgressAt = now;
      mem.navPrevRel = Math.abs(rel);
      return;
    }

    if (now >= num(mem.navCheckAt, now)) {
      const moved = Math.hypot(mem.px - mem.navX, mem.py - mem.navY);
      const progress = num(mem.navPrevDist, dist) - dist;
      const turned = num(mem.navPrevRel, Math.abs(rel)) -
        Math.abs(rel) > 11;

      if (progress > 0.55 || moved > 1.25 || turned) {
        mem.navProgressAt = now;
        mem.navFails = 0;
      } else if (dist > stopRadius + 2.5 &&
                 now - num(mem.navProgressAt, now) > 5.5) {
        mem.navFails = Math.min(5, num(mem.navFails, 0) + 1);
        mem.navProgressAt = now;
        if (mem.navFails <= 2 && mem.recoveryPhase === 0) {
          startRecovery(openSide());
        }
      }

      mem.navCheckAt = now + 6;
      mem.navPrevDist = dist;
      mem.navX = mem.px;
      mem.navY = mem.py;
      mem.navPrevRel = Math.abs(rel);
    }
  }

  function navigateRel(goalRel, dist, stopRadius, cruise, key) {
    goalRel = wrap(goalRel);
    dist = Math.max(0, num(dist, 0));
    if (!isFinite(dist) || dist <= stopRadius) {
      return motor(0, 0, false, true);
    }

    noteNav(key, dist, stopRadius, goalRel);
    const recovery = recoveryOutput();
    if (recovery) return recovery;

    const actualYaw = clamp(yawRate, -5, 5);
    if (Math.abs(goalRel) > 118) {
      const omega = clamp(
        1.55 * goalRel * rad - 0.42 * actualYaw,
        -1.25,
        1.25
      );
      return motor(0, omega, false, false);
    }

    let bestA = clamp(goalRel, -80, 80);
    let bestClear = 15;
    let bestCost = 1e30;

    for (let a = -80; a <= 80; a += 10) {
      const difference = Math.abs(wrap(goalRel - a));
      const clear = clearAt(a);
      let cost = 0.012 * difference * difference;

      if (clear < 4.8) {
        const q = 4.8 - clear;
        cost += 1.35 * q * q;
      }
      if (clear < 2.3) cost += 12 + (2.3 - clear) * 7;
      if (clear < 1.0) cost += 24;
      cost += 0.001 * Math.abs(a - num(mem.prevSteer, 0));

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestClear = clear;
      }
    }

    mem.prevSteer = bestA;

    let speed = 0;
    if (Math.abs(bestA) <= 58) {
      speed = cruise * Math.max(0.25, Math.cos(bestA * rad));
    }

    const remaining = Math.max(0, dist - stopRadius);
    speed = Math.min(speed, Math.sqrt(0.9 * remaining));
    if (bestClear < 5) speed = Math.min(speed, 0.55);
    if (bestClear < 3.5) speed = Math.min(speed, 0.32);
    if (bestClear < 2.4) speed = Math.min(speed, 0.16);
    if (bestClear < 1.2) speed = 0;

    const omega = clamp(
      1.55 * bestA * rad - 0.42 * actualYaw,
      -1.3,
      1.3
    );
    return motor(speed, omega, false, false);
  }

  function navigateAbs(tx, ty, stopRadius, cruise, key) {
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const dist = Math.hypot(dx, dy);
    if (!isFinite(dist) || dist <= stopRadius) {
      return motor(0, 0, false, true);
    }
    const bearing = Math.atan2(dy, dx) * deg;
    return navigateRel(
      wrap(bearing - heading),
      dist,
      stopRadius,
      cruise,
      key
    );
  }

  function returnOutput() {
    if (validBeacon()) {
      const d = Math.max(0, obs.beacon.distance);
      if (d <= 2.25) return motor(0, 0, false, true);
      return navigateRel(
        obs.beacon.bearing,
        d,
        2.25,
        0.78,
        "return"
      );
    }

    const dx = mem.baseX - mem.px;
    const dy = mem.baseY - mem.py;
    const d = Math.hypot(dx, dy);
    if (d <= 2.25) return motor(0, 0, false, true);
    return navigateAbs(mem.baseX, mem.baseY, 2.25, 0.78, "return");
  }

  function hintById(id) {
    if (id === null || id === undefined || id < 0) return null;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].id === id) return mem.hints[i];
    }
    return null;
  }

  function nearestHintId(x, y) {
    let best = null;
    let bestDist = 34;
    for (let i = 0; i < mem.hints.length; i++) {
      const h0 = mem.hints[i];
      if (h0.state >= 2) continue;
      const d = Math.hypot(x - h0.x, y - h0.y);
      if (d < bestDist) {
        bestDist = d;
        best = h0.id;
      }
    }
    return best;
  }

  function markHintSampled(st) {
    if (!st) return;
    let chosen = hintById(st.hintId);
    if (!chosen || chosen.state >= 2 ||
        Math.hypot(st.x - chosen.x, st.y - chosen.y) > 42) {
      chosen = null;
      let bestDist = 36;
      for (let i = 0; i < mem.hints.length; i++) {
        const h0 = mem.hints[i];
        if (h0.state >= 2) continue;
        const d = Math.hypot(st.x - h0.x, st.y - h0.y);
        if (d < bestDist) {
          bestDist = d;
          chosen = h0;
        }
      }
    }

    if (chosen) {
      chosen.state = 2;
      for (let j = 0; j < chosen.points.length; j++) {
        chosen.points[j].done = true;
      }
      if (mem.current && mem.current.type === "hint" &&
          mem.current.hid === chosen.id) {
        mem.current = null;
      }
    }

    for (let i = 0; i < mem.grid.length; i++) {
      if (Math.hypot(st.x - mem.grid[i].x, st.y - mem.grid[i].y) < 13) {
        mem.grid[i].done = true;
      }
    }
  }

  function isFailedSite(x, y) {
    for (let i = mem.failedSites.length - 1; i >= 0; i--) {
      const f = mem.failedSites[i];
      if (f.until <= now) {
        mem.failedSites.splice(i, 1);
      } else if (Math.hypot(x - f.x, y - f.y) < 4.5) {
        return true;
      }
    }
    return false;
  }

  function addFailedSite(st) {
    if (!st) return;
    for (let i = 0; i < mem.failedSites.length; i++) {
      const f = mem.failedSites[i];
      if (Math.hypot(st.x - f.x, st.y - f.y) < 4) {
        f.until = now + 140;
        f.count = (f.count || 0) + 1;
        return;
      }
    }
    mem.failedSites.push({
      x: st.x,
      y: st.y,
      count: 1,
      until: now + 140
    });
    if (mem.failedSites.length > 18) mem.failedSites.shift();
  }

  function clearFailedSite(st) {
    if (!st) return;
    for (let i = mem.failedSites.length - 1; i >= 0; i--) {
      if (Math.hypot(st.x - mem.failedSites[i].x,
                     st.y - mem.failedSites[i].y) < 5) {
        mem.failedSites.splice(i, 1);
      }
    }
  }

  function markPointDone(c) {
    if (!c) return;
    if (c.type === "hint") {
      const h0 = hintById(c.hid);
      if (h0 && c.idx >= 0 && c.idx < h0.points.length) {
        h0.points[c.idx].done = true;
      }
    } else if (c.type === "grid" &&
               c.idx >= 0 && c.idx < mem.grid.length) {
      mem.grid[c.idx].done = true;
    }
  }

  function updateCurrent() {
    const c = mem.current;
    if (!c) return;

    if (c.type === "hint") {
      const h0 = hintById(c.hid);
      if (!h0 || h0.state >= 2 ||
          c.idx < 0 || c.idx >= h0.points.length ||
          h0.points[c.idx].done) {
        mem.current = null;
        return;
      }
    } else if (c.type === "grid" &&
               (c.idx < 0 || c.idx >= mem.grid.length ||
                mem.grid[c.idx].done)) {
      mem.current = null;
      return;
    }

    const d = Math.hypot(c.x - mem.px, c.y - mem.py);
    const timedOut =
      now - num(c.started, now) >
      Math.max(105, 3.2 * num(c.startDist, d) + 75);
    const navFailed =
      mem.navKey === c.key && num(mem.navFails, 0) >= 4;

    if (d <= 3.3 || timedOut || navFailed) {
      markPointDone(c);
      mem.current = null;
      if (mem.navKey === c.key) {
        mem.navKey = null;
        mem.navFails = 0;
      }
    }
  }

  function chooseTarget() {
    let best = null;
    let bestScore = -1;

    for (let i = 0; i < mem.hints.length; i++) {
      const h0 = mem.hints[i];
      if (h0.state >= 2) continue;

      if (Math.hypot(mem.px - h0.x, mem.py - h0.y) < 48) {
        h0.maxScience = Math.max(
          num(h0.maxScience, 0),
          num(mem.scienceSmooth, science)
        );
      }

      let doneCount = 0;
      for (let j = 0; j < h0.points.length; j++) {
        if (h0.points[j].done) doneCount++;
      }

      if (doneCount >= h0.points.length ||
          (doneCount >= 9 && h0.maxScience < 0.00001)) {
        h0.state = 2;
        for (let j = 0; j < h0.points.length; j++) {
          h0.points[j].done = true;
        }
        continue;
      }

      for (let j = 0; j < h0.points.length; j++) {
        const p = h0.points[j];
        if (p.done) continue;

        const d1 = Math.hypot(p.x - mem.px, p.y - mem.py);
        if (d1 <= 3.3) {
          p.done = true;
          continue;
        }

        const d2 = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
        const need = tripNeed(d1, d2, carried);
        const eta = tripTime(d1, d2, carried);
        if (need > mem.maxBattery * 1.08 || eta + 12 > timeLeft) continue;

        let score = Math.pow(Math.max(0.1, h0.value), 0.88) /
          (38 + d1 + 0.68 * d2);
        if (h0.maxScience > 0) score *= 1.08;

        if (score > bestScore) {
          bestScore = score;
          best = {
            x: p.x,
            y: p.y,
            key: "h" + h0.id + "_" + j,
            type: "hint",
            hid: h0.id,
            idx: j,
            started: now,
            startDist: d1
          };
        }
      }
    }

    if (best) return best;

    for (let round = 0; round < 2; round++) {
      let gridBest = null;
      let gridScore = -1;

      for (let i = 0; i < mem.grid.length; i++) {
        const g = mem.grid[i];
        if (g.done) continue;

        const d1 = Math.hypot(g.x - mem.px, g.y - mem.py);
        if (d1 <= 3.3) {
          g.done = true;
          continue;
        }

        const d2 = Math.hypot(g.x - mem.baseX, g.y - mem.baseY);
        const need = tripNeed(d1, d2, carried);
        const eta = tripTime(d1, d2, carried);
        if (need > mem.maxBattery * 1.08 || eta + 12 > timeLeft) continue;

        const score = 0.15 / (48 + d1 + 0.72 * d2);
        if (score > gridScore) {
          gridScore = score;
          gridBest = {
            x: g.x,
            y: g.y,
            key: "g" + i,
            type: "grid",
            hid: -1,
            idx: i,
            started: now,
            startDist: d1
          };
        }
      }

      if (gridBest) return gridBest;
      if (round === 0) {
        let any = false;
        for (let i = 0; i < mem.grid.length; i++) {
          if (!mem.grid[i].done) {
            any = true;
            break;
          }
        }
        if (any) break;
        for (let i = 0; i < mem.grid.length; i++) {
          mem.grid[i].done = false;
        }
        mem.gridRound++;
      }
    }

    return null;
  }

  function scienceGradient() {
    const list = mem.scienceSamples || [];
    const pts = [];
    const start = Math.max(0, list.length - 22);
    for (let i = start; i < list.length; i++) {
      const q = list[i];
      if (Math.hypot(q.x - mem.px, q.y - mem.py) <= 52) pts.push(q);
    }
    if (pts.length < 5) return null;

    let mx = 0, my = 0, ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let xx = 0, yy = 0, xy = 0, xs = 0, ys = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      xx += dx * dx;
      yy += dy * dy;
      xy += dx * dy;
      xs += dx * ds;
      ys += dy * ds;
    }

    const det = xx * yy - xy * xy;
    if (det < 45) return null;

    const gx = (xs * yy - ys * xy) / det;
    const gy = (ys * xx - xs * xy) / det;
    const norm = Math.hypot(gx, gy);
    if (!isFinite(norm) || norm < 1e-7) return null;
    return { x: gx, y: gy, n: norm };
  }

  const previousCarried = num(mem.lastCarried, carried);
  let sampleSucceeded = false;

  if (carried > previousCarried) {
    sampleSucceeded = true;
    markHintSampled(mem.lastSample || mem.siteLock);
    clearFailedSite(mem.lastSample || mem.siteLock);
    mem.siteLock = null;
    mem.lastSample = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.gradTarget = null;
  } else if (carried < previousCarried && docked) {
    mem.siteLock = null;
    mem.lastSample = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.returning = false;
  }

  mem.lastCarried = carried;
  mem.lastDelivered = num(obs.delivered, mem.lastDelivered || 0);

  const site = obs.site && typeof obs.site === "object" ? obs.site : null;
  const siteDistance = site ? num(site.distance, -1) : -1;
  const siteBearing = site ? num(site.bearing, 0) : 0;
  const siteValid = !!site &&
    siteDistance >= 0 &&
    siteDistance <= 8.5 &&
    isFinite(siteBearing);

  if (siteValid && carried < capacity && !sampleSucceeded) {
    const a = (heading + siteBearing) * rad;
    const sx = mem.px + siteDistance * Math.cos(a);
    const sy = mem.py + siteDistance * Math.sin(a);

    if (isFailedSite(sx, sy)) {
      if (mem.siteLock &&
          Math.hypot(sx - mem.siteLock.x, sy - mem.siteLock.y) < 5) {
        mem.siteLock = null;
      }
    } else if (!mem.sampling) {
      let st = mem.siteLock;
      if (!st || now - num(st.lastSeen, now) > 18 ||
          Math.hypot(sx - st.x, sy - st.y) > 11) {
        st = {
          x: sx,
          y: sy,
          value: num(site.value, 0),
          hintId: nearestHintId(sx, sy),
          lastSeen: now,
          key: "s" + Math.round(sx / 6) + "_" + Math.round(sy / 6)
        };
        mem.siteLock = st;
      } else {
        st.x = st.x * 0.72 + sx * 0.28;
        st.y = st.y * 0.72 + sy * 0.28;
        st.value = num(site.value, st.value);
        st.lastSeen = now;
        if (st.hintId === null || st.hintId === undefined) {
          st.hintId = nearestHintId(sx, sy);
        }
      }
    }
  } else if (mem.siteLock && !mem.sampling &&
             now - num(mem.siteLock.lastSeen, now) > 18) {
    mem.siteLock = null;
  }

  if (drilling > 0) {
    if (!mem.sampling) {
      mem.sampling = true;
      mem.sampleStart = now - drilling;
    } else if (mem.sampleStart < 0) {
      mem.sampleStart = now - drilling;
    }
    if (!mem.lastSample && mem.siteLock) {
      mem.lastSample = {
        x: mem.siteLock.x,
        y: mem.siteLock.y,
        hintId: mem.siteLock.hintId
      };
    }
  }

  if (mem.sampling && mem.sampleStart >= 0 &&
      now - mem.sampleStart > 10.5 &&
      carried === previousCarried) {
    addFailedSite(mem.lastSample || mem.siteLock);
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.lastSample = null;
    mem.siteLock = null;
  }

  if (bumped && !mem.prevBumped && !docked) {
    if (mem.sampling) {
      addFailedSite(mem.lastSample || mem.siteLock);
      mem.sampling = false;
      mem.sampleStart = -1;
      mem.lastSample = null;
      mem.siteLock = null;
    }
    startRecovery(openSide());
  }
  mem.prevBumped = bumped;

  const recovery = recoveryOutput();
  if (recovery) return recovery;

  if (docked && carried > 0) {
    mem.returning = true;
    return idle();
  }
  if (docked && carried === 0) {
    mem.returning = false;
  }

  const baseD = baseDistanceNow();
  const retNeed = returnEnergy(baseD, carried);
  const retTime = returnTime(baseD, carried);

  if (!docked && !mem.returning) {
    if (carried >= capacity ||
        (carried > 0 &&
         (battery < retNeed + 0.085 || timeLeft < retTime + 20)) ||
        (carried === 0 && baseD > 4 &&
         battery < retNeed + 0.10)) {
      mem.returning = true;
    }
  }

  if (!docked && mem.returning) {
    return returnOutput();
  }

  if (mem.sampling) {
    const safe =
      carried < capacity &&
      battery > returnEnergy(baseD, carried + 1) + 0.025 &&
      timeLeft > returnTime(baseD, carried + 1) + 8;

    if (!safe) {
      mem.sampling = false;
      mem.sampleStart = -1;
      mem.returning = true;
      if (docked) return idle();
      return returnOutput();
    }

    return motor(0, 0, true, true);
  }

  if (mem.siteLock && carried < capacity) {
    const lock = mem.siteLock;
    const age = now - num(lock.lastSeen, now);
    const d = siteValid
      ? siteDistance
      : Math.hypot(lock.x - mem.px, lock.y - mem.py);

    if (!siteValid && age > 18) {
      mem.siteLock = null;
    } else {
      const directBaseD = Math.hypot(lock.x - mem.baseX, lock.y - mem.baseY);
      const lo = Math.max(0, baseD - Math.max(0, d) - 3);
      const hi = baseD + Math.max(0, d) + 3;
      const siteBaseD = clamp(directBaseD, lo, hi);
      const approachEnergy =
        mem.energyRate * Math.max(0, d - 1.15) *
        (1 + 0.18 * carried) * 1.6;
      const safe =
        battery >
          returnEnergy(siteBaseD, carried + 1) + approachEnergy + 0.055 &&
        timeLeft >
          returnTime(siteBaseD, carried + 1) +
          Math.max(0, d - 1.15) / 0.38 + 15;

      if (!safe) {
        if (docked) return idle();
        mem.returning = true;
        return returnOutput();
      }

      if (d <= 1.32) {
        const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
        if (speedNow < 0.13) {
          mem.sampling = true;
          mem.sampleStart = now;
          mem.lastSample = {
            x: lock.x,
            y: lock.y,
            hintId: lock.hintId
          };
          return motor(0, 0, true, true);
        }
        return motor(0, 0, false, true);
      }

      if (siteValid) {
        return navigateRel(
          siteBearing,
          siteDistance,
          1.05,
          0.38,
          lock.key || "site"
        );
      }

      return navigateAbs(lock.x, lock.y, 1.05, 0.34, lock.key || "site");
    }
  }

  updateCurrent();

  if (!mem.current) {
    mem.current = chooseTarget();
    if (mem.current) {
      mem.navKey = null;
      mem.navFails = 0;
      mem.gradTarget = null;
      mem.gradKey = mem.current.key;
      mem.gradCount = 0;
      mem.gradCooldown = now + 2;
    }
  }

  if (!mem.current) {
    if (carried > 0) {
      mem.returning = true;
      return returnOutput();
    }
    if (!docked && baseD > 4 &&
        battery < returnEnergy(baseD, 0) + 0.12) {
      mem.returning = true;
      return returnOutput();
    }
    return docked ? idle() : motor(0, 0, false, true);
  }

  const current = mem.current;
  const currentDist = Math.hypot(current.x - mem.px, current.y - mem.py);
  const currentBaseDist = Math.hypot(
    current.x - mem.baseX,
    current.y - mem.baseY
  );
  const need = tripNeed(currentDist, currentBaseDist, carried);
  const eta = tripTime(currentDist, currentBaseDist, carried);

  if (need > mem.maxBattery * 1.10) {
    markPointDone(current);
    mem.current = null;
    mem.navKey = null;
    if (carried > 0 || (!docked && battery < retNeed + 0.12)) {
      mem.returning = true;
      return docked ? idle() : returnOutput();
    }
    return docked ? idle() : motor(0, 0, false, true);
  }

  if (docked) {
    if (battery < need + 0.035 || timeLeft < eta + 12) return idle();
  } else {
    if (battery < need + 0.065) {
      mem.returning = true;
      return returnOutput();
    }
    if (timeLeft < eta + 8) {
      if (carried > 0) {
        mem.returning = true;
        return returnOutput();
      }
      return motor(0, 0, false, true);
    }
  }

  if (mem.gradKey !== current.key) {
    mem.gradKey = current.key;
    mem.gradCount = 0;
    mem.gradTarget = null;
    mem.gradCooldown = now + 2;
  }

  if (mem.gradTarget) {
    const gd = Math.hypot(
      mem.gradTarget.x - mem.px,
      mem.gradTarget.y - mem.py
    );
    const gradKey = "grad:" + current.key + ":" + mem.gradCount;
    if (gd <= 2.5 || now > num(mem.gradStartT, now) + 25 ||
        (mem.navKey === gradKey && num(mem.navFails, 0) >= 3)) {
      mem.gradTarget = null;
      mem.gradCooldown = now + 12;
    }
  }

  if (!mem.gradTarget &&
      mem.gradCount < 2 &&
      now >= num(mem.gradCooldown, 0) &&
      science > 0.00005 &&
      !mem.siteLock) {
    const g = scienceGradient();
    if (g &&
        g.n * 9 > Math.max(0.0008, mem.scienceSmooth * 0.018)) {
      const tx = clamp(
        mem.px + 9 * g.x / g.n,
        3,
        Math.max(3, mem.W - 3)
      );
      const ty = clamp(
        mem.py + 9 * g.y / g.n,
        3,
        Math.max(3, mem.H - 3)
      );

      let inRegion = true;
      if (current.type === "hint") {
        const h0 = hintById(current.hid);
        if (h0) inRegion = Math.hypot(tx - h0.x, ty - h0.y) < 38;
      } else {
        inRegion = Math.hypot(tx - current.x, ty - current.y) < 42;
      }

      if (inRegion && Math.hypot(tx - mem.px, ty - mem.py) > 4) {
        mem.gradCount++;
        mem.gradTarget = { x: tx, y: ty };
        mem.gradStartT = now;
      }
    }
  }

  if (mem.gradTarget) {
    const key = "grad:" + current.key + ":" + mem.gradCount;
    return navigateAbs(
      mem.gradTarget.x,
      mem.gradTarget.y,
      1.4,
      0.55,
      key
    );
  }

  return navigateAbs(
    current.x,
    current.y,
    1.35,
    0.82,
    current.key
  );
}

function act(obs, mem) {
  if (!obs || typeof obs !== "object") obs = {};
  if (!mem || typeof mem !== "object") mem = {};

  const rad = Math.PI / 180;
  const deg = 180 / Math.PI;

  function num(v, fallback) {
    return typeof v === "number" && isFinite(v) ? v : fallback;
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function wrap(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }

  function rebuildGrid(round) {
    mem.grid = [];
    const offset = round % 2 === 0 ? 24 : 48;
    const step = 48;
    for (let y = offset; y <= mem.H - 20; y += step) {
      for (let x = offset; x <= mem.W - 20; x += step) {
        mem.grid.push({ x: x, y: y, done: false });
      }
    }
  }

  const rawX0 = num(obs.x, 200);
  const rawY0 = num(obs.y, 200);
  const rawH0 = num(obs.heading, 0);
  const battery0 = Math.max(0, num(obs.battery, 1));

  if (!mem.initialized) {
    const mission = obs.mission || {};
    let w = 400;
    let h = 400;

    if (typeof mission.size === "number" && mission.size > 0) {
      w = mission.size;
      h = mission.size;
    } else if (mission.size && typeof mission.size === "object") {
      w = num(mission.size.width, num(mission.size.x, 400));
      h = num(mission.size.height, num(mission.size.y, 400));
    }

    mem.W = w;
    mem.H = h;
    mem.missionSecs = num(mission.seconds, 1200);
    mem.capacity = Math.max(1, num(mission.capacity, 5));

    const base = mission.base || {};
    mem.baseX = num(base.x, rawX0);
    mem.baseY = num(base.y, rawY0);

    mem.hints = [];
    if (Array.isArray(mission.hints)) {
      for (let i = 0; i < mission.hints.length; i++) {
        const q = mission.hints[i] || {};
        if (typeof q.x !== "number" || typeof q.y !== "number") continue;

        const hx = clamp(q.x, 3, Math.max(3, w - 3));
        const hy = clamp(q.y, 3, Math.max(3, h - 3));
        const points = [];

        function addPoint(x, y) {
          x = clamp(x, 3, Math.max(3, w - 3));
          y = clamp(y, 3, Math.max(3, h - 3));
          for (let j = 0; j < points.length; j++) {
            if (Math.hypot(points[j].x - x, points[j].y - y) < 2) return;
          }
          points.push({ x: x, y: y, done: false });
        }

        addPoint(hx, hy);
        addPoint(hx + 18, hy);
        addPoint(hx, hy + 18);
        addPoint(hx - 18, hy);
        addPoint(hx, hy - 18);

        mem.hints.push({
          id: i,
          x: hx,
          y: hy,
          value: Math.max(0.05, num(q.estimate, 1)),
          maxScience: 0,
          state: 0,
          points: points
        });
      }
    }

    mem.gridRound = 0;
    rebuildGrid(0);
    mem.target = null;
    mem.activeHint = -1;

    mem.px = rawX0;
    mem.py = rawY0;
    mem.heading = rawH0;
    mem.compassBias = 0;
    mem.ignoreCompassUntil = 0;
    mem.lastRawHeading = rawH0;
    mem.lastRawX = rawX0;
    mem.lastRawY = rawY0;

    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    mem.gpsAnchorX = rawX0;
    mem.gpsAnchorY = rawY0;

    mem.calActive = false;
    mem.calX = rawX0;
    mem.calY = rawY0;
    mem.calT = 0;
    mem.calSin = 0;
    mem.calCos = 0;

    mem.energyRate = 0.0013;
    mem.energyCost = 0;
    mem.energyDistance = 0;
    mem.energyReady = false;
    mem.prevBattery = battery0;
    mem.prevSolar = Math.max(0, num(obs.solar, 0));
    mem.prevDock = !!obs.docked;

    mem.lastCarried = Math.max(0, num(obs.carried, 0));
    mem.returning = false;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.sampleSite = null;
    mem.lastSiteObs = null;
    mem.failedSites = [];

    mem.rayLast = new Array(9);
    mem.raySame = new Array(9);
    mem.rayStale = new Array(9);
    mem.rayStartX = new Array(9);
    mem.rayStartY = new Array(9);
    mem.rayStartH = new Array(9);
    mem.raysClean = new Array(9);
    for (let i = 0; i < 9; i++) {
      mem.rayLast[i] = null;
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = rawX0;
      mem.rayStartY[i] = rawY0;
      mem.rayStartH[i] = rawH0;
      mem.raysClean[i] = 15;
    }

    mem.gainL = 2.8;
    mem.gainR = 2.8;
    mem.iL = 0;
    mem.iR = 0;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;

    mem.navKey = null;
    mem.navFails = 0;
    mem.navCheckAt = 0;
    mem.navPrevDist = 0;
    mem.navX = rawX0;
    mem.navY = rawY0;
    mem.navH = rawH0;
    mem.navProgressAt = 0;
    mem.bumpSide = 1;
    mem.recoveryPhase = 0;
    mem.recoveryUntil = 0;
    mem.prevBumped = false;

    mem.scienceSmooth = null;
    mem.scienceSamples = [];
    mem.sciLastX = null;
    mem.sciLastY = null;
    mem.sciLastT = 0;

    mem.gradTarget = null;
    mem.gradStartSci = 0;
    mem.gradUntil = 0;
    mem.gradCooldown = 0;
    mem.gradCount = 0;

    mem.tick = 0;
    mem.lastNow = 0;
    mem.initialized = true;
  }

  mem.tick = (mem.tick || 0) + 1;
  const now = Math.max(
    num(obs.t, mem.tick * 0.1),
    num(mem.lastNow, 0)
  );
  const rawDt = now - num(mem.lastNow, 0);
  const dt = clamp(rawDt > 0.0001 ? rawDt : 0.1, 0.05, 0.2);
  mem.lastNow = now;

  const timeLeft = Math.max(
    0,
    num(obs.timeLeft, Math.max(0, mem.missionSecs - now))
  );
  const rawX = num(obs.x, mem.px);
  const rawY = num(obs.y, mem.py);
  const rawHeading = num(obs.heading, mem.heading);
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const forward = 0.5 * (wl + wr);
  const wheelMotion = 0.5 * (Math.abs(wl) + Math.abs(wr)) * dt;
  const battery = Math.max(0, num(obs.battery, mem.prevBattery));
  const solar = Math.max(0, num(obs.solar, 0));
  const pitch = num(obs.pitch, 0);
  const carried = Math.max(0, num(obs.carried, mem.lastCarried || 0));
  const drilling = Math.max(0, num(obs.drilling, 0));
  const science = Math.max(0, num(obs.science, 0));
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;
  const capacity = Math.max(
    1,
    num(obs.mission && obs.mission.capacity, mem.capacity || 5)
  );

  const oldHeading = mem.heading;
  const yawRate = (wr - wl) / 0.6;
  const yawDeg = yawRate * dt * deg;
  const rawHChange = wrap(rawHeading - mem.lastRawHeading);
  const rawStep = Math.hypot(rawX - mem.lastRawX, rawY - mem.lastRawY);
  const gpsJump = rawStep > 18;
  const predictedHeading = wrap(oldHeading + yawDeg);
  const compassJump =
    Math.abs(wrap(rawHChange - yawDeg)) > 50 &&
    Math.abs(yawDeg) < 30;

  let heading = predictedHeading;
  if (compassJump) {
    mem.compassBias = wrap(predictedHeading - rawHeading);
    mem.ignoreCompassUntil = now + 1.5;
  } else if (now >= num(mem.ignoreCompassUntil, 0)) {
    const compassTarget = wrap(rawHeading + num(mem.compassBias, 0));
    const herr = wrap(compassTarget - predictedHeading);
    if (Math.abs(herr) < 65) {
      heading = wrap(predictedHeading + clamp(herr, -14, 14) * 0.15);
    }
  }

  if (!docked && !gpsJump && !mem.gpsFrozen &&
      forward > 0.25 && Math.abs(wr - wl) < 0.14) {
    if (!mem.calActive) {
      mem.calActive = true;
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calT = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
    mem.calT += dt;
    mem.calSin += Math.sin(rawHeading * rad) * dt;
    mem.calCos += Math.cos(rawHeading * rad) * dt;

    const cdx = rawX - mem.calX;
    const cdy = rawY - mem.calY;
    if (Math.hypot(cdx, cdy) > 4.5 && mem.calT > 3) {
      const course = Math.atan2(cdy, cdx) * deg;
      const meanRaw = Math.atan2(mem.calSin, mem.calCos) * deg;
      const measuredBias = wrap(course - meanRaw);
      const biasError = wrap(measuredBias - mem.compassBias);
      mem.compassBias = wrap(
        mem.compassBias + clamp(biasError, -24, 24) * 0.24
      );
      heading = wrap(
        heading + clamp(wrap(course - heading), -8, 8) * 0.06
      );
      mem.calActive = false;
      mem.calT = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
  } else {
    mem.calActive = false;
    mem.calT = 0;
    mem.calSin = 0;
    mem.calCos = 0;
  }

  if (!docked && wheelMotion > 0.015 && rawStep < 0.03) {
    mem.gpsSameTime += dt;
    mem.gpsMoveWhileSame += wheelMotion;
  } else if (rawStep > 0.12) {
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
  }

  if (!mem.gpsFrozen &&
      mem.gpsSameTime > 3.2 &&
      mem.gpsMoveWhileSame > 1.7) {
    mem.gpsFrozen = true;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
  }

  let releasedGPS = false;
  if (mem.gpsFrozen &&
      Math.hypot(rawX - mem.gpsAnchorX, rawY - mem.gpsAnchorY) > 2.2) {
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    releasedGPS = true;
  }

  const midHeading = wrap(
    oldHeading + 0.5 * wrap(heading - oldHeading)
  );
  const predX = mem.px + forward * dt * Math.cos(midHeading * rad);
  const predY = mem.py + forward * dt * Math.sin(midHeading * rad);

  let px = predX;
  let py = predY;
  if (docked) {
    px = mem.baseX;
    py = mem.baseY;
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
  } else if (!mem.gpsFrozen && !gpsJump) {
    let alpha = wheelMotion > 0.025 ? 0.25 : 0.09;
    if (releasedGPS) alpha = 0.42;
    if (Math.hypot(rawX - predX, rawY - predY) > 10) alpha = 0.025;
    px = predX + alpha * (rawX - predX);
    py = predY + alpha * (rawY - predY);
  }

  mem.px = clamp(px, -5, mem.W + 5);
  mem.py = clamp(py, -5, mem.H + 5);
  mem.heading = heading;
  mem.lastRawHeading = rawHeading;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;

  if (mem.energyReady && !docked && !mem.prevDock && wheelMotion > 0.01) {
    const solarAvg = clamp((mem.prevSolar + solar) * 0.5, 0, 0.2);
    const gross = clamp(
      mem.prevBattery - battery + solarAvg * dt * 0.12,
      0,
      0.03
    );
    mem.energyDistance += wheelMotion;
    mem.energyCost += gross;

    if (mem.energyDistance >= 8) {
      const measured = clamp(
        mem.energyCost /
          Math.max(2, mem.energyDistance * (1 + 0.14 * carried)),
        0.00035,
        0.004
      );
      const mix = measured > mem.energyRate ? 0.20 : 0.07;
      mem.energyRate = clamp(
        mem.energyRate * (1 - mix) + measured * mix,
        0.00035,
        0.004
      );
      mem.energyDistance = 0;
      mem.energyCost = 0;
    }
  } else if (docked) {
    mem.energyDistance = 0;
    mem.energyCost = 0;
  }

  mem.prevBattery = battery;
  mem.prevSolar = solar;
  mem.prevDock = docked;
  mem.energyReady = true;

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    const v = clamp(num(rays[i], 15), 0, 15);
    if (mem.rayLast[i] !== null &&
        Math.abs(v - mem.rayLast[i]) < 0.015) {
      mem.raySame[i] += dt;
      const moved = Math.hypot(
        mem.px - mem.rayStartX[i],
        mem.py - mem.rayStartY[i]
      );
      const turned = Math.abs(wrap(heading - mem.rayStartH[i]));
      if (mem.raySame[i] > 6 && (moved > 2 || turned > 35)) {
        mem.rayStale[i] = true;
      }
    } else {
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = mem.px;
      mem.rayStartY[i] = mem.py;
      mem.rayStartH[i] = heading;
    }
    mem.rayLast[i] = v;
    mem.raysClean[i] = mem.rayStale[i] ? 15 : v;
  }

  if (mem.scienceSmooth === null || mem.scienceSmooth === undefined) {
    mem.scienceSmooth = science;
  } else {
    mem.scienceSmooth = mem.scienceSmooth * 0.78 + science * 0.22;
  }

  const movedSinceScience = mem.sciLastX === null
    ? 1e9
    : Math.hypot(mem.px - mem.sciLastX, mem.py - mem.sciLastY);
  if (!docked &&
      (mem.sciLastX === null ||
       (movedSinceScience > 2.5 && now - mem.sciLastT > 1.2))) {
    mem.scienceSamples.push({
      x: mem.px,
      y: mem.py,
      s: mem.scienceSmooth,
      t: now
    });
    if (mem.scienceSamples.length > 26) mem.scienceSamples.shift();
    mem.sciLastX = mem.px;
    mem.sciLastY = mem.py;
    mem.sciLastT = now;
  }

  function validBeacon() {
    const b = obs.beacon;
    return !!b &&
      typeof b.distance === "number" &&
      typeof b.bearing === "number" &&
      isFinite(b.distance) &&
      isFinite(b.bearing) &&
      b.distance >= 0 &&
      b.distance <= 20.5;
  }

  function baseDistanceNow() {
    if (validBeacon()) return Math.max(0, obs.beacon.distance);
    return Math.hypot(mem.baseX - mem.px, mem.baseY - mem.py);
  }

  function returnEnergy(distance, load) {
    distance = Math.max(0, distance);
    load = Math.max(0, load);
    return 0.08 +
      mem.energyRate * (distance + 12) *
        (1 + 0.16 * load) * 1.45 +
      0.018 * load;
  }

  function returnTime(distance, load) {
    return 18 + Math.max(0, distance) * 1.8 + 8 * Math.max(0, load);
  }

  function tripNeed(d1, d2, load) {
    d1 = Math.max(0, d1);
    d2 = Math.max(0, d2);
    load = Math.max(0, load);
    return 0.10 +
      mem.energyRate *
        ((d1 + 10) * (1 + 0.14 * load) +
         (d2 + 14) * (1 + 0.18 * (load + 1))) * 1.30 +
      0.02 * (load + 1);
  }

  function tripTime(d1, d2, load) {
    return 45 +
      1.9 * (Math.max(0, d1) + Math.max(0, d2)) +
      10 * Math.max(0, load);
  }

  function nearestHintId(x, y) {
    let best = -1;
    let bestD = 1e30;

    if (mem.activeHint >= 0) {
      for (let i = 0; i < mem.hints.length; i++) {
        const h0 = mem.hints[i];
        if (h0.id === mem.activeHint) {
          const d = Math.hypot(x - h0.x, y - h0.y);
          if (d < 34) return h0.id;
        }
      }
    }

    for (let i = 0; i < mem.hints.length; i++) {
      const h0 = mem.hints[i];
      const d = Math.hypot(x - h0.x, y - h0.y);
      if (d < bestD) {
        bestD = d;
        best = h0.id;
      }
    }
    return bestD < 38 ? best : -1;
  }

  function siteBaseDistance(s) {
    if (!s) return baseDistanceNow();
    const baseD = baseDistanceNow();
    const siteD = Math.max(0, num(s.distance, 0));
    const direct = Math.hypot(s.x - mem.baseX, s.y - mem.baseY);
    const lo = Math.max(0, baseD - siteD - 1);
    const hi = baseD + siteD + 2;
    return clamp(direct + 1.5, lo, Math.max(lo, hi));
  }

  function isFailedSite(s) {
    if (!s) return false;
    for (let i = mem.failedSites.length - 1; i >= 0; i--) {
      const f = mem.failedSites[i];
      if (f.until <= now) {
        mem.failedSites.splice(i, 1);
      } else if (Math.hypot(s.x - f.x, s.y - f.y) < 4.5) {
        return true;
      }
    }
    return false;
  }

  function addFailedSite(s) {
    if (!s) return;
    for (let i = 0; i < mem.failedSites.length; i++) {
      const f = mem.failedSites[i];
      if (Math.hypot(s.x - f.x, s.y - f.y) < 4) {
        f.until = now + 120;
        f.count = (f.count || 0) + 1;
        return;
      }
    }
    mem.failedSites.push({
      x: s.x,
      y: s.y,
      until: now + 120,
      count: 1
    });
    if (mem.failedSites.length > 16) mem.failedSites.shift();
  }

  function clearFailedSite(s) {
    if (!s) return;
    for (let i = mem.failedSites.length - 1; i >= 0; i--) {
      if (Math.hypot(s.x - mem.failedSites[i].x,
                     s.y - mem.failedSites[i].y) < 5) {
        mem.failedSites.splice(i, 1);
      }
    }
  }

  function markTargetDone(t) {
    if (!t) return;

    if (t.type === "hint") {
      for (let i = 0; i < mem.hints.length; i++) {
        const h0 = mem.hints[i];
        if (h0.id === t.hid &&
            t.idx >= 0 && t.idx < h0.points.length) {
          h0.points[t.idx].done = true;
          let all = true;
          for (let j = 0; j < h0.points.length; j++) {
            if (!h0.points[j].done) {
              all = false;
              break;
            }
          }
          if (all) {
            h0.state = 2;
            if (mem.activeHint === h0.id) mem.activeHint = -1;
          }
          break;
        }
      }
    } else if (t.type === "grid" &&
               t.round === mem.gridRound &&
               t.idx >= 0 && t.idx < mem.grid.length) {
      mem.grid[t.idx].done = true;
    }

    mem.target = null;
    mem.navKey = null;
    mem.navFails = 0;
  }

  function markSampled(s) {
    let chosen = -1;
    if (s && typeof s.hintId === "number" && s.hintId >= 0) {
      chosen = s.hintId;
    } else if (s) {
      chosen = nearestHintId(s.x, s.y);
    } else if (mem.activeHint >= 0) {
      chosen = mem.activeHint;
    }

    let chosenHint = null;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].id === chosen) {
        chosenHint = mem.hints[i];
        break;
      }
    }

    if (chosenHint) {
      chosenHint.state = 2;
      for (let j = 0; j < chosenHint.points.length; j++) {
        chosenHint.points[j].done = true;
      }

      for (let i = 0; i < mem.hints.length; i++) {
        const h0 = mem.hints[i];
        if (h0.id !== chosen &&
            Math.hypot(h0.x - chosenHint.x, h0.y - chosenHint.y) < 8) {
          h0.state = 2;
          for (let j = 0; j < h0.points.length; j++) {
            h0.points[j].done = true;
          }
        }
      }
      if (mem.activeHint === chosen) mem.activeHint = -1;
    }

    if (s) {
      for (let i = 0; i < mem.grid.length; i++) {
        if (Math.hypot(s.x - mem.grid[i].x, s.y - mem.grid[i].y) < 14) {
          mem.grid[i].done = true;
        }
      }
      if (mem.target && mem.target.type === "grid" &&
          Math.hypot(s.x - mem.target.x, s.y - mem.target.y) < 14) {
        markTargetDone(mem.target);
      }
    }

    if (mem.target && mem.target.type === "hint" &&
        (mem.target.hid === chosen || (chosenHint && chosenHint.state >= 2))) {
      mem.target = null;
      mem.navKey = null;
      mem.navFails = 0;
    }
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    const f = (a + 80) / 20;
    const i = Math.floor(f);
    if (i >= 8) return mem.raysClean[8];
    const q = f - i;
    return mem.raysClean[i] * (1 - q) + mem.raysClean[i + 1] * q;
  }

  function wallDist(a) {
    const ang = (heading + a) * rad;
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    let d = 1e6;

    if (dx > 0.0001) d = Math.min(d, (mem.W - 2.5 - mem.px) / dx);
    else if (dx < -0.0001) d = Math.min(d, (2.5 - mem.px) / dx);

    if (dy > 0.0001) d = Math.min(d, (mem.H - 2.5 - mem.py) / dy);
    else if (dy < -0.0001) d = Math.min(d, (2.5 - mem.py) / dy);

    return Math.max(0, d);
  }

  function clearAt(a) {
    return Math.min(rayAt(a), wallDist(a));
  }

  function openSide() {
    const left = rayAt(40) + rayAt(70) +
      Math.min(wallDist(40), wallDist(70));
    const right = rayAt(-40) + rayAt(-70) +
      Math.min(wallDist(-40), wallDist(-70));
    if (left > right + 0.2) return 1;
    if (right > left + 0.2) return -1;
    return mem.bumpSide || 1;
  }

  function wheelOne(target, actual, side, bias) {
    let integral = side === 0 ? num(mem.iL, 0) : num(mem.iR, 0);
    const lastTarget = side === 0 ? num(mem.lastTL, 0) : num(mem.lastTR, 0);
    const lastCommand = side === 0 ? num(mem.lastUL, 0) : num(mem.lastUR, 0);
    let gain = clamp(
      side === 0 ? num(mem.gainL, 2.8) : num(mem.gainR, 2.8),
      0.55,
      5.5
    );

    if (Math.abs(target) > 0.12 &&
        Math.abs(lastTarget - target) < 0.16 &&
        Math.abs(lastCommand) > 0.16 &&
        actual * lastCommand > 0 &&
        Math.abs(actual) < 2.8) {
      const apparent = Math.abs(actual) /
        Math.max(0.10, Math.abs(lastCommand) - 0.06);
      if (apparent > 0.45 && apparent < 6) {
        gain = clamp(gain * 0.94 + apparent * 0.06, 0.55, 5.5);
        if (side === 0) mem.gainL = gain;
        else mem.gainR = gain;
      }
    }

    if (target * lastTarget < -0.04) integral *= 0.2;

    if (Math.abs(target) < 0.05) {
      integral *= 0.70;
      const raw = -0.75 * actual + bias;
      if (side === 0) mem.iL = integral;
      else mem.iR = integral;
      return clamp(raw, -0.65, 0.65);
    }

    const error = target - actual;
    const oldIntegral = integral;
    let nextIntegral = clamp(integral + 0.18 * error * dt, -0.30, 0.30);
    const feed = target / gain + Math.sign(target) * 0.06;
    let raw = feed + 0.17 * error + nextIntegral + bias;

    if ((raw > 1 && error > 0) || (raw < -1 && error < 0)) {
      nextIntegral = oldIntegral;
      raw = feed + 0.17 * error + nextIntegral + bias;
    }

    if (Math.abs(target) > 0.14 &&
        Math.abs(raw) < 0.09 &&
        target * raw >= 0) {
      raw = Math.sign(target) * 0.09;
    }

    if (side === 0) mem.iL = nextIntegral;
    else mem.iR = nextIntegral;
    return clamp(raw, -1, 1);
  }

  function motor(v, omega, drillFlag, hold) {
    v = clamp(v, -0.75, 0.75);
    omega = clamp(omega, -0.82, 0.82);
    const targetL = clamp(v - 0.3 * omega, -1.05, 1.05);
    const targetR = clamp(v + 0.3 * omega, -1.05, 1.05);
    const pitchBias = hold
      ? clamp(0.20 * Math.sin(pitch * rad), -0.12, 0.12)
      : 0;

    const left = wheelOne(targetL, wl, 0, pitchBias);
    const right = wheelOne(targetR, wr, 1, pitchBias);

    mem.lastTL = targetL;
    mem.lastTR = targetR;
    mem.lastUL = left;
    mem.lastUR = right;

    return { left: left, right: right, drill: !!drillFlag };
  }

  function idle() {
    mem.iL *= 0.65;
    mem.iR *= 0.65;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;
    return { left: 0, right: 0, drill: false };
  }

  function startRecovery(side) {
    mem.bumpSide = side || 1;
    mem.recoveryPhase = 1;
    mem.recoveryUntil = now + 0.55;
  }

  function recoveryOutput() {
    if (docked) {
      mem.recoveryPhase = 0;
      return null;
    }

    if (mem.recoveryPhase === 1) {
      if (now < mem.recoveryUntil) {
        return motor(-0.22, 0, false, false);
      }
      mem.recoveryPhase = 2;
      mem.recoveryUntil = now + 0.82;
    }

    if (mem.recoveryPhase === 2) {
      if (now < mem.recoveryUntil) {
        return motor(0, (mem.bumpSide || 1) * 0.62, false, false);
      }
      mem.recoveryPhase = 0;
    }

    return null;
  }

  function noteNav(key, dist) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navFails = 0;
      mem.navCheckAt = now + 5;
      mem.navPrevDist = dist;
      mem.navX = mem.px;
      mem.navY = mem.py;
      mem.navH = heading;
      mem.navProgressAt = now;
      return;
    }

    if (now >= num(mem.navCheckAt, now)) {
      const moved = Math.hypot(mem.px - mem.navX, mem.py - mem.navY);
      const progress = num(mem.navPrevDist, dist) - dist;
      const turned = Math.abs(wrap(heading - num(mem.navH, heading))) > 35;

      if (progress > 0.4 || moved > 1.4 || turned) {
        mem.navProgressAt = now;
        mem.navFails = 0;
      } else if (now - num(mem.navProgressAt, now) > 8.5) {
        mem.navFails = Math.min(6, num(mem.navFails, 0) + 1);
        mem.navProgressAt = now;
        if ((mem.navFails <= 3 || key === "return" || key === "site") &&
            mem.recoveryPhase === 0) {
          startRecovery(openSide());
        }
      }

      mem.navCheckAt = now + 5;
      mem.navPrevDist = dist;
      mem.navX = mem.px;
      mem.navY = mem.py;
      mem.navH = heading;
    }
  }

  function navigateRel(goalRel, dist, stopRadius, cruise, key) {
    goalRel = wrap(goalRel);
    dist = Math.max(0, num(dist, 0));

    if (!isFinite(dist) || dist <= stopRadius) {
      return motor(0, 0, false, true);
    }

    noteNav(key, dist);
    const recovery = recoveryOutput();
    if (recovery) return recovery;

    const actualYaw = clamp(yawRate, -5, 5);
    if (Math.abs(goalRel) > 108) {
      const omega = clamp(
        1.35 * goalRel * rad - 0.48 * actualYaw,
        -0.78,
        0.78
      );
      return motor(0, omega, false, false);
    }

    let bestA = clamp(goalRel, -80, 80);
    let bestClear = 15;
    let bestCost = 1e30;

    for (let a = -80; a <= 80; a += 10) {
      const diff = Math.abs(wrap(goalRel - a));
      const clear = clearAt(a);
      let cost = 0.00115 * diff * diff;

      if (clear < 4) {
        const q = 4 - clear;
        cost += 0.22 * q * q;
      }
      if (clear < 2.8) cost += 10 + (2.8 - clear) * 6;
      if (clear < 1.2) cost += 25;
      cost += 0.0008 * Math.abs(a - num(mem.prevSteer, 0));

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestClear = clear;
      }
    }

    mem.prevSteer = bestA;

    let speed = 0;
    if (Math.abs(bestA) <= 60) {
      speed = cruise * Math.max(0.25, Math.cos(bestA * rad));
    }

    const remaining = Math.max(0, dist - stopRadius);
    speed = Math.min(speed, Math.sqrt(0.65 * remaining));
    if (bestClear < 5) speed = Math.min(speed, 0.46);
    if (bestClear < 3.5) speed = Math.min(speed, 0.28);
    if (bestClear < 2.4) speed = Math.min(speed, 0.12);
    if (bestClear < 1.2) speed = 0;

    const omega = clamp(
      1.35 * bestA * rad - 0.48 * actualYaw,
      -0.78,
      0.78
    );
    return motor(speed, omega, false, false);
  }

  function navigateAbs(tx, ty, stopRadius, cruise, key) {
    const dx = tx - mem.px;
    const dy = ty - mem.py;
    const dist = Math.hypot(dx, dy);
    if (!isFinite(dist) || dist <= stopRadius) {
      return motor(0, 0, false, true);
    }
    const bearing = Math.atan2(dy, dx) * deg;
    return navigateRel(
      wrap(bearing - heading),
      dist,
      stopRadius,
      cruise,
      key
    );
  }

  function returnOutput() {
    if (validBeacon()) {
      const d = Math.max(0, obs.beacon.distance);
      if (d <= 2.05) return motor(0, 0, false, true);
      return navigateRel(
        obs.beacon.bearing,
        d,
        2.05,
        0.48,
        "return"
      );
    }

    const d = Math.hypot(mem.baseX - mem.px, mem.baseY - mem.py);
    if (d <= 2.05) return motor(0, 0, false, true);
    return navigateAbs(mem.baseX, mem.baseY, 2.05, 0.48, "return");
  }

  function refreshHints() {
    for (let i = 0; i < mem.hints.length; i++) {
      const h0 = mem.hints[i];
      if (h0.state >= 2) continue;

      let all = true;
      for (let j = 0; j < h0.points.length; j++) {
        if (!h0.points[j].done) {
          all = false;
          break;
        }
      }

      if (all) {
        h0.state = 2;
        if (mem.activeHint === h0.id) mem.activeHint = -1;
      }
    }
  }

  function chooseTarget() {
    refreshHints();

    let best = null;
    let bestScore = -1;

    for (let i = 0; i < mem.hints.length; i++) {
      const h0 = mem.hints[i];
      if (h0.state >= 2) continue;

      if (Math.hypot(mem.px - h0.x, mem.py - h0.y) < 46) {
        h0.maxScience = Math.max(
          num(h0.maxScience, 0),
          num(mem.scienceSmooth, science)
        );
      }

      for (let j = 0; j < h0.points.length; j++) {
        const p = h0.points[j];
        if (p.done) continue;

        const d1 = Math.hypot(p.x - mem.px, p.y - mem.py);
        if (d1 <= 3) {
          p.done = true;
          continue;
        }

        const d2 = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
        const need = tripNeed(d1 + 8, d2 + 8, carried);
        const eta = tripTime(d1 + 8, d2 + 8, carried);
        if (need > battery - 0.02 || eta + 5 > timeLeft) continue;

        let score = Math.pow(Math.max(0.1, h0.value), 0.9) /
          (35 + d1 + 0.55 * d2);
        if (mem.activeHint === h0.id) score *= 1.45;
        if (h0.maxScience > 0.02) score *= 1.12;

        if (score > bestScore) {
          bestScore = score;
          best = {
            x: p.x,
            y: p.y,
            key: "h" + h0.id + "_" + j,
            type: "hint",
            hid: h0.id,
            idx: j
          };
        }
      }
    }

    if (best) {
      const h0 = mem.hints[best.hid];
      if (h0) h0.state = 1;
      mem.activeHint = best.hid;
      return best;
    }

    for (let round = 0; round < 2; round++) {
      let allDone = true;
      for (let i = 0; i < mem.grid.length; i++) {
        if (!mem.grid[i].done) {
          allDone = false;
          break;
        }
      }

      if (allDone) {
        mem.gridRound++;
        rebuildGrid(mem.gridRound);
      }

      let gridBest = null;
      let gridScore = 1e30;

      for (let i = 0; i < mem.grid.length; i++) {
        const g = mem.grid[i];
        if (g.done) continue;

        const d1 = Math.hypot(g.x - mem.px, g.y - mem.py);
        if (d1 <= 3) {
          g.done = true;
          continue;
        }

        const d2 = Math.hypot(g.x - mem.baseX, g.y - mem.baseY);
        const need = tripNeed(d1 + 8, d2 + 8, carried);
        const eta = tripTime(d1 + 8, d2 + 8, carried);
        if (need > battery - 0.02 || eta + 5 > timeLeft) continue;

        const score = d1 + 0.48 * d2;
        if (score < gridScore) {
          gridScore = score;
          gridBest = {
            x: g.x,
            y: g.y,
            key: "g" + mem.gridRound + "_" + i,
            type: "grid",
            idx: i,
            round: mem.gridRound
          };
        }
      }

      if (gridBest) return gridBest;
      if (round === 0) {
        let any = false;
        for (let i = 0; i < mem.grid.length; i++) {
          if (!mem.grid[i].done) {
            any = true;
            break;
          }
        }
        if (any) break;
        mem.gridRound++;
        rebuildGrid(mem.gridRound);
      }
    }

    return null;
  }

  function scienceGradient() {
    const list = mem.scienceSamples || [];
    const pts = [];
    const start = Math.max(0, list.length - 22);

    for (let i = start; i < list.length; i++) {
      const q = list[i];
      if (now - q.t < 130 &&
          Math.hypot(q.x - mem.px, q.y - mem.py) < 48) {
        pts.push(q);
      }
    }
    if (pts.length < 5) return null;

    let mx = 0, my = 0, ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let xx = 0, yy = 0, xy = 0, xs = 0, ys = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      xx += dx * dx;
      yy += dy * dy;
      xy += dx * dy;
      xs += dx * ds;
      ys += dy * ds;
    }

    const det = xx * yy - xy * xy;
    if (det < 45) return null;

    const gx = (xs * yy - ys * xy) / det;
    const gy = (ys * xx - xs * xy) / det;
    const norm = Math.hypot(gx, gy);
    if (!isFinite(norm) || norm < 1e-7) return null;
    return { x: gx, y: gy, n: norm };
  }

  const site = obs.site && typeof obs.site === "object" ? obs.site : null;
  const siteDistance = site ? num(site.distance, -1) : -1;
  const siteBearing = site ? num(site.bearing, 0) : 0;
  const siteValid = !!site &&
    siteDistance >= 0 &&
    siteDistance <= 8.5 &&
    isFinite(siteBearing);

  let siteObs = null;
  let siteUsable = false;
  if (siteValid) {
    const a = (heading + siteBearing) * rad;
    const sx = mem.px + siteDistance * Math.cos(a);
    const sy = mem.py + siteDistance * Math.sin(a);
    siteObs = {
      x: sx,
      y: sy,
      distance: siteDistance,
      bearing: siteBearing,
      value: num(site.value, 0),
      hintId: nearestHintId(sx, sy),
      lastSeen: now
    };
    siteObs.baseD = siteBaseDistance(siteObs);
    siteUsable = carried < capacity && !isFailedSite(siteObs);
    if (siteUsable) mem.lastSiteObs = siteObs;
  }

  const previousCarried = num(mem.lastCarried, carried);
  let sampleSucceeded = false;

  if (carried > previousCarried) {
    sampleSucceeded = true;
    const sampled = mem.sampleSite || mem.lastSiteObs || siteObs;
    markSampled(sampled);
    clearFailedSite(sampled);
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.sampleSite = null;
    mem.lastSiteObs = null;
    mem.gradTarget = null;
    siteUsable = false;
  } else if (carried < previousCarried && docked) {
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.sampleSite = null;
    mem.lastSiteObs = null;
    mem.returning = false;
  }

  mem.lastCarried = carried;

  if (drilling > 0 && !sampleSucceeded && !mem.sampling) {
    const recentSite = siteUsable
      ? siteObs
      : (mem.lastSiteObs && now - mem.lastSiteObs.lastSeen < 15
          ? mem.lastSiteObs
          : null);
    if (recentSite) {
      mem.sampling = true;
      mem.sampleStart = Math.max(0, now - drilling);
      mem.sampleSite = recentSite;
    }
  } else if (drilling > 0 && mem.sampling && mem.sampleStart < 0) {
    mem.sampleStart = Math.max(0, now - drilling);
  }

  if (mem.sampling &&
      mem.sampleStart >= 0 &&
      now - mem.sampleStart > 12 &&
      carried === previousCarried) {
    addFailedSite(mem.sampleSite || mem.lastSiteObs);
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.sampleSite = null;
    mem.lastSiteObs = null;
    if (siteObs && isFailedSite(siteObs)) siteUsable = false;
  }

  if (bumped && !mem.prevBumped && !docked) {
    if (mem.sampling) {
      addFailedSite(mem.sampleSite || mem.lastSiteObs);
      mem.sampling = false;
      mem.sampleStart = -1;
      mem.sampleSite = null;
      if (siteObs && isFailedSite(siteObs)) siteUsable = false;
    }
    mem.bumpSide = openSide();
    startRecovery(mem.bumpSide);
  }
  mem.prevBumped = bumped;

  if (docked) mem.recoveryPhase = 0;
  if (!docked && mem.recoveryPhase > 0) {
    const recovery = recoveryOutput();
    if (recovery) return recovery;
  }

  if (docked && carried > 0) {
    mem.returning = true;
    return idle();
  }
  if (docked && carried === 0) {
    mem.returning = false;
    mem.navKey = null;
    mem.navFails = 0;
  }

  if (mem.returning && !docked) return returnOutput();

  if (mem.sampling) {
    const ss = mem.sampleSite || mem.lastSiteObs || siteObs;
    const sampleBaseD = ss ? num(ss.baseD, baseDistanceNow()) : baseDistanceNow();
    const sampleReturn = returnEnergy(sampleBaseD, carried + 1);
    const sameSite = siteObs && (!ss ||
      Math.hypot(siteObs.x - ss.x, siteObs.y - ss.y) < 5);

    if (battery <= sampleReturn + 0.035 ||
        timeLeft <= returnTime(sampleBaseD, carried + 1) + 6) {
      mem.sampling = false;
      mem.sampleStart = -1;
      mem.returning = true;
      if (docked) return idle();
      return returnOutput();
    }

    if (sameSite && siteDistance > 1.9) {
      mem.sampling = false;
      mem.sampleStart = -1;
      mem.sampleSite = siteObs;
    } else {
      const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
      return motor(0, 0, speedNow < 0.14, true);
    }
  }

  const baseD = baseDistanceNow();
  const retNeed = returnEnergy(baseD, carried);
  const retEta = returnTime(baseD, carried);

  if (!docked && baseD > 3 &&
      (carried >= capacity ||
       battery <= retNeed + (carried > 0 ? 0.16 : 0.11) ||
       (carried > 0 && timeLeft <= retEta + 9))) {
    mem.returning = true;
    return returnOutput();
  }

  if (siteUsable && carried < capacity) {
    const approach = Math.max(0, siteDistance - 1.25);
    const need =
      returnEnergy(siteObs.baseD, carried + 1) +
      mem.energyRate * (approach + 5) *
        (1 + 0.15 * carried) * 1.25 +
      0.10;
    const eta =
      returnTime(siteObs.baseD, carried + 1) +
      approach / 0.42 + 18;

    if (battery <= need || timeLeft <= eta) {
      if (docked) return idle();
      mem.returning = true;
      return returnOutput();
    }

    if (siteDistance <= 1.45) {
      const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
      if (speedNow < 0.14) {
        mem.sampling = true;
        mem.sampleStart = now;
        mem.sampleSite = siteObs;
        return motor(0, 0, true, true);
      }
      return motor(0, 0, false, true);
    }

    return navigateRel(
      siteBearing,
      siteDistance,
      1.12,
      0.30,
      "site"
    );
  }

  if (mem.target) {
    let invalid = false;
    if (mem.target.type === "hint") {
      let h0 = null;
      for (let i = 0; i < mem.hints.length; i++) {
        if (mem.hints[i].id === mem.target.hid) {
          h0 = mem.hints[i];
          break;
        }
      }
      if (!h0 || h0.state >= 2 ||
          mem.target.idx < 0 ||
          mem.target.idx >= h0.points.length ||
          h0.points[mem.target.idx].done) {
        invalid = true;
      }
    } else if (mem.target.type === "grid" &&
               (mem.target.round !== mem.gridRound ||
                mem.target.idx < 0 ||
                mem.target.idx >= mem.grid.length ||
                mem.grid[mem.target.idx].done)) {
      invalid = true;
    }

    if (invalid) {
      mem.target = null;
      mem.navKey = null;
      mem.navFails = 0;
    } else {
      const d = Math.hypot(mem.target.x - mem.px, mem.target.y - mem.py);
      if (d <= 2.8 ||
          (mem.navKey === mem.target.key && num(mem.navFails, 0) >= 4)) {
        markTargetDone(mem.target);
      }
    }
  }

  if (!mem.target) {
    mem.target = chooseTarget();
    if (mem.target) {
      mem.navKey = null;
      mem.navFails = 0;
      mem.gradTarget = null;
      mem.gradCount = 0;
      mem.gradCooldown = now + 2;
    }
  }

  if (!mem.target) {
    if (carried > 0) {
      mem.returning = true;
      return docked ? idle() : returnOutput();
    }
    if (!docked && baseD > 3) {
      mem.returning = true;
      return returnOutput();
    }
    return docked ? idle() : motor(0, 0, false, true);
  }

  const target = mem.target;
  const targetDist = Math.hypot(target.x - mem.px, target.y - mem.py);
  const targetBaseDist = Math.hypot(
    target.x - mem.baseX,
    target.y - mem.baseY
  );
  const planNeed = tripNeed(targetDist + 8, targetBaseDist + 8, carried);
  const planEta = tripTime(targetDist + 8, targetBaseDist + 8, carried);

  if (planNeed > battery - 0.01 || planEta + 5 > timeLeft) {
    mem.target = null;
    mem.navKey = null;
    mem.navFails = 0;
    if (docked) return idle();
    mem.returning = true;
    return returnOutput();
  }

  if (mem.gradTarget) {
    const gd = Math.hypot(
      mem.gradTarget.x - mem.px,
      mem.gradTarget.y - mem.py
    );
    const gradKey = "grad:" + target.key;
    if (gd <= 2.5 ||
        now > num(mem.gradUntil, now) ||
        (mem.navKey === gradKey && num(mem.navFails, 0) >= 4)) {
      const improvement =
        mem.scienceSmooth - num(mem.gradStartSci, mem.scienceSmooth);
      if (improvement > Math.max(0.004, mem.gradStartSci * 0.025)) {
        mem.gradCount = 0;
        mem.gradCooldown = now + 1;
      } else {
        mem.gradCount = Math.min(5, num(mem.gradCount, 0) + 1);
        mem.gradCooldown = now + 8;
      }
      mem.gradTarget = null;
    } else {
      return navigateAbs(
        mem.gradTarget.x,
        mem.gradTarget.y,
        1.8,
        0.42,
        gradKey
      );
    }
  }

  if (!mem.gradTarget &&
      mem.gradCount < 4 &&
      now >= num(mem.gradCooldown, 0) &&
      num(mem.scienceSmooth, science) > 0.003) {
    const g = scienceGradient();
    if (g &&
        g.n * 8 > Math.max(0.004, mem.scienceSmooth * 0.012)) {
      const tx = clamp(
        mem.px + 8 * g.x / g.n,
        3,
        Math.max(3, mem.W - 3)
      );
      const ty = clamp(
        mem.py + 8 * g.y / g.n,
        3,
        Math.max(3, mem.H - 3)
      );
      if (Math.hypot(tx - mem.px, ty - mem.py) > 3.5) {
        mem.gradTarget = { x: tx, y: ty };
        mem.gradStartSci = mem.scienceSmooth;
        mem.gradUntil = now + 22;
        return navigateAbs(
          tx,
          ty,
          1.8,
          0.42,
          "grad:" + target.key
        );
      }
    }
  }

  return navigateAbs(
    target.x,
    target.y,
    2.25,
    0.52,
    target.key
  );
}

function act(obs, mem) {
  if (!obs || typeof obs !== "object") obs = {};
  if (!mem || typeof mem !== "object") mem = {};

  const rad = Math.PI / 180;
  const deg = 180 / Math.PI;

  function num(v, fallback) {
    return typeof v === "number" && isFinite(v) ? v : fallback;
  }

  function clamp(v, lo, hi) {
    return Math.max(lo, Math.min(hi, v));
  }

  function wrap(a) {
    a = (a + 180) % 360;
    if (a < 0) a += 360;
    return a - 180;
  }

  function buildGrid(round) {
    mem.grid = [];
    mem.gridRound = round;
    const step = 58;
    const offset = round % 2 === 0 ? 32 : 61;
    for (let y = offset; y <= mem.H - 18; y += step) {
      for (let x = offset; x <= mem.W - 18; x += step) {
        mem.grid.push({
          x: x,
          y: y,
          done: false,
          key: "g" + round + "_" + mem.grid.length
        });
      }
    }
  }

  const rawX0 = num(obs.x, 200);
  const rawY0 = num(obs.y, 200);
  const rawH0 = num(obs.heading, 0);
  const battery0 = Math.max(0, num(obs.battery, 1));

  if (!mem.initialized) {
    const mission = obs.mission || {};
    let w = 400;
    let h = 400;

    if (typeof mission.size === "number" && mission.size > 0) {
      w = mission.size;
      h = mission.size;
    } else if (mission.size && typeof mission.size === "object") {
      w = num(mission.size.width, num(mission.size.x, 400));
      h = num(mission.size.height, num(mission.size.y, 400));
    }

    mem.W = w;
    mem.H = h;
    mem.missionSecs = num(mission.seconds, 1200);
    mem.capacity = Math.max(1, num(mission.capacity, 5));

    const base = mission.base || {};
    mem.baseX = num(base.x, rawX0);
    mem.baseY = num(base.y, rawY0);

    mem.hints = [];
    if (Array.isArray(mission.hints)) {
      for (let i = 0; i < mission.hints.length; i++) {
        const q = mission.hints[i] || {};
        if (typeof q.x !== "number" || typeof q.y !== "number") continue;

        const hx = clamp(q.x, 4, Math.max(4, w - 4));
        const hy = clamp(q.y, 4, Math.max(4, h - 4));
        const points = [];

        function addPoint(x, y) {
          x = clamp(x, 4, Math.max(4, w - 4));
          y = clamp(y, 4, Math.max(4, h - 4));
          for (let j = 0; j < points.length; j++) {
            if (Math.hypot(points[j].x - x, points[j].y - y) < 2) return;
          }
          points.push({ x: x, y: y, done: false });
        }

        addPoint(hx, hy);
        for (const radius of [9, 18]) {
          for (let a = 0; a < 360; a += 45) {
            addPoint(
              hx + radius * Math.cos(a * rad),
              hy + radius * Math.sin(a * rad)
            );
          }
        }

        mem.hints.push({
          id: i,
          x: hx,
          y: hy,
          value: Math.max(0.1, num(q.estimate, 1)),
          state: 0,
          maxScience: 0,
          points: points
        });
      }
    }

    mem.gridRound = 0;
    buildGrid(0);
    mem.current = null;

    mem.x = rawX0;
    mem.y = rawY0;
    mem.heading = rawH0;
    mem.headingBias = 0;
    mem.compassIgnoreUntil = 0;
    mem.compassMismatch = 0;
    mem.lastRawH = rawH0;
    mem.lastRawX = rawX0;
    mem.lastRawY = rawY0;

    mem.gpsFrozen = false;
    mem.gpsFreezeSince = 0;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    mem.gpsAnchorX = rawX0;
    mem.gpsAnchorY = rawY0;

    mem.calActive = false;
    mem.calX = rawX0;
    mem.calY = rawY0;
    mem.calT = 0;
    mem.calSin = 0;
    mem.calCos = 0;

    mem.energyRate = 0.0010;
    mem.energyCost = 0;
    mem.energyDistance = 0;
    mem.energyReady = false;
    mem.prevBattery = battery0;
    mem.prevSolar = Math.max(0, num(obs.solar, 0));
    mem.prevDock = !!obs.docked;
    mem.maxBattery = Math.max(0.1, battery0);

    mem.lastCarried = Math.max(0, num(obs.carried, 0));
    mem.lastDelivered = num(obs.delivered, 0);
    mem.returning = false;

    mem.siteLock = null;
    mem.sampleSite = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.sampleBaseD = 0;
    mem.failedSites = [];

    mem.rayLast = new Array(9);
    mem.raySame = new Array(9);
    mem.rayStale = new Array(9);
    mem.rayStartX = new Array(9);
    mem.rayStartY = new Array(9);
    mem.rayStartH = new Array(9);
    mem.raysClean = new Array(9);
    for (let i = 0; i < 9; i++) {
      mem.rayLast[i] = null;
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = rawX0;
      mem.rayStartY[i] = rawY0;
      mem.rayStartH[i] = rawH0;
      mem.raysClean[i] = 15;
    }

    mem.gainL = 2.2;
    mem.gainR = 2.2;
    mem.iL = 0;
    mem.iR = 0;
    mem.stableL = 0;
    mem.stableR = 0;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;

    mem.navKey = null;
    mem.navFails = 0;
    mem.navNoProgress = 0;
    mem.navCheckAt = 0;
    mem.navPrevDist = 0;
    mem.navX = rawX0;
    mem.navY = rawY0;
    mem.prevSteer = 0;

    mem.recoveryPhase = 0;
    mem.recoveryUntil = 0;
    mem.bumpSide = 1;
    mem.prevBumped = false;

    mem.scienceSmooth = null;
    mem.scienceSamples = [];
    mem.sciLastX = null;
    mem.sciLastY = null;
    mem.sciLastT = 0;

    mem.gradTarget = null;
    mem.gradKey = null;
    mem.gradCount = 0;
    mem.gradStartSci = 0;
    mem.gradStartT = 0;
    mem.gradCooldown = 0;

    mem.tick = 0;
    mem.lastNow = 0;
    mem.initialized = true;
  }

  mem.tick = (mem.tick || 0) + 1;
  const now = Math.max(
    num(obs.t, mem.tick * 0.1),
    num(mem.lastNow, 0)
  );
  const rawDt = now - num(mem.lastNow, 0);
  const dt = clamp(rawDt > 0.0001 ? rawDt : 0.1, 0.05, 0.25);
  mem.lastNow = now;

  const timeLeft = Math.max(
    0,
    num(obs.timeLeft, Math.max(0, mem.missionSecs - now))
  );
  const rawX = num(obs.x, mem.x);
  const rawY = num(obs.y, mem.y);
  const rawHeading = num(obs.heading, mem.heading);
  const wl = num(obs.wheelLeft, 0);
  const wr = num(obs.wheelRight, 0);
  const forward = 0.5 * (wl + wr);
  const wheelMotion = 0.5 * (Math.abs(wl) + Math.abs(wr)) * dt;
  const battery = Math.max(0, num(obs.battery, mem.prevBattery));
  const solar = Math.max(0, num(obs.solar, 0));
  const pitch = num(obs.pitch, 0);
  const carried = Math.max(0, num(obs.carried, mem.lastCarried || 0));
  const drilling = Math.max(0, num(obs.drilling, 0));
  const science = Math.max(0, num(obs.science, 0));
  const docked = !!obs.docked;
  const bumped = !!obs.bumped;
  const capacity = Math.max(
    1,
    num(obs.mission && obs.mission.capacity, mem.capacity || 5)
  );

  const yawRate = clamp((wr - wl) / 0.6, -5, 5);
  const yawChange = yawRate * dt * deg;
  const rawHChange = wrap(rawHeading - mem.lastRawH);
  const rawStep = Math.hypot(rawX - mem.lastRawX, rawY - mem.lastRawY);
  const gpsJump = rawStep > 16;

  const oldHeading = mem.heading;
  let heading = wrap(oldHeading + yawChange);
  const compassJump =
    Math.abs(wrap(rawHChange - yawChange)) > 58 &&
    Math.abs(yawChange) < 35;

  if (compassJump) {
    mem.compassIgnoreUntil = now + 0.8;
    mem.compassMismatch = 0;
  } else if (now >= num(mem.compassIgnoreUntil, 0)) {
    const compassTarget = wrap(rawHeading + num(mem.headingBias, 0));
    const compassError = wrap(compassTarget - heading);

    if (Math.abs(compassError) > 68) {
      mem.compassMismatch = num(mem.compassMismatch, 0) + dt;
      if (mem.compassMismatch > 2.0) {
        mem.headingBias = wrap(heading - rawHeading);
        mem.compassMismatch = 0;
        mem.compassIgnoreUntil = now + 0.5;
      }
    } else {
      mem.compassMismatch = 0;
      heading = wrap(heading + clamp(compassError, -18, 18) * 0.20);
    }
  }

  if (!docked && !gpsJump && !mem.gpsFrozen &&
      forward > 0.28 && Math.abs(wr - wl) < 0.16) {
    if (!mem.calActive) {
      mem.calActive = true;
      mem.calX = rawX;
      mem.calY = rawY;
      mem.calT = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
    mem.calT += dt;
    mem.calSin += Math.sin(rawHeading * rad) * dt;
    mem.calCos += Math.cos(rawHeading * rad) * dt;

    const cdx = rawX - mem.calX;
    const cdy = rawY - mem.calY;
    if (Math.hypot(cdx, cdy) > 4.5 && mem.calT > 2.5) {
      const course = Math.atan2(cdy, cdx) * deg;
      const meanRaw = Math.atan2(mem.calSin, mem.calCos) * deg;
      const measuredBias = wrap(course - meanRaw);
      const biasError = wrap(measuredBias - mem.headingBias);
      mem.headingBias = wrap(
        mem.headingBias + clamp(biasError, -22, 22) * 0.16
      );
      heading = wrap(heading + clamp(biasError, -14, 14) * 0.06);
      mem.calActive = false;
      mem.calT = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
  } else {
    mem.calActive = false;
    mem.calT = 0;
    mem.calSin = 0;
    mem.calCos = 0;
  }

  if (!docked && wheelMotion > 0.015 && rawStep < 0.025) {
    mem.gpsSameTime += dt;
    mem.gpsMoveWhileSame += Math.abs(forward) * dt;
  } else if (rawStep > 0.12) {
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
  }

  if (!mem.gpsFrozen &&
      mem.gpsSameTime > 2.5 &&
      mem.gpsMoveWhileSame > 0.8) {
    mem.gpsFrozen = true;
    mem.gpsFreezeSince = now;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
  }

  let releasedGPS = false;
  if (mem.gpsFrozen &&
      Math.hypot(rawX - mem.gpsAnchorX, rawY - mem.gpsAnchorY) > 1.4) {
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    releasedGPS = true;
  }

  const midHeading = wrap(
    oldHeading + 0.5 * wrap(heading - oldHeading)
  );
  const predX = mem.x + forward * dt * Math.cos(midHeading * rad);
  const predY = mem.y + forward * dt * Math.sin(midHeading * rad);

  let px = predX;
  let py = predY;
  if (docked) {
    px = mem.baseX;
    py = mem.baseY;
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
  } else if (!mem.gpsFrozen && !gpsJump) {
    let alpha = wheelMotion > 0.025 ? 0.58 : 0.38;
    if (releasedGPS) alpha = 0.68;
    if (Math.hypot(rawX - predX, rawY - predY) > 10) alpha = 0.04;
    px = predX + alpha * (rawX - predX);
    py = predY + alpha * (rawY - predY);
  }

  const b0 = obs.beacon;
  const beaconValid =
    !!b0 &&
    typeof b0.distance === "number" &&
    typeof b0.bearing === "number" &&
    isFinite(b0.distance) &&
    isFinite(b0.bearing) &&
    b0.distance >= 0 &&
    b0.distance <= 20.5;

  if (docked) {
    px = mem.baseX;
    py = mem.baseY;
  } else if (beaconValid && b0.distance > 3) {
    const beaconBearingGlobal = Math.atan2(
      mem.baseY - py,
      mem.baseX - px
    ) * deg;
    const headingFromBeacon = wrap(beaconBearingGlobal - b0.bearing);
    const beaconHeadingError = wrap(headingFromBeacon - heading);

    if (Math.abs(beaconHeadingError) < 42) {
      const correction = beaconHeadingError * 0.06;
      heading = wrap(heading + correction);
      mem.headingBias = wrap(mem.headingBias + correction);
    }

    const a = (heading + b0.bearing) * rad;
    const bx = mem.baseX - b0.distance * Math.cos(a);
    const by = mem.baseY - b0.distance * Math.sin(a);
    const blend = mem.gpsFrozen ? 0.28 : 0.12;
    px = px * (1 - blend) + bx * blend;
    py = py * (1 - blend) + by * blend;
  }

  mem.x = clamp(px, -5, mem.W + 5);
  mem.y = clamp(py, -5, mem.H + 5);
  mem.heading = heading;
  mem.lastRawH = rawHeading;
  mem.lastRawX = rawX;
  mem.lastRawY = rawY;

  if (mem.energyReady && !docked && !mem.prevDock && wheelMotion > 0.01) {
    const solarAvg = clamp((mem.prevSolar + solar) * 0.5, 0, 0.2);
    const gross = Math.max(0, mem.prevBattery - battery) +
      solarAvg * dt * 0.10;
    mem.energyDistance += wheelMotion;
    mem.energyCost += gross;

    if (mem.energyDistance >= 8) {
      const measured = clamp(
        mem.energyCost /
          Math.max(2, mem.energyDistance * (1 + 0.14 * carried)),
        0.0003,
        0.005
      );
      const mix = measured > mem.energyRate ? 0.12 : 0.045;
      mem.energyRate = clamp(
        mem.energyRate * (1 - mix) + measured * mix,
        0.00035,
        0.005
      );
      mem.energyDistance = 0;
      mem.energyCost = 0;
    }
  } else if (docked) {
    mem.energyDistance = 0;
    mem.energyCost = 0;
  }

  mem.prevBattery = battery;
  mem.prevSolar = solar;
  mem.prevDock = docked;
  mem.energyReady = true;
  mem.maxBattery = Math.max(num(mem.maxBattery, battery), battery);

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    const v = clamp(num(rays[i], 15), 0, 15);
    if (mem.rayLast[i] !== null &&
        Math.abs(v - mem.rayLast[i]) < 0.015) {
      mem.raySame[i] += dt;
      const moved = Math.hypot(
        mem.x - mem.rayStartX[i],
        mem.y - mem.rayStartY[i]
      );
      const turned = Math.abs(wrap(heading - mem.rayStartH[i]));
      if (mem.raySame[i] > 5 &&
          (moved > 2.0 || turned > 36)) {
        mem.rayStale[i] = true;
      }
    } else {
      mem.raySame[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = mem.x;
      mem.rayStartY[i] = mem.y;
      mem.rayStartH[i] = heading;
    }
    mem.rayLast[i] = v;
    mem.raysClean[i] = mem.rayStale[i] ? 15 : v;
  }

  if (mem.scienceSmooth === null || mem.scienceSmooth === undefined) {
    mem.scienceSmooth = science;
  } else {
    mem.scienceSmooth = mem.scienceSmooth * 0.76 + science * 0.24;
  }

  const movedSinceScience = mem.sciLastX === null
    ? 1e9
    : Math.hypot(mem.x - mem.sciLastX, mem.y - mem.sciLastY);

  if (mem.sciLastX === null ||
      (movedSinceScience > 2.0 && now - mem.sciLastT > 1.0) ||
      now - mem.sciLastT > 5.0) {
    mem.scienceSamples.push({
      x: mem.x,
      y: mem.y,
      s: mem.scienceSmooth,
      t: now
    });
    if (mem.scienceSamples.length > 36) mem.scienceSamples.shift();
    mem.sciLastX = mem.x;
    mem.sciLastY = mem.y;
    mem.sciLastT = now;
  }

  function validBeacon() {
    return beaconValid;
  }

  function baseDistanceNow() {
    if (validBeacon()) return Math.max(0, b0.distance);
    return Math.hypot(mem.baseX - mem.x, mem.baseY - mem.y);
  }

  function returnEnergy(distance, load) {
    distance = Math.max(0, distance);
    load = Math.max(0, load);
    return 0.09 +
      mem.energyRate *
        (distance * 1.48 + 14) *
        (1 + 0.16 * load) +
      0.025 * load;
  }

  function returnTime(distance, load) {
    return 25 + (1.65 * Math.max(0, distance) + 12) / 0.40 +
      8 * Math.max(0, load);
  }

  function tripEnergy(d1, d2, load) {
    d1 = Math.max(0, d1);
    d2 = Math.max(0, d2);
    load = Math.max(0, load);
    return 0.11 +
      mem.energyRate *
        ((d1 * 1.42 + 14) * (1 + 0.14 * load) +
         (d2 * 1.52 + 18) * (1 + 0.17 * (load + 1))) +
      0.03 * (load + 1);
  }

  function tripTime(d1, d2, load) {
    return 35 +
      (1.45 * Math.max(0, d1) +
       1.55 * Math.max(0, d2) + 28) / 0.42 +
      9 * (Math.max(0, load) + 1);
  }

  function nearestHintId(x, y) {
    let best = -1;
    let bestD = 38;
    for (let i = 0; i < mem.hints.length; i++) {
      const h0 = mem.hints[i];
      const d = Math.hypot(x - h0.x, y - h0.y);
      if (d < bestD) {
        bestD = d;
        best = h0.id;
      }
    }
    return best;
  }

  function cleanFailedSites() {
    for (let i = mem.failedSites.length - 1; i >= 0; i--) {
      if (mem.failedSites[i].until <= now) {
        mem.failedSites.splice(i, 1);
      }
    }
  }

  function isFailedSite(x, y) {
    cleanFailedSites();
    for (let i = 0; i < mem.failedSites.length; i++) {
      if (Math.hypot(
        x - mem.failedSites[i].x,
        y - mem.failedSites[i].y
      ) < 4.5) return true;
    }
    return false;
  }

  function addFailedSite(s) {
    if (!s) return;
    for (let i = 0; i < mem.failedSites.length; i++) {
      const f = mem.failedSites[i];
      if (Math.hypot(s.x - f.x, s.y - f.y) < 4) {
        f.until = now + 140;
        return;
      }
    }
    mem.failedSites.push({ x: s.x, y: s.y, until: now + 140 });
    if (mem.failedSites.length > 20) mem.failedSites.shift();
  }

  function clearFailedSite(s) {
    if (!s) return;
    for (let i = mem.failedSites.length - 1; i >= 0; i--) {
      if (Math.hypot(s.x - mem.failedSites[i].x,
                     s.y - mem.failedSites[i].y) < 5) {
        mem.failedSites.splice(i, 1);
      }
    }
  }

  const site = obs.site && typeof obs.site === "object" ? obs.site : null;
  const siteDistance = site ? num(site.distance, -1) : -1;
  const siteBearing = site ? num(site.bearing, 0) : 0;
  const siteValid = !!site &&
    siteDistance >= 0 &&
    siteDistance <= 8.5 &&
    isFinite(siteBearing);

  let siteInfo = null;
  if (siteValid && carried < capacity) {
    const a = (heading + siteBearing) * rad;
    const sx = mem.x + siteDistance * Math.cos(a);
    const sy = mem.y + siteDistance * Math.sin(a);

    if (!isFailedSite(sx, sy)) {
      const hid = nearestHintId(sx, sy);
      siteInfo = {
        x: sx,
        y: sy,
        distance: siteDistance,
        bearing: siteBearing,
        value: num(site.value, 0),
        hid: hid,
        lastSeen: now
      };

      let lock = mem.siteLock;
      if (!lock ||
          now - num(lock.lastSeen, now) > 18 ||
          Math.hypot(sx - lock.x, sy - lock.y) > 10) {
        mem.siteLock = {
          x: sx,
          y: sy,
          value: siteInfo.value,
          hid: hid,
          lastSeen: now
        };
      } else {
        lock.x = lock.x * 0.65 + sx * 0.35;
        lock.y = lock.y * 0.65 + sy * 0.35;
        lock.value = siteInfo.value;
        if (lock.hid < 0 && hid >= 0) lock.hid = hid;
        lock.lastSeen = now;
      }
    }
  } else if (mem.siteLock && !mem.sampling &&
             now - num(mem.siteLock.lastSeen, now) > 18) {
    mem.siteLock = null;
  }

  function markTargetDone(t) {
    if (!t) return;

    if (t.type === "hint") {
      const h0 = mem.hints[t.hid];
      if (h0 && t.idx >= 0 && t.idx < h0.points.length) {
        h0.points[t.idx].done = true;
        let allDone = true;
        for (let j = 0; j < h0.points.length; j++) {
          if (!h0.points[j].done) {
            allDone = false;
            break;
          }
        }
        if (allDone) h0.state = 2;
      }
    } else if (t.type === "grid" &&
               t.round === mem.gridRound &&
               t.idx >= 0 && t.idx < mem.grid.length) {
      mem.grid[t.idx].done = true;
    }

    mem.current = null;
    mem.navKey = null;
    mem.navFails = 0;
    mem.navNoProgress = 0;
  }

  function markHintSampled(s) {
    if (!s) return;
    let chosen = typeof s.hid === "number" ? s.hid : -1;
    if (chosen < 0 || !mem.hints[chosen]) {
      chosen = nearestHintId(s.x, s.y);
    }

    if (chosen >= 0 && mem.hints[chosen]) {
      const h0 = mem.hints[chosen];
      h0.state = 2;
      for (let j = 0; j < h0.points.length; j++) {
        h0.points[j].done = true;
      }
      for (let i = 0; i < mem.hints.length; i++) {
        const other = mem.hints[i];
        if (other.id !== chosen &&
            Math.hypot(other.x - h0.x, other.y - h0.y) < 7) {
          other.state = 2;
          for (let j = 0; j < other.points.length; j++) {
            other.points[j].done = true;
          }
        }
      }
    }

    for (let i = 0; i < mem.grid.length; i++) {
      if (Math.hypot(s.x - mem.grid[i].x, s.y - mem.grid[i].y) < 12) {
        mem.grid[i].done = true;
      }
    }

    if (mem.current &&
        mem.current.type === "grid" &&
        Math.hypot(s.x - mem.current.x, s.y - mem.current.y) < 12) {
      markTargetDone(mem.current);
    } else if (mem.current &&
               mem.current.type === "hint" &&
               mem.current.hid === chosen) {
      mem.current = null;
      mem.navKey = null;
      mem.navFails = 0;
    }
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    const f = (a + 80) / 20;
    const i = Math.floor(f);
    if (i >= 8) return mem.raysClean[8];
    const q = f - i;
    return mem.raysClean[i] * (1 - q) + mem.raysClean[i + 1] * q;
  }

  function wallDist(a) {
    const ang = (heading + a) * rad;
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    let d = 1e6;

    if (dx > 0.0001) d = Math.min(d, (mem.W - 2.5 - mem.x) / dx);
    else if (dx < -0.0001) d = Math.min(d, (2.5 - mem.x) / dx);

    if (dy > 0.0001) d = Math.min(d, (mem.H - 2.5 - mem.y) / dy);
    else if (dy < -0.0001) d = Math.min(d, (2.5 - mem.y) / dy);

    return Math.max(0, d);
  }

  function clearAt(a) {
    return Math.min(rayAt(a), wallDist(a));
  }

  function openSide() {
    const left = clearAt(45) + clearAt(70) + clearAt(20);
    const right = clearAt(-45) + clearAt(-70) + clearAt(-20);
    if (left > right + 0.2) return 1;
    if (right > left + 0.2) return -1;
    mem.bumpSide = -(mem.bumpSide || 1);
    return mem.bumpSide;
  }

  function wheelOne(target, actual, side, bias) {
    let integral = side === 0 ? num(mem.iL, 0) : num(mem.iR, 0);
    const lastTarget = side === 0 ? num(mem.lastTL, 0) : num(mem.lastTR, 0);
    const lastCommand = side === 0 ? num(mem.lastUL, 0) : num(mem.lastUR, 0);
    let gain = clamp(
      side === 0 ? num(mem.gainL, 2.2) : num(mem.gainR, 2.2),
      0.55,
      5
    );

    if (Math.abs(target) > 0.12 &&
        Math.abs(lastTarget - target) < 0.12 &&
        Math.abs(lastCommand) > 0.18 &&
        actual * lastCommand > 0) {
      if (side === 0) mem.stableL += dt;
      else mem.stableR += dt;

      const stable = side === 0 ? mem.stableL : mem.stableR;
      if (stable > 0.45) {
        const apparent = Math.abs(actual) /
          Math.max(0.12, Math.abs(lastCommand));
        if (apparent > 0.5 && apparent < 5) {
          gain = clamp(gain * 0.985 + apparent * 0.015, 0.55, 5);
          if (side === 0) mem.gainL = gain;
          else mem.gainR = gain;
        }
      }
    } else {
      if (side === 0) mem.stableL = 0;
      else mem.stableR = 0;
    }

    if (target * lastTarget < -0.04) integral *= 0.2;

    if (Math.abs(target) < 0.045) {
      integral *= 0.62;
      const raw = -0.88 * actual + bias;
      if (side === 0) mem.iL = integral;
      else mem.iR = integral;
      return clamp(raw, -0.75, 0.75);
    }

    const error = target - actual;
    const oldIntegral = integral;
    let nextIntegral = clamp(
      integral + 0.13 * error * dt,
      -0.30,
      0.30
    );
    const feed = target / gain + Math.sign(target) * 0.065;
    let raw = feed + 0.25 * error + nextIntegral + bias;

    if ((raw > 1 && error > 0) || (raw < -1 && error < 0)) {
      nextIntegral = oldIntegral;
      raw = feed + 0.25 * error + nextIntegral + bias;
    }

    if (Math.abs(target) > 0.12 &&
        Math.abs(raw) < 0.085 &&
        target * raw >= 0) {
      raw = Math.sign(target) * 0.085;
    }

    if (side === 0) mem.iL = nextIntegral;
    else mem.iR = nextIntegral;
    return clamp(raw, -1, 1);
  }

  function motor(v, omega, drillFlag, hold) {
    v = clamp(v, -0.78, 0.78);
    omega = clamp(omega, -1.15, 1.15);

    const targetL = clamp(v - 0.3 * omega, -1.10, 1.10);
    const targetR = clamp(v + 0.3 * omega, -1.10, 1.10);
    const pitchBias = hold
      ? clamp(0.55 * Math.sin(pitch * rad), -0.25, 0.25)
      : 0;

    const left = wheelOne(targetL, wl, 0, pitchBias);
    const right = wheelOne(targetR, wr, 1, pitchBias);

    mem.lastTL = targetL;
    mem.lastTR = targetR;
    mem.lastUL = left;
    mem.lastUR = right;

    return { left: left, right: right, drill: !!drillFlag };
  }

  function idle() {
    mem.iL *= 0.65;
    mem.iR *= 0.65;
    mem.lastTL = 0;
    mem.lastTR = 0;
    mem.lastUL = 0;
    mem.lastUR = 0;
    return { left: 0, right: 0, drill: false };
  }

  function startRecovery(side) {
    mem.bumpSide = side || 1;
    mem.recoveryPhase = 1;
    mem.recoveryUntil = now + 0.7;
  }

  function recoveryOutput() {
    if (docked) {
      mem.recoveryPhase = 0;
      return null;
    }

    if (mem.recoveryPhase === 1) {
      if (now < mem.recoveryUntil) {
        return motor(-0.28, 0, false, false);
      }
      mem.recoveryPhase = 2;
      mem.recoveryUntil = now + 1.0;
    }

    if (mem.recoveryPhase === 2) {
      if (now < mem.recoveryUntil) {
        return motor(0, (mem.bumpSide || 1) * 0.78, false, false);
      }
      mem.recoveryPhase = 3;
      mem.recoveryUntil = now + 0.65;
    }

    if (mem.recoveryPhase === 3) {
      if (now < mem.recoveryUntil) {
        return motor(0.28, (mem.bumpSide || 1) * 0.20, false, false);
      }
      mem.recoveryPhase = 0;
      mem.navCheckAt = now + 4;
      mem.navX = mem.x;
      mem.navY = mem.y;
      mem.navNoProgress = 0;
    }

    return null;
  }

  function noteNavigation(key, distance, stopRadius) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navFails = 0;
      mem.navNoProgress = 0;
      mem.navCheckAt = now + 5;
      mem.navPrevDist = distance;
      mem.navX = mem.x;
      mem.navY = mem.y;
      return;
    }

    if (now >= num(mem.navCheckAt, now)) {
      const moved = Math.hypot(mem.x - mem.navX, mem.y - mem.navY);
      const progress = num(mem.navPrevDist, distance) - distance;

      if (progress > 0.35 || moved > 1.6) {
        mem.navNoProgress = 0;
      } else if (distance > stopRadius + 2.5) {
        mem.navNoProgress = num(mem.navNoProgress, 0) + 1;
      }

      if (mem.navNoProgress >= 2 &&
          mem.recoveryPhase === 0 &&
          distance > stopRadius + 2.5) {
        mem.navFails = Math.min(7, num(mem.navFails, 0) + 1);
        mem.navNoProgress = 0;
        const side = mem.navFails % 2 === 0
          ? -(openSide())
          : openSide();
        startRecovery(side);
      }

      mem.navCheckAt = now + 5;
      mem.navPrevDist = distance;
      mem.navX = mem.x;
      mem.navY = mem.y;
    }
  }

  function navigateRel(goalRel, distance, stopRadius, cruise, key) {
    goalRel = wrap(goalRel);
    distance = Math.max(0, num(distance, 0));

    if (!isFinite(distance) || distance <= stopRadius) {
      return motor(0, 0, false, true);
    }

    noteNavigation(key, distance, stopRadius);
    const recovery = recoveryOutput();
    if (recovery) return recovery;

    const actualYaw = clamp(yawRate, -5, 5);
    if (Math.abs(goalRel) > 105) {
      const omega = clamp(
        1.65 * goalRel * rad - 0.58 * actualYaw,
        -0.95,
        0.95
      );
      return motor(0, omega, false, false);
    }

    let bestA = clamp(goalRel, -80, 80);
    let bestClear = 15;
    let bestCost = 1e30;

    for (let a = -80; a <= 80; a += 10) {
      const diff = Math.abs(wrap(goalRel - a));
      const clear = clearAt(a);
      let cost = 0.00125 * diff * diff;

      if (clear < 5.0) {
        const q = 5.0 - clear;
        cost += 0.30 * q * q;
      }
      if (clear < 2.5) cost += 5 + (2.5 - clear) * 5;
      if (clear < 1.2) cost += 22;
      cost += 0.00055 * Math.abs(a - num(mem.prevSteer, 0));

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestClear = clear;
      }
    }

    mem.prevSteer = bestA;

    let speed = 0;
    if (Math.abs(bestA) <= 68) {
      speed = cruise * Math.max(0, Math.cos(bestA * rad));
    }

    const remaining = Math.max(0, distance - stopRadius);
    speed = Math.min(speed, Math.sqrt(0.42 * remaining));
    if (bestClear < 5) speed = Math.min(speed, 0.42);
    if (bestClear < 3.5) speed = Math.min(speed, 0.26);
    if (bestClear < 2.4) speed = Math.min(speed, 0.12);
    if (bestClear < 1.2) speed = 0;

    const omega = clamp(
      1.75 * bestA * rad - 0.62 * actualYaw,
      -1.05,
      1.05
    );
    return motor(speed, omega, false, false);
  }

  function navigateAbs(tx, ty, stopRadius, cruise, key) {
    const dx = tx - mem.x;
    const dy = ty - mem.y;
    const distance = Math.hypot(dx, dy);
    if (!isFinite(distance) || distance <= stopRadius) {
      return motor(0, 0, false, true);
    }

    const bearing = Math.atan2(dy, dx) * deg;
    return navigateRel(
      wrap(bearing - heading),
      distance,
      stopRadius,
      cruise,
      key
    );
  }

  function returnOutput() {
    if (validBeacon()) {
      const distance = Math.max(0, b0.distance);
      if (distance <= 2.15) return motor(0, 0, false, true);
      return navigateRel(
        b0.bearing,
        distance,
        2.15,
        0.50,
        "return"
      );
    }

    const distance = Math.hypot(mem.baseX - mem.x, mem.baseY - mem.y);
    if (distance <= 2.15) return motor(0, 0, false, true);
    return navigateAbs(mem.baseX, mem.baseY, 2.15, 0.50, "return");
  }

  function siteBaseDistance(s, localDistance, baseDistance) {
    if (!s) return baseDistance;
    const direct = Math.hypot(s.x - mem.baseX, s.y - mem.baseY);
    const upper = baseDistance + Math.max(0, localDistance) + 2;
    const lower = Math.max(0, baseDistance - Math.max(0, localDistance) - 2);
    return clamp(direct + 3, lower, Math.max(lower, upper));
  }

  function chooseTarget() {
    let best = null;
    let bestScore = -1;

    for (let i = 0; i < mem.hints.length; i++) {
      const h0 = mem.hints[i];
      if (h0.state >= 2) continue;

      if (Math.hypot(mem.x - h0.x, mem.y - h0.y) < 48) {
        h0.maxScience = Math.max(
          num(h0.maxScience, 0),
          num(mem.scienceSmooth, science)
        );
      }

      let allDone = true;
      for (let j = 0; j < h0.points.length; j++) {
        const p = h0.points[j];
        if (p.done) continue;
        allDone = false;

        const d1 = Math.hypot(p.x - mem.x, p.y - mem.y);
        if (d1 <= 3.2) {
          p.done = true;
          continue;
        }

        const d2 = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
        const need = tripEnergy(d1 + 7, d2 + 7, carried);
        const eta = tripTime(d1 + 7, d2 + 7, carried);
        if (need > battery - 0.06 || eta + 15 > timeLeft) continue;

        let score = Math.pow(Math.max(0.1, h0.value), 0.84) /
          (30 + d1 + 0.60 * d2);
        if (h0.maxScience > 0.02) score *= 1.10;

        if (score > bestScore) {
          bestScore = score;
          best = {
            x: p.x,
            y: p.y,
            key: "h" + h0.id + "_" + j,
            type: "hint",
            hid: h0.id,
            idx: j,
            started: now,
            startDist: d1
          };
        }
      }

      if (allDone) h0.state = 2;
    }

    if (best) return best;

    let anyGrid = false;
    for (let i = 0; i < mem.grid.length; i++) {
      if (!mem.grid[i].done) {
        anyGrid = true;
        break;
      }
    }

    if (!anyGrid) {
      if (mem.gridRound >= 1) return null;
      buildGrid(mem.gridRound + 1);
    }

    let gridBest = null;
    let gridScore = 1e30;
    for (let i = 0; i < mem.grid.length; i++) {
      const g = mem.grid[i];
      if (g.done) continue;

      const d1 = Math.hypot(g.x - mem.x, g.y - mem.y);
      if (d1 <= 3.2) {
        g.done = true;
        continue;
      }

      const d2 = Math.hypot(g.x - mem.baseX, g.y - mem.baseY);
      const need = tripEnergy(d1 + 7, d2 + 7, carried);
      const eta = tripTime(d1 + 7, d2 + 7, carried);
      if (need > battery - 0.06 || eta + 15 > timeLeft) continue;

      const score = d1 + 0.48 * d2;
      if (score < gridScore) {
        gridScore = score;
        gridBest = {
          x: g.x,
          y: g.y,
          key: g.key,
          type: "grid",
          idx: i,
          round: mem.gridRound,
          started: now,
          startDist: d1
        };
      }
    }

    return gridBest;
  }

  function scienceGradient() {
    const list = mem.scienceSamples || [];
    const pts = [];
    const start = Math.max(0, list.length - 24);

    for (let i = start; i < list.length; i++) {
      const q = list[i];
      if (now - q.t < 100 &&
          Math.hypot(q.x - mem.x, q.y - mem.y) < 50) {
        pts.push(q);
      }
    }
    if (pts.length < 5) return null;

    let mx = 0, my = 0, ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let xx = 0, yy = 0, xy = 0, xs = 0, ys = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      xx += dx * dx;
      yy += dy * dy;
      xy += dx * dy;
      xs += dx * ds;
      ys += dy * ds;
    }

    const det = xx * yy - xy * xy;
    if (det < 100) return null;

    const gx = (xs * yy - ys * xy) / det;
    const gy = (ys * xx - xs * xy) / det;
    const norm = Math.hypot(gx, gy);
    if (!isFinite(norm) || norm < 1e-7) return null;
    return { x: gx, y: gy, n: norm };
  }

  const previousCarried = num(mem.lastCarried, carried);
  let sampleSucceeded = false;

  if (carried > previousCarried) {
    sampleSucceeded = true;
    const sampled = mem.sampleSite || mem.siteLock || siteInfo;
    markHintSampled(sampled);
    clearFailedSite(sampled);
    mem.siteLock = null;
    mem.sampleSite = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.gradTarget = null;
  } else if (carried < previousCarried && docked) {
    mem.siteLock = null;
    mem.sampleSite = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.returning = false;
    mem.navKey = null;
    mem.navFails = 0;
  }

  mem.lastCarried = carried;
  mem.lastDelivered = num(obs.delivered, mem.lastDelivered || 0);

  if (drilling > 0 && !mem.sampling && carried < capacity) {
    const s = mem.siteLock || siteInfo;
    if (s) {
      mem.sampling = true;
      mem.sampleStart = Math.max(0, now - drilling);
      mem.sampleSite = {
        x: s.x,
        y: s.y,
        hid: s.hid,
        value: s.value
      };
      mem.sampleBaseD = baseDistanceNow();
    }
  } else if (drilling > 0 && mem.sampling && mem.sampleStart < 0) {
    mem.sampleStart = Math.max(0, now - drilling);
  }

  if (mem.sampling &&
      mem.sampleStart >= 0 &&
      now - mem.sampleStart > 22 &&
      carried === previousCarried) {
    addFailedSite(mem.sampleSite || mem.siteLock);
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.sampleSite = null;
    mem.siteLock = null;
  }

  if (bumped && !mem.prevBumped && !docked) {
    if (mem.sampling) {
      addFailedSite(mem.sampleSite || mem.siteLock);
      mem.sampling = false;
      mem.sampleStart = -1;
      mem.sampleSite = null;
      mem.siteLock = null;
    }
    startRecovery(openSide());
  }
  mem.prevBumped = bumped;

  const recoveryNow = recoveryOutput();
  if (recoveryNow) return recoveryNow;

  if (docked && carried > 0) {
    mem.returning = true;
    return idle();
  }
  if (docked && carried === 0) {
    mem.returning = false;
  }

  const baseD = baseDistanceNow();
  const retNeed = returnEnergy(baseD, carried);
  const retEta = returnTime(baseD, carried);

  if (!docked && !mem.returning) {
    if (carried >= capacity ||
        battery <= retNeed + 0.11 ||
        (carried > 0 && timeLeft <= retEta + 12) ||
        (carried === 0 && baseD > 3 && timeLeft <= retEta + 25)) {
      mem.returning = true;
    }
  }

  if (!docked && mem.returning) {
    return returnOutput();
  }

  if (mem.sampling) {
    const ss = mem.sampleSite || mem.siteLock || siteInfo;
    const sampleBaseD = ss
      ? Math.max(num(mem.sampleBaseD, 0),
          siteBaseDistance(ss, 0, baseD) - 3)
      : baseD;
    const sampleReturn = returnEnergy(sampleBaseD, carried + 1);

    if (battery <= sampleReturn + 0.045 ||
        timeLeft <= returnTime(sampleBaseD, carried + 1) + 6) {
      mem.sampling = false;
      mem.sampleStart = -1;
      mem.returning = true;
      return returnOutput();
    }

    const sameSite = siteInfo && (!mem.sampleSite ||
      Math.hypot(siteInfo.x - mem.sampleSite.x,
                 siteInfo.y - mem.sampleSite.y) < 5);

    if (sameSite && siteDistance > 1.55) {
      mem.sampling = false;
      mem.sampleStart = -1;
    } else if (!siteInfo && mem.sampleSite &&
               Math.hypot(mem.sampleSite.x - mem.x,
                          mem.sampleSite.y - mem.y) > 1.9) {
      mem.sampling = false;
      mem.sampleStart = -1;
    } else {
      const localD = sameSite
        ? siteDistance
        : (mem.sampleSite
            ? Math.hypot(mem.sampleSite.x - mem.x,
                         mem.sampleSite.y - mem.y)
            : 1.2);
      const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
      const drillNow = localD <= 1.30 && speedNow < 0.14;
      return motor(0, 0, drillNow, true);
    }
  }

  if (siteInfo && carried < capacity) {
    const lock = mem.siteLock || siteInfo;
    const siteBaseD = siteBaseDistance(lock, siteDistance, baseD);
    const approach = Math.max(0, siteDistance - 0.9);
    const sampleNeed =
      returnEnergy(siteBaseD, carried + 1) +
      mem.energyRate * (approach + 3) *
        (1 + 0.14 * carried) * 1.5 +
      0.07;
    const sampleTime =
      returnTime(siteBaseD, carried + 1) +
      approach * 3.0 + 14;

    if (battery <= sampleNeed || timeLeft <= sampleTime) {
      mem.returning = true;
      return returnOutput();
    }

    if (siteDistance <= 1.08) {
      const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
      if (speedNow < 0.14) {
        mem.sampling = true;
        mem.sampleStart = now;
        mem.sampleSite = {
          x: lock.x,
          y: lock.y,
          hid: lock.hid,
          value: lock.value
        };
        mem.sampleBaseD = siteBaseD;
        return motor(0, 0, true, true);
      }
      return motor(0, 0, false, true);
    }

    return navigateRel(
      siteBearing,
      siteDistance,
      0.82,
      0.30,
      "site"
    );
  }

  if (mem.siteLock && carried < capacity) {
    const lock = mem.siteLock;
    const age = now - num(lock.lastSeen, now);

    if (age > 18) {
      mem.siteLock = null;
    } else {
      const d = Math.hypot(lock.x - mem.x, lock.y - mem.y);
      const siteBaseD = siteBaseDistance(lock, d, baseD);
      const approach = Math.max(0, d - 0.9);
      const sampleNeed =
        returnEnergy(siteBaseD, carried + 1) +
        mem.energyRate * (approach + 3) *
          (1 + 0.14 * carried) * 1.5 +
        0.07;
      const sampleTime =
        returnTime(siteBaseD, carried + 1) +
        approach * 3.0 + 14;

      if (battery <= sampleNeed || timeLeft <= sampleTime) {
        mem.returning = true;
        return returnOutput();
      }

      if (d <= 1.08) {
        const speedNow = Math.max(Math.abs(wl), Math.abs(wr));
        if (speedNow < 0.14) {
          mem.sampling = true;
          mem.sampleStart = now;
          mem.sampleSite = {
            x: lock.x,
            y: lock.y,
            hid: lock.hid,
            value: lock.value
          };
          mem.sampleBaseD = siteBaseD;
          return motor(0, 0, true, true);
        }
        return motor(0, 0, false, true);
      }

      return navigateAbs(lock.x, lock.y, 0.82, 0.26, "site");
    }
  }

  if (mem.current) {
    let invalid = false;
    const c = mem.current;

    if (c.type === "hint") {
      const h0 = mem.hints[c.hid];
      if (!h0 || h0.state >= 2 ||
          c.idx < 0 || c.idx >= h0.points.length ||
          h0.points[c.idx].done) {
        invalid = true;
      }
    } else if (c.type === "grid" &&
               (c.round !== mem.gridRound ||
                c.idx < 0 || c.idx >= mem.grid.length ||
                mem.grid[c.idx].done)) {
      invalid = true;
    }

    if (invalid) {
      mem.current = null;
      mem.navKey = null;
      mem.navFails = 0;
    } else {
      const d = Math.hypot(c.x - mem.x, c.y - mem.y);
      const timeout =
        now - num(c.started, now) >
        Math.max(100, 5.2 * num(c.startDist, d) + 70);
      const navFailed =
        mem.navKey === c.key && num(mem.navFails, 0) >= 4;

      if (d <= 3.2 || timeout || navFailed) {
        markTargetDone(c);
      }
    }
  }

  if (!mem.current) {
    mem.current = chooseTarget();
    if (mem.current) {
      mem.navKey = null;
      mem.navFails = 0;
      mem.navNoProgress = 0;
      mem.gradTarget = null;
      mem.gradKey = mem.current.key;
      mem.gradCount = 0;
      mem.gradCooldown = now + 2;
    }
  }

  if (!mem.current) {
    if (carried > 0 || (!docked && baseD > 3)) {
      mem.returning = true;
      return docked ? idle() : returnOutput();
    }
    return docked ? idle() : motor(0, 0, false, true);
  }

  const current = mem.current;
  const currentDist = Math.hypot(current.x - mem.x, current.y - mem.y);
  const currentBaseDist = Math.hypot(
    current.x - mem.baseX,
    current.y - mem.baseY
  );
  const planNeed = tripEnergy(currentDist + 7, currentBaseDist + 7, carried);
  const planEta = tripTime(currentDist + 7, currentBaseDist + 7, carried);

  if (planNeed > battery - 0.06 || planEta + 15 > timeLeft) {
    mem.current = null;
    mem.navKey = null;
    mem.navFails = 0;
    if (carried > 0 || (!docked && baseD > 3)) {
      mem.returning = true;
      return docked ? idle() : returnOutput();
    }
    return docked ? idle() : motor(0, 0, false, true);
  }

  if (mem.gradKey !== current.key) {
    mem.gradKey = current.key;
    mem.gradCount = 0;
    mem.gradTarget = null;
    mem.gradCooldown = now + 2;
  }

  if (mem.gradTarget) {
    const gd = Math.hypot(
      mem.gradTarget.x - mem.x,
      mem.gradTarget.y - mem.y
    );

    if (gd <= 2.2 || now > num(mem.gradStartT, now) + 24) {
      const improvement =
        mem.scienceSmooth - num(mem.gradStartSci, mem.scienceSmooth);
      if (improvement > Math.max(0.015, mem.gradStartSci * 0.018)) {
        mem.gradCount = 0;
        mem.gradCooldown = now + 2;
      } else {
        mem.gradCount = Math.min(4, num(mem.gradCount, 0) + 1);
        mem.gradCooldown = now + 12;
      }
      mem.gradTarget = null;
    } else {
      return navigateAbs(
        mem.gradTarget.x,
        mem.gradTarget.y,
        1.8,
        0.42,
        "grad:" + current.key
      );
    }
  }

  if (!mem.gradTarget &&
      mem.gradCount < 3 &&
      now >= num(mem.gradCooldown, 0) &&
      science > 0.03) {
    const g = scienceGradient();
    if (g &&
        g.n * 7 > Math.max(0.012, mem.scienceSmooth * 0.018)) {
      const tx = clamp(
        mem.x + 7 * g.x / g.n,
        4,
        Math.max(4, mem.W - 4)
      );
      const ty = clamp(
        mem.y + 7 * g.y / g.n,
        4,
        Math.max(4, mem.H - 4)
      );

      let inRegion = true;
      if (current.type === "hint") {
        const h0 = mem.hints[current.hid];
        if (h0) inRegion = Math.hypot(tx - h0.x, ty - h0.y) < 40;
      } else {
        inRegion = Math.hypot(tx - current.x, ty - current.y) < 42;
      }

      if (inRegion && Math.hypot(tx - mem.x, ty - mem.y) > 3.5) {
        mem.gradCount++;
        mem.gradTarget = { x: tx, y: ty };
        mem.gradStartT = now;
        mem.gradStartSci = mem.scienceSmooth;
        return navigateAbs(tx, ty, 1.8, 0.42, "grad:" + current.key);
