  const yawChange = yawRate * dt * deg;
  const rawHChange = wrap(rawHeading - mem.lastRawH);
  const rawStep = Math.hypot(rawX - mem.lastRawX, rawY - mem.lastRawY);
  const gpsJump = rawStep > 18;

  const oldHeading = mem.heading;
  const predictedHeading = wrap(oldHeading + yawChange);
  const compassJump =
