      const meanRaw = Math.atan2(mem.calSin, mem.calCos) * deg;
      const measuredBias = wrap(course - meanRaw);
      const biasError = wrap(measuredBias - mem.headingBias);
      mem.headingBias = wrap(
        mem.headingBias + clamp(biasError, -22, 22) * 0.15
      );
      heading = wrap(
        heading + clamp(wrap(course - heading), -12, 12) * 0.06
      );
      mem.calActive = false;
      mem.calT = 0;
      mem.calSin = 0;
      mem.calCos = 0;
    }
  } else {
    mem.calActive = false;
    mem.calT = 0;
    mem.calSin = 0;
    mem.calCos = 0;
  }

  if (!docked && wheelMotion > 0.015 && rawStep < 0.025) {
    mem.gpsSameTime += dt;
    mem.gpsMoveWhileSame += wheelMotion;
  } else if (rawStep > 0.12) {
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
  }

  if (!mem.gpsFrozen &&
      mem.gpsSameTime > 2.5 &&
      mem.gpsMoveWhileSame > 1.0) {
