    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
  }

  let releasedGPS = false;
  if (mem.gpsFrozen &&
      Math.hypot(rawX - mem.gpsAnchorX, rawY - mem.gpsAnchorY) > 1.5) {
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    releasedGPS = true;
  }

  const midHeading = wrap(
    oldHeading + 0.5 * wrap(heading - oldHeading)
  );
  const predX = mem.x + forward * dt * Math.cos(midHeading * rad);
  const predY = mem.y + forward * dt * Math.sin(midHeading * rad);

  let px = predX;
  let py = predY;
  if (docked) {
    px = mem.baseX;
    py = mem.baseY;
    mem.gpsFrozen = false;
    mem.gpsSameTime = 0;
    mem.gpsMoveWhileSame = 0;
    mem.gpsAnchorX = rawX;
    mem.gpsAnchorY = rawY;
  } else if (!mem.gpsFrozen && !gpsJump) {
    let alpha = wheelMotion > 0.01 ? 0.28 : 0.12;
    if (releasedGPS) alpha = 0.52;
    if (Math.hypot(rawX - predX, rawY - predY) > 10) alpha = 0.025;
