    mem.energyCost = 0;
  }

  mem.prevBattery = battery;
  mem.prevSolar = solar;
  mem.prevDock = docked;
  mem.energyReady = true;

  const maxWheelSpeed = Math.max(Math.abs(wl), Math.abs(wr));
  if (now - num(mem.capAt, 0) > 1.0) {
    const lastCommandMax = Math.max(
      Math.abs(num(mem.lastUL, 0)),
      Math.abs(num(mem.lastUR, 0))
    );
    if (maxWheelSpeed > 0.92) {
      mem.commandCap = Math.max(0.22, num(mem.commandCap, 0.32) * 0.86);
    } else if (maxWheelSpeed < 0.50 &&
               lastCommandMax > num(mem.commandCap, 0.32) * 0.80) {
      mem.commandCap = Math.min(0.72, num(mem.commandCap, 0.32) + 0.02);
    }
    mem.capAt = now;
  }

  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  for (let i = 0; i < 9; i++) {
    const v = clamp(num(rays[i], 15), 0, 15);
    if (mem.rayLast[i] !== null &&
        Math.abs(v - mem.rayLast[i]) < 0.02) {
      mem.raySameTime[i] += dt;
      const moved = Math.hypot(
        mem.x - mem.rayStartX[i],
        mem.y - mem.rayStartY[i]
      );
      const turned = Math.abs(wrap(heading - mem.rayStartH[i]));
      if (mem.raySameTime[i] > 4.5 && (moved > 2 || turned > 35)) {
        mem.rayStale[i] = true;
      }
    } else {
      mem.raySameTime[i] = 0;
      mem.rayStale[i] = false;
      mem.rayStartX[i] = mem.x;
      mem.rayStartY[i] = mem.y;
      mem.rayStartH[i] = heading;
    }
    mem.rayLast[i] = v;
    mem.raysClean[i] = mem.rayStale[i] ? 15 : v;
  }

  if (mem.scienceSmooth === null || mem.scienceSmooth === undefined) {
    mem.scienceSmooth = science;
  } else {
    mem.scienceSmooth = mem.scienceSmooth * 0.72 + science * 0.28;
  }

  const movedSinceScience = mem.sciLastX === null
    ? 1e9
    : Math.hypot(mem.x - mem.sciLastX, mem.y - mem.sciLastY);

  if (mem.sciLastX === null ||
      (movedSinceScience > 2.1 && now - mem.sciLastT > 1.0) ||
      now - mem.sciLastT > 5.0) {
    mem.scienceSamples.push({
      x: mem.x,
      y: mem.y,
      s: mem.scienceSmooth,
      t: now
    });
    if (mem.scienceSamples.length > 32) mem.scienceSamples.shift();
    mem.sciLastX = mem.x;
    mem.sciLastY = mem.y;
    mem.sciLastT = now;
  }

  function validBeacon() {
    return beaconValid;
  }

  function baseDistanceNow() {
    if (validBeacon()) return Math.max(0, b0.distance);
    return Math.hypot(mem.baseX - mem.x, mem.baseY - mem.y);
  }

  function returnEnergy(distance, load) {
    distance = Math.max(0, distance);
    load = Math.max(0, load);
    return 0.12 +
      mem.energyRate *
        (1.75 * distance + 16) *
        (1 + 0.18 * load) +
      0.03 * load;
  }

  function returnTime(distance, load) {
    return 35 + 2.5 * Math.max(0, distance) + 10 * Math.max(0, load);
  }

  function tripEnergy(d1, d2, load) {
    d1 = Math.max(0, d1);
    d2 = Math.max(0, d2);
    load = Math.max(0, load);
    return 0.16 +
      mem.energyRate *
        ((1.55 * d1 + 14) * (1 + 0.16 * load) +
         (1.70 * d2 + 18) * (1 + 0.19 * (load + 1))) +
      0.025 * (load + 1);
  }

  function tripTime(d1, d2, load) {
    return 55 +
      2.25 * (Math.max(0, d1) + Math.max(0, d2)) +
      14 * (Math.max(0, load) + 1);
  }

  function findHint(id) {
    if (typeof id !== "number" || id < 0) return null;
    for (let i = 0; i < mem.hints.length; i++) {
      if (mem.hints[i].id === id) return mem.hints[i];
    }
    return null;
  }

  function nearestHintId(x, y, limit) {
    let best = -1;
    let bestD = typeof limit === "number" ? limit : 45;
    for (let i = 0; i < mem.hints.length; i++) {
      const h0 = mem.hints[i];
      const d = Math.hypot(x - h0.x, y - h0.y);
      if (d < bestD) {
        bestD = d;
        best = h0.id;
      }
    }
    return best;
  }

  function cleanFailedSites() {
    for (let i = mem.failedSites.length - 1; i >= 0; i--) {
      if (mem.failedSites[i].until <= now) {
        mem.failedSites.splice(i, 1);
      }
    }
  }

  function isFailedSite(x, y) {
    cleanFailedSites();
    for (let i = 0; i < mem.failedSites.length; i++) {
      if (Math.hypot(x - mem.failedSites[i].x,
                     y - mem.failedSites[i].y) < 4.5) return true;
    }
    return false;
  }

  function addFailedSite(s) {
    if (!s) return;
    for (let i = 0; i < mem.failedSites.length; i++) {
      const f = mem.failedSites[i];
      if (Math.hypot(s.x - f.x, s.y - f.y) < 4) {
        f.until = now + 120;
        return;
      }
    }
    mem.failedSites.push({
      x: s.x,
      y: s.y,
      until: now + 120
    });
    if (mem.failedSites.length > 20) mem.failedSites.shift();
  }

  function clearFailedSite(s) {
    if (!s) return;
    for (let i = mem.failedSites.length - 1; i >= 0; i--) {
      if (Math.hypot(s.x - mem.failedSites[i].x,
                     s.y - mem.failedSites[i].y) < 5) {
        mem.failedSites.splice(i, 1);
      }
    }
  }

  function markTargetDone(t) {
    if (!t) return;

    if (t.type === "hint") {
      const h0 = findHint(t.hid);
      if (h0 && t.idx >= 0 && t.idx < h0.points.length) {
        h0.points[t.idx].done = true;
        let all = true;
        for (let j = 0; j < h0.points.length; j++) {
          if (!h0.points[j].done) {
            all = false;
            break;
          }
        }
        if (all) h0.state = 2;
      }
    } else if (t.type === "grid" &&
               t.round === mem.gridRound &&
               t.idx >= 0 && t.idx < mem.grid.length) {
      mem.grid[t.idx].done = true;
    }

    if (mem.target === t) mem.target = null;
    mem.navKey = null;
    mem.navFails = 0;
    mem.navAbandon = null;
  }

  function markHintSampled(s) {
    if (!s) return;
    let chosen = typeof s.hid === "number" ? s.hid : -1;
    if (!findHint(chosen)) chosen = nearestHintId(s.x, s.y, 45);

    const chosenHint = findHint(chosen);
    if (chosenHint) {
      chosenHint.state = 2;
      for (let j = 0; j < chosenHint.points.length; j++) {
        chosenHint.points[j].done = true;
      }

      for (let i = 0; i < mem.hints.length; i++) {
        const other = mem.hints[i];
        if (other.id !== chosen &&
            Math.hypot(other.x - chosenHint.x,
                       other.y - chosenHint.y) < 8) {
          other.state = 2;
          for (let j = 0; j < other.points.length; j++) {
            other.points[j].done = true;
          }
        }
      }
      if (mem.activeHint === chosen) mem.activeHint = -1;
    }

    for (let i = 0; i < mem.grid.length; i++) {
      if (Math.hypot(s.x - mem.grid[i].x,
                     s.y - mem.grid[i].y) < 14) {
        mem.grid[i].done = true;
      }
    }

    if (mem.target && mem.target.type === "grid" &&
        Math.hypot(s.x - mem.target.x, s.y - mem.target.y) < 14) {
      markTargetDone(mem.target);
    } else if (mem.target && mem.target.type === "hint" &&
               mem.target.hid === chosen) {
      mem.target = null;
      mem.navKey = null;
      mem.navFails = 0;
      mem.navAbandon = null;
    }
  }

  function siteBaseDistance(s, localDistance, baseDistance) {
    if (!s) return baseDistance;
    const direct = Math.hypot(s.x - mem.baseX, s.y - mem.baseY);
    const d = Math.max(0, num(localDistance, 0));
    const lower = Math.max(0, baseDistance - d - 3);
    const upper = Math.max(lower, baseDistance + d + 3);
    return clamp(direct + 2, lower, upper);
  }

  let site = obs.site && typeof obs.site === "object" ? obs.site : null;
  let siteDistance = site ? num(site.distance, -1) : -1;
  const siteBearing = site ? num(site.bearing, 0) : 0;
  const siteValid = !!site &&
    siteDistance >= 0 &&
    siteDistance <= 8.5 &&
    isFinite(siteBearing);

  let siteInfo = null;
  if (siteValid && carried < capacity) {
    const a = (mem.heading + siteBearing) * rad;
    const sx = mem.x + siteDistance * Math.cos(a);
    const sy = mem.y + siteDistance * Math.sin(a);
    if (!isFailedSite(sx, sy)) {
      const hid = nearestHintId(sx, sy, 45);
      siteInfo = {
        x: sx,
        y: sy,
        distance: siteDistance,
        bearing: siteBearing,
        value: num(site.value, 0),
        hid: hid,
        lastSeen: now
      };

      const old = mem.siteLock;
      if (!old ||
          now - num(old.lastSeen, now) > 14 ||
          Math.hypot(sx - old.x, sy - old.y) > 9) {
        mem.siteLock = {
          x: sx,
          y: sy,
          value: siteInfo.value,
          hid: hid,
          lastSeen: now
        };
      } else {
        old.x = old.x * 0.55 + sx * 0.45;
        old.y = old.y * 0.55 + sy * 0.45;
        old.value = siteInfo.value;
        if (old.hid < 0 && hid >= 0) old.hid = hid;
        old.lastSeen = now;
      }
    }
  } else if (mem.siteLock && !mem.sampling &&
             now - num(mem.siteLock.lastSeen, now) > 14) {
    mem.siteLock = null;
  }

  function rayAt(a) {
    a = clamp(a, -80, 80);
    const f = (a + 80) / 20;
    const i = Math.floor(f);
    if (i >= 8) return mem.raysClean[8];
    const q = f - i;
    return mem.raysClean[i] * (1 - q) + mem.raysClean[i + 1] * q;
  }

  function wallDist(a) {
    const ang = (mem.heading + a) * rad;
    const dx = Math.cos(ang);
    const dy = Math.sin(ang);
    let d = 1e6;

    if (dx > 0.0001) d = Math.min(d, (mem.W - 2.5 - mem.x) / dx);
    else if (dx < -0.0001) d = Math.min(d, (2.5 - mem.x) / dx);

    if (dy > 0.0001) d = Math.min(d, (mem.H - 2.5 - mem.y) / dy);
    else if (dy < -0.0001) d = Math.min(d, (2.5 - mem.y) / dy);

    return Math.max(0, d);
  }

  function clearAt(a) {
    return Math.min(rayAt(a), wallDist(a));
  }

  function openSide() {
    const left =
      clearAt(25) + clearAt(45) + clearAt(70);
    const right =
      clearAt(-25) + clearAt(-45) + clearAt(-70);
    if (left > right + 0.25) return 1;
    if (right > left + 0.25) return -1;
    mem.bumpSide = -(mem.bumpSide || 1);
    return mem.bumpSide;
  }

  function wheelControl(target, actual, side, bias) {
    let integral = side === 0 ? num(mem.iL, 0) : num(mem.iR, 0);
    const lastTarget = side === 0
      ? num(mem.lastTL, 0)
      : num(mem.lastTR, 0);
    const lastCommand = side === 0
      ? num(mem.lastUL, 0)
      : num(mem.lastUR, 0);
    let gain = clamp(
      side === 0 ? num(mem.gainL, 2.8) : num(mem.gainR, 2.8),
      0.6,
      5.5
    );

    if (Math.abs(target) > 0.12 &&
        Math.abs(lastTarget - target) < 0.15 &&
        Math.abs(lastCommand) > 0.13 &&
        actual * lastCommand > 0) {
      if (side === 0) mem.stableL += dt;
      else mem.stableR += dt;

      const stable = side === 0 ? mem.stableL : mem.stableR;
      if (stable > 0.4) {
        const apparent = Math.abs(actual) /
          Math.max(0.10, Math.abs(lastCommand));
        if (apparent > 0.5 && apparent < 6) {
          gain = clamp(gain * 0.94 + apparent * 0.06, 0.6, 5.5);
          if (side === 0) mem.gainL = gain;
          else mem.gainR = gain;
        }
      }
    } else {
      if (side === 0) mem.stableL = 0;
      else mem.stableR = 0;
    }

    if (target * lastTarget < -0.04) integral *= 0.2;

    if (Math.abs(target) < 0.045) {
      integral *= 0.58;
      const raw = -0.82 * actual + bias;
      if (side === 0) mem.iL = integral;
      else mem.iR = integral;
      return clamp(raw, -mem.commandCap, mem.commandCap);
    }

    const error = target - actual;
    const oldIntegral = integral;
    let nextIntegral = clamp(
      integral + 0.12 * error * dt,
      -0.25,
      0.25
    );
    const feed = target / gain + Math.sign(target) * 0.05;
    let raw = feed + 0.24 * error + nextIntegral + bias;

    if ((raw > mem.commandCap && error > 0) ||
        (raw < -mem.commandCap && error < 0)) {
      nextIntegral = oldIntegral;
      raw = feed + 0.24 * error + nextIntegral + bias;
    }

    if (Math.abs(target) > 0.14 &&
        Math.abs(raw) < 0.08 &&
        target * raw >= 0) {
      raw = Math.sign(target) * 0.08;
    }

    if (side === 0) mem.iL = nextIntegral;
    else mem.iR = nextIntegral;

    return clamp(raw, -mem.commandCap, mem.commandCap);
  }

  function drive(v, omega, drillFlag, hold) {
    v = clamp(v, -0.72, 0.72);
    omega = clamp(omega, -1.12, 1.12);

    const targetL = clamp(v - 0.3 * omega, -1.15, 1.15);
    const targetR = clamp(v + 0.3 * omega, -1.15, 1.15);
    const pitchBias = hold
      ? clamp(0.50 * Math.sin(pitch * rad), -0.22, 0.22)
      : 0;

    const left = wheelControl(targetL, wl, 0, pitchBias);
    const right = wheelControl(targetR, wr, 1, pitchBias);

    mem.lastTL = targetL;
    mem.lastTR = targetR;
    mem.lastUL = left;
    mem.lastUR = right;
    mem.lastV = v;

    return { left: left, right: right, drill: !!drillFlag };
  }

  function idle() {
    return drive(0, 0, false, true);
  }

  function startRecovery(side) {
    mem.bumpSide = side < 0 ? -1 : 1;
    mem.recoveryPhase = 1;
    mem.recoveryUntil = now + 0.65;
  }

  function recoveryOutput() {
    if (docked) {
      mem.recoveryPhase = 0;
      return null;
    }

    if (mem.recoveryPhase === 1) {
      if (now < mem.recoveryUntil) {
        return drive(-0.26, 0, false, false);
      }
      mem.recoveryPhase = 2;
      mem.recoveryUntil = now + 1.0;
    }

    if (mem.recoveryPhase === 2) {
      if (now < mem.recoveryUntil) {
        return drive(0, (mem.bumpSide || 1) * 0.82, false, false);
      }
      mem.recoveryPhase = 3;
      mem.recoveryUntil = now + 1.2;
    }

    if (mem.recoveryPhase === 3) {
      if (now < mem.recoveryUntil) {
        return drive(0.30, (mem.bumpSide || 1) * 0.18, false, false);
      }
      mem.recoveryPhase = 0;
      mem.navLastProgress = now;
      mem.navBestDist = 1e9;
    }

    return null;
  }

  function noteNavigation(key, distance, stopRadius) {
    if (mem.navKey !== key) {
      mem.navKey = key;
      mem.navBestDist = distance;
      mem.navLastProgress = now;
      mem.navFails = 0;
      return;
    }

    if (distance < num(mem.navBestDist, distance) - 1.8) {
      mem.navBestDist = distance;
      mem.navLastProgress = now;
      mem.navFails = 0;
    }

    if (distance > stopRadius + 2 &&
        now - num(mem.navLastProgress, now) > 20) {
      mem.navFails = Math.min(7, num(mem.navFails, 0) + 1);
      mem.navLastProgress = now;
      mem.navBestDist = distance;

      let side = openSide();
      if (mem.navFails % 2 === 0) side = -side;
      startRecovery(side);

      if (key !== "return" && mem.navFails >= 3) {
        mem.navAbandon = key;
      } else if (key === "return" && mem.navFails >= 3) {
        mem.navFails = 0;
        mem.avoidUntil = 0;
        mem.bumpSide = -(mem.bumpSide || 1);
      }
    }
  }

  function navigateRel(goalRel, distance, stopRadius, cruise, key) {
    goalRel = wrap(goalRel);
    distance = Math.max(0, num(distance, 0));

    if (!isFinite(distance) || distance <= stopRadius) {
      return drive(0, 0, false, true);
    }

    noteNavigation(key, distance, stopRadius);
    const recovery = recoveryOutput();
    if (recovery) return recovery;

    const actualYaw = clamp(yawRate, -5, 5);

    if (Math.abs(goalRel) > 105) {
      const omega = clamp(
        1.65 * goalRel * rad - 0.55 * actualYaw,
        -1.05,
        1.05
      );
      return drive(0, omega, false, false);
    }

    const directClear = clearAt(clamp(goalRel, -80, 80));
    if (directClear < 3.5 && now > num(mem.avoidUntil, 0)) {
      const left =
        clearAt(25) + clearAt(45) + clearAt(65);
      const right =
        clearAt(-25) + clearAt(-45) + clearAt(-65);
      if (left > right + 0.2) mem.avoidSide = 1;
      else if (right > left + 0.2) mem.avoidSide = -1;
      else mem.avoidSide = mem.bumpSide || 1;
      mem.avoidUntil = now + 3.5;
    }
    if (directClear > 5 &&
        now > num(mem.avoidUntil, 0)) {
      mem.avoidSide = 0;
    }

    let bestA = clamp(goalRel, -80, 80);
    let bestClear = clearAt(bestA);
    let bestCost = 1e30;

    for (let a = -80; a <= 80; a += 10) {
      const diff = Math.abs(wrap(goalRel - a));
      const clear = clearAt(a);
      let cost = 0.0008 * diff * diff;

      if (clear < 5) {
        const q = 5 - clear;
        cost += 0.18 * q * q;
      }
      if (clear < 2.5) cost += 7 + (2.5 - clear) * 5;
      if (clear < 1.2) cost += 24;
      cost += 0.0007 * Math.abs(a - num(mem.prevSteer, 0));

      if (now < num(mem.avoidUntil, 0) &&
          directClear < 4 &&
          mem.avoidSide !== 0 &&
          a * mem.avoidSide < -5) {
        cost += 0.7;
      }

      if (cost < bestCost) {
        bestCost = cost;
        bestA = a;
        bestClear = clear;
      }
    }

    mem.prevSteer = bestA;

    let speed = cruise * Math.max(0.18, Math.cos(bestA * rad));
    if (Math.abs(bestA) > 66) speed = 0;

    const remaining = Math.max(0, distance - stopRadius);
    speed = Math.min(speed, Math.sqrt(0.45 * remaining));
    if (bestClear < 5) speed = Math.min(speed, 0.40);
    if (bestClear < 3.5) speed = Math.min(speed, 0.26);
    if (bestClear < 2.4) speed = Math.min(speed, 0.14);
    if (bestClear < 1.2) speed = 0;

    const omega = clamp(
      1.65 * bestA * rad - 0.55 * actualYaw,
      -1.05,
      1.05
    );
    return drive(speed, omega, false, false);
  }

  function navigateAbs(tx, ty, stopRadius, cruise, key) {
    const dx = tx - mem.x;
    const dy = ty - mem.y;
    const distance = Math.hypot(dx, dy);
    if (!isFinite(distance) || distance <= stopRadius) {
      return drive(0, 0, false, true);
    }
    const bearing = Math.atan2(dy, dx) * deg;
    return navigateRel(
      wrap(bearing - mem.heading),
      distance,
      stopRadius,
      cruise,
      key
    );
  }

  function returnOutput() {
    if (docked) return idle();

    if (validBeacon()) {
      const d = Math.max(0, b0.distance);
      if (d <= 1.35) return drive(0, 0, false, true);
      return navigateRel(
        b0.bearing,
        d,
        1.35,
        0.52,
        "return"
      );
    }

    const d = Math.hypot(mem.baseX - mem.x, mem.baseY - mem.y);
    if (d <= 1.35) return drive(0, 0, false, true);
    return navigateAbs(mem.baseX, mem.baseY, 1.35, 0.52, "return");
  }

  function targetPlanOK(d1, d2, load, extra) {
    const e = Math.max(0, num(extra, 0));
    const need = tripEnergy(d1 + e, d2 + e, load);
    const eta = tripTime(d1 + e, d2 + e, load);
    return need <= battery - 0.025 && eta + 18 <= timeLeft;
  }

  function chooseTarget() {
    let best = null;
    let bestScore = -1;

    for (let i = 0; i < mem.hints.length; i++) {
      const h0 = mem.hints[i];
      if (h0.state >= 2) continue;

      if (Math.hypot(mem.x - h0.x, mem.y - h0.y) < 48) {
        h0.maxScience = Math.max(
          num(h0.maxScience, 0),
          num(mem.scienceSmooth, science)
        );
      }

      let allDone = true;
      for (let j = 0; j < h0.points.length; j++) {
        const p = h0.points[j];
        if (p.done) continue;

        const d1 = Math.hypot(p.x - mem.x, p.y - mem.y);
        if (d1 <= 2.8) {
          p.done = true;
          continue;
        }

        allDone = false;
        const d2 = Math.hypot(p.x - mem.baseX, p.y - mem.baseY);
        if (!targetPlanOK(d1, d2, carried, 10)) continue;

        let score = Math.pow(Math.max(0.1, h0.value), 0.88) /
          (34 + d1 + 0.58 * d2);
        if (h0.maxScience > 0.02) score *= 1.08;
        if (mem.activeHint === h0.id) score *= 1.12;

        if (score > bestScore) {
          bestScore = score;
          best = {
            x: p.x,
            y: p.y,
            key: p.key,
            type: "hint",
            hid: h0.id,
            idx: j,
            started: now,
            startDist: d1
          };
        }
      }

      if (allDone) h0.state = 2;
    }

    if (best) {
      mem.activeHint = best.hid;
      const h0 = findHint(best.hid);
      if (h0) h0.state = 1;
      return best;
    }

    let anyGrid = false;
    for (let i = 0; i < mem.grid.length; i++) {
      if (!mem.grid[i].done) {
        anyGrid = true;
        break;
      }
    }

    if (!anyGrid && mem.gridRound < 1) {
      buildGrid(mem.gridRound + 1);
    }

    let gridBest = null;
    let gridScore = 1e30;
    for (let i = 0; i < mem.grid.length; i++) {
      const g = mem.grid[i];
      if (g.done) continue;

      const d1 = Math.hypot(g.x - mem.x, g.y - mem.y);
      if (d1 <= 2.8) {
        g.done = true;
        continue;
      }

      const d2 = Math.hypot(g.x - mem.baseX, g.y - mem.baseY);
      if (!targetPlanOK(d1, d2, carried, 8)) continue;

      const score = d1 + 0.50 * d2;
      if (score < gridScore) {
        gridScore = score;
        gridBest = {
          x: g.x,
          y: g.y,
          key: g.key,
          type: "grid",
          idx: i,
          round: mem.gridRound,
          started: now,
          startDist: d1
        };
      }
    }

    return gridBest;
  }

  function scienceGradient() {
    const list = mem.scienceSamples || [];
    const pts = [];
    const start = Math.max(0, list.length - 24);

    for (let i = start; i < list.length; i++) {
      const q = list[i];
      if (now - q.t < 100 &&
          Math.hypot(q.x - mem.x, q.y - mem.y) < 48) {
        pts.push(q);
      }
    }
    if (pts.length < 5) return null;

    let mx = 0;
    let my = 0;
    let ms = 0;
    for (let i = 0; i < pts.length; i++) {
      mx += pts[i].x;
      my += pts[i].y;
      ms += pts[i].s;
    }
    mx /= pts.length;
    my /= pts.length;
    ms /= pts.length;

    let xx = 0;
    let yy = 0;
    let xy = 0;
    let xs = 0;
    let ys = 0;
    for (let i = 0; i < pts.length; i++) {
      const dx = pts[i].x - mx;
      const dy = pts[i].y - my;
      const ds = pts[i].s - ms;
      xx += dx * dx;
      yy += dy * dy;
      xy += dx * dy;
      xs += dx * ds;
      ys += dy * ds;
    }

    const det = xx * yy - xy * xy;
    if (det < 100) return null;

    const gx = (xs * yy - ys * xy) / det;
    const gy = (ys * xx - xs * xy) / det;
    const norm = Math.hypot(gx, gy);
    if (!isFinite(norm) || norm < 1e-7) return null;
    return { x: gx, y: gy, n: norm };
  }

  function gradientOutput(current) {
    if (!current) return null;

    if (mem.gradFor !== current.key) {
      mem.gradFor = current.key;
      mem.gradTarget = null;
      mem.gradNavKey = null;
      mem.gradAttempts = 0;
      mem.gradCooldown = now + 2;
      if (mem.navAbandon &&
          String(mem.navAbandon).indexOf("grad:") === 0) {
        mem.navAbandon = null;
      }
    }

    if (mem.gradTarget) {
      if (mem.navAbandon === mem.gradNavKey) {
        mem.navAbandon = null;
        mem.navKey = null;
        mem.gradTarget = null;
        mem.gradCooldown = now + 12;
      } else {
        const gd = Math.hypot(
          mem.gradTarget.x - mem.x,
          mem.gradTarget.y - mem.y
        );
        if (gd <= 2.4 || now > mem.gradStartT + 20) {
          const improvement =
            mem.scienceSmooth - num(mem.gradStartSci, mem.scienceSmooth);
          mem.gradTarget = null;
          mem.navKey = null;
          mem.gradCooldown = improvement >
            Math.max(0.012, mem.gradStartSci * 0.02)
            ? now + 2
            : now + 13;
        } else {
          return navigateAbs(
            mem.gradTarget.x,
            mem.gradTarget.y,
            1.8,
            0.40,
            mem.gradNavKey
          );
        }
      }
    }

    if (mem.gradAttempts >= 4 ||
        now < num(mem.gradCooldown, 0) ||
        mem.scienceSmooth < 0.035) {
      return null;
    }

    const g = scienceGradient();
    if (!g || g.n * 7 < Math.max(0.012, mem.scienceSmooth * 0.02)) {
      return null;
    }

    const tx = clamp(
      mem.x + 7 * g.x / g.n,
      4,
      Math.max(4, mem.W - 4)
    );
    const ty = clamp(
      mem.y + 7 * g.y / g.n,
      4,
      Math.max(4, mem.H - 4)
    );

    let inRegion;
    if (current.type === "hint") {
      const h0 = findHint(current.hid);
      inRegion = !h0 ||
        Math.hypot(tx - h0.x, ty - h0.y) < 44;
    } else {
      inRegion = Math.hypot(tx - current.x, ty - current.y) < 42;
    }

    if (!inRegion || Math.hypot(tx - mem.x, ty - mem.y) < 3.5) {
      return null;
    }

    mem.gradAttempts++;
    mem.gradTarget = { x: tx, y: ty };
    mem.gradNavKey =
      "grad:" + current.key + ":" + mem.gradAttempts;
    mem.gradStartT = now;
    mem.gradStartSci = mem.scienceSmooth;
    return navigateAbs(
      tx,
      ty,
      1.8,
      0.40,
      mem.gradNavKey
    );
  }

  const previousCarried = num(mem.lastCarried, carried);
  let sampleSucceeded = false;

  if (carried > previousCarried) {
    sampleSucceeded = true;
    const sampled = mem.sampleSite || mem.siteLock || siteInfo;
    markHintSampled(sampled);
    clearFailedSite(sampled);
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.sampleSite = null;
    mem.sampleBaseD = 0;
    mem.siteLock = null;
    mem.navKey = null;
    if (mem.gradTarget) {
      mem.gradTarget = null;
      mem.gradNavKey = null;
    }
    siteInfo = null;
  } else if (carried < previousCarried && docked) {
    mem.siteLock = null;
    mem.sampleSite = null;
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.returning = false;
    mem.navKey = null;
    mem.navFails = 0;
  }

  mem.lastCarried = carried;
  mem.lastDelivered = num(obs.delivered, mem.lastDelivered || 0);

  if (!sampleSucceeded && drilling > 0 &&
      !mem.sampling && carried < capacity) {
    const s = siteInfo || mem.siteLock;
    if (s) {
      mem.sampling = true;
      mem.sampleStart = Math.max(0, now - drilling);
      mem.sampleSite = {
        x: s.x,
        y: s.y,
        hid: s.hid,
        value: s.value
      };
      mem.sampleBaseD = baseDistanceNow();
    }
  }

  if (mem.sampling &&
      mem.sampleStart >= 0 &&
      now - mem.sampleStart > 16 &&
      carried === previousCarried) {
    addFailedSite(mem.sampleSite || mem.siteLock);
    mem.sampling = false;
    mem.sampleStart = -1;
    mem.sampleSite = null;
    mem.siteLock = null;
    mem.navKey = null;
  }

  if (bumped && !mem.prevBumped && !docked) {
    if (mem.sampling) {
      addFailedSite(mem.sampleSite || mem.siteLock);
      mem.sampling = false;
      mem.sampleStart = -1;
      mem.sampleSite = null;
      mem.siteLock = null;
    }
    startRecovery(openSide());
  }
  mem.prevBumped = bumped;

  if (mem.navAbandon === "site") {
    addFailedSite(mem.siteLock || siteInfo);
    mem.siteLock = null;
    siteInfo = null;
    mem.navAbandon = null;
    mem.navKey = null;
  }

  if (docked && carried > 0) {
    mem.returning = true;
    return idle();
  }
  if (docked && carried === 0) {
    mem.returning = false;
  }

  if (!docked && mem.recoveryPhase > 0) {
    const recovery = recoveryOutput();
    if (recovery) return recovery;
  }

  if (mem.sampling) {
    const ss = mem.sampleSite || mem.siteLock || siteInfo;
    const baseD = baseDistanceNow();
    let sampleBaseD = num(mem.sampleBaseD, baseD);
    if (ss) {
      const localForBase = siteInfo
        ? siteInfo.distance
        : Math.hypot(ss.x - mem.x, ss.y - mem.y);
      sampleBaseD = Math.max(
        sampleBaseD,
