      }
    }
  }
  var endIdx = found ? goal : best;
  if (endIdx === start) return null;
  var path = [];
  var cur2 = endIdx;
  var guard = 0;
  while (cur2 !== -1 && cur2 !== start && guard++ < 5000) {
    var cy2 = Math.floor(cur2 / w);
    var cx2 = cur2 - cy2 * w;
    path.push({
      x: mem.gx0 + (cx2 + 0.5) * mem.res,
      y: mem.gy0 + (cy2 + 0.5) * mem.res
    });
    cur2 = came[cur2];
  }
  if (!path.length) return null;
  path.reverse();
  if (found) {
    var orig = idxAt(mem, tx, ty);
    if (orig >= 0 && mem.grid[orig] !== 2) {
      var pl = path[path.length - 1];
      if (dist(pl.x, pl.y, tx, ty) > 0.1) path.push({ x: tx, y: ty });
    }
  }
  return smoothPath(mem, path, sx, sy);
}

function wheelControl(st, target, actual, dt) {
  if (!st) st = { i: 0 };
  if (!(dt > 0) || dt > 0.5) dt = 0.1;
  target = num(target, 0);
  actual = num(actual, 0);
  st.i *= Math.max(0, 1 - 0.4 * dt);
  var err = target - actual;
  st.i += err * dt;
  st.i = clamp(st.i, -2.5, 2.5);
  var ff = Math.abs(target) > 0.03 ? target / 3.0 : 0;
  var u = ff + 0.95 * err + 0.22 * st.i;
  if (target > 0.05) u += 0.035;
  else if (target < -0.05) u -= 0.035;
  return clamp(u, -1, 1);
}

function rawDrive(obs, mem, v, omega, drill) {
  var dt = mem.dt || 0.1;
  var tl = clamp(v - omega * 0.3, -3.2, 3.2);
  var tr = clamp(v + omega * 0.3, -3.2, 3.2);
  var l = wheelControl(mem.wL, tl, num(obs.wheelLeft, 0), dt);
  var r = wheelControl(mem.wR, tr, num(obs.wheelRight, 0), dt);
  return { left: l, right: r, drill: !!drill };
}

function holdStillCmd(obs, mem, drill) {
  var dt = mem.dt || 0.1;
  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  var l = wheelControl(mem.wL, 0, wl, dt);
  var r = wheelControl(mem.wR, 0, wr, dt);
  var pitch = num(obs.pitch, 0);
  var slope = clamp(pitch * 0.012, -0.18, 0.18);
  l = clamp(l + slope - wl * 0.5, -1, 1);
  r = clamp(r + slope - wr * 0.5, -1, 1);
  return { left: l, right: r, drill: !!drill };
}

function avoidance(obs, mem, err) {
  var rays = obs.rays;
  if (!rays || rays.length < 9) return { steer: 0, maxSpeed: 15, minFront: 15 };
  var A = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
  var minFront = 15;
  var leftSum = 0, rightSum = 0, leftN = 0, rightN = 0;
  var i, r, a;
  for (i = 0; i < 9; i++) {
    r = num(rays[i], 15);
    if (r > 15) r = 15;
    a = A[i];
    if (a >= -21 && a <= 21) minFront = Math.min(minFront, r);
    if (a >= 20) { leftSum += Math.min(r, 8); leftN++; }
    if (a <= -20) { rightSum += Math.min(r, 8); rightN++; }
  }
  var lc = leftN ? leftSum / leftN : 8;
  var rc = rightN ? rightSum / rightN : 8;
  var steerSum = 0;
  for (i = 0; i < 9; i++) {
    r = num(rays[i], 15);
    if (r < 0.1 || r >= 5.8) continue;
    a = A[i];
    var rel = norm180(a - err);
    if (Math.abs(rel) > 70) continue;
    var urgency = (5.8 - r) / 5.8 * (1 - Math.abs(rel) / 90);
    if (urgency <= 0) continue;
    var away;
    if (Math.abs(a) < 15) away = lc > rc ? 1 : -1;
    else away = a > 0 ? -1 : 1;
    steerSum += away * urgency;
  }
  var steer = clamp(steerSum * 38, -70, 70);
  var maxSpeed = 15;
  if (minFront < 0.65) maxSpeed = 0;
  else if (minFront < 1.6) maxSpeed = clamp((minFront - 0.45) * 0.8, 0, 0.9);
  else if (minFront < 3.2) maxSpeed = clamp((minFront - 0.8) * 0.75, 0, 1.8);
  else if (minFront < 4.8) maxSpeed = Math.min(2.8, (minFront - 1.0) * 0.55 + 0.5);
  var leftMin = 15, rightMin = 15;
  for (i = 0; i < 9; i++) {
    r = num(rays[i], 15);
    if (A[i] > 0) leftMin = Math.min(leftMin, r);
    if (A[i] < 0) rightMin = Math.min(rightMin, r);
  }
  if (Math.min(leftMin, rightMin) < 0.5) maxSpeed = Math.min(maxSpeed, 0.45);
  return { steer: steer, maxSpeed: maxSpeed, minFront: minFront };
}

function makeDrive(obs, mem, desiredWorld, speedMax) {
  var trueH = effectiveHeading(obs, mem);
  var err = norm180(desiredWorld - trueH);
  var av = avoidance(obs, mem, err);
  var errAdj = norm180(err + av.steer);
  var v = Math.min(Math.max(0, speedMax), av.maxSpeed);
  if (mem.cautiousUntil && num(obs.t, 0) < mem.cautiousUntil) v = Math.min(v, 0.9);
  var ae = Math.abs(errAdj);
  if (ae > 130) v = Math.min(v, 0.15);
  else if (ae > 80) v = Math.min(v, 0.45);
  else if (ae > 45) v *= 0.65;
  else if (ae > 25) v *= 0.85;
  var omega = clamp(errAdj * D2R * 2.4, -3.0, 3.0);
  var tl = v - omega * 0.3;
  var tr = v + omega * 0.3;
  if (Math.abs(v) < 0.04 && Math.abs(errAdj) < 2) {
    tl = 0;
    tr = 0;
  }
  var dt = mem.dt || 0.1;
  var l = wheelControl(mem.wL, clamp(tl, -3.2, 3.2), num(obs.wheelLeft, 0), dt);
  var r = wheelControl(mem.wR, clamp(tr, -3.2, 3.2), num(obs.wheelRight, 0), dt);
  return { left: l, right: r, drill: false };
}

function driveRelative(obs, mem, bearing, speedMax) {
  var trueH = effectiveHeading(obs, mem);
  return makeDrive(obs, mem, norm180(trueH + bearing), speedMax);
}

function directDriveToPoint(obs, mem, tx, ty, speedMax) {
  var d = dist(mem.posX, mem.posY, tx, ty);
  if (d < 0.05) return holdStillCmd(obs, mem, false);
  var desired = Math.atan2(ty - mem.posY, tx - mem.posX) * R2D;
  return makeDrive(obs, mem, desired, speedMax);
}

function navTo(obs, mem, tx, ty, speedMax, stopDist) {
  tx = clamp(tx, mem.worldMinX + 0.6, mem.worldMaxX - 0.6);
  ty = clamp(ty, mem.worldMinY + 0.6, mem.worldMaxY - 0.6);
  var x = mem.posX, y = mem.posY;
  var d = dist(x, y, tx, ty);
  if (d <= stopDist) return { cmd: holdStillCmd(obs, mem, false), reached: true, d: d };
  var usePath = d > 3.5;
  var wx = tx, wy = ty;
  var pathFailed = false;
  if (usePath) {
    var nav = mem.nav;
    if (!nav || dist(nav.tx, nav.ty, tx, ty) > 2.5 || !nav.path) {
      nav = { tx: tx, ty: ty, path: null, lastPlan: -1 };
      mem.nav = nav;
    }
    if (!nav.path || (num(obs.t, 0) - nav.lastPlan > 2.5)) {
      var pts = planPath(mem, x, y, tx, ty);
      nav.path = pts || [];
      nav.lastPlan = num(obs.t, 0);
    }
    var path = nav.path;
    var guard = 0;
    while (path.length && dist(x, y, path[0].x, path[0].y) < 1.1 && guard++ < 20) path.shift();
    if (path.length) {
      wx = path[0].x;
      wy = path[0].y;
    } else {
      pathFailed = true;
      wx = tx;
      wy = ty;
    }
  } else {
    mem.nav = null;
  }
  if (pathFailed) speedMax = Math.min(speedMax, 0.8);
  var desired = Math.atan2(wy - y, wx - x) * R2D;
  return { cmd: makeDrive(obs, mem, desired, speedMax), reached: false, d: d };
}

function refreshValRef(mem) {
  var a = mem.sampleValues || [];
  if (a.length >= 2) {
    var b = a.slice().sort(function (x, y) { return x - y; });
    mem.valRef = b[Math.floor(b.length / 2)];
  } else {
    mem.valRef = mem.valMed || 1;
  }
}

function startSample(obs, mem, site, t) {
  var trueH = effectiveHeading(obs, mem);
  var bw = norm180(trueH + num(site.bearing, 0));
  var sd = num(site.distance, 0);
  var wx = mem.posX + sd * Math.cos(bw * D2R);
  var wy = mem.posY + sd * Math.sin(bw * D2R);
  var assoc = null;
  var bd = 1e9;
  for (var i = 0; i < mem.cands.length; i++) {
    var c = mem.cands[i];
    if (c.status !== 0) continue;
    var dd = dist(c.x, c.y, wx, wy);
    if (dd < bd) { bd = dd; assoc = c; }
  }
  if (bd > 30) assoc = null;
  mem.sample = {
    active: true,
    baseCarried: Math.round(num(obs.carried, 0)),
    startTime: t,
    siteX: wx,
    siteY: wy,
    value: num(site.value, 0),
    assoc: assoc,
    lastSite: site,
    missT: 0
  };
  mem.target = null;
  mem.search = null;
  mem.nav = null;
}

function completeSample(obs, mem, s) {
  s.active = false;
  var val = num(s.value, 0);
  if (val > 0) {
    mem.sampleValues = mem.sampleValues || [];
    mem.sampleValues.push(val);
    if (mem.sampleValues.length > 20) mem.sampleValues.shift();
  }
  refreshValRef(mem);
  var sx = s.siteX;
  var sy = s.siteY;
  var best = null;
  var bd = 1e9;
  for (var i = 0; i < mem.cands.length; i++) {
    var c = mem.cands[i];
    if (c.status !== 0) continue;
    var dd = dist(c.x, c.y, sx, sy);
    if (dd < bd) { bd = dd; best = c; }
  }
  if (best && bd < 28) best.status = 2;
  mem.sample = null;
  mem.target = null;
  mem.search = null;
  mem.nav = null;
}

function updateSampling(obs, mem, t, carried) {
  var s = mem.sample;
  if (!s || !s.active) return null;
  if (carried > s.baseCarried) {
    completeSample(obs, mem, s);
    return null;
  }
  if (carried >= mem.cap) {
    s.active = false;
    mem.sample = null;
    return null;
  }
  var site = obs.site;
  var d = site ? num(site.distance, 99) : 99;
  var speed = Math.abs((num(obs.wheelLeft, 0) + num(obs.wheelRight, 0)) / 2);
  if (!site) {
    s.missT += mem.dt || 0.1;
  } else {
    s.missT = 0;
    var trueH = effectiveHeading(obs, mem);
    var bw = norm180(trueH + num(site.bearing, 0));
    s.siteX = mem.posX + num(site.distance, 0) * Math.cos(bw * D2R);
    s.siteY = mem.posY + num(site.distance, 0) * Math.sin(bw * D2R);
    s.value = num(site.value, s.value);
  }
  if (!site || s.missT > 1.0) {
    if (s.missT > 1.0) {
      s.active = false;
      mem.sample = null;
      mem.target = null;
      mem.nav = null;
      return holdStillCmd(obs, mem, false);
    }
    var sd = dist(mem.posX, mem.posY, s.siteX, s.siteY);
    if (sd > 1.2) {
      var desired = Math.atan2(s.siteY - mem.posY, s.siteX - mem.posX) * R2D;
      return makeDrive(obs, mem, desired, 0.8);
    }
    return holdStillCmd(obs, mem, false);
  }
  if (d > 1.45) {
    var sp = Math.min(1.1, Math.max(0.22, (d - 1.15) * 0.8));
    var des = norm180(effectiveHeading(obs, mem) + num(site.bearing, 0));
    return makeDrive(obs, mem, des, sp);
  }
  if (speed < 0.14) return holdStillCmd(obs, mem, true);
  return holdStillCmd(obs, mem, false);
}

function shouldSample(obs, mem, site, t, carried, baseD) {
  if (!site) return false;
  if (carried >= mem.cap) return false;
  var val = num(site.value, 0);
  if (val <= 0) return false;
  var timeLeft = num(obs.timeLeft, mem.missionSeconds - (t - mem.t0));
  if (timeLeft < 12) return false;
  var db = dist(mem.posX, mem.posY, mem.base.x, mem.base.y);
  if (baseD < 8 && carried > 0) return false;
  if (timeLeft < (db + 20) / 1.1 + 14) return false;
  var ref = mem.valRef || mem.valMed || 1;
  var thr = ref * 0.06;
  if (carried === 0) thr *= 0.5;
  if (carried >= mem.cap - 1) thr *= 1.3;
  if (timeLeft < 350) thr *= 0.5;
  if (timeLeft < 150) thr *= 0.3;
  if (num(obs.battery, 1) < 0.12 && db > 20 && carried > 0) return false;
  if (site.distance < 1.5) thr *= 0.5;
  return val >= thr || carried === 0 || timeLeft < 250;
}

function shouldCharge(obs, mem, t, timeLeft) {
  var b = num(obs.battery, 1);
  if (timeLeft < 12) return false;
  if (!mem.chargeStart) mem.chargeStart = t;
  var target = 0.92;
  if (timeLeft < 500) target = 0.82;
  if (timeLeft < 250) target = 0.65;
  if (timeLeft < 120) target = 0.45;
  if (b >= target) {
    mem.chargeStart = null;
    return false;
  }
  if (t - mem.chargeStart > 35 && b > 0.35) {
    mem.chargeStart = null;
    return false;
  }
  return true;
}

function goHome(obs, mem, t) {
  var db = dist(mem.posX, mem.posY, mem.base.x, mem.base.y);
  if (db < 2.8 || obs.docked) return holdStillCmd(obs, mem, false);
  if (obs.beacon && num(obs.beacon.distance, 99) < 20) {
    var bd = num(obs.beacon.distance, db);
    if (bd < 2.5) return holdStillCmd(obs, mem, false);
    var sp = Math.min(2.0, 0.4 + bd * 0.35);
    mem.nav = null;
    return driveRelative(obs, mem, num(obs.beacon.bearing, 0), sp);
  }
  var speed = 2.1 - 0.1 * Math.round(num(obs.carried, 0));
  if (num(obs.battery, 1) < 0.2) speed = Math.min(speed, 1.2);
  if (mem.cautiousUntil > t) speed = Math.min(speed, 1.3);
  var rr = navTo(obs, mem, mem.base.x, mem.base.y, speed, 1.0);
  return rr.cmd;
}

function chooseCandidate(obs, mem, t, carried, baseD) {
  var x = mem.posX, y = mem.posY;
  var base = mem.base;
  var timeLeft = num(obs.timeLeft, mem.missionSeconds - (t - mem.t0));
  var ref = mem.valRef || mem.valMed || 1;
  var best = null;
  var bestScore = -1e9;
  var bestExtra = 0;
  for (var i = 0; i < mem.cands.length; i++) {
    var c = mem.cands[i];
    if (c.status !== 0) continue;
    var d = dist(x, y, c.x, c.y);
    var dB = dist(c.x, c.y, base.x, base.y);
    if (timeLeft < (d + dB) / 1.0 + 30) continue;
    var searchCost = 20 + (num(c.est, 1) > ref * 1.2 ? 15 : 0);
    var extra;
    if (carried > 0) {
      extra = d + dB - baseD;
      if (extra < 0) extra = 0;
      extra += searchCost * 0.6 + 7;
    } else {
      extra = d + 0.55 * dB + searchCost + 8;
    }
    if (extra < 8) extra = 8;
    var est = Math.max(0.01, num(c.est, 1));
    var score = est / extra;
    if (carried > 0 && est < ref * 0.05 && extra > 40) score *= 0.3;
    if (timeLeft < 220) score *= 1.5 / (1 + extra / 100);
    if (score > bestScore) {
      bestScore = score;
      best = c;
      bestExtra = extra;
    }
  }
  if (best && carried > 0) {
    var curVal = num(obs.carriedValue, 0);
    if (curVal > 0 && bestExtra > 90 && best.est < curVal * 0.2) return null;
  }
  return best;
}

function makeExplorePoints(mem) {
  var pts = [];
  var minx = mem.worldMinX + 20;
  var maxx = mem.worldMaxX - 20;
  var miny = mem.worldMinY + 20;
  var maxy = mem.worldMaxY - 20;
  var step = 70;
  var row = 0;
  for (var yy = miny; yy <= maxy + 0.1; yy += step) {
    if (row % 2 === 0) {
      for (var xx = minx; xx <= maxx + 0.1; xx += step) pts.push({ x: xx, y: yy });
    } else {
      for (var xx2 = maxx; xx2 >= minx - 0.1; xx2 -= step) pts.push({ x: xx2, y: yy });
    }
    row++;
  }
  return pts;
}

function chooseExplore(obs, mem, t) {
  if (!mem.explorePts) mem.explorePts = makeExplorePoints(mem);
  if (!mem.exploreDone) mem.exploreDone = [];
  var best = null;
  var bd = 1e9;
  for (var i = 0; i < mem.explorePts.length; i++) {
    if (mem.exploreDone[i]) continue;
    var p = mem.explorePts[i];
    var d = dist(mem.posX, mem.posY, p.x, p.y);
    if (d < 5) {
      mem.exploreDone[i] = 1;
      continue;
    }
    if (d < bd) {
      bd = d;
      best = { x: p.x, y: p.y, idx: i };
    }
  }
  return best;
}

function makeSearchPoints(mem, c) {
  var ref = mem.valRef || mem.valMed || 1;
  var high = num(c.est, 1) > ref * 1.2;
  var R = high ? 16 : 11;
  var pts = [{ x: c.x, y: c.y }];
  var n = high ? 10 : 8;
  var off = (c.id || 0) * 0.7;
  for (var k = 0; k < n; k++) {
    var a = off + 2 * Math.PI * k / n;
    pts.push({ x: c.x + R * Math.cos(a), y: c.y + R * Math.sin(a) });
  }
  var tLeft = mem.timeLeftLast || 1200;
  if (high && tLeft > 400) {
    var R2 = R * 1.55;
    for (var k2 = 0; k2 < 4; k2++) {
      var a2 = off + Math.PI / 4 + Math.PI / 2 * k2;
      pts.push({ x: c.x + R2 * Math.cos(a2), y: c.y + R2 * Math.sin(a2) });
    }
  }
  for (var i = 0; i < pts.length; i++) {
    pts[i].x = clamp(pts[i].x, mem.worldMinX + 1.5, mem.worldMaxX - 1.5);
    pts[i].y = clamp(pts[i].y, mem.worldMinY + 1.5, mem.worldMaxY - 1.5);
  }
  return pts;
}

function startSearch(mem, c, t) {
  mem.target = null;
  mem.nav = null;
  var ref = mem.valRef || mem.valMed || 1;
  var high = num(c.est, 1) > ref * 1.2;
  mem.search = {
    cand: c,
    pts: makeSearchPoints(mem, c),
    idx: 0,
    start: t,
    pointStart: t,
    maxTime: high ? 48 : 30
  };
}

function controlSearch(obs, mem, t, carried) {
  var s = mem.search;
  if (!s) return null;
  var c = s.cand;
  if (!c || c.status !== 0) {
    mem.search = null;
    return null;
  }
  if (s.idx >= s.pts.length || t - s.start > s.maxTime) {
    c.status = 2;
    c.false = true;
    mem.search = null;
    mem.target = null;
    mem.nav = null;
    return holdStillCmd(obs, mem, false);
  }
  var p = s.pts[s.idx];
  var d = dist(mem.posX, mem.posY, p.x, p.y);
  if (d < 2.0 || t - s.pointStart > 8.0) {
    s.idx++;
    s.pointStart = t;
    var guard = 0;
    while (s.idx < s.pts.length && guard++ < 3) {
      p = s.pts[s.idx];
      d = dist(mem.posX, mem.posY, p.x, p.y);
      if (d < 1.6) {
        s.idx++;
        continue;
      }
      break;
    }
    if (s.idx >= s.pts.length || t - s.start > s.maxTime) {
      c.status = 2;
      c.false = true;
      mem.search = null;
      mem.target = null;
      mem.nav = null;
      return holdStillCmd(obs, mem, false);
    }
    p = s.pts[s.idx];
  }
  var sp = 1.9;
  if (carried > 2) sp -= 0.08 * carried;
  if (mem.cautiousUntil > t) sp = Math.min(sp, 1.1);
  if (num(obs.battery, 1) < 0.25) sp = Math.min(sp, 1.2);
  return directDriveToPoint(obs, mem, p.x, p.y, sp);
}

function act(obs, mem) {
  try {
    if (!mem.init) {
      mem.init = 1;
      mem.t0 = num(obs.t, 0);
      var mission = obs.mission || {};
      mem.missionSeconds = num(mission.seconds, 1200);
      var mb = mission.base || { x: num(obs.x, 0), y: num(obs.y, 0) };
      mem.base = { x: num(mb.x, 0), y: num(mb.y, 0) };
      mem.cap = Math.round(num(mission.capacity, 5));
      if (!(mem.cap > 0)) mem.cap = 5;
      var hs = mission.hints || [];
      mem.hints = [];
      for (var hi0 = 0; hi0 < hs.length; hi0++) {
        var hh = hs[hi0] || {};
        var est0 = num(hh.estimate, 1);
        if (!(est0 > 0)) est0 = 1;
        mem.hints.push({ x: num(hh.x, mem.base.x), y: num(hh.y, mem.base.y), est: est0, id: hi0 });
      }
      mem.cands = [];
      for (var ci0 = 0; ci0 < mem.hints.length; ci0++) {
        var hc = mem.hints[ci0];
        mem.cands.push({ x: hc.x, y: hc.y, est: hc.est, status: 0, id: hc.id, false: false, sampled: false });
      }
      var vals = [];
      for (var vi = 0; vi < mem.hints.length; vi++) vals.push(mem.hints[vi].est);
      vals.sort(function (a, b) { return a - b; });
      var med0 = vals.length ? vals[Math.floor(vals.length / 2)] : 1;
      mem.valMed = med0;
      mem.valRef = med0;
      mem.sampleValues = [];
      var sz = mission.size;
      var sx = 400, sy = 400;
      if (typeof sz === "number") {
        sx = sy = sz;
      } else if (Array.isArray(sz)) {
        sx = num(sz[0], 400);
        sy = num(sz[1], sx);
      } else if (sz && typeof sz === "object") {
        sx = num(sz.x, num(sz.w, num(sz.width, 400)));
        sy = num(sz.y, num(sz.h, num(sz.height, sx)));
      }
      if (!(sx > 10)) sx = 400;
      if (!(sy > 10)) sy = sx;
      var pts0 = [mem.base].concat(mem.cands);
      var minx = Infinity, maxx = -Infinity, miny = Infinity, maxy = -Infinity;
      for (var pi0 = 0; pi0 < pts0.length; pi0++) {
        var pp = pts0[pi0];
        if (!pp || !isFinite(pp.x) || !isFinite(pp.y)) continue;
        minx = Math.min(minx, pp.x);
        maxx = Math.max(maxx, pp.x);
        miny = Math.min(miny, pp.y);
        maxy = Math.max(maxy, pp.y);
      }
      if (!isFinite(minx)) { minx = 0; maxx = sx; miny = 0; maxy = sy; }
      var cx0 = (minx + maxx) / 2;
      var cy0 = (miny + maxy) / 2;
      var centered = (minx < -8 && Math.abs(cx0) < sx * 0.35) ||
                     (miny < -8 && Math.abs(cy0) < sy * 0.35);
      if (centered) {
        mem.worldMinX = -sx / 2;
        mem.worldMaxX = sx / 2;
        mem.worldMinY = -sy / 2;
        mem.worldMaxY = sy / 2;
      } else {
        mem.worldMinX = 0;
        mem.worldMaxX = sx;
        mem.worldMinY = 0;
        mem.worldMaxY = sy;
      }
      mem.res = 2.0;
      mem.gx0 = mem.worldMinX;
      mem.gy0 = mem.worldMinY;
      mem.gW = Math.ceil((mem.worldMaxX - mem.worldMinX) / mem.res) + 1;
      mem.gH = Math.ceil((mem.worldMaxY - mem.worldMinY) / mem.res) + 1;
      mem.grid = new Uint8Array(mem.gW * mem.gH);
      mem.posX = num(obs.x, mem.base.x);
      mem.posY = num(obs.y, mem.base.y);
      mem.lastGpsX = mem.posX;
      mem.lastGpsY = mem.posY;
      mem.lastPosX = mem.posX;
      mem.lastPosY = mem.posY;
      mem.odoX = mem.posX;
      mem.odoY = mem.posY;
      mem.gpsStill = 0;
      mem.hBias = 0;
      mem.hJumpOffset = 0;
      mem.biasUpdates = 0;
      mem.lastReportedRaw = norm180(num(obs.heading, 0));
      mem.lastReportedEff = mem.lastReportedRaw;
      mem.lastT = num(obs.t, 0);
      mem.wL = { i: 0 };
      mem.wR = { i: 0 };
      mem.lastBattery = num(obs.battery, 1);
      mem.energyPerM = 0.004;
      mem.energySamples = 0;
      mem.sample = null;
      mem.target = null;
      mem.search = null;
      mem.nav = null;
      mem.recoverUntil = -1;
      mem.bumpTime = -99;
      mem.bumpTurn = 1;
      mem.bumpCount = 0;
      mem.lastBumpT = -99;
      mem.cautiousUntil = -1;
      mem.explorePts = null;
      mem.exploreDone = [];
      mem.prevCarried = Math.round(num(obs.carried, 0));
      mem.returning = false;
      mem.chargeStart = null;
      mem.timeLeftLast = num(obs.timeLeft, mem.missionSeconds);
      mem.deliveredLast = num(obs.delivered, 0);
    }

    var t = num(obs.t, 0);
    var dt = t - num(mem.lastT, t - 0.1);
    if (!(dt > 0) || dt > 0.5) dt = 0.1;
    mem.dt = dt;

    var gx = num(obs.x, mem.posX || 0);
    var gy = num(obs.y, mem.posY || 0);
    var repRaw = norm180(num(obs.heading, mem.lastReportedRaw || 0));
    var wl = num(obs.wheelLeft, 0);
    var wr = num(obs.wheelRight, 0);
    var wheelV = (wl + wr) / 2;
    var expectedYaw = (wr - wl) / 0.6 * R2D * dt;
    var dhRaw = norm180(repRaw - num(mem.lastReportedRaw, repRaw));
    if (Math.abs(dhRaw) > 70 && Math.abs(expectedYaw) < 30) {
      mem.hJumpOffset = norm180((mem.hJumpOffset || 0) - dhRaw);
    }
    var repEff = norm180(repRaw + (mem.hJumpOffset || 0));

    var oldTrueH = norm180((mem.lastReportedEff || repEff) + (mem.hBias || 0));
    var hForOdo = norm180((oldTrueH + (repEff + (mem.hBias || 0))) / 2);
    mem.odoX += wheelV * Math.cos(hForOdo * D2R) * dt;
    mem.odoY += wheelV * Math.sin(hForOdo * D2R) * dt;

    var sameGps = Math.abs(gx - mem.lastGpsX) < 0.002 && Math.abs(gy - mem.lastGpsY) < 0.002;
    if (!sameGps || Math.abs(wheelV) < 0.05) mem.gpsStill = 0;
    else mem.gpsStill += dt;
    var useOdo = mem.gpsStill > 2.0 && Math.abs(wheelV) > 0.08;
    var px, py;
    if (useOdo) {
      px = mem.odoX;
      py = mem.odoY;
    } else {
      px = gx;
      py = gy;
      var mdx = gx - mem.lastGpsX;
      var mdy = gy - mem.lastGpsY;
      var md = Math.sqrt(mdx * mdx + mdy * mdy);
      if (!sameGps && md > 0.15 && wheelV > 0.1) {
        var moveAng = Math.atan2(mdy, mdx) * R2D;
        var avgRep = norm180((mem.lastReportedEff || repEff) +
                             norm180(repEff - (mem.lastReportedEff || repEff)) / 2);
        var rawBias = norm180(moveAng - avgRep);
        var diffB = norm180(rawBias - (mem.hBias || 0));
        var alpha = (mem.biasUpdates || 0) < 5 ? 0.35 : 0.06;
        var stepB = diffB * alpha;
        mem.hBias = norm180((mem.hBias || 0) + stepB);
        if (Math.abs(stepB) > 10) mem.grid.fill(0);
        mem.biasUpdates = (mem.biasUpdates || 0) + 1;
      }
      mem.odoX = px;
      mem.odoY = py;
    }
    mem.posX = px;
    mem.posY = py;
    var trueH = norm180(repEff + (mem.hBias || 0));
    updateMap(mem, px, py, trueH, obs.rays);

    var battery = num(obs.battery, mem.lastBattery || 1);
    var oldBattery = num(mem.lastBattery, battery);
    var moveDist = dist(px, py, num(mem.lastPosX, px), num(mem.lastPosY, py));
    if (moveDist > 0.08 && dt > 0) {
      var drop = oldBattery - battery;
      if (drop > 0 && drop < 0.5) {
        var eEst = drop / moveDist;
        if (eEst > 0.00005 && eEst < 0.2) {
          if (!mem.energySamples) mem.energyPerM = eEst;
          else mem.energyPerM = mem.energyPerM * 0.97 + eEst * 0.03;
          mem.energySamples++;
        }
      }
    }
    mem.lastBattery = battery;
    mem.lastPosX = px;
    mem.lastPosY = py;

    var carried = Math.round(num(obs.carried, 0));
    var prevCarried = Math.round(num(mem.prevCarried, 0));
    if (carried < prevCarried) mem.returning = false;
    mem.prevCarried = carried;
    var baseD = dist(px, py, mem.base.x, mem.base.y);
    var timeLeft = num(obs.timeLeft, mem.missionSeconds - (t - mem.t0));
    if (!isFinite(timeLeft) || timeLeft < 0) timeLeft = 0;
    mem.timeLeftLast = timeLeft;

    mem.lastGpsX = gx;
    mem.lastGpsY = gy;
    mem.lastReportedRaw = repRaw;
    mem.lastReportedEff = repEff;
    mem.lastT = t;

    if (obs.bumped) {
      mem.bumpTime = t;
      mem.recoverUntil = t + 1.6;
      var lSum = 0, rSum = 0;
      if (obs.rays && obs.rays.length >= 9) {
        lSum = num(obs.rays[5], 15) + num(obs.rays[6], 15) + num(obs.rays[7], 15) + num(obs.rays[8], 15);
        rSum = num(obs.rays[0], 15) + num(obs.rays[1], 15) + num(obs.rays[2], 15) + num(obs.rays[3], 15);
      }
      mem.bumpTurn = lSum > rSum ? 1 : -1;
      if (t - num(mem.lastBumpT, -99) < 3) mem.bumpCount = (mem.bumpCount || 0) + 1;
      else mem.bumpCount = 1;
      mem.lastBumpT = t;
      if (mem.bumpCount >= 3) mem.cautiousUntil = t + 20;
      mem.nav = null;
      mem.search = null;
      if (mem.sample && mem.sample.active) {
        mem.sample.active = false;
        mem.sample = null;
      }
    }

    if (mem.recoverUntil > t) {
      var phase = t - mem.bumpTime;
      var dir = mem.bumpTurn || 1;
      var vv, om;
      if (phase < 0.55) {
        vv = -0.75;
        om = dir * 1.2;
      } else if (phase < 1.3) {
        vv = 0.10;
        om = dir * 2.0;
      } else {
        vv = 0.05;
        om = dir * 1.0;
      }
      return rawDrive(obs, mem, vv, om, false);
    }

    if (mem.sample && mem.sample.active) {
      var sdb = dist(px, py, mem.base.x, mem.base.y);
      var drillNow = num(obs.drilling, 0);
      if ((battery < 0.04 || (carried > 0 && timeLeft < sdb / 1.0 + 12 && drillNow < 5.5)) && sdb > 15) {
        mem.sample.active = false;
        mem.sample = null;
      } else {
        var rsample = updateSampling(obs, mem, t, carried);
        if (rsample) return rsample;
      }
      carried = Math.round(num(obs.carried, 0));
    }

    baseD = dist(px, py, mem.base.x, mem.base.y);

    if (baseD < 3.0 || obs.docked) {
      if (carried > 0) {
        mem.target = null;
        mem.search = null;
        mem.nav = null;
        return holdStillCmd(obs, mem, false);
      } else {
        mem.returning = false;
        if (shouldCharge(obs, mem, t, timeLeft)) {
          return holdStillCmd(obs, mem, false);
        }
      }
    } else {
      mem.chargeStart = null;
    }

    var ePerM = mem.energySamples > 3 ? mem.energyPerM : Math.max(mem.energyPerM, 0.0025);
    var req = baseD * ePerM * (1 + 0.12 * carried) * 1.8 + 0.06;
    var urgentBattery = false;
    if (baseD > 10 && battery < req) urgentBattery = true;
    if (battery < 0.08 && baseD > 5) urgentBattery = true;
    if (battery < 0.22 && baseD > 30) urgentBattery = true;

    var returnTime = baseD / 1.15 + 15;
    var mustReturn = false;
    if (carried >= mem.cap) mustReturn = true;
    if (carried > 0 && timeLeft < returnTime * 1.15 + 8) mustReturn = true;
    if (urgentBattery && (carried > 0 || timeLeft > 60)) mustReturn = true;
    if (urgentBattery && carried === 0 && battery < 0.04) mustReturn = true;

    if (mustReturn && baseD > 2.8) {
      mem.returning = true;
      mem.target = { kind: "base" };
      mem.search = null;
      mem.nav = null;
      return goHome(obs, mem, t);
    }
    if (mem.returning && carried > 0 && baseD > 2.8) {
      return goHome(obs, mem, t);
    }
    if (timeLeft < 8 && carried === 0) return holdStillCmd(obs, mem, false);

    if (obs.site && carried < mem.cap && !mem.returning) {
      var take = shouldSample(obs, mem, obs.site, t, carried, baseD);
      if (take && !(baseD < 8 && carried > 0)) {
        startSample(obs, mem, obs.site, t);
        var rs2 = updateSampling(obs, mem, t, carried);
        if (rs2) return rs2;
        carried = Math.round(num(obs.carried, 0));
      }
    }

    if (mem.search) {
      var rsearch = controlSearch(obs, mem, t, carried);
      if (rsearch) return rsearch;
      carried = Math.round(num(obs.carried, 0));
    }

    if (mem.target) {
      if (mem.target.kind === "cand") {
        var tcand = mem.target.cand;
        if (!tcand || tcand.status !== 0) {
          mem.target = null;
          mem.nav = null;
        }
      }
      if (mem.target && mem.target.kind === "explore") {
        if (mem.exploreDone && mem.exploreDone[mem.target.idx]) mem.target = null;
      }
    }

    if (mem.target) {
      if (mem.target.kind === "base") {
        return goHome(obs, mem, t);
      } else if (mem.target.kind === "cand") {
        var ctar = mem.target.cand;
        var dTar = dist(px, py, ctar.x, ctar.y);
        if (!mem.target.best || dTar < mem.target.best - 1.0) {
          mem.target.best = dTar;
          mem.target.lastProg = t;
        }
        if (!mem.target.lastProg) mem.target.lastProg = t;
        if (dTar < 3.2) {
          startSearch(mem, ctar, t);
          var rchk = controlSearch(obs, mem, t, carried);
          if (rchk) return rchk;
          carried = Math.round(num(obs.carried, 0));
        } else if (t - mem.target.lastProg > 32 && dTar > 8) {
          ctar.status = 2;
          ctar.false = true;
          mem.target = null;
          mem.search = null;
          mem.nav = null;
          return holdStillCmd(obs, mem, false);
        } else {
          var spd = 2.1 - 0.10 * carried;
          if (num(obs.battery, 1) < 0.25) spd = Math.min(spd, 1.4);
          if (mem.cautiousUntil > t) spd = Math.min(spd, 1.2);
          var rnav = navTo(obs, mem, ctar.x, ctar.y, Math.max(0.8, spd), 1.0);
          return rnav.cmd;
        }
      } else if (mem.target.kind === "explore") {
        var ex = mem.target.x;
        var ey = mem.target.y;
        var dEx = dist(px, py, ex, ey);
        if (!mem.target.best || dEx < mem.target.best - 1.0) {
          mem.target.best = dEx;
          mem.target.lastProg = t;
        }
        if (!mem.target.lastProg) mem.target.lastProg = t;
        if (dEx < 4.0) {
          mem.exploreDone[mem.target.idx] = 1;
          mem.target = null;
          mem.nav = null;
          return holdStillCmd(obs, mem, false);
        }
        if (t - mem.target.lastProg > 30 && dEx > 7) {
          mem.exploreDone[mem.target.idx] = 1;
          mem.target = null;
          mem.nav = null;
          return holdStillCmd(obs, mem, false);
        }
        var rEx = navTo(obs, mem, ex, ey, 1.7, 1.0);
        return rEx.cmd;
      }
    }

    if (mem.search) {
      var rsearch2 = controlSearch(obs, mem, t, carried);
      if (rsearch2) return rsearch2;
      carried = Math.round(num(obs.carried, 0));
    }

    if (!mem.target && !mem.search) {
      if (carried > 0 && baseD < 12) {
        mem.returning = true;
        return goHome(obs, mem, t);
      }
      var cand = chooseCandidate(obs, mem, t, carried, baseD);
      if (cand) {
        var d0 = dist(px, py, cand.x, cand.y);
        mem.target = {
          kind: "cand",
          cand: cand,
          best: d0,
          lastProg: t
        };
        mem.nav = null;
        mem.search = null;
        if (d0 < 3.2) {
          startSearch(mem, cand, t);
          var rnew = controlSearch(obs, mem, t, carried);
          if (rnew) return rnew;
          carried = Math.round(num(obs.carried, 0));
        } else {
          var sp2 = 2.1 - 0.10 * carried;
          if (num(obs.battery, 1) < 0.25) sp2 = Math.min(sp2, 1.4);
          if (mem.cautiousUntil > t) sp2 = Math.min(sp2, 1.2);
          var rnav2 = navTo(obs, mem, cand.x, cand.y, Math.max(0.8, sp2), 1.0);
          return rnav2.cmd;
        }
      } else {
        if (carried > 0) {
          mem.returning = true;
          return goHome(obs, mem, t);
        }
        var ep = chooseExplore(obs, mem, t);
        if (ep) {
          var de0 = dist(px, py, ep.x, ep.y);
          mem.target = {
            kind: "explore",
            x: ep.x,
            y: ep.y,
            idx: ep.idx,
            best: de0,
            lastProg: t
          };
          mem.nav = null;
          var rex0 = navTo(obs, mem, ep.x, ep.y, 1.7, 1.0);
          return rex0.cmd;
        }
        return holdStillCmd(obs, mem, false);
      }
    }

    if (mem.search) {
      var rlast = controlSearch(obs, mem, t, carried);
      if (rlast) return rlast;
    }

    return holdStillCmd(obs, mem, false);
  } catch (e) {
    mem.errCount = (mem.errCount || 0) + 1;
    mem.lastError = String(e);
    return { left: 0, right: 0, drill: false };
  }
}

var D2R = Math.PI / 180;
var R2D = 180 / Math.PI;
var RAY_A = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function num(v, d) {
  v = +v;
  return isFinite(v) ? v : d;
}
function clamp(v, a, b) {
  v = +v;
  if (!isFinite(v)) return a;
  return v < a ? a : (v > b ? b : v);
}
function norm180(a) {
  a = +a;
  if (!isFinite(a)) return 0;
  a = ((a + 180) % 360 + 360) % 360 - 180;
  return a;
}
function dist(x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
}
function clampWorldX(mem, x) {
  return clamp(x, mem.worldMinX + 1.5, mem.worldMaxX - 1.5);
}
function clampWorldY(mem, y) {
  return clamp(y, mem.worldMinY + 1.5, mem.worldMaxY - 1.5);
}

function initMission(obs, mem) {
  mem.init = 1;
  mem.t0 = num(obs.t, 0);
  var mission = obs.mission || {};
  mem.seconds = num(mission.seconds, 1200);
  mem.cap = Math.round(num(mission.capacity, 5));
  if (!(mem.cap > 0)) mem.cap = 5;

  var mb = mission.base || { x: num(obs.x, 0), y: num(obs.y, 0) };
  mem.base = { x: num(mb.x, num(obs.x, 0)), y: num(mb.y, num(obs.y, 0)) };

  var hs = mission.hints || [];
  mem.hints = [];
  var vals = [];
  for (var i = 0; i < hs.length; i++) {
    var h = hs[i] || {};
    var est = num(h.estimate, 1);
    if (!(est > 0)) est = 1;
    mem.hints.push({
      x: num(h.x, mem.base.x),
      y: num(h.y, mem.base.y),
      est: est,
      id: mem.hints.length,
      status: 0
    });
    vals.push(est);
  }
  vals.sort(function (a, b) { return a - b; });
  mem.medEst = vals.length ? vals[Math.floor(vals.length / 2)] : 1;

  var sx = 400, sy = 400;
  var sz = mission.size;
  if (typeof sz === "number") {
    sx = sy = sz;
  } else if (Array.isArray(sz)) {
    sx = num(sz[0], 400);
    sy = num(sz[1], sx);
  } else if (sz && typeof sz === "object") {
    sx = num(sz.x, num(sz.width, 400));
    sy = num(sz.y, num(sz.height, sx));
  }
  if (!(sx > 20)) sx = 400;
  if (!(sy > 20)) sy = sx;

  var minx = mem.base.x, maxx = mem.base.x, miny = mem.base.y, maxy = mem.base.y;
  for (var j = 0; j < mem.hints.length; j++) {
    var hh = mem.hints[j];
    minx = Math.min(minx, hh.x);
    maxx = Math.max(maxx, hh.x);
    miny = Math.min(miny, hh.y);
    maxy = Math.max(maxy, hh.y);
  }
  var centered = (minx < -8 || miny < -8 || maxx > sx + 8 || maxy > sy + 8);
  if (centered) {
    mem.worldMinX = -sx / 2;
    mem.worldMaxX = sx / 2;
    mem.worldMinY = -sy / 2;
    mem.worldMaxY = sy / 2;
  } else {
    mem.worldMinX = 0;
    mem.worldMaxX = sx;
    mem.worldMinY = 0;
    mem.worldMaxY = sy;
  }
  mem.worldW = mem.worldMaxX - mem.worldMinX;
  mem.worldH = mem.worldMaxY - mem.worldMinY;

  mem.px = num(obs.x, mem.base.x);
  mem.py = num(obs.y, mem.base.y);
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastGpsX = mem.px;
  mem.lastGpsY = mem.py;
  mem.gpsFrozen = 0;
  mem.gpsX = mem.px;
  mem.gpsY = mem.py;

  mem.rawPrev = norm180(num(obs.heading, 0));
  mem.jumpOff = 0;
  mem.jumpN = 0;
  mem.bias = 0;
  mem.biasN = 0;
  mem.yaw = mem.rawPrev;

  mem.wcL = { i: 0 };
  mem.wcR = { i: 0 };
  mem.lastWheelL = num(obs.wheelLeft, 0);
  mem.lastWheelR = num(obs.wheelRight, 0);
  mem.lastBattery = num(obs.battery, 1);
  mem.ePerM = 0.004;
  mem.eN = 0;

  mem.lastT = mem.t0;
  mem.dt = 0.1;
  mem.target = null;
  mem.search = null;
  mem.sample = null;
  mem.returning = false;
  mem.chargeMode = 0;
  mem.bump = null;
  mem.escape = null;
  mem.cautiousUntil = 0;
  mem.calibrated = false;
  mem.calibUntil = mem.t0 + 1.2;
  mem.explorePts = null;
  mem.lastCarried = Math.round(num(obs.carried, 0));
  mem.lastDelivered = num(obs.delivered, 0);
  mem.timeLeftLast = num(obs.timeLeft, mem.seconds);
}

function updateState(obs, mem, t, dt) {
  var oldPx = mem.px, oldPy = mem.py;
  var raw = norm180(num(obs.heading, mem.rawPrev));
  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  var oldL = num(mem.lastWheelL, wl);
  var oldR = num(mem.lastWheelR, wr);
  var avgL = (wl + oldL) / 2;
  var avgR = (wr + oldR) / 2;
  var avgV = (avgL + avgR) / 2;
  var yawDelta = (avgR - avgL) / 0.6 * R2D * dt;

  var dhRaw = norm180(raw - mem.rawPrev);
  if (Math.abs(dhRaw) > 70 && Math.abs(yawDelta) < 25) {
    mem.jumpOff = norm180(mem.jumpOff - dhRaw);
    mem.jumpN++;
  }
  var effRaw = norm180(raw + mem.jumpOff);

  mem.yaw = norm180(mem.yaw + yawDelta);

  var comp = norm180(effRaw + mem.bias);
  var dcomp = norm180(comp - mem.yaw);
  if (Math.abs(dcomp) < 60) {
    mem.yaw = norm180(mem.yaw + dcomp * 0.25);
  } else if (Math.abs(dcomp) < 110) {
    mem.yaw = norm180(mem.yaw + dcomp * 0.03);
  }

  var gx = num(obs.x, mem.px);
  var gy = num(obs.y, mem.py);
  var stillGps = Math.abs(gx - mem.lastGpsX) < 0.006 && Math.abs(gy - mem.lastGpsY) < 0.006;
  if (stillGps && Math.abs(avgV) > 0.12) {
    mem.gpsFrozen += dt;
  } else {
    mem.gpsFrozen = 0;
  }

  if (mem.gpsFrozen > 1.2) {
    mem.px += avgV * Math.cos(mem.yaw * D2R) * dt;
    mem.py += avgV * Math.sin(mem.yaw * D2R) * dt;
  } else {
    mem.px = gx;
    mem.py = gy;
  }
  mem.px = clamp(mem.px, mem.worldMinX + 0.2, mem.worldMaxX - 0.2);
  mem.py = clamp(mem.py, mem.worldMinY + 0.2, mem.worldMaxY - 0.2);

  var gd = dist(gx, gy, mem.lastGpsX, mem.lastGpsY);
  if (gd > 0.07 && avgV > 0.25 && Math.abs(avgR - avgL) < 1.2) {
    var moveAng = Math.atan2(gy - mem.lastGpsY, gx - mem.lastGpsX) * R2D;
    var sampleB = norm180(moveAng - effRaw);
    var bd = norm180(sampleB - mem.bias);
    if (Math.abs(bd) < 140 || mem.biasN < 5) {
      var alpha = mem.biasN < 5 ? 0.30 : 0.03;
      var step = clamp(bd * alpha, -20, 20);
      mem.bias = norm180(mem.bias + step);
      mem.biasN++;
      var c2 = norm180(effRaw + mem.bias);
      var d2 = norm180(c2 - mem.yaw);
      if (Math.abs(d2) < 100) mem.yaw = norm180(mem.yaw + d2 * 0.5);
    }
  }

  var battery = num(obs.battery, mem.lastBattery);
  var moveD = dist(mem.px, mem.py, oldPx, oldPy);
  if (moveD > 0.05 && mem.lastBattery != null) {
    var drop = mem.lastBattery - battery;
    if (drop > 0 && drop < 0.25) {
      var e = drop / moveD;
      if (e > 0.00002 && e < 0.20) {
        if (!mem.eN) mem.ePerM = e;
        else mem.ePerM = mem.ePerM * 0.97 + e * 0.03;
        mem.eN++;
      }
    }
  }

  mem.lastBattery = battery;
  mem.lastWheelL = wl;
  mem.lastWheelR = wr;
  mem.rawPrev = raw;
  mem.lastGpsX = gx;
  mem.lastGpsY = gy;
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastT = t;
}

function wheelCmd(st, target, actual, dt) {
  if (!st) st = { i: 0 };
  if (!(dt > 0) || dt > 0.5) dt = 0.1;
  target = num(target, 0);
  actual = num(actual, 0);
  var err = target - actual;
  st.i += err * dt;
  st.i = clamp(st.i, -1.5, 1.5);

  if (Math.abs(target) < 0.03) {
    return clamp(-actual * 1.3 + st.i * 0.10, -1, 1);
  }
  var ff = target / 2.8;
  var u = ff + 0.85 * err + 0.28 * st.i;
  if (target > 0.03) u += 0.035;
  else if (target < -0.03) u -= 0.035;
  return clamp(u, -1, 1);
}

function setWheels(obs, mem, tl, tr, drill) {
  var dt = mem.dt || 0.1;
  var l = wheelCmd(mem.wcL, tl, num(obs.wheelLeft, 0), dt);
  var r = wheelCmd(mem.wcR, tr, num(obs.wheelRight, 0), dt);
  return { left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: !!drill };
}

function holdCmd(obs, mem, drill) {
  var dt = mem.dt || 0.1;
  var pitch = num(obs.pitch, 0);
  var slope = clamp(pitch * 0.020, -0.35, 0.35);
  var l = wheelCmd(mem.wcL, 0, num(obs.wheelLeft, 0), dt) + slope;
  var r = wheelCmd(mem.wcR, 0, num(obs.wheelRight, 0), dt) + slope;
  return { left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: !!drill };
}

function applyControl(obs, mem, err, wantV) {
  var rays = obs.rays || [];
  var frontMin = 15;
  var leftMin = 15;
  var rightMin = 15;
  var rep = 0;
  var i, r, a, w;
  for (i = 0; i < 9 && i < rays.length; i++) {
    r = num(rays[i], 15);
    if (r > 15) r = 15;
    if (r < 0) r = 0;
    if (RAY_A[i] >= -40 && RAY_A[i] <= 40) frontMin = Math.min(frontMin, r);
    if (RAY_A[i] >= 20) leftMin = Math.min(leftMin, r);
    if (RAY_A[i] <= -20) rightMin = Math.min(rightMin, r);
    if (r < 5.5) {
      a = RAY_A[i] * D2R;
      w = (5.5 - r) / 5.5;
      w *= w;
      rep += -Math.sin(a) * w * 1.8;
      if (Math.abs(RAY_A[i]) < 25) {
        rep += clamp((leftMin - rightMin) * 0.25, -1, 1) * w;
      }
    }
  }
  var avoid = clamp(rep * 35, -75, 75);
  var errA = norm180(err + avoid);

  var cap = 3.0;
  if (frontMin < 0.7) cap = 0.0;
  else if (frontMin < 1.2) cap = 0.25;
  else if (frontMin < 2.0) cap = 0.60;
  else if (frontMin < 3.2) cap = 1.20;
  else if (frontMin < 4.5) cap = 2.00;
  if (leftMin < 0.35 || rightMin < 0.35) cap = Math.min(cap, 0.7);

  var v = Math.min(num(wantV, 0), cap);
  if (mem.cautiousUntil > num(obs.t, 0)) v = Math.min(v, 0.9);
  if (num(obs.battery, 1) < 0.18) v = Math.min(v, 0.8);

  var ae = Math.abs(errA);
  if (ae > 140) v = Math.min(v, 0.15);
  else if (ae > 90) v = Math.min(v, 0.35);
  else if (ae > 50) v *= 0.55;
  else if (ae > 25) v *= 0.80;

  var omega = clamp(errA * D2R * 2.0, -2.2, 2.2);
  var tl = v - omega * 0.3;
  var tr = v + omega * 0.3;
  tl = clamp(tl, -2.9, 2.9);
  tr = clamp(tr, -2.9, 2.9);
  return setWheels(obs, mem, tl, tr, false);
}

function rawDrive(obs, mem, v, omega, drill) {
  var tl = clamp(v - omega * 0.3, -2.9, 2.9);
  var tr = clamp(v + omega * 0.3, -2.9, 2.9);
  return setWheels(obs, mem, tl, tr, drill);
}

function driveToPoint(obs, mem, x, y, speed) {
  var d = dist(mem.px, mem.py, x, y);
  if (d < 0.3) return holdCmd(obs, mem, false);
  var bearing = Math.atan2(y - mem.py, x - mem.px) * R2D;
  var err = norm180(bearing - mem.yaw);
  var sp = Math.min(speed, 0.35 + d * 0.9);
  return applyControl(obs, mem, err, sp);
}

function findHint(mem, id) {
  for (var i = 0; i < mem.hints.length; i++) {
    if (mem.hints[i].id === id) return mem.hints[i];
  }
  return null;
}

function leftClearance(obs) {
  var rays = obs.rays || [];
  var v = 15;
  for (var i = 4; i < 9 && i < rays.length; i++) v = Math.min(v, num(rays[i], 15));
  return v;
}
function rightClearance(obs) {
  var rays = obs.rays || [];
  var v = 15;
  for (var i = 0; i < 5 && i < rays.length; i++) v = Math.min(v, num(rays[i], 15));
  return v;
}

function makeSearchPoints(mem, h, high) {
  var pts = [];
  var R = high ? 22 : 15;
  var id = num(h.id, 0);
  pts.push({ x: clampWorldX(mem, h.x), y: clampWorldY(mem, h.y) });
  for (var rr = 6; rr <= R + 0.1; rr += 6) {
    var n = Math.max(5, Math.round(2 * Math.PI * rr / 10));
    for (var k = 0; k < n; k++) {
      var ang = id * 0.7 + (rr / 6) * 0.8 + 2 * Math.PI * k / n;
      pts.push({
        x: clampWorldX(mem, h.x + rr * Math.cos(ang)),
        y: clampWorldY(mem, h.y + rr * Math.sin(ang))
      });
    }
  }
  return pts;
}

function startSearch(obs, mem, t) {
  if (!mem.target || mem.target.type !== "hint") return;
  var h = findHint(mem, mem.target.id);
  if (!h || h.status !== 0) {
    mem.target = null;
    mem.search = null;
    return;
  }
  var high = num(h.est, 1) > (mem.medEst || 1) * 1.25;
  mem.search = {
    hintId: h.id,
    pts: makeSearchPoints(mem, h, high),
    idx: 0,
    start: t,
    ptStart: t,
    maxTime: high ? 52 : 32,
    high: high
  };
  mem.target.lastProg = t;
}

function finishSearch(mem) {
  if (mem.search) {
    var h = findHint(mem, mem.search.hintId);
    if (h && h.status === 0) h.status = 2;
  }
  mem.search = null;
  if (mem.target && mem.target.type === "hint") mem.target = null;
}

function controlSearch(obs, mem, t, carried, baseD, timeLeft, battery) {
  var s = mem.search;
  if (!s) return null;
  if (t - s.start > s.maxTime || (timeLeft < baseD / 0.8 + 18 && carried > 0) || timeLeft < 20) {
    finishSearch(mem);
    return null;
  }
  if (s.idx >= s.pts.length) {
    finishSearch(mem);
    return null;
  }
  var p = s.pts[s.idx];
  var d = dist(mem.px, mem.py, p.x, p.y);
  if (d < 2.0 || t - s.ptStart > 10.0) {
    s.idx++;
    s.ptStart = t;
    var guard = 0;
    while (s.idx < s.pts.length && guard++ < 20) {
      p = s.pts[s.idx];
      if (dist(mem.px, mem.py, p.x, p.y) < 1.8) {
        s.idx++;
        continue;
      }
      break;
    }
    if (s.idx >= s.pts.length) {
      finishSearch(mem);
      return null;
    }
    p = s.pts[s.idx];
  }
  var sp = s.high ? 1.7 : 1.5;
  if (carried > 0) sp -= 0.06 * carried;
  if (battery < 0.25) sp = Math.min(sp, 1.0);
  return driveToPoint(obs, mem, p.x, p.y, Math.max(0.7, sp));
}

function startSample(obs, mem, t, carried) {
  var site = obs.site;
  if (!site) return false;
  var bw = norm180(mem.yaw + num(site.bearing, 0));
  var a = bw * D2R;
  var sd = num(site.distance, 0);
  var sx = mem.px + sd * Math.cos(a);
  var sy = mem.py + sd * Math.sin(a);
  mem.sample = {
    active: true,
    startT: t,
    carried0: carried,
    value: num(site.value, 0),
    sx: sx,
    sy: sy,
    lastSeen: t,
    bestD: sd
  };
  mem.search = null;
  return true;
}

function completeSample(obs, mem) {
  var s = mem.sample;
  if (!s) return;
  var sx = s.sx, sy = s.sy;
  var best = null, bd = 1e9;
  for (var i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.status !== 0) continue;
    var d = dist(h.x, h.y, sx, sy);
    if (d < bd) {
      bd = d;
      best = h;
    }
  }
  if (best && bd < 28) best.status = 2;

  if (mem.target && mem.target.type === "hint") {
    if (dist(mem.target.x, mem.target.y, mem.px, mem.py) < 35) {
      var th = findHint(mem, mem.target.id);
      if (th) th.status = 2;
      mem.target = null;
      mem.search = null;
    }
  }
  mem.sample = null;
}

function controlSample(obs, mem, t, carried, baseD, timeLeft, battery) {
  var s = mem.sample;
  if (!s || !s.active) {
    mem.sample = null;
    return null;
  }
  if (carried > s.carried0) {
    completeSample(obs, mem);
    return null;
  }
  if (carried >= mem.cap) {
    mem.sample = null;
    return null;
  }
  if (battery < 0.055 && baseD > 10) {
    mem.sample = null;
    return null;
  }
  if (timeLeft < baseD / 0.7 + 10 && carried > 0) {
    mem.sample = null;
    return null;
  }
  if (t - s.startT > 20 && carried <= s.carried0) {
    mem.sample = null;
    return null;
  }

  var site = obs.site;
  var d;
  if (site) {
    s.lastSeen = t;
    s.value = num(site.value, s.value);
    var sd = num(site.distance, 99);
    s.bestD = Math.min(s.bestD, sd);
    var bw = norm180(mem.yaw + num(site.bearing, 0));
    var a = bw * D2R;
    s.sx = mem.px + sd * Math.cos(a);
    s.sy = mem.py + sd * Math.sin(a);
    d = sd;
  } else {
    d = dist(mem.px, mem.py, s.sx, s.sy);
  }

  var avgSpeed = Math.abs((num(obs.wheelLeft, 0) + num(obs.wheelRight, 0)) / 2);
  var drillNow = num(obs.drilling, 0);

  if (d > 1.48) {
    var err;
    if (site) {
      err = norm180(num(site.bearing, 0));
    } else {
      var bearing = Math.atan2(s.sy - mem.py, s.sx - mem.px) * R2D;
      err = norm180(bearing - mem.yaw);
    }
    var sp = clamp((d - 1.0) * 0.9, 0.15, 0.9);
    return applyControl(obs, mem, err, sp);
  }

  if (avgSpeed > 0.14 || d > 1.55) {
    return holdCmd(obs, mem, false);
  }
  return holdCmd(obs, mem, true);
}

function shouldSample(obs, mem, carried, baseD, timeLeft, battery) {
  if (!obs.site) return false;
  if (carried >= mem.cap) return false;
  if (mem.returning) return false;
  if (timeLeft < baseD / 0.65 + 14) return false;
  if (battery < 0.06) return false;
  var val = num(obs.site.value, 0);
  if (carried > 0 && carried >= mem.cap - 1) {
    var avg = num(obs.carriedValue, 0) / Math.max(1, carried);
    if (val < avg * 0.10 && baseD > 25) return false;
  }
  return true;
}

function needReturn(obs, mem, carried, baseD, timeLeft, battery) {
  if (carried <= 0) return false;
  if (carried >= mem.cap) return true;
  var tNeed = baseD / 0.75 + 18;
  if (timeLeft < tNeed + 8) return true;
  var eNeed = baseD * (mem.ePerM || 0.004) * (1 + 0.15 * carried) * 2.2 + 0.06;
  if (battery < eNeed && baseD > 8) return true;
  if (battery < 0.20 && baseD > 8) return true;
  if (timeLeft < 120 && baseD < 260) return true;
  return false;
}

function goHome(obs, mem, t, baseD, timeLeft, battery) {
  if (baseD < 2.9 || obs.docked) return holdCmd(obs, mem, false);
  if (obs.beacon && num(obs.beacon.distance, 99) < 20) {
    var bd = num(obs.beacon.distance, baseD);
    if (bd < 2.4) return holdCmd(obs, mem, false);
    var sp = bd < 5 ? 0.8 : 1.8;
    if (num(obs.battery, 1) < 0.25) sp = Math.min(sp, 1.0);
    return applyControl(obs, mem, num(obs.beacon.bearing, 0), sp);
  }
  var speed = 1.9 - 0.05 * Math.round(num(obs.carried, 0));
  if (battery < 0.25) speed = Math.min(speed, 1.0);
  if (timeLeft < 80) speed = Math.min(speed, 1.3);
  return driveToPoint(obs, mem, mem.base.x, mem.base.y, Math.max(0.6, speed));
}

function initExplore(mem) {
  var pts = [];
  var step = 55;
  var margin = 22;
  var minx = mem.worldMinX + margin;
  var maxx = mem.worldMaxX - margin;
  var miny = mem.worldMinY + margin;
  var maxy = mem.worldMaxY - margin;
  for (var y = miny; y <= maxy + 0.1; y += step) {
    for (var x = minx; x <= maxx + 0.1; x += step) {
      pts.push({ x: x, y: y, done: false, idx: pts.length });
    }
  }
  if (!pts.length) {
    pts.push({ x: mem.base.x, y: mem.base.y, done: false, idx: 0 });
  }
  mem.explorePts = pts;
}

function chooseExplore(mem, obs, t) {
  if (!mem.explorePts) initExplore(mem);
  var best = null, bd = 1e9;
  for (var i = 0; i < mem.explorePts.length; i++) {
    var p = mem.explorePts[i];
    if (p.done) continue;
    var d = dist(mem.px, mem.py, p.x, p.y);
    if (d < 6) {
      p.done = true;
      continue;
    }
    if (d < bd) {
      bd = d;
      best = p;
    }
  }
  if (!best) return null;
  return {
    type: "explore",
    x: best.x,
    y: best.y,
    idx: best.idx,
    best: bd,
    lastProg: t,
    start: t
  };
}

function chooseNext(obs, mem, t, carried, baseD, timeLeft, battery) {
  var best = null;
  var bestScore = -1e18;
  var bestDetour = 0;
  for (var i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.status !== 0) continue;
    var d = dist(mem.px, mem.py, h.x, h.y);
    var db = dist(h.x, h.y, mem.base.x, mem.base.y);
    var v = Math.max(0.1, num(h.est, 1));
    var searchCost = 18 + clamp(v / Math.max(0.001, mem.medEst) * 10, 0, 30);
    var need;
    var score;
    var detour = 0;

    if (carried > 0) {
      detour = d + db - baseD;
      if (detour < 0) detour = 0;
      need = (d + db) / 0.8 + 28 + searchCost;
      score = v / Math.pow(detour + 20 + searchCost * 0.6, 0.9);
    } else {
      need = d / 0.8 + 28 + searchCost + db * 0.25 / 0.8;
      score = v / Math.pow(d + db * 0.25 + 25 + searchCost * 0.7, 0.85);
    }
    if (timeLeft < need) continue;
    if (battery < 0.10 && d > 20) continue;
    if (timeLeft < 400) score *= 1 / (1 + d / 250);
    if (carried > 0 && detour > 110 && v < (mem.medEst || 1) * 0.7) score *= 0.4;

    if (score > bestScore) {
      bestScore = score;
      best = {
        type: "hint",
        id: h.id,
        x: h.x,
        y: h.y,
        est: v,
        best: d,
        lastProg: t,
        start: t
      };
      bestDetour = detour;
    }
  }

  if (best && carried > 0) {
    var avg = num(obs.carriedValue, 0) / Math.max(1, carried);
    if (best.est < avg * 0.20 && bestDetour > 50) return null;
    if (timeLeft < 300 && best.est < avg * 0.7 && bestDetour > 30) return null;
  }
  if (best) return best;

  if (carried > 0) return null;
  return chooseExplore(mem, obs, t);
}

function startEscape(obs, mem, t) {
  var lc = leftClearance(obs);
  var rc = rightClearance(obs);
  var dir = lc > rc ? 1 : -1;
  mem.escape = {
    start: t,
    until: t + 4.0,
    heading: norm180(mem.yaw + dir * 75)
  };
  if (mem.target) mem.target.lastProg = t;
}

function act(obs, mem) {
  try {
    if (!mem.init) initMission(obs, mem);

    var t = num(obs.t, 0);
    var dt = t - num(mem.lastT, t - 0.1);
    if (!(dt > 0) || dt > 0.5) dt = 0.1;
    mem.dt = dt;

    updateState(obs, mem, t, dt);

    var carried = Math.round(num(obs.carried, 0));
    var battery = num(obs.battery, mem.lastBattery || 1);
    var timeLeft = num(obs.timeLeft, mem.seconds - (t - mem.t0));
    if (!isFinite(timeLeft) || timeLeft < 0) timeLeft = 0;
    var baseD = dist(mem.px, mem.py, mem.base.x, mem.base.y);

    if (carried < mem.lastCarried) mem.returning = false;
    mem.lastCarried = carried;
    mem.timeLeftLast = timeLeft;

    if (obs.bumped) {
      var lc = leftClearance(obs);
      var rc = rightClearance(obs);
      mem.bump = {
        start: t,
        until: t + 1.15,
        dir: lc > rc ? 1 : -1
      };
      if (t - num(mem.lastBumpT, -99) < 4) mem.bumpCount = (mem.bumpCount || 0) + 1;
      else mem.bumpCount = 1;
      mem.lastBumpT = t;
      if (mem.bumpCount >= 3) mem.cautiousUntil = t + 18;
      mem.search = null;
      if (mem.sample && mem.sample.active) mem.sample = null;
      mem.escape = null;
    }
    if (mem.bump && t < mem.bump.until) {
      var phase = t - mem.bump.start;
      var dir = mem.bump.dir || 1;
      if (phase < 0.55) return rawDrive(obs, mem, -0.55, dir * 1.0, false);
      return rawDrive(obs, mem, 0.18, dir * 1.6, false);
    }

    if (!mem.calibrated) {
      if (t < mem.calibUntil) {
        return applyControl(obs, mem, 0, 0.75);
      }
      mem.calibrated = true;
    }

    if (mem.sample && mem.sample.active) {
      var sc = controlSample(obs, mem, t, carried, baseD, timeLeft, battery);
      if (sc) return sc;
      carried = Math.round(num(obs.carried, 0));
      mem.lastCarried = carried;
    }

    baseD = dist(mem.px, mem.py, mem.base.x, mem.base.y);

    if (baseD < 2.9 || obs.docked) {
      if (carried > 0) {
        mem.chargeMode = 0;
        return holdCmd(obs, mem, false);
      }
      mem.returning = false;
      if (mem.chargeMode) {
        if (battery < 0.90 && timeLeft > 75) {
          return holdCmd(obs, mem, false);
        }
        mem.chargeMode = 0;
      } else if (battery < 0.55 && timeLeft > 180) {
        mem.chargeMode = 1;
        return holdCmd(obs, mem, false);
      }
    } else {
      mem.chargeMode = 0;
    }

    var mustReturn = false;
    if (mem.returning && baseD > 2.9) mustReturn = true;
    if (carried > 0 && needReturn(obs, mem, carried, baseD, timeLeft, battery)) mustReturn = true;
    if (carried >= mem.cap) mustReturn = true;
    if (carried === 0 && battery < 0.18 && baseD > 12) mustReturn = true;

    if (mustReturn) {
      mem.returning = true;
      return goHome(obs, mem, t, baseD, timeLeft, battery);
    }

    if (!mem.returning && obs.site && carried < mem.cap &&
        shouldSample(obs, mem, carried, baseD, timeLeft, battery)) {
      if (startSample(obs, mem, t, carried)) {
        var sc2 = controlSample(obs, mem, t, carried, baseD, timeLeft, battery);
        if (sc2) return sc2;
        carried = Math.round(num(obs.carried, 0));
        mem.lastCarried = carried;
      }
    }

    if (mem.search) {
      var rs = controlSearch(obs, mem, t, carried, baseD, timeLeft, battery);
      if (rs) return rs;
      carried = Math.round(num(obs.carried, 0));
      mem.lastCarried = carried;
    }

    if (mem.target && mem.target.type === "hint") {
      var th0 = findHint(mem, mem.target.id);
      if (!th0 || th0.status !== 0) {
        mem.target = null;
        mem.search = null;
      }
    }

    if (!mem.target && !mem.search) {
      var next = chooseNext(obs, mem, t, carried, baseD, timeLeft, battery);
      if (next) {
        mem.target = next;
        mem.escape = null;
      } else {
        if (carried > 0) {
          mem.returning = true;
          return goHome(obs, mem, t, baseD, timeLeft, battery);
        }
        if (!mem.returning && timeLeft > 55) {
          var ex = chooseExplore(mem, obs, t);
          if (ex) mem.target = ex;
        }
        if (!mem.target) return holdCmd(obs, mem, false);
      }
    }

    if (mem.escape && t < mem.escape.until) {
      var escErr = norm180(mem.escape.heading - mem.yaw);
      return applyControl(obs, mem, escErr, 1.0);
    }

    if (mem.target) {
      if (mem.target.type === "hint") {
        var d = dist(mem.px, mem.py, mem.target.x, mem.target.y);
        if (!mem.target.best || d < mem.target.best - 0.6) {
          mem.target.best = d;
          mem.target.lastProg = t;
        }
        if (!mem.target.lastProg) mem.target.lastProg = t;

        if (d < 6.0) {
          startSearch(obs, mem, t);
          var rs2 = controlSearch(obs, mem, t, carried, baseD, timeLeft, battery);
          if (rs2) return rs2;
          carried = Math.round(num(obs.carried, 0));
          mem.lastCarried = carried;
        } else {
          if (t - mem.target.lastProg > 15 && d > 7) {
            if (d < 25) {
              startSearch(obs, mem, t);
              var rs3 = controlSearch(obs, mem, t, carried, baseD, timeLeft, battery);
              if (rs3) return rs3;
            } else if (t - mem.target.lastProg > 48) {
              var hbad = findHint(mem, mem.target.id);
              if (hbad) hbad.status = 2;
              mem.target = null;
              mem.search = null;
              return holdCmd(obs, mem, false);
            } else if (!mem.escape || t >= mem.escape.until) {
              startEscape(obs, mem, t);
              return applyControl(obs, mem, norm180(mem.escape.heading - mem.yaw), 1.0);
            }
          }

          var sp0 = 2.0 - 0.08 * carried;
          if (battery < 0.30) sp0 = Math.min(sp0, 1.2);
          if (mem.cautiousUntil > t) sp0 = Math.min(sp0, 1.1);
          return driveToPoint(obs, mem, mem.target.x, mem.target.y, Math.max(0.6, sp0));
        }
      } else if (mem.target.type === "explore") {
        var de = dist(mem.px, mem.py, mem.target.x, mem.target.y);
        if (de < 4.0 || t - mem.target.start > 75) {
          if (mem.explorePts && mem.target.idx != null && mem.explorePts[mem.target.idx]) {
            mem.explorePts[mem.target.idx].done = true;
          }
          mem.target = null;
          return holdCmd(obs, mem, false);
        }
        if (!mem.target.best || de < mem.target.best - 0.5) {
          mem.target.best = de;
          mem.target.lastProg = t;
        }
        if (t - mem.target.lastProg > 22 && de > 5) {
          if (mem.explorePts && mem.target.idx != null && mem.explorePts[mem.target.idx]) {
            mem.explorePts[mem.target.idx].done = true;
          }
          mem.target = null;
          return holdCmd(obs, mem, false);
        }
        var spe = 1.7;
        if (battery < 0.25) spe = Math.min(spe, 1.0);
        return driveToPoint(obs, mem, mem.target.x, mem.target.y, spe);
      }
    }

    if (carried > 0) {
      mem.returning = true;
      return goHome(obs, mem, t, baseD, timeLeft, battery);
    }
    return holdCmd(obs, mem, false);
  } catch (e) {
    mem.err = (mem.err || 0) + 1;
    mem.lastError = String(e);
    return { left: 0, right: 0, drill: false };
  }
}

var D2R = Math.PI / 180;
var R2D = 180 / Math.PI;
var RAY_A = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function num(v, d) {
  v = +v;
  return isFinite(v) ? v : d;
}
function clamp(v, a, b) {
  v = +v;
  if (!isFinite(v)) return a;
  return v < a ? a : (v > b ? b : v);
}
function norm180(a) {
  a = +a;
  if (!isFinite(a)) return 0;
  a = ((a + 180) % 360 + 360) % 360 - 180;
  return a;
}
function dist(x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
}

function initMission(obs, mem) {
  mem.init = true;
  mem.t0 = num(obs.t, 0);
  var m = obs.mission || {};
  var mb = m.base || {};
  mem.base = {
    x: num(mb.x, num(obs.x, 0)),
    y: num(mb.y, num(obs.y, 0))
  };
  mem.seconds = num(m.seconds, 1200);
  mem.cap = Math.round(num(m.capacity, 5));
  if (!(mem.cap > 0)) mem.cap = 5;

  mem.cands = [];
  var hs = m.hints || [];
  for (var i = 0; i < hs.length; i++) {
    var h = hs[i] || {};
    var est = num(h.estimate, 1);
    if (!(est > 0)) est = 1;
    mem.cands.push({
      x: num(h.x, mem.base.x),
      y: num(h.y, mem.base.y),
      est: est,
      id: i,
      status: 0
    });
  }
  var vals = [];
  for (i = 0; i < mem.cands.length; i++) vals.push(mem.cands[i].est);
  vals.sort(function (a, b) { return a - b; });
  mem.medEst = vals.length ? vals[Math.floor(vals.length / 2)] : 1;

  var sx = 400, sy = 400, sz = m.size;
  if (typeof sz === "number") {
    sx = sy = sz;
  } else if (Array.isArray(sz)) {
    sx = num(sz[0], 400);
    sy = num(sz[1], sx);
  } else if (sz && typeof sz === "object") {
    sx = num(sz.x, num(sz.width, 400));
    sy = num(sz.y, num(sz.height, sx));
  }
  if (!(sx > 20)) sx = 400;
  if (!(sy > 20)) sy = 400;

  var minx = mem.base.x, maxx = mem.base.x;
  var miny = mem.base.y, maxy = mem.base.y;
  for (i = 0; i < mem.cands.length; i++) {
    var c = mem.cands[i];
    if (c.x < minx) minx = c.x;
    if (c.x > maxx) maxx = c.x;
    if (c.y < miny) miny = c.y;
    if (c.y > maxy) maxy = c.y;
  }
  mem.wMinX = Math.min(0, minx - 12, -8);
  mem.wMaxX = Math.max(sx, maxx + 12, sx + 8);
  mem.wMinY = Math.min(0, miny - 12, -8);
  mem.wMaxY = Math.max(sy, maxy + 12, sy + 8);

  mem.px = num(obs.x, mem.base.x);
  mem.py = num(obs.y, mem.base.y);
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastGpsX = mem.px;
  mem.lastGpsY = mem.py;
  mem.gpsFreezeT = 0;

  mem.lastRaw = norm180(num(obs.heading, 0));
  mem.heading = mem.lastRaw;
  mem.jumpOff = 0;
  mem.bias = 0;
  mem.biasN = 0;

  mem.mL = { i: 0 };
  mem.mR = { i: 0 };
  mem.lastWl = num(obs.wheelLeft, 0);
  mem.lastWr = num(obs.wheelRight, 0);

  mem.lastBattery = num(obs.battery, 1);
  mem.ePerM = 0.002;
  mem.eN = 0;
  mem.lastT = mem.t0;
  mem.dt = 0.1;

  mem.carried0 = Math.round(num(obs.carried, 0));
  mem.samplesDone = 0;
  mem.task = null;
  mem.drill = null;
  mem.returning = false;
  mem.recoverUntil = -1;
  mem.recoverDir = 1;
  mem.lastBumpT = -99;
  mem.bumpCount = 0;
  mem.cautiousUntil = 0;

  mem.calX = mem.px;
  mem.calY = mem.py;
  mem.calRaw = mem.lastRaw;
  mem.calibActive = true;
  mem.calibStartT = mem.t0;
  mem.calibStartX = mem.px;
  mem.calibStartY = mem.py;
  mem.calibRawStart = mem.lastRaw;

  mem.explore = null;
  mem.chargeStart = null;
  mem.holdBias = 0;
  mem.lastError = "";
}

function updateState(obs, mem, dt) {
  var raw = norm180(num(obs.heading, mem.lastRaw));
  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  var oldWl = num(mem.lastWl, wl);
  var oldWr = num(mem.lastWr, wr);
  var avgRate = (((wr + oldWr) / 2 - (wl + oldWl) / 2) / 0.6) * R2D;
  var expDelta = avgRate * dt;
  var rawDelta = norm180(raw - mem.lastRaw);

  if (Math.abs(rawDelta) > 80 && Math.abs(expDelta) < 20 &&
      Math.abs(rawDelta - expDelta) > 95) {
    mem.jumpOff = norm180(mem.jumpOff - rawDelta);
  }

  var effRaw = norm180(raw + mem.jumpOff);
  var pred = norm180(mem.heading + expDelta);
  var comp = norm180(effRaw + mem.bias);
  var diff = norm180(comp - pred);

  if (Math.abs(diff) < 55) {
    mem.heading = norm180(pred + diff * 0.18);
  } else if (Math.abs(diff) > 140 && Math.abs(expDelta) < 4 &&
             Math.abs(wl) + Math.abs(wr) < 0.25) {
    mem.heading = pred;
  } else {
    mem.heading = pred;
  }

  if (obs.beacon && !mem.calibActive) {
    var bdist = num(obs.beacon.distance, 99);
    if (bdist > 0.4 && bdist < 20) {
      var bB = Math.atan2(mem.base.y - mem.py, mem.base.x - mem.px) * R2D;
      var bRel = num(obs.beacon.bearing, 0);
      var trueH = norm180(bB - bRel);
      var hd = norm180(trueH - mem.heading);
      if (Math.abs(hd) < 70) {
        mem.heading = norm180(mem.heading + hd * 0.12);
        var bs = norm180(trueH - effRaw);
        var bd = norm180(bs - mem.bias);
        if (Math.abs(bd) < 50) {
          mem.bias = norm180(mem.bias + bd * 0.03);
        }
      }
    }
  }

  var gx = num(obs.x, mem.px);
  var gy = num(obs.y, mem.py);
  var gpsSame = Math.abs(gx - mem.lastGpsX) < 0.006 &&
                Math.abs(gy - mem.lastGpsY) < 0.006;
  var avgV = (wl + wr) / 2;
  if (gpsSame && Math.abs(avgV) > 0.12) mem.gpsFreezeT += dt;
  else mem.gpsFreezeT = 0;

  if (mem.gpsFreezeT > 1.5) {
    mem.px += avgV * Math.cos(mem.heading * D2R) * dt;
    mem.py += avgV * Math.sin(mem.heading * D2R) * dt;
  } else {
    mem.px = gx;
    mem.py = gy;
  }
  mem.px = clamp(mem.px, mem.wMinX + 0.5, mem.wMaxX - 0.5);
  mem.py = clamp(mem.py, mem.wMinY + 0.5, mem.wMaxY - 0.5);

  var battery = num(obs.battery, mem.lastBattery);
  var moveD = dist(mem.px, mem.py, mem.lastPx, mem.lastPy);
  if (moveD > 0.08) {
    var drop = mem.lastBattery - battery;
    if (drop > 0 && drop < 0.35) {
      var e = drop / moveD;
      if (e > 0.00001 && e < 0.2) {
        if (mem.eN < 3) mem.ePerM = e;
        else mem.ePerM = mem.ePerM * 0.97 + e * 0.03;
        mem.eN++;
      }
    }
  }

  if (!mem.calibActive && Math.abs(wl - wr) < 0.55 && Math.abs(avgV) > 0.25) {
    var calD = dist(mem.px, mem.py, mem.calX, mem.calY);
    if (calD > 0.9) {
      var moveA = Math.atan2(mem.py - mem.calY, mem.px - mem.calX) * R2D;
      var rawAvg = norm180((mem.calRaw + effRaw) / 2);
      var sampleB = norm180(moveA - rawAvg);
      var bb = norm180(sampleB - mem.bias);
      if (Math.abs(bb) < 80) {
        var alpha = mem.biasN < 5 ? 0.25 : 0.015;
        mem.bias = norm180(mem.bias + bb * alpha);
        mem.biasN++;
        mem.heading = norm180(mem.heading + bb * alpha * 0.5);
      }
      mem.calX = mem.px;
      mem.calY = mem.py;
      mem.calRaw = effRaw;
    }
  } else if (Math.abs(avgV) > 0.35) {
    if (dist(mem.px, mem.py, mem.calX, mem.calY) > 2.0) {
      mem.calX = mem.px;
      mem.calY = mem.py;
      mem.calRaw = effRaw;
    }
  }

  mem.lastRaw = raw;
  mem.lastWl = wl;
  mem.lastWr = wr;
  mem.lastGpsX = gx;
  mem.lastGpsY = gy;
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastBattery = battery;
  mem.lastT = num(obs.t, mem.lastT);
}

function wheelPower(s, target, actual, dt) {
  var err = target - actual;
  var ff = 0;
  if (target > 0.04) ff = 0.12 + 0.32 * target;
  else if (target < -0.04) ff = -0.12 + 0.32 * target;

  s.i += err * dt * 0.7;
  s.i = clamp(s.i, -1.2, 1.2);

  var u = ff + 0.55 * err + 0.25 * s.i;
  if (u > 1) {
    u = 1;
    if (err > 0) s.i = Math.min(s.i, 0.6);
  }
  if (u < -1) {
    u = -1;
    if (err < 0) s.i = Math.max(s.i, -0.6);
  }
  return clamp(u, -1, 1);
}

function setSpeeds(obs, mem, tl, tr, drill) {
  var dt = mem.dt || 0.1;
  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  tl = clamp(tl, -2.9, 2.9);
  tr = clamp(tr, -2.9, 2.9);
  var l = wheelPower(mem.mL, tl, wl, dt);
  var r = wheelPower(mem.mR, tr, wr, dt);
  return { left: clamp(l, -1, 1), right: clamp(r, -1, 1), drill: !!drill };
}

function holdStill(obs, mem, drill) {
  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  var pitch = num(obs.pitch, 0);
  var avg = (wl + wr) / 2;

  if (mem.holdBias == null) mem.holdBias = 0;
  mem.holdBias += -avg * 0.04;
  mem.holdBias = clamp(mem.holdBias, -0.45, 0.45);

  var pcomp = clamp(pitch * 0.022, -0.30, 0.30);
  var base = mem.holdBias + pcomp;
  var uL = base - wl * 1.25;
  var uR = base - wr * 1.25;

  if (Math.abs(wl) < 0.035) uL = base;
  if (Math.abs(wr) < 0.035) uR = base;
  if (Math.abs(avg) > 0.12) {
    uL -= avg * 0.5;
    uR -= avg * 0.5;
  }

  mem.mL.i *= 0.7;
  mem.mR.i *= 0.7;

  return {
    left: clamp(uL, -1, 1),
    right: clamp(uR, -1, 1),
    drill: !!drill
  };
}

function minFront(obs) {
  var rays = obs.rays || [];
  if (rays.length < 9) return 15;
  var f = 15;
  for (var i = 0; i < 9; i++) {
    var a = RAY_A[i];
    if (a >= -30 && a <= 30) {
      f = Math.min(f, num(rays[i], 15));
    }
  }
  return f;
}

function avoidBias(obs) {
  var rays = obs.rays || [];
  if (rays.length < 9) return 0;

  var front = 15;
  var lSum = 0, lN = 0, rSum = 0, rN = 0;
  var i, r, a;

  for (i = 0; i < 9; i++) {
    r = num(rays[i], 15);
    if (r > 15) r = 15;
    a = RAY_A[i];
    if (a >= -30 && a <= 30) front = Math.min(front, r);
    if (a >= 20) { lSum += Math.min(r, 5); lN++; }
    if (a <= -20) { rSum += Math.min(r, 5); rN++; }
  }
  var lc = lN ? lSum / lN : 5;
  var rc = rN ? rSum / rN : 5;

  var steer = 0;
  for (i = 0; i < 9; i++) {
    r = num(rays[i], 15);
    if (r > 15) r = 15;
    if (r < 3.2) {
      var w = (3.2 - r) / 3.2;
      a = RAY_A[i];
      if (Math.abs(a) <= 20) {
        var side = lc >= rc ? 1 : -1;
        steer += side * w * 35;
      } else {
        steer += (a > 0 ? -1 : 1) * w * 28;
      }
    }
  }
  if (front < 1.0) steer += (lc >= rc ? 1 : -1) * 25;
  return clamp(steer, -70, 70);
}

function driveRel(obs, mem, bearing, v, avoid) {
  var e = norm180(bearing);
  if (avoid) e = norm180(e + avoidBias(obs));

  var mf = minFront(obs);
  if (avoid) {
    if (mf < 0.65) v = 0;
    else if (mf < 1.2) v = Math.min(v, 0.30);
    else if (mf < 2.0) v = Math.min(v, 0.70);
    else if (mf < 3.0) v = Math.min(v, 1.30);
  } else {
    if (mf < 0.45) v = Math.min(v, 0);
  }

  var ae = Math.abs(e);
  if (ae > 110) v = Math.min(v, 0.10);
  else if (ae > 70) v = Math.min(v, 0.40);
  else if (ae > 35) v *= 0.75;

  var omega = clamp(e * D2R * 1.9, -2.3, 2.3);
  if (ae < 2.5) omega = 0;

  var tl = v - omega * 0.3;
  var tr = v + omega * 0.3;

  if (v < 0.10 && ae > 20) {
    tl = -omega * 0.3;
    tr = omega * 0.3;
  }
  return setSpeeds(obs, mem, tl, tr, false);
}

function driveToPoint(obs, mem, x, y, v) {
  var d = dist(mem.px, mem.py, x, y);
  if (d < 0.7) return holdStill(obs, mem, false);
  var bearing = Math.atan2(y - mem.py, x - mem.px) * R2D;
  var err = norm180(bearing - mem.heading);
  var sp = Math.min(v, 0.35 + d * 0.9);
  return driveRel(obs, mem, err, sp, true);
}

function seekSite(obs, mem, site) {
  var d = num(site.distance, 99);
  var b = num(site.bearing, 0);
  if (d < 0.9) return holdStill(obs, mem, false);

  var v;
  if (d > 4) v = 1.35;
  else if (d > 2) v = 0.72;
  else v = 0.34;
  if (d < 1.35) v = 0.18;

  var avoid = d > 2.0;
  return driveRel(obs, mem, b, v, avoid);
}

function shouldReturn(obs, mem, carried, baseD, timeLeft, battery) {
  if (carried <= 0) {
    if (battery < 0.15 && baseD > 30) return true;
    return false;
  }
  if (carried >= mem.cap) return true;

  var e = Math.max(mem.ePerM || 0.002, 0.0005);
  var need = baseD * e * (1 + 0.18 * carried) * 3.0 + 0.08;
  if (baseD > 12 && battery < need) return true;
  if (battery < 0.20 && baseD > 12) return true;

  var rt = baseD / 0.9 + 25;
  if (timeLeft < rt) return true;
  if (timeLeft < 120 && baseD < 180) return true;
  return false;
}

function goHome(obs, mem) {
  var baseD = dist(mem.px, mem.py, mem.base.x, mem.base.y);
  if (baseD < 3.0 || obs.docked) return holdStill(obs, mem, false);

  if (obs.beacon) {
    var bd = num(obs.beacon.distance, 99);
    if (bd < 20) {
      if (bd < 2.0) return holdStill(obs, mem, false);
      var v = bd > 10 ? 1.8 : (bd > 5 ? 1.1 : 0.6);
      if (num(obs.battery, 1) < 0.2) v = Math.min(v, 0.8);
      return driveRel(obs, mem, num(obs.beacon.bearing, 0), v, true);
    }
  }

  var sp = 2.0 - 0.07 * Math.round(num(obs.carried, 0));
  if (num(obs.battery, 1) < 0.25) sp = Math.min(sp, 1.0);
  return driveToPoint(obs, mem, mem.base.x, mem.base.y, sp);
}

function makeSearchPoints(mem, c) {
  var high = c.est > (mem.medEst || 1) * 1.3;
  var ex = high ? 22 : 16;
  var offs = high ? [-14, 0, 14] : [-10, 0, 10];
  var pts = [];

  for (var i = 0; i < offs.length; i++) {
    var y = clamp(c.y + offs[i], mem.wMinY + 1, mem.wMaxY - 1);
    var x1 = clamp(c.x - ex, mem.wMinX + 1, mem.wMaxX - 1);
    var x2 = clamp(c.x + ex, mem.wMinX + 1, mem.wMaxX - 1);
    if (i % 2 === 0) {
      pts.push({ x: x1, y: y });
      pts.push({ x: x2, y: y });
    } else {
      pts.push({ x: x2, y: y });
      pts.push({ x: x1, y: y });
    }
  }
  return pts;
}

function chooseCandidate(obs, mem, carried, baseD, timeLeft) {
  var best = null;
  var bestScore = -1e18;
  var med = mem.medEst || 1;

  for (var i = 0; i < mem.cands.length; i++) {
    var c = mem.cands[i];
    if (c.status !== 0) continue;

    var d = dist(mem.px, mem.py, c.x, c.y);
    var db = dist(c.x, c.y, mem.base.x, mem.base.y);

    if (timeLeft < d / 1.0 + 25 && d > 30) continue;
    if (carried > 0 && timeLeft < (d + db - baseD) / 1.0 + 30 && d > 35) continue;
    if (carried === 0 && timeLeft < (d + db) / 1.0 + 35 && d > 50) continue;

    var extra;
    if (carried > 0) extra = Math.max(15, d + db - baseD) + 25;
    else extra = d + 0.35 * db + 30;

    var est = Math.max(0.1, c.est);
    var score = est / Math.pow(extra, 0.9);

    if (mem.samplesDone === 0) score *= 1 / (1 + d / 250);
    if (est < med * 0.15 && timeLeft < 500) score *= 0.35;
    if (d < 25) score *= 1.15;

    if (score > bestScore) {
      bestScore = score;
      best = c;
    }
  }
  return best;
}

function markCandidateNear(mem, x, y, r) {
  var bi = -1, bd = 1e9;
  for (var i = 0; i < mem.cands.length; i++) {
    var c = mem.cands[i];
    if (c.status !== 0) continue;
    var d = dist(c.x, c.y, x, y);
    if (d < bd) {
      bd = d;
      bi = i;
    }
  }
  if (bi >= 0 && bd < r) mem.cands[bi].status = 1;
}

function executeTask(obs, mem, t, carried, battery) {
  var task = mem.task;
  if (!task) return holdStill(obs, mem, false);

  if (task.type === "hint") {
    var c = task.cand;
    if (!c || c.status !== 0) {
      mem.task = null;
      return holdStill(obs, mem, false);
    }

    if (task.phase === "travel") {
      var d = dist(mem.px, mem.py, c.x, c.y);
      if (!task.lastDist) task.lastDist = d;

      if (d < task.lastDist - 0.4) {
        task.lastDist = d;
        task.lastProgT = t;
      }
      if (!task.lastProgT) task.lastProgT = t;

      if (t - task.lastProgT > 35 && d > 7) {
        c.status = 1;
        mem.task = null;
        return holdStill(obs, mem, false);
      }

      if (d < 5.0) {
        task.phase = "search";
        task.searchPts = makeSearchPoints(mem, c);
        task.si = 0;
        task.searchStart = t;
        task.ptStart = t;
        task.maxSearch = c.est > (mem.medEst || 1) * 1.3 ? 70 : 50;
      } else {
        var sp = 2.1 - 0.08 * carried;
        if (battery < 0.28) sp = Math.min(sp, 1.2);
        if (mem.cautiousUntil > t) sp = Math.min(sp, 1.0);
        return driveToPoint(obs, mem, c.x, c.y, Math.max(0.6, sp));
      }
    }

    if (task.phase === "search") {
      if (c.status !== 0) {
        mem.task = null;
        return holdStill(obs, mem, false);
      }
      if (!task.searchPts) {
        task.searchPts = makeSearchPoints(mem, c);
        task.si = 0;
        task.searchStart = t;
        task.ptStart = t;
        task.maxSearch = c.est > (mem.medEst || 1) * 1.3 ? 70 : 50;
      }

      if (t - task.searchStart > task.maxSearch) {
        c.status = 1;
        mem.task = null;
        return holdStill(obs, mem, false);
      }
      if (task.si >= task.searchPts.length) {
        c.status = 1;
        mem.task = null;
        return holdStill(obs, mem, false);
      }

      var p = task.searchPts[task.si];
      var dp = dist(mem.px, mem.py, p.x, p.y);
      if (dp < 1.6 || t - task.ptStart > 15) {
        task.si++;
        task.ptStart = t;
        if (task.si >= task.searchPts.length) {
          c.status = 1;
          mem.task = null;
          return holdStill(obs, mem, false);
        }
        p = task.searchPts[task.si];
      }

      var sp2 = c.est > (mem.medEst || 1) * 1.3 ? 1.65 : 1.40;
      if (battery < 0.25) sp2 = Math.min(sp2, 0.9);
      return driveToPoint(obs, mem, p.x, p.y, sp2);
    }
  }
  return holdStill(obs, mem, false);
}

function exploreStep(obs, mem, t) {
  if (!mem.explore) {
    var pts = [];
    var step = 45;
    for (var y = mem.wMinY + 20; y <= mem.wMaxY - 20; y += step) {
      for (var x = mem.wMinX + 20; x <= mem.wMaxX - 20; x += step) {
        pts.push({ x: x, y: y, done: false });
      }
    }
    mem.explore = pts;
  }

  var best = -1, bd = 1e9;
  for (var i = 0; i < mem.explore.length; i++) {
    var p = mem.explore[i];
    if (p.done) continue;
    var d = dist(mem.px, mem.py, p.x, p.y);
    if (d < bd) {
      bd = d;
      best = i;
    }
  }
  if (best < 0) return holdStill(obs, mem, false);

  var q = mem.explore[best];
  if (bd < 7) {
    q.done = true;
    return holdStill(obs, mem, false);
  }
  return driveToPoint(obs, mem, q.x, q.y, 1.8);
}

function act(obs, mem) {
  try {
    if (!mem.init) initMission(obs, mem);

    var t = num(obs.t, 0);
    var dt = t - num(mem.lastT, t - 0.1);
    if (!(dt > 0) || dt > 0.5) dt = 0.1;
    mem.dt = dt;

    updateState(obs, mem, dt);

    if (obs.bumped) {
      var prevBump = num(mem.lastBumpT, -99);
      if (t - prevBump > 0.6) {
        if (t - prevBump < 3) mem.bumpCount = (mem.bumpCount || 0) + 1;
        else mem.bumpCount = 1;
        mem.lastBumpT = t;

        var lc = 0, rc = 0;
        if (obs.rays && obs.rays.length >= 9) {
          for (var i = 0; i < 9; i++) {
            var rr = num(obs.rays[i], 15);
            if (RAY_A[i] >= 20) lc += Math.min(rr, 5);
            if (RAY_A[i] <= -20) rc += Math.min(rr, 5);
          }
        }
        mem.recoverDir = lc >= rc ? 1 : -1;
        mem.recoverUntil = t + 1.3;
        mem.drill = null;
        mem.task = null;
        mem.calibActive = false;
        if (mem.bumpCount >= 3) mem.cautiousUntil = t + 18;
      }
    }

    if (mem.recoverUntil > t) {
      var phase = t - (mem.recoverUntil - 1.3);
      var dir = mem.recoverDir || 1;
      if (phase < 0.5) {
        return setSpeeds(obs, mem, -0.8, -0.8, false);
      }
      return setSpeeds(obs, mem, -dir * 0.5, dir * 0.5, false);
    }

    if (mem.calibActive) {
      if (t - mem.calibStartT < 1.25) {
        return setSpeeds(obs, mem, 0.85, 0.85, false);
      }
      var dx = mem.px - mem.calibStartX;
      var dy = mem.py - mem.calibStartY;
      if (dx * dx + dy * dy > 0.06) {
        var ma = Math.atan2(dy, dx) * R2D;
        var eff = norm180(num(obs.heading, 0) + mem.jumpOff);
        var rawAvg = norm180((mem.calibRawStart + eff) / 2);
        mem.bias = norm180(ma - rawAvg);
        mem.heading = norm180(eff + mem.bias);
      }
      mem.calibActive = false;
      mem.calX = mem.px;
      mem.calY = mem.py;
      mem.calRaw = norm180(num(obs.heading, 0) + mem.jumpOff);
    }

    var carried = Math.round(num(obs.carried, 0));

    if (mem.drill) {
      var s = mem.drill;
      if (carried > s.carried0) {
        mem.drill = null;
        mem.samplesDone++;
        markCandidateNear(mem, mem.px, mem.py, 35);
        if (mem.task) {
          if (mem.task.cand) mem.task.cand.status = 1;
          mem.task = null;
        }
      } else {
        var site = obs.site;
        var sd = site ? num(site.distance, 99) : 99;
        var speed = Math.abs((num(obs.wheelLeft, 0) + num(obs.wheelRight, 0)) / 2);
        var baseD0 = dist(mem.px, mem.py, mem.base.x, mem.base.y);
        var timeLeft0 = num(obs.timeLeft, mem.seconds - (t - mem.t0));
        var bat0 = num(obs.battery, 1);

        if ((carried > 0 && timeLeft0 < baseD0 / 0.8 + 18) || bat0 < 0.08) {
          mem.drill = null;
        } else if (site && sd <= 1.8) {
          s.lastSeen = t;
          if (sd <= 1.55 && speed < 0.16) {
            return holdStill(obs, mem, true);
          }
          return holdStill(obs, mem, false);
        } else {
          if (t - s.lastSeen < 1.0) return holdStill(obs, mem, true);
          mem.drill = null;
        }

        if (mem.drill && t - s.start > 30) mem.drill = null;
      }
    }

    carried = Math.round(num(obs.carried, 0));
    var battery = num(obs.battery, 1);
    var timeLeft = num(obs.timeLeft, mem.seconds - (t - mem.t0));
    if (!isFinite(timeLeft) || timeLeft < 0) timeLeft = 0;
    var baseD = dist(mem.px, mem.py, mem.base.x, mem.base.y);

    if (baseD < 3.0 || obs.docked) {
      if (carried > 0) {
        mem.task = null;
        mem.returning = false;
        return holdStill(obs, mem, false);
      }
      mem.returning = false;
      if (timeLeft > 90 && battery < 0.75) {
        if (mem.chargeStart == null) mem.chargeStart = t;
        if (battery < 0.9 && t - mem.chargeStart < 45) {
          return holdStill(obs, mem, false);
        }
      } else {
        mem.chargeStart = null;
      }
    } else {
      mem.chargeStart = null;
    }

    if (carried > 0 && shouldReturn(obs, mem, carried, baseD, timeLeft, battery)) {
      mem.returning = true;
      mem.task = null;
      mem.drill = null;
      return goHome(obs, mem);
    }

    if (mem.returning) {
      if (carried > 0 && baseD > 3.0) {
        return goHome(obs, mem);
      }
      mem.returning = false;
    }

    if (carried === 0 && battery < 0.15 && baseD > 35 && timeLeft > 30) {
      mem.returning = true;
      mem.task = null;
      return goHome(obs, mem);
    }

    if (obs.site && carried < mem.cap && !mem.returning && timeLeft > 20) {
      if (!(carried > 0 && baseD < 8)) {
        var siteNow = obs.site;
        var dNow = num(siteNow.distance, 99);

        if (dNow <= 1.55) {
          var spNow = Math.abs((num(obs.wheelLeft, 0) + num(obs.wheelRight, 0)) / 2);
          if (spNow < 0.14) {
            mem.drill = {
              start: t,
              lastSeen: t,
              carried0: carried,
              value: num(siteNow.value, 0)
            };
            return holdStill(obs, mem, true);
          }
          return holdStill(obs, mem, false);
        }

        return seekSite(obs, mem, siteNow);
      }
    }

    if (!mem.task) {
      var c = chooseCandidate(obs, mem, carried, baseD, timeLeft);
      if (c) {
        mem.task = {
          type: "hint",
          cand: c,
          phase: "travel",
          lastDist: dist(mem.px, mem.py, c.x, c.y),
          lastProgT: t
        };
      }
    }

    if (mem.task) {
      return executeTask(obs, mem, t, carried, battery);
    }

    if (carried > 0) {
      mem.returning = true;
      return goHome(obs, mem);
    }

    if (timeLeft > 30) {
      return exploreStep(obs, mem, t);
    }

    return holdStill(obs, mem, false);
  } catch (e) {
    mem.lastError = String(e);
    mem.errCount = (mem.errCount || 0) + 1;
    return { left: 0, right: 0, drill: false };
  }
}

var D2R = Math.PI / 180;
var R2D = 180 / Math.PI;
var RAY_A = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function num(v, d) {
  v = +v;
  return isFinite(v) ? v : d;
}
function clamp(v, a, b) {
  v = +v;
  if (!isFinite(v)) return a;
  return v < a ? a : (v > b ? b : v);
}
function norm180(a) {
  a = +a;
  if (!isFinite(a)) return 0;
  return ((a + 180) % 360 + 360) % 360 - 180;
}
function dist(x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
}
function midAng(a, b) {
  var d = norm180(b - a);
  return norm180(a + d / 2);
}
function frontMin(obs) {
  var rr = obs.rays || [];
  var f = 15;
  for (var i = 0; i < 9 && i < rr.length; i++) {
    if (RAY_A[i] >= -30 && RAY_A[i] <= 30) f = Math.min(f, num(rr[i], 15));
  }
  return f;
}
function leftClear(obs) {
  var rr = obs.rays || [];
  var f = 15;
  for (var i = 0; i < 9 && i < rr.length; i++) {
    if (RAY_A[i] >= 20) f = Math.min(f, num(rr[i], 15));
  }
  return f;
}
function rightClear(obs) {
  var rr = obs.rays || [];
  var f = 15;
  for (var i = 0; i < 9 && i < rr.length; i++) {
    if (RAY_A[i] <= -20) f = Math.min(f, num(rr[i], 15));
  }
  return f;
}
function clampX(mem, x) {
  return clamp(x, mem.wMinX + 1.6, mem.wMaxX - 1.6);
}
function clampY(mem, y) {
  return clamp(y, mem.wMinY + 1.6, mem.wMaxY - 1.6);
}

function initMission(obs, mem) {
  mem.init = true;
  var t = num(obs.t, 0);
  mem.t0 = t;
  mem.t = t;
  mem.lastT = t;

  var m = obs.mission || {};
  mem.seconds = num(m.seconds, 1200);
  mem.cap = Math.round(num(m.capacity, 5));
  if (!(mem.cap > 0)) mem.cap = 5;

  var mb = m.base || {};
  mem.base = {
    x: num(mb.x, num(obs.x, 0)),
    y: num(mb.y, num(obs.y, 0))
  };

  var i, hs = m.hints || [];
  mem.hints = [];
  for (i = 0; i < hs.length; i++) {
    var h = hs[i] || {};
    var est = num(h.estimate, 1);
    if (!(est > 0)) est = 1;
    mem.hints.push({
      x: num(h.x, mem.base.x),
      y: num(h.y, mem.base.y),
      est: est,
      status: 0
    });
  }
  var vals = [];
  for (i = 0; i < mem.hints.length; i++) vals.push(mem.hints[i].est);
  vals.sort(function (a, b) { return a - b; });
  mem.medEst = vals.length ? vals[Math.floor(vals.length / 2)] : 1;

  var sx = 400, sy = 400, sz = m.size;
  if (typeof sz === "number") {
    sx = sy = sz;
  } else if (Array.isArray(sz)) {
    sx = num(sz[0], 400);
    sy = num(sz[1], sx);
  } else if (sz && typeof sz === "object") {
    sx = num(sz.x, num(sz.width, 400));
    sy = num(sz.y, num(sz.height, sx));
  }
  if (!(sx > 20)) sx = 400;
  if (!(sy > 20)) sy = 400;

  var minx = mem.base.x, maxx = mem.base.x;
  var miny = mem.base.y, maxy = mem.base.y;
  for (i = 0; i < mem.hints.length; i++) {
    var hh = mem.hints[i];
    if (hh.x < minx) minx = hh.x;
    if (hh.x > maxx) maxx = hh.x;
    if (hh.y < miny) miny = hh.y;
    if (hh.y > maxy) maxy = hh.y;
  }

  var centered = (minx < -1 || miny < -1 || maxx > sx + 1 || maxy > sy + 1);
  if (centered) {
    mem.wMinX = -sx / 2;
    mem.wMaxX = sx / 2;
    mem.wMinY = -sy / 2;
    mem.wMaxY = sy / 2;
  } else {
    mem.wMinX = 0;
    mem.wMaxX = sx;
    mem.wMinY = 0;
    mem.wMaxY = sy;
  }

  mem.px = num(obs.x, mem.base.x);
  mem.py = num(obs.y, mem.base.y);
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastGpsX = mem.px;
  mem.lastGpsY = mem.py;
  mem.gpsStill = 0;
  mem.gpsFrozen = false;

  mem.rawPrev = norm180(num(obs.heading, 0));
  mem.jumpOff = 0;
  mem.bias = 0;
  mem.biasN = 0;
  mem.hdg = mem.rawPrev;

  mem.mL = { i: 0 };
  mem.mR = { i: 0 };
  mem.lastWl = num(obs.wheelLeft, 0);
  mem.lastWr = num(obs.wheelRight, 0);
  mem.lastBattery = num(obs.battery, 1);
  mem.ePerM = 0.001;
  mem.eN = 0;
  mem.dt = 0.1;

  mem.cal = {
    active: true,
    startT: t,
    x0: mem.px,
    y0: mem.py,
    raw0: mem.rawPrev
  };
  mem.calX = mem.px;
  mem.calY = mem.py;
  mem.calRaw = mem.rawPrev;

  mem.task = null;
  mem.sample = null;
  mem.chase = null;
  mem.returning = false;
  mem.recoverUntil = -1;
  mem.escapeUntil = -1;
  mem.escapeDir = 1;
  mem.ignoreSiteUntil = -1;
  mem.lastBumpT = -99;
  mem.bumpCount = 0;
  mem.cautiousUntil = 0;
  mem.localDone = false;
  mem.expPts = null;
  mem.sciCooldown = 0;
  mem.chargeStart = null;

  mem.lastCarried = Math.round(num(obs.carried, 0));
  mem.samplesTotal = 0;
  mem.samplesDelivered = 0;
  mem.deliveries = 0;
  mem.lastCarryT = t;
  mem.lastDeliveredAt = -1;
  mem.hIL = 0;
  mem.hIR = 0;
  mem.errCount = 0;
  mem.lastError = "";
}

function updateState(obs, mem) {
  var t = num(obs.t, mem.t || 0);
  var dt = t - num(mem.lastT, t - 0.1);
  if (!(dt > 0) || dt > 0.5) dt = 0.1;
  mem.dt = dt;
  mem.t = t;

  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  var avgV = (wl + wr) / 2;
  var raw = norm180(num(obs.heading, mem.rawPrev));
  var yawDelta = ((wr - wl) / 0.6) * R2D * dt;
  var rawDelta = norm180(raw - mem.rawPrev);

  if (Math.abs(rawDelta) > 70 && Math.abs(yawDelta) < 20) {
    mem.jumpOff = norm180(mem.jumpOff + rawDelta);
  }
  var effRaw = norm180(raw - mem.jumpOff);

  var gx = num(obs.x, mem.px);
  var gy = num(obs.y, mem.py);
  var gpsMove = dist(gx, gy, mem.lastGpsX, mem.lastGpsY);

  if (gpsMove < 0.008 && Math.abs(avgV) > 0.12) mem.gpsStill += dt;
  else if (gpsMove > 0.035) mem.gpsStill = 0;
  else if (Math.abs(avgV) <= 0.12) mem.gpsStill = Math.max(0, mem.gpsStill - dt * 0.7);

  mem.gpsFrozen = mem.gpsStill > 1.5;

  if (mem.gpsFrozen) {
    mem.px += avgV * Math.cos(mem.hdg * D2R) * dt;
    mem.py += avgV * Math.sin(mem.hdg * D2R) * dt;
  } else {
    mem.px = gx;
    mem.py = gy;
  }
  mem.px = clamp(mem.px, mem.wMinX + 0.25, mem.wMaxX - 0.25);
  mem.py = clamp(mem.py, mem.wMinY + 0.25, mem.wMaxY - 0.25);

  var pred = norm180(mem.hdg + yawDelta);
  var comp = norm180(effRaw + mem.bias);
  var dh = norm180(comp - pred);
  if (Math.abs(dh) < 65) {
    mem.hdg = norm180(pred + dh * 0.35);
  } else if (Math.abs(dh) > 125) {
    mem.hdg = pred;
  } else {
    mem.hdg = comp;
  }
  if (Math.abs(avgV) < 0.06) {
    var d2 = norm180(comp - mem.hdg);
    if (Math.abs(d2) < 40) mem.hdg = norm180(mem.hdg + d2 * 0.18);
  }

  if (!mem.gpsFrozen && gpsMove > 0.005) {
    var gpsDist = dist(gx, gy, mem.calX, mem.calY);
    if (gpsDist > 0.9 && Math.abs(wr - wl) < 0.9 && Math.abs(avgV) > 0.18) {
      var moveAng = Math.atan2(gy - mem.calY, gx - mem.calX) * R2D;
      var avgRaw = midAng(effRaw, mem.calRaw);
      var sampleBias = norm180(moveAng - avgRaw);
      var bd = norm180(sampleBias - mem.bias);
      if (Math.abs(bd) < 80) {
        var alpha = mem.biasN < 6 ? 0.25 : 0.025;
        mem.bias = norm180(mem.bias + bd * alpha);
        mem.biasN++;
      }
      mem.calX = gx;
      mem.calY = gy;
      mem.calRaw = effRaw;
    } else if (Math.abs(avgV) > 0.35 && gpsDist > 2.5) {
      mem.calX = gx;
      mem.calY = gy;
      mem.calRaw = effRaw;
    }
  }

  var moveD = dist(mem.px, mem.py, mem.lastPx, mem.lastPy);
  var bat = num(obs.battery, mem.lastBattery);
  if (moveD > 0.08 && mem.lastBattery != null) {
    var drop = mem.lastBattery - bat;
    if (drop > 0 && drop < 0.35) {
      var e = drop / moveD;
      if (e > 0.00001 && e < 0.2) {
        if (mem.eN < 3) mem.ePerM = e;
        else mem.ePerM = mem.ePerM * 0.97 + e * 0.03;
        mem.eN++;
      }
    }
  }

  mem.lastBattery = bat;
  mem.lastWl = wl;
  mem.lastWr = wr;
  mem.rawPrev = raw;
  mem.lastGpsX = gx;
  mem.lastGpsY = gy;
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastT = t;
}

function wheelCtrl(obs, mem, targetL, targetR, drill) {
  var dt = mem.dt || 0.1;
  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  targetL = clamp(targetL, -2.9, 2.9);
  targetR = clamp(targetR, -2.9, 2.9);

  function one(st, target, actual) {
    if (!st) st = { i: 0 };
    var err = target - actual;
    st.i += err * dt;
    st.i = clamp(st.i, -1.3, 1.3);

    var ff = 0;
    if (target > 0.04) ff = 0.10 + 0.31 * target;
    else if (target < -0.04) ff = -0.10 + 0.31 * target;

    var u = ff + 0.55 * err + 0.16 * st.i;
    if (u > 1) {
      u = 1;
      if (err > 0) st.i = Math.min(st.i, 0.65);
    }
    if (u < -1) {
      u = -1;
      if (err < 0) st.i = Math.max(st.i, -0.65);
    }
    return clamp(u, -1, 1);
  }

  return {
    left: one(mem.mL, targetL, wl),
    right: one(mem.mR, targetR, wr),
    drill: !!drill
  };
}

function holdCmd(obs, mem, drill) {
  var wl = num(obs.wheelLeft, 0);
  var wr = num(obs.wheelRight, 0);
  var pitch = num(obs.pitch, 0);
  var p = clamp(pitch * 0.030, -0.26, 0.26);
  var uL = clamp(p - wl * 2.8, -1, 1);
  var uR = clamp(p - wr * 2.8, -1, 1);

  if (drill) {
    if (Math.abs(wl) > 0.018) {
      mem.hIL = clamp((mem.hIL || 0) - wl * mem.dt * 0.55, -0.30, 0.30);
    }
    if (Math.abs(wr) > 0.018) {
      mem.hIR = clamp((mem.hIR || 0) - wr * mem.dt * 0.55, -0.30, 0.30);
    }
    uL = clamp(uL + (mem.hIL || 0), -1, 1);
    uR = clamp(uR + (mem.hIR || 0), -1, 1);
  } else {
    mem.hIL = 0;
    mem.hIR = 0;
  }

  mem.mL.i *= 0.90;
  mem.mR.i *= 0.90;
  if (Math.abs(wl) < 0.018 && Math.abs(p) < 0.015) uL = clamp(uL * 0.5, -1, 1);
  if (Math.abs(wr) < 0.018 && Math.abs(p) < 0.015) uR = clamp(uR * 0.5, -1, 1);

  return { left: clamp(uL, -1, 1), right: clamp(uR, -1, 1), drill: !!drill };
}

function driveRel(obs, mem, err, v, avoid) {
  var rr = obs.rays || [];
  var front = 15, lc = 15, rc = 15, steer = 0;
  var i, r, a;

  for (i = 0; i < 9 && i < rr.length; i++) {
    r = num(rr[i], 15);
    if (r > 15) r = 15;
    if (r < 0) r = 0;
    a = RAY_A[i];
    if (a >= -30 && a <= 30) front = Math.min(front, r);
    if (a >= 20) lc = Math.min(lc, r);
    if (a <= -20) rc = Math.min(rc, r);

    if (avoid && r < 4.8) {
      var w = (4.8 - r) / 4.8;
      w *= w;
      if (a > 15) steer -= w * 28;
      else if (a < -15) steer += w * 28;
    }
  }

  if (avoid) {
    if (front < 3.1) {
      var side = lc >= rc ? 1 : -1;
      steer += side * (3.1 - front) * 13;
    }
    if (front < 0.58) v = 0;
    else if (front < 1.05) v = Math.min(v, 0.27);
    else if (front < 1.85) v = Math.min(v, 0.70);
    else if (front < 3.0) v = Math.min(v, 1.30);
    else if (front < 5.0) v = Math.min(v, 2.00);
    if (lc < 0.35 || rc < 0.35) v = Math.min(v, 0.65);
  }

  var e = norm180(err + clamp(steer, -72, 72));
  var ae = Math.abs(e);
  if (ae > 120) v = Math.min(v, 0.05);
  else if (ae > 90) v = Math.min(v, 0.22);
  else if (ae > 50) v *= 0.65;
  else if (ae > 25) v *= 0.85;

  var omega = clamp(e * D2R * 2.0, -2.6, 2.6);
  if (ae < 2.0) omega = 0;

  var tl = v - omega * 0.3;
  var tr = v + omega * 0.3;
  return wheelCtrl(obs, mem, tl, tr, false);
}

function driveToPoint(obs, mem, x, y, speed, avoid) {
  var d = dist(mem.px, mem.py, x, y);
  if (d < 0.65) return holdCmd(obs, mem, false);
  var bearing = Math.atan2(y - mem.py, x - mem.px) * R2D;
  var err = norm180(bearing - mem.hdg);
  var sp = speed;
  if (d < 2.5) sp = Math.min(sp, 0.60);
  else if (d < 5.0) sp = Math.min(sp, 1.30);
  return driveRel(obs, mem, err, sp, avoid !== false);
}

function driveToSite(obs, mem, site) {
  var d = num(site.distance, 99);
  var err = num(site.bearing, 0);
  var v;
  if (d < 1.7) v = 0.16;
  else if (d < 2.3) v = 0.30;
  else if (d < 3.5) v = 0.55;
  else if (d < 5.0) v = 0.95;
  else v = 1.65;
  return driveRel(obs, mem, err, v, true);
}

function goHome(obs, mem) {
  var bd = dist(mem.px, mem.py, mem.base.x, mem.base.y);
  var carried = Math.round(num(obs.carried, 0));
  var battery = num(obs.battery, 1);

  if (obs.beacon) {
    var be = num(obs.beacon.distance, 99);
    if (be < 20) {
      if (be < 2.4 || obs.docked) return holdCmd(obs, mem, false);
      var v = be > 8 ? 1.9 : (be > 4 ? 1.1 : 0.55);
      if (battery < 0.24) v = Math.min(v, 0.85);
      return driveRel(obs, mem, num(obs.beacon.bearing, 0), v, true);
    }
  }

  if (bd < 2.85 || obs.docked) return holdCmd(obs, mem, false);
  var sp = 2.05 - 0.06 * carried;
  if (battery < 0.24) sp = Math.min(sp, 0.90);
  if (mem.cautiousUntil > mem.t) sp = Math.min(sp, 1.0);
  return driveToPoint(obs, mem, mem.base.x, mem.base.y, Math.max(0.65, sp), true);
}

function makeSpiral(mem, cx, cy, R) {
  var pts = [];
  var pitch = 8.0;
  var a = pitch / (2 * Math.PI);
  var thetaMax = R / a;
  var lastx = null, lasty = null;
  for (var th = 0; th <= thetaMax + 0.05; th += 0.13) {
    var r = a * th;
    var x = clampX(mem, cx + r * Math.cos(th));
    var y = clampY(mem, cy + r * Math.sin(th));
    if (lastx == null || dist(x, y, lastx, lasty) > 1.45) {
      pts.push({ x: x, y: y });
      lastx = x;
      lasty = y;
    }
  }
  if (!pts.length) pts.push({ x: clampX(mem, cx), y: clampY(mem, cy) });
  return pts;
}

function followSpiral(obs, mem, t, task) {
  if (!task.searchPts) {
    task.searchPts = makeSpiral(mem, task.cx, task.cy, task.R || 22);
    task.idx = 0;
    task.searchStart = t;
    task.ptStart = t;
  }
  if (t - task.searchStart > (task.maxSearch || 45)) return -1;
  if (task.idx >= task.searchPts.length) return -1;

  var p = task.searchPts[task.idx];
  var d = dist(mem.px, mem.py, p.x, p.y);
  if (d < 1.7 || t - task.ptStart > 8.0) {
    task.idx++;
    task.ptStart = t;
    if (task.idx >= task.searchPts.length) return -1;
    p = task.searchPts[task.idx];
  }

  var sp = task.speed || 1.6;
  if (mem.cautiousUntil > t) sp = Math.min(sp, 1.0);
  return driveToPoint(obs, mem, p.x, p.y, sp, true);
}

function initExplore(mem) {
  var pts = [];
  var step = 55;
  var margin = 26;
  for (var y = mem.wMinY + margin; y <= mem.wMaxY - margin + 0.1; y += step) {
    for (var x = mem.wMinX + margin; x <= mem.wMaxX - margin + 0.1; x += step) {
      pts.push({ x: clampX(mem, x), y: clampY(mem, y), done: false, idx: pts.length });
    }
  }
  if (!pts.length) {
    pts.push({ x: mem.base.x, y: mem.base.y, done: false, idx: 0 });
  }
  mem.expPts = pts;
}

function chooseExplore(obs, mem, t) {
  if (!mem.expPts) initExplore(mem);
  var best = null, bd = 1e9;
  for (var i = 0; i < mem.expPts.length; i++) {
    var p = mem.expPts[i];
    if (p.done) continue;
    var d = dist(mem.px, mem.py, p.x, p.y);
    if (d < 7) {
      p.done = true;
      continue;
    }
    if (d < bd) {
      bd = d;
      best = p;
    }
  }
  if (!best) return null;
  return {
    type: "explore",
    x: best.x,
    y: best.y,
    idx: best.idx,
    start: t,
    bestD: bd,
    lastProg: t
  };
}

function needReturn(obs, mem, carried, baseD, timeLeft, battery) {
  if (carried <= 0) return false;

  if (carried >= mem.cap) return true;

  var tNeed = baseD / 1.25 + 30;
  if (timeLeft < tNeed + 18) return true;

  if (carried >= 2) return true;

  var em = Math.max(num(mem.ePerM, 0.001), 0.0008);
  var reserve = baseD * Math.max(0.0025, em * 3.0) * (1 + 0.15 * carried) + 0.08;
  if (battery < reserve) return true;
  if (battery < 0.26 && baseD > 12) return true;
  if (timeLeft < 180 && baseD > 90) return true;

  return false;
}

function canSampleNow(obs, mem, carried, baseD, timeLeft, battery) {
  if (carried >= mem.cap) return false;
  if (timeLeft < 12) return false;
  if (battery < 0.035) return false;
  if (carried > 0) {
    if (timeLeft < baseD / 1.20 + 12) return false;
    if (battery < 0.07) return false;
  }
  return true;
}

function onSampleSuccess(obs, mem, t) {
  mem.samplesTotal++;
  mem.lastCarryT = t;
  mem.sample = null;
  mem.chase = null;

  for (var i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.status === 0 && dist(h.x, h.y, mem.px, mem.py) < 36) {
      h.status = 2;
    }
  }
  if (mem.task && mem.task.type === "hint" && mem.task.id != null) {
    if (mem.hints[mem.task.id]) mem.hints[mem.task.id].status = 2;
  }
  mem.task = null;
}

function chooseTarget(obs, mem, carried, baseD, timeLeft, battery) {
  var t = mem.t;
  var i;

  if (!mem.localDone && mem.samplesTotal === 0) {
    mem.localDone = true;
    var nearHint = false;
    for (i = 0; i < mem.hints.length; i++) {
      var hn = mem.hints[i];
      if (hn.status === 0 && dist(hn.x, hn.y, mem.base.x, mem.base.y) < 28) {
        nearHint = true;
        break;
      }
    }
    if (!nearHint && timeLeft > 75) {
      return {
        type: "spiral",
        kind: "base",
        cx: mem.base.x,
        cy: mem.base.y,
        R: 24,
        maxSearch: 28,
        searchPts: null,
        idx: 0,
        searchStart: t,
        ptStart: t,
        speed: 1.55
      };
    }
  }

  var best = null, bestScore = -1e18;
  var med = mem.medEst || 1;

  for (i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.status !== 0) continue;

    var d = dist(mem.px, mem.py, h.x, h.y);
    var db = dist(h.x, h.y, mem.base.x, mem.base.y);
    var est = Math.max(0.1, num(h.est, 1));
    var high = est > med * 1.30;
    var searchCost = high ? 65 : 45;
    var score, cost, needT, eNeed;

    if (carried > 0) {
      if (carried >= 2) continue;
      var detour = Math.max(0, d + db - baseD);
      needT = (d + db) / 1.15 + searchCost + 28;
      if (timeLeft < needT) continue;
      cost = detour + searchCost * 0.80 + 20;
      score = est / Math.pow(cost, 0.90);
      if (est < med * 0.25 && detour > 45) score *= 0.35;
      if (mem.samplesDelivered === 0 && d < 60) score *= 1.20;
      eNeed = (d + db) * 0.0055 + 0.08;
    } else {
      needT = (d + db * 0.45) / 1.15 + searchCost + 28;
      if (timeLeft < needT) continue;
      cost = d + 0.30 * db + searchCost * 0.70 + 20;
      score = est / Math.pow(cost, 0.85);
      if (mem.samplesTotal === 0) score *= 1 / (1 + d / 160);
      eNeed = (d + db) * 0.0055 + 0.10;
    }

    if (battery < eNeed && d > 25) continue;

    if (score > bestScore) {
      bestScore = score;
      best = {
        type: "hint",
        id: i,
        phase: "travel",
        high: high,
        bestD: d,
        lastProg: t,
        lastPtProg: t,
        searchStart: 0,
        ptStart: 0,
        maxSearch: high ? 65 : 45,
        R: high ? 28 : 22,
        speed: high ? 1.8 : 1.6,
        searchPts: null,
        idx: 0
      };
    }
  }

  return best;
}

function runTask(obs, mem, carried, baseD, battery, timeLeft) {
  var t = mem.t;
  var task = mem.task;
  if (!task) return null;

  if (task.type === "hint") {
    var h = mem.hints[task.id];
    if (!h || h.status !== 0) {
      mem.task = null;
      return null;
    }

    if (task.phase === "travel") {
      var d = dist(mem.px, mem.py, h.x, h.y);
      if (!task.bestD || d < task.bestD - 0.4) {
        task.bestD = d;
        task.lastProg = t;
      }
      if (!task.lastProg) task.lastProg = t;

      if (t - task.lastProg > 25 && d > 7) {
        h.status = 2;
        mem.task = null;
        return null;
      }

      if (d < 4.5) {
        task.phase = "search";
        task.searchPts = null;
        task.searchStart = t;
        task.ptStart = t;
        task.maxSearch = task.high ? 65 : 45;
        task.R = task.high ? 28 : 22;
        task.speed = task.high ? 1.8 : 1.6;
      } else {
        var sp = 2.10 - 0.06 * carried;
        if (battery < 0.30) sp = Math.min(sp, 1.2);
        if (mem.cautiousUntil > t) sp = Math.min(sp, 1.0);
        return driveToPoint(obs, mem, h.x, h.y, Math.max(0.65, sp), true);
      }
    }

    if (task.phase === "search") {
      var ctl = followSpiral(obs, mem, t, task);
      if (ctl === -1) {
        h.status = 2;
        mem.task = null;
        return null;
      }
      return ctl;
    }
  }

  if (task.type === "spiral") {
    var ctl2 = followSpiral(obs, mem, t, task);
    if (ctl2 === -1) {
      mem.task = null;
      return null;
    }
    return ctl2;
  }

  if (task.type === "explore") {
    var de = dist(mem.px, mem.py, task.x, task.y);
    if (!task.bestD || de < task.bestD - 0.4) {
      task.bestD = de;
      task.lastProg = t;
    }
    if (!task.lastProg) task.lastProg = t;

    if (de < 5.0 || t - task.start > 42 || (t - task.lastProg > 22 && de > 5)) {
      if (mem.expPts && task.idx != null && mem.expPts[task.idx]) {
        mem.expPts[task.idx].done = true;
      }
      mem.task = null;
      return null;
    }

    var sp2 = 1.9 - 0.05 * carried;
    if (battery < 0.25) sp2 = Math.min(sp2, 1.0);
    return driveToPoint(obs, mem, task.x, task.y, sp2, true);
  }

  return null;
}

function act(obs, mem) {
  try {
    if (!mem.init) initMission(obs, mem);

    updateState(obs, mem);

    var t = mem.t;
    var carried = Math.round(num(obs.carried, 0));
    var battery = num(obs.battery, mem.lastBattery);
    mem.lastBattery = battery;
    var timeLeft = num(obs.timeLeft, mem.seconds - (t - mem.t0));
    if (!isFinite(timeLeft) || timeLeft < 0) timeLeft = 0;

    var prevCarried = mem.lastCarried;
    if (prevCarried == null) prevCarried = carried;

    if (carried > prevCarried && mem.sample) {
      onSampleSuccess(obs, mem, t);
    }
    if (carried < prevCarried) {
      mem.deliveries += prevCarried - carried;
      mem.samplesDelivered += prevCarried - carried;
      mem.returning = false;
      mem.sample = null;
      mem.chase = null;
      mem.chargeStart = null;
      mem.lastDeliveredAt = t;
    }
    mem.lastCarried = carried;

    var baseD = dist(mem.px, mem.py, mem.base.x, mem.base.y);

    if (obs.bumped) {
      var prevBump = mem.lastBumpT;
      if (t - prevBump > 0.6) {
        if (t - prevBump < 4.0) mem.bumpCount = (mem.bumpCount || 0) + 1;
        else mem.bumpCount = 1;
        mem.lastBumpT = t;
        mem.recoverUntil = t + 1.2;
        mem.escapeUntil = -1;
        mem.escapeDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
        mem.task = null;
        mem.sample = null;
        mem.chase = null;
        mem.cal.active = false;
        if (mem.bumpCount >= 3) mem.cautiousUntil = t + 20;
      }
    }

    if (t < mem.recoverUntil) {
      var ph = t - (mem.recoverUntil - 1.2);
      if (ph < 0.45) return wheelCtrl(obs, mem, -0.62, -0.62, false);
      var dr = mem.escapeDir || 1;
      return wheelCtrl(obs, mem, -0.34 * dr, 0.34 * dr, false);
    }
    if (t < mem.escapeUntil) {
      var ph2 = t - (mem.escapeUntil - 1.2);
      if (ph2 < 0.45) return wheelCtrl(obs, mem, -0.58, -0.58, false);
      var dr2 = mem.escapeDir || 1;
      return wheelCtrl(obs, mem, -0.32 * dr2, 0.32 * dr2, false);
    }

    if (mem.cal && mem.cal.active) {
      var closeSite = obs.site && num(obs.site.distance, 99) < 1.55;
      if (closeSite || frontMin(obs) < 1.0) {
        mem.cal.active = false;
      } else if (t - mem.cal.startT < 0.8) {
        return wheelCtrl(obs, mem, 0.72, 0.72, false);
      } else {
        var dx = mem.px - mem.cal.x0;
        var dy = mem.py - mem.cal.y0;
        if (dx * dx + dy * dy > 0.09) {
          var ma = Math.atan2(dy, dx) * R2D;
          var ra = norm180(num(obs.heading, mem.rawPrev) - mem.jumpOff);
          mem.bias = norm180(ma - midAng(ra, mem.cal.raw0));
          mem.biasN = Math.max(1, mem.biasN);
          mem.hdg = norm180(ra + mem.bias);
        }
        mem.cal.active = false;
        mem.calX = mem.px;
        mem.calY = mem.py;
        mem.calRaw = norm180(num(obs.heading, mem.rawPrev) - mem.jumpOff);
      }
    }

    var site = obs.site;
    if (t < mem.ignoreSiteUntil) site = null;

    if (site) {
      var sd0 = num(site.distance, 99);
      if (!mem.chase) {
        mem.chase = { start: t, best: sd0, lastProg: t };
      }
      if (sd0 < mem.chase.best - 0.25) {
        mem.chase.best = sd0;
        mem.chase.lastProg = t;
      }
      if (sd0 > 1.65 && t - mem.chase.lastProg > 12) {
        mem.ignoreSiteUntil = t + 8;
        mem.chase = null;
        mem.task = null;
        mem.escapeUntil = t + 1.2;
        mem.escapeDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
        site = null;
      }
    }

    if (t < mem.escapeUntil) {
      var ph3 = t - (mem.escapeUntil - 1.2);
      if (ph3 < 0.45) return wheelCtrl(obs, mem, -0.58, -0.58, false);
      var dr3 = mem.escapeDir || 1;
      return wheelCtrl(obs, mem, -0.32 * dr3, 0.32 * dr3, false);
    }

    if (mem.sample && carried <= mem.sample.carried0 && carried < mem.cap) {
      var siteNow = obs.site;
      var sdNow = siteNow ? num(siteNow.distance, 99) : 99;
      if (!siteNow || sdNow > 1.68 || t - mem.sample.startT > 24) {
        mem.sample = null;
      } else {
        return holdCmd(obs, mem, true);
      }
    }

    var beaconD = obs.beacon ? num(obs.beacon.distance, 99) : 99;
    var atBase = !!obs.docked || (obs.beacon && beaconD < 3.0) || baseD < 2.85;

    if (atBase) {
      if (carried > 0) {
        mem.returning = false;
        mem.task = null;
        mem.sample = null;
        mem.chase = null;
        return holdCmd(obs, mem, false);
      }

      mem.returning = false;
      mem.task = null;
      mem.sample = null;
      mem.chase = null;

      if (battery < 0.65 && timeLeft > 85) {
        if (mem.chargeStart == null) mem.chargeStart = t;
        if (t - mem.chargeStart < 22) return holdCmd(obs, mem, false);
      } else {
        mem.chargeStart = null;
      }
    } else {
      mem.chargeStart = null;
    }

    var mustReturn = false;
    if (carried > 0) {
      mustReturn = needReturn(obs, mem, carried, baseD, timeLeft, battery);
    } else {
      if (battery < 0.12 && baseD > 10) mustReturn = true;
      if (timeLeft < 12 && baseD > 6) mustReturn = true;
    }

    if (mustReturn) mem.returning = true;

    if (mem.returning) {
      if (carried === 0 && baseD < 2.9) {
        mem.returning = false;
      } else {
        mem.task = null;
        mem.sample = null;
        mem.chase = null;
        return goHome(obs, mem);
      }
    }

    if (site && carried < mem.cap && !mem.returning &&
        canSampleNow(obs, mem, carried, baseD, timeLeft, battery)) {
      var sd = num(site.distance, 99);
      if (sd <= 1.36) {
        mem.sample = {
          startT: t,
          carried0: carried
        };
        mem.hIL = 0;
        mem.hIR = 0;
        mem.task = null;
        mem.chase = null;
        return holdCmd(obs, mem, true);
      }
      return driveToSite(obs, mem, site);
    }

    if (carried > 0 && !mem.returning && t - num(mem.lastCarryT, t) > 180) {
      mem.returning = true;
      mem.task = null;
      mem.sample = null;
      return goHome(obs, mem);
    }

    if (!mem.task) {
      var chosen = chooseTarget(obs, mem, carried, baseD, timeLeft, battery);

      if (!chosen && carried < mem.cap && !mem.returning &&
          num(obs.science, 0) > 1.8 && t > num(mem.sciCooldown, 0) &&
          timeLeft > 75) {
        chosen = {
          type: "spiral",
          kind: "science",
          cx: mem.px,
          cy: mem.py,
          R: 17,
          maxSearch: 22,
          searchPts: null,
          idx: 0,
          searchStart: t,
          ptStart: t,
          speed: 1.5
        };
        mem.sciCooldown = t + 85;
      }

      if (!chosen && carried === 0) {
        chosen = chooseExplore(obs, mem, t);
      }

      if (!chosen) {
        if (carried > 0) {
          mem.returning = true;
          mem.task = null;
          return goHome(obs, mem);
        }
        return holdCmd(obs, mem, false);
      }

      mem.task = chosen;
    }

    if (mem.task) {
      var ctl = runTask(obs, mem, carried, baseD, battery, timeLeft);
      if (ctl) return ctl;
      return holdCmd(obs, mem, false);
    }

    if (carried > 0) {
      mem.returning = true;
      return goHome(obs, mem);
    }

    return holdCmd(obs, mem, false);
  } catch (e) {
    mem.errCount = (mem.errCount || 0) + 1;
    mem.lastError = String(e);
    return { left: 0, right: 0, drill: false };
  }
}

var D2R = Math.PI / 180;
var R2D = 180 / Math.PI;
var RA = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function N(v, d) {
  v = +v;
  return isFinite(v) ? v : d;
}
function clamp(v, a, b) {
  v = +v;
  if (!isFinite(v)) return a;
  return v < a ? a : (v > b ? b : v);
}
function norm(a) {
  a = +a;
  if (!isFinite(a)) return 0;
  return ((a + 180) % 360 + 360) % 360 - 180;
}
function dist(x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
}
function midAng(a, b) {
  return norm(a + norm(b - a) / 2);
}
function frontMin(obs) {
  var r = obs.rays || [], m = 15;
  for (var i = 0; i < 9 && i < r.length; i++) {
    if (RA[i] >= -30 && RA[i] <= 30) m = Math.min(m, N(r[i], 15));
  }
  return m;
}
function leftClear(obs) {
  var r = obs.rays || [], m = 15;
  for (var i = 0; i < 9 && i < r.length; i++) {
    if (RA[i] >= 20) m = Math.min(m, N(r[i], 15));
  }
  return m;
}
function rightClear(obs) {
  var r = obs.rays || [], m = 15;
  for (var i = 0; i < 9 && i < r.length; i++) {
    if (RA[i] <= -20) m = Math.min(m, N(r[i], 15));
  }
  return m;
}

function initMission(obs, mem) {
  mem.init = true;
  mem.t0 = N(obs.t, 0);
  mem.lastT = mem.t0;
  mem.dt = 0.1;

  var m = obs.mission || {};
  mem.seconds = N(m.seconds, 1200);
  mem.cap = Math.round(N(m.capacity, 5));
  if (!(mem.cap > 0)) mem.cap = 5;

  var b = m.base || {};
  mem.base = {
    x: N(b.x, N(obs.x, 0)),
    y: N(b.y, N(obs.y, 0))
  };

  var sx = 400, sy = 400, sz = m.size;
  if (typeof sz === "number") {
    sx = sy = N(sz, 400);
  } else if (Array.isArray(sz)) {
    sx = N(sz[0], 400);
    sy = N(sz[1], sx);
  } else if (sz && typeof sz === "object") {
    sx = N(sz.x, N(sz.width, 400));
    sy = N(sz.y, N(sz.height, sx));
  }
  if (!(sx > 20)) sx = 400;
  if (!(sy > 20)) sy = 400;

  var hs = m.hints || [], i;
  mem.hints = [];
  var minx = mem.base.x, maxx = mem.base.x, miny = mem.base.y, maxy = mem.base.y;
  for (i = 0; i < hs.length; i++) {
    var h = hs[i] || {};
    var hx = N(h.x, mem.base.x);
    var hy = N(h.y, mem.base.y);
    var est = N(h.estimate, 1);
    if (!(est > 0)) est = 1;
    mem.hints.push({ x: hx, y: hy, est: est, state: 0 });
    if (hx < minx) minx = hx;
    if (hx > maxx) maxx = hx;
    if (hy < miny) miny = hy;
    if (hy > maxy) maxy = hy;
  }

  var centered = minx < -5 || miny < -5 || maxx > sx + 5 || maxy > sy + 5;
  if (centered) {
    mem.wMinX = -sx / 2;
    mem.wMaxX = sx / 2;
    mem.wMinY = -sy / 2;
    mem.wMaxY = sy / 2;
  } else {
    mem.wMinX = 0;
    mem.wMaxX = sx;
    mem.wMinY = 0;
    mem.wMaxY = sy;
  }

  var vals = [];
  for (i = 0; i < mem.hints.length; i++) vals.push(mem.hints[i].est);
  vals.sort(function (a, b) { return a - b; });
  mem.medEst = vals.length ? vals[Math.floor(vals.length / 2)] : 1;

  mem.px = N(obs.x, mem.base.x);
  mem.py = N(obs.y, mem.base.y);
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastGpsX = mem.px;
  mem.lastGpsY = mem.py;
  mem.gpsStill = 0;
  mem.bodySpeed = 0;

  mem.raw = norm(N(obs.heading, 0));
  mem.lastRaw = mem.raw;
  mem.jumpOff = 0;
  mem.bias = 0;
  mem.biasN = 0;
  mem.hdg = mem.raw;

  mem.calX = mem.px;
  mem.calY = mem.py;
  mem.calRaw = mem.raw;

  mem.lastWl = N(obs.wheelLeft, 0);
  mem.lastWr = N(obs.wheelRight, 0);
  mem.mL = { i: 0 };
  mem.mR = { i: 0 };

  mem.battery = N(obs.battery, 1);
  mem.lastBattery = mem.battery;
  mem.ePerM = 0.002;
  mem.eN = 0;

  mem.lastCarried = Math.round(N(obs.carried, 0));
  mem.samplesTotal = 0;
  mem.tripsDone = 0;
  mem.deliveredOnce = false;

  mem.sample = null;
  mem.task = null;
  mem.returning = false;
  mem.ignoreUntil = -1;
  mem.escapeUntil = -1;
  mem.escapeDir = 1;
  mem.recoverUntil = -1;
  mem.recoverDir = 1;
  mem.lastBumpT = -99;
  mem.bumpCount = 0;
  mem.cautiousUntil = 0;
  mem.blacklist = [];
  mem.chase = null;
  mem.chargeStart = null;

  mem.calPhase = true;
  mem.calPhaseStart = mem.t0;
  mem.calStartX = mem.px;
  mem.calStartY = mem.py;
  mem.calStartRaw = mem.raw;

  mem.expPts = null;
  mem.sciCooldown = 0;
  mem.lastError = "";
  mem.errCount = 0;
}

function updateState(obs, mem) {
  var t = N(obs.t, mem.lastT);
  var dt = t - N(mem.lastT, t - 0.1);
  if (!(dt > 0) || dt > 0.5) dt = 0.1;
  mem.dt = dt;
  mem.t = t;

  var wl = N(obs.wheelLeft, 0);
  var wr = N(obs.wheelRight, 0);
  var avg = (wl + wr) / 2;
  var raw = norm(N(obs.heading, mem.lastRaw));
  var yaw = ((wr - wl) / 0.6) * R2D * dt;
  var dRaw = norm(raw - mem.lastRaw);

  if (Math.abs(dRaw) > 65 && Math.abs(yaw) < 15) {
    mem.jumpOff = norm(mem.jumpOff - dRaw);
  }
  var eff = norm(raw + mem.jumpOff);
  var pred = norm(mem.hdg + yaw);
  var comp = norm(eff + mem.bias);
  var dh = norm(comp - pred);

  if (Math.abs(dh) < 55) {
    mem.hdg = norm(pred + dh * 0.55);
  } else if (Math.abs(avg) < 0.08) {
    var dh2 = norm(comp - mem.hdg);
    if (Math.abs(dh2) < 80) mem.hdg = norm(mem.hdg + dh2 * 0.18);
  } else {
    mem.hdg = pred;
  }

  var gx = N(obs.x, mem.px);
  var gy = N(obs.y, mem.py);
  var gMove = dist(gx, gy, mem.lastGpsX, mem.lastGpsY);
  if (gMove < 0.006 && Math.abs(avg) > 0.08) mem.gpsStill += dt;
  else if (gMove > 0.03) mem.gpsStill = 0;
  else mem.gpsStill = Math.max(0, mem.gpsStill - dt * 1.5);

  var frozen = mem.gpsStill > 1.2;
  var oldpx = mem.px, oldpy = mem.py;
  if (frozen) {
    mem.px += avg * Math.cos(mem.hdg * D2R) * dt;
    mem.py += avg * Math.sin(mem.hdg * D2R) * dt;
  } else {
    mem.px = gx;
    mem.py = gy;
  }
  mem.px = clamp(mem.px, mem.wMinX + 0.2, mem.wMaxX - 0.2);
  mem.py = clamp(mem.py, mem.wMinY + 0.2, mem.wMaxY - 0.2);

  var moved = dist(mem.px, mem.py, oldpx, oldpy);
  mem.bodySpeed = moved / dt;

  if (!frozen && gMove > 0.01) {
    var calD = dist(gx, gy, mem.calX, mem.calY);
    if (calD > 0.9 && Math.abs(wr - wl) < 0.9 && Math.abs(avg) > 0.15) {
      var movAng = Math.atan2(gy - mem.calY, gx - mem.calX) * R2D;
      var avgRaw = midAng(eff, mem.calRaw);
      var sb = norm(movAng - avgRaw);
      var bd = norm(sb - mem.bias);
      if (Math.abs(bd) < 85) {
        var alpha = mem.biasN < 6 ? 0.28 : 0.02;
        mem.bias = norm(mem.bias + bd * alpha);
        mem.hdg = norm(mem.hdg + bd * alpha * 0.5);
        mem.biasN++;
      }
      mem.calX = gx;
      mem.calY = gy;
      mem.calRaw = eff;
    } else if (calD > 2.5 && Math.abs(wr - wl) > 1.0) {
      mem.calX = gx;
      mem.calY = gy;
      mem.calRaw = eff;
    }
  }

  var bat = N(obs.battery, mem.lastBattery);
  var eDist = dist(mem.px, mem.py, mem.lastPx, mem.lastPy);
  if (eDist > 0.1 && !mem.sample) {
    var drop = mem.lastBattery - bat;
    if (drop > 0 && drop < 0.2) {
      var e = drop / eDist;
      if (e > 0.00001 && e < 0.2) {
        if (mem.eN < 3) mem.ePerM = e;
        else mem.ePerM = mem.ePerM * 0.97 + e * 0.03;
        mem.eN++;
      }
    }
  }

  mem.lastRaw = raw;
  mem.lastWl = wl;
  mem.lastWr = wr;
  mem.lastGpsX = gx;
  mem.lastGpsY = gy;
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastBattery = bat;
  mem.battery = bat;
  mem.lastT = t;
}

function wheelDrive(obs, mem, tl, tr, drillFlag) {
  var dt = mem.dt || 0.1;
  var wl = N(obs.wheelLeft, 0);
  var wr = N(obs.wheelRight, 0);

  function one(st, target, actual) {
    target = clamp(target, -2.9, 2.9);
    var err = target - actual;
    st.i = clamp(st.i + err * dt * 0.65, -1.5, 1.5);

    var ff = 0;
    if (target > 0.05) ff = 0.10 + 0.31 * target;
    else if (target < -0.05) ff = -0.10 + 0.31 * target;

    var u = ff + 0.48 * err + 0.18 * st.i;
    if (Math.abs(target) < 0.03) u = 0.55 * err + 0.12 * st.i;

    if (u > 1) {
      u = 1;
      if (err > 0) st.i = Math.min(st.i, 0.8);
    }
    if (u < -1) {
      u = -1;
      if (err < 0) st.i = Math.max(st.i, -0.8);
    }
    return clamp(u, -1, 1);
  }

  return {
    left: one(mem.mL, tl, wl),
    right: one(mem.mR, tr, wr),
    drill: !!drillFlag
  };
}

function driveRel(obs, mem, err, v, avoid) {
  var rays = obs.rays || [];
  var front = 15, lc = 15, rc = 15, steer = 0;
  var i, r, a, w;

  for (i = 0; i < 9 && i < rays.length; i++) {
    r = N(rays[i], 15);
    if (r < 0) r = 0;
    if (r > 15) r = 15;
    a = RA[i];
    if (a >= -30 && a <= 30) front = Math.min(front, r);
    if (a >= 20) lc = Math.min(lc, r);
    if (a <= -20) rc = Math.min(rc, r);

    if (avoid && r < 4.5) {
      w = (4.5 - r) / 4.5;
      w *= w;
      if (a > 10) steer -= w * 34;
      else if (a < -10) steer += w * 34;
    }
  }

  if (avoid) {
    if (front < 3.0) {
      var side = lc >= rc ? 1 : -1;
      steer += side * (3.0 - front) * 11;
    }
    if (front < 0.55) v = 0;
    else if (front < 1.0) v = Math.min(v, 0.25);
    else if (front < 1.8) v = Math.min(v, 0.60);
    else if (front < 3.0) v = Math.min(v, 1.20);
    else if (front < 5.0) v = Math.min(v, 2.00);
    if (lc < 0.40 || rc < 0.40) v = Math.min(v, 0.60);
  }

  var e = norm(err + clamp(steer, -72, 72));
  var ae = Math.abs(e);
  if (ae > 120) v = Math.min(v, 0.05);
  else if (ae > 90) v = Math.min(v, 0.20);
  else if (ae > 50) v *= 0.70;

  var omega = clamp(e * D2R * 1.8, -2.4, 2.4);
  if (ae < 2.0) omega = 0;

  var tl = v - omega * 0.3;
  var tr = v + omega * 0.3;
  if (v < 0.10 && ae > 20) {
    tl = -omega * 0.3;
    tr = omega * 0.3;
  }
  return wheelDrive(obs, mem, tl, tr, false);
}

function driveToPoint(obs, mem, x, y, speed, avoid) {
  var d = dist(mem.px, mem.py, x, y);
  if (d < 0.65) return wheelDrive(obs, mem, 0, 0, false);
  var bearing = Math.atan2(y - mem.py, x - mem.px) * R2D;
  var err = norm(bearing - mem.hdg);
  var sp = speed;
  if (d < 2.5) sp = Math.min(sp, 0.55);
  else if (d < 5.0) sp = Math.min(sp, 1.20);
  return driveRel(obs, mem, err, sp, avoid !== false);
}

function stopCmd(obs, mem) {
  return wheelDrive(obs, mem, 0, 0, false);
}

function makeSpiral(mem, cx, cy, R) {
  var pts = [];
  var pitch = 12.0;
  var a = pitch / (2 * Math.PI);
  var thmax = R / a;
  var lastx = null, lasty = null;
  for (var th = 0; th <= thmax + 0.05; th += 0.16) {
    var r = a * th;
    var x = clamp(cx + r * Math.cos(th), mem.wMinX + 2, mem.wMaxX - 2);
    var y = clamp(cy + r * Math.sin(th), mem.wMinY + 2, mem.wMaxY - 2);
    if (lastx === null || dist(x, y, lastx, lasty) > 1.5) {
      pts.push({ x: x, y: y });
      lastx = x;
      lasty = y;
    }
  }
  if (!pts.length) pts.push({ x: cx, y: cy });
  return pts;
}

function approachSite(obs, mem, site) {
  var d = N(site.distance, 99);
  var b = N(site.bearing, 0);
  var v;
  if (d > 5.0) v = 1.50;
  else if (d > 3.0) v = 0.85;
  else if (d > 2.0) v = 0.45;
  else if (d > 1.55) v = 0.18;
  else v = 0.07;
  if (Math.abs(b) > 55) v = Math.min(v, 0.50);
  return driveRel(obs, mem, b, v, d > 2.0);
}

function markNearHints(mem, x, y, r, state) {
  for (var i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.state === 0 && dist(h.x, h.y, x, y) < r) h.state = state;
  }
}

function abortSample(obs, mem, t) {
  mem.blacklist.push({ x: mem.px, y: mem.py, until: t + 240 });
  if (mem.blacklist.length > 24) mem.blacklist.shift();
  markNearHints(mem, mem.px, mem.py, 42, 1);
  mem.sample = null;
  mem.task = null;
  mem.chase = null;
  mem.ignoreUntil = t + 12;
  mem.escapeUntil = t + 1.4;
  mem.escapeDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
}

function runSample(obs, mem, t, battery) {
  var s = mem.sample;
  var site = obs.site;
  var d = site ? N(site.distance, 99) : 99;
  var wl = N(obs.wheelLeft, 0);
  var wr = N(obs.wheelRight, 0);
  var avg = (wl + wr) / 2;
  var dr = N(obs.drilling, 0);

  if (s.lastDrill > 0.4 && dr + 0.35 < s.lastDrill) s.resets++;
  s.lastDrill = dr;

  if (t - s.start > 26 || battery < 0.07 || s.resets > 3) {
    abortSample(obs, mem, t);
    return null;
  }

  if (!site) {
    if (dr < 5.2) {
      abortSample(obs, mem, t);
      return null;
    }
  } else if (d > 1.58) {
    abortSample(obs, mem, t);
    return null;
  }

  var pitch = N(obs.pitch, 0);
  var fdx = s.ax - mem.px;
  var fdy = s.ay - mem.py;
  var fwd = fdx * Math.cos(mem.hdg * D2R) + fdy * Math.sin(mem.hdg * D2R);

  var u = 0;
  if (Math.abs(fwd) > 0.04) u += clamp(fwd * 0.9, -0.20, 0.20);
  u += clamp(pitch * 0.004, -0.10, 0.10);
  u += clamp(-avg * 0.50, -0.25, 0.25);

  var uL = u - wl * 0.35;
  var uR = u - wr * 0.35;

  var disp = Math.sqrt(fdx * fdx + fdy * fdy);
  if (disp > 0.50) {
    var corr = clamp(fwd * 1.2, -0.30, 0.30);
    uL += corr;
    uR += corr;
  }

  return {
    left: clamp(uL, -0.62, 0.62),
    right: clamp(uR, -0.62, 0.62),
    drill: true
  };
}

function needReturn(obs, mem, carried, baseD, timeLeft, battery) {
  if (carried <= 0) return false;
  if (carried >= mem.cap) return true;
  if (!mem.deliveredOnce) return true;
  if (carried >= 3) return true;

  var e = Math.max(0.0008, mem.ePerM || 0.002);
  var reserve = 0.08 + baseD * e * (1 + 0.15 * carried) * 4 + 0.025 * carried;
  if (battery < reserve) return true;
  if (battery < 0.22 && baseD > 25) return true;
  if (timeLeft < baseD / 0.85 + 35) return true;
  if (timeLeft < 120) return true;
  return false;
}

function canSampleNow(obs, mem, carried, baseD, timeLeft, battery) {
  if (carried >= mem.cap) return false;
  if (timeLeft < 15) return false;
  if (battery < 0.045) return false;
  if (carried > 0) {
    if (timeLeft < baseD / 0.8 + 15) return false;
    if (battery < 0.08) return false;
  }
  return true;
}

function goHome(obs, mem) {
  var bd = dist(mem.px, mem.py, mem.base.x, mem.base.y);
  var carried = Math.round(N(obs.carried, 0));
  var battery = N(obs.battery, 1);

  if (obs.beacon) {
    var be = N(obs.beacon.distance, 99);
    if (be < 20) {
      if (be < 2.2 || obs.docked) return stopCmd(obs, mem);
      var v = be > 8 ? 1.8 : (be > 4 ? 1.0 : 0.50);
      if (battery < 0.18) v = Math.min(v, 0.75);
      return driveRel(obs, mem, N(obs.beacon.bearing, 0), v, true);
    }
  }

  if (bd < 2.0 || obs.docked) return stopCmd(obs, mem);
  var sp = 1.9 - 0.05 * carried;
  if (battery < 0.20) sp = Math.min(sp, 0.95);
  return driveToPoint(obs, mem, mem.base.x, mem.base.y, Math.max(0.65, sp), true);
}

function chooseHint(obs, mem, carried, baseD, timeLeft, battery) {
  var best = null, bestScore = -1e18;
  var med = mem.medEst || 1;

  for (var i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.state !== 0) continue;

    var d = dist(mem.px, mem.py, h.x, h.y);
    var db = dist(h.x, h.y, mem.base.x, mem.base.y);
    var est = Math.max(0.05, h.est);
    var search = est > med * 1.30 ? 65 : 50;

    if (carried > 0) {
      if (timeLeft < (d + db) / 1.10 + search + 35) continue;
    } else {
      if (timeLeft < d / 1.10 + search + 25) continue;
    }

    if (battery < 0.08 && d > 25) continue;

    var cost = d + search * 0.70 + (carried > 0 ? 0.30 * db : 0.15 * db) + 15;
    var score = est / Math.pow(Math.max(1, cost), 0.90);

    if (!mem.deliveredOnce) score *= 1 / (1 + d / 180);
    if (d < 25) score *= 1.20;
    if (est > med * 2.0) score *= 1.15;
    if (db > 240) score *= 0.7;

    if (score > bestScore) {
      bestScore = score;
      best = {
        type: "hint",
        idx: i,
        phase: "travel",
        t0: mem.t,
        lastD: d,
        lastProg: mem.t,
        searchPts: null,
        si: 0,
        ptStart: mem.t,
        searchStart: 0,
        R: est > med * 1.30 ? 26 : 20,
        maxSearch: search
      };
    }
  }
  return best;
}

function chooseExplore(obs, mem, t) {
  if (!mem.expPts) {
    mem.expPts = [];
    var step = 55;
    for (var y = mem.wMinY + 20; y <= mem.wMaxY - 20 + 0.1; y += step) {
      for (var x = mem.wMinX + 20; x <= mem.wMaxX - 20 + 0.1; x += step) {
        mem.expPts.push({ x: x, y: y, done: false });
      }
    }
  }

  if (N(obs.science, 0) > 1.25 && t > mem.sciCooldown) {
    mem.sciCooldown = t + 70;
    return {
      type: "spiral",
      cx: mem.px,
      cy: mem.py,
      R: 17,
      maxSearch: 26,
      searchPts: null,
      si: 0,
      ptStart: t,
      searchStart: t,
      t0: t
    };
  }

  var bi = -1, bd = 1e9;
  for (var i = 0; i < mem.expPts.length; i++) {
    var p = mem.expPts[i];
    if (p.done) continue;
    var d = dist(mem.px, mem.py, p.x, p.y);
    if (d < 7) {
      p.done = true;
      continue;
    }
    if (d < bd) {
      bd = d;
      bi = i;
    }
  }

  if (bi >= 0) {
    var q = mem.expPts[bi];
    return {
      type: "point",
      idx: bi,
      x: q.x,
      y: q.y,
      t0: t
    };
  }

  return {
    type: "spiral",
    cx: mem.px,
    cy: mem.py,
    R: 16,
    maxSearch: 24,
    searchPts: null,
    si: 0,
    ptStart: t,
    searchStart: t,
    t0: t
  };
}

function runTask(obs, mem, t, carried, baseD, battery, timeLeft) {
  var task = mem.task;
  if (!task) return null;

  if (task.type === "hint") {
    var h = mem.hints[task.idx];
    if (!h || h.state !== 0) {
      mem.task = null;
      return null;
    }

    if (task.phase === "travel") {
      var d = dist(mem.px, mem.py, h.x, h.y);
      if (d < task.lastD - 0.35) {
        task.lastD = d;
        task.lastProg = t;
      }

      if (t - task.lastProg > 30 && d > 6) {
        h.state = 1;
        mem.task = null;
        return null;
      }

      if (d < 5.0) {
        task.phase = "search";
        task.searchPts = null;
        task.si = 0;
        task.searchStart = t;
        task.ptStart = t;
      } else {
        var sp = 1.85;
        if (battery < 0.28) sp = Math.min(sp, 1.10);
        if (mem.cautiousUntil > t) sp = Math.min(sp, 1.0);
        return driveToPoint(obs, mem, h.x, h.y, Math.max(0.65, sp), true);
      }
    }

    if (task.phase === "search") {
      if (!task.searchPts) {
        task.searchPts = makeSpiral(mem, h.x, h.y, task.R || 20);
        task.si = 0;
        task.searchStart = t;
        task.ptStart = t;
      }

      if (t - task.searchStart > (task.maxSearch || 50) ||
          task.si >= task.searchPts.length) {
        h.state = 1;
        mem.task = null;
        return null;
      }

      var p = task.searchPts[task.si];
      var dp = dist(mem.px, mem.py, p.x, p.y);
      if (dp < 1.9 || t - task.ptStart > 8.0) {
        task.si++;
        task.ptStart = t;
        if (task.si >= task.searchPts.length) {
          h.state = 1;
          mem.task = null;
          return null;
        }
        p = task.searchPts[task.si];
      }

      var sp2 = 1.70;
      if (battery < 0.25) sp2 = Math.min(sp2, 1.0);
      if (mem.cautiousUntil > t) sp2 = Math.min(sp2, 1.05);
      return driveToPoint(obs, mem, p.x, p.y, sp2, true);
    }
  }

  if (task.type === "point") {
    var dq = dist(mem.px, mem.py, task.x, task.y);
    if (dq < 4.5 || t - task.t0 > 50) {
      if (mem.expPts && mem.expPts[task.idx]) mem.expPts[task.idx].done = true;
      mem.task = null;
      return null;
    }
    var spq = 1.55;
    if (battery < 0.25) spq = Math.min(spq, 0.95);
    return driveToPoint(obs, mem, task.x, task.y, spq, true);
  }

  if (task.type === "spiral") {
    if (!task.searchPts) {
      task.searchPts = makeSpiral(mem, task.cx, task.cy, task.R || 16);
      task.si = 0;
      task.searchStart = t;
      task.ptStart = t;
    }

    if (t - task.searchStart > (task.maxSearch || 25) ||
        task.si >= task.searchPts.length) {
      mem.task = null;
      return null;
    }

    var ps = task.searchPts[task.si];
    var ds = dist(mem.px, mem.py, ps.x, ps.y);
    if (ds < 1.9 || t - task.ptStart > 8.0) {
      task.si++;
      task.ptStart = t;
      if (task.si >= task.searchPts.length) {
        mem.task = null;
        return null;
      }
      ps = task.searchPts[task.si];
    }

    var sps = 1.50;
    if (battery < 0.25) sps = Math.min(sps, 0.95);
    return driveToPoint(obs, mem, ps.x, ps.y, sps, true);
  }

  mem.task = null;
  return null;
}

function act(obs, mem) {
  try {
    if (!mem.init) initMission(obs, mem);

    updateState(obs, mem);

    var t = mem.t;
    var dt = mem.dt || 0.1;
    var timeLeft = N(obs.timeLeft, mem.seconds - (t - mem.t0));
    if (!isFinite(timeLeft) || timeLeft < 0) timeLeft = 0;

    var battery = N(obs.battery, mem.battery);
    var carried = Math.round(N(obs.carried, mem.lastCarried));
    var baseD = dist(mem.px, mem.py, mem.base.x, mem.base.y);
    var beaconD = obs.beacon ? N(obs.beacon.distance, 99) : 99;
    var atBase = !!obs.docked || beaconD < 2.8 || baseD < 2.8;

    var prevCarried = mem.lastCarried;

    if (carried > prevCarried) {
      mem.samplesTotal++;
      if (mem.sample && mem.sample.hintIdx >= 0) {
        var hi = mem.sample.hintIdx;
        if (mem.hints[hi]) mem.hints[hi].state = 2;
      }
      markNearHints(mem, mem.px, mem.py, 42, 2);
      mem.sample = null;
      mem.task = null;
      mem.chase = null;
      mem.ignoreUntil = -1;

      if (!mem.deliveredOnce || carried >= mem.cap || carried >= 3) {
        mem.returning = true;
      } else if (timeLeft < baseD / 0.8 + 110) {
        mem.returning = true;
      }
    }

    if (carried < prevCarried) {
      mem.deliveredOnce = true;
      mem.tripsDone += prevCarried - carried;
      mem.returning = false;
      mem.task = null;
      mem.sample = null;
      mem.chase = null;
      mem.chargeStart = t;
    }

    mem.lastCarried = carried;

    if (carried >= mem.cap) mem.returning = true;

    if (obs.bumped) {
      if (t - mem.lastBumpT > 0.6) {
        if (t - mem.lastBumpT < 4.0) mem.bumpCount++;
        else mem.bumpCount = 1;
        mem.lastBumpT = t;
        mem.recoverUntil = t + 1.2;
        mem.recoverDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
        mem.task = null;
        mem.chase = null;
        mem.sample = null;
        mem.ignoreUntil = Math.max(mem.ignoreUntil, t + 8);
        if (mem.bumpCount >= 3) mem.cautiousUntil = t + 20;
      }
    }

    if (t < mem.recoverUntil) {
      var ph = t - (mem.recoverUntil - 1.2);
      if (ph < 0.45) return wheelDrive(obs, mem, -0.72, -0.72, false);
      var dr = mem.recoverDir || 1;
      return wheelDrive(obs, mem, -dr * 0.38, dr * 0.38, false);
    }

    if (mem.calPhase) {
      if (t - mem.calPhaseStart < 0.9 && frontMin(obs) > 1.1) {
        return wheelDrive(obs, mem, 1.0, 1.0, false);
      }

      var md = dist(mem.px, mem.py, mem.calStartX, mem.calStartY);
      if (md > 0.25 && !mem.gpsStill) {
        var ma = Math.atan2(mem.py - mem.calStartY, mem.px - mem.calStartX) * R2D;
        var ra = midAng(mem.lastRaw, mem.calStartRaw);
        var targetBias = norm(ma - ra);
        var db = norm(targetBias - mem.bias);
        if (Math.abs(db) < 120) {
          mem.bias = norm(mem.bias + db * 0.75);
          mem.hdg = norm(mem.lastRaw + mem.jumpOff + mem.bias);
        }
      }
      mem.calPhase = false;
      mem.calX = mem.px;
      mem.calY = mem.py;
      mem.calRaw = norm(mem.lastRaw + mem.jumpOff);
    }

    if (mem.sample) {
      var sampleCtl = runSample(obs, mem, t, battery);
      if (sampleCtl) return sampleCtl;
    }

    if (t < mem.escapeUntil) {
      var ph2 = t - (mem.escapeUntil - 1.4);
      if (ph2 < 0.50) return wheelDrive(obs, mem, -0.60, -0.60, false);
      var dirE = mem.escapeDir || 1;
      return wheelDrive(obs, mem, -dirE * 0.35, dirE * 0.35, false);
    }

    if (atBase && carried === 0 && !mem.returning) {
      if (battery < 0.88 && timeLeft > 70) {
        if (mem.chargeStart == null) mem.chargeStart = t;
        var maxWait = battery < 0.35 ? 30 : 12;
        if (t - mem.chargeStart < maxWait && battery < 0.93) {
          return stopCmd(obs, mem);
        }
      }
      if (battery >= 0.88 || (mem.chargeStart != null && t - mem.chargeStart > 22)) {
        mem.chargeStart = null;
      }
    } else if (!atBase) {
      mem.chargeStart = null;
    }

    if (carried > 0) {
      if (!mem.returning && needReturn(obs, mem, carried, baseD, timeLeft, battery)) {
        mem.returning = true;
      }
    } else {
      if (!mem.returning && baseD > 8) {
        if (battery < 0.08 || (timeLeft < baseD / 0.70 + 15)) {
          mem.returning = true;
        }
      }
    }

    if (mem.returning) {
      if (carried === 0 && atBase) {
        mem.returning = false;
      } else {
        if (atBase && carried > 0) return stopCmd(obs, mem);
        return goHome(obs, mem);
      }
    }

    if (atBase && carried > 0) return stopCmd(obs, mem);

    if (!mem.returning && carried < mem.cap && obs.site &&
        timeLeft > 8 && battery > 0.04 &&
        canSampleNow(obs, mem, carried, baseD, timeLeft, battery)) {
      var site = obs.site;
      var sd = N(site.distance, 99);
      var sb = N(site.bearing, 0);

      var blocked = t < mem.ignoreUntil;
      if (!blocked) {
        for (var bi = 0; bi < mem.blacklist.length; bi++) {
          var bl = mem.blacklist[bi];
          if (t < bl.until && dist(mem.px, mem.py, bl.x, bl.y) < 4.5) {
            blocked = true;
            break;
          }
        }
      }

      if (!blocked) {
        if (!mem.chase) {
          mem.chase = { start: t, best: sd, lastProg: t };
        }
        if (sd < mem.chase.best - 0.25) {
          mem.chase.best = sd;
          mem.chase.lastProg = t;
        }

        if (t - mem.chase.lastProg > 30 && sd > 2.0) {
          var estAngle = (mem.hdg + sb) * D2R;
          var esx = mem.px + sd * Math.cos(estAngle);
          var esy = mem.py + sd * Math.sin(estAngle);
          mem.blacklist.push({ x: esx, y: esy, until: t + 200 });
          if (mem.blacklist.length > 24) mem.blacklist.shift();
          markNearHints(mem, esx, esy, 45, 1);
          mem.ignoreUntil = t + 12;
          mem.escapeUntil = t + 1.4;
          mem.escapeDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
          mem.chase = null;
          mem.task = null;
          return wheelDrive(obs, mem, -0.50, -0.50, false);
        }

        var maxW = Math.max(Math.abs(N(obs.wheelLeft, 0)), Math.abs(N(obs.wheelRight, 0)));
        if (sd <= 1.38 && mem.bodySpeed < 0.060 && maxW < 0.095) {
          mem.sample = {
            start: t,
            ax: mem.px,
            ay: mem.py,
            lastDrill: N(obs.drilling, 0),
            resets: 0,
            carried0: carried,
            value: N(site.value, 0),
            hintIdx: -1
          };
          mem.task = null;
          mem.chase = null;
          mem.ignoreUntil = -1;
          return { left: 0, right: 0, drill: true };
        }

        if (sd <= 1.55) {
          return wheelDrive(obs, mem, 0, 0, false);
        }

        if (sd < 2.0 && mem.bodySpeed > 0.25) {
          return wheelDrive(obs, mem, 0, 0, false);
        }

        return approachSite(obs, mem, site);
      }
    } else if (!obs.site) {
      mem.chase = null;
    }

    if (!mem.task) {
      var chosen = null;
      if (carried < mem.cap) {
        chosen = chooseHint(obs, mem, carried, baseD, timeLeft, battery);
      }
      if (!chosen) {
        if (carried > 0) {
          mem.returning = true;
          return goHome(obs, mem);
        }
        if (battery > 0.10 && timeLeft > 40) {
          chosen = chooseExplore(obs, mem, t);
        }
      }
      if (chosen) mem.task = chosen;
    }

    if (mem.task) {
      var ctl = runTask(obs, mem, t, carried, baseD, battery, timeLeft);
      if (ctl) return ctl;
      if (mem.task) return stopCmd(obs, mem);
    }

    if (carried > 0) {
      mem.returning = true;
      return goHome(obs, mem);
    }

    return stopCmd(obs, mem);
  } catch (e) {
    mem.errCount = (mem.errCount || 0) + 1;
    mem.lastError = String(e);
    return { left: 0, right: 0, drill: false };
  }
}

var D2R = Math.PI / 180;
var R2D = 180 / Math.PI;
var RA = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function N(v, d) {
  v = +v;
  return isFinite(v) ? v : d;
}
function clamp(v, a, b) {
  v = +v;
  if (!isFinite(v)) return a;
  return v < a ? a : (v > b ? b : v);
}
function norm(a) {
  a = +a;
  if (!isFinite(a)) return 0;
  return ((a + 180) % 360 + 360) % 360 - 180;
}
function dist(x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
}
function midAng(a, b) {
  return norm(a + norm(b - a) / 2);
}
function frontMin(obs) {
  var rr = obs.rays || [];
  var m = 15;
  for (var i = 0; i < 9 && i < rr.length; i++) {
    if (RA[i] >= -30 && RA[i] <= 30) m = Math.min(m, N(rr[i], 15));
  }
  return m;
}
function leftClear(obs) {
  var rr = obs.rays || [];
  var m = 15;
  for (var i = 0; i < 9 && i < rr.length; i++) {
    if (RA[i] >= 20) m = Math.min(m, N(rr[i], 15));
  }
  return m;
}
function rightClear(obs) {
  var rr = obs.rays || [];
  var m = 15;
  for (var i = 0; i < 9 && i < rr.length; i++) {
    if (RA[i] <= -20) m = Math.min(m, N(rr[i], 15));
  }
  return m;
}

function initMission(obs, mem) {
  mem.init = true;
  var t = N(obs.t, 0);
  mem.t0 = t;
  mem.t = t;
  mem.lastT = t;
  mem.dt = 0.1;

  var m = obs.mission || {};
  mem.seconds = N(m.seconds, 1200);
  mem.cap = Math.round(N(m.capacity, 5));
  if (!(mem.cap > 0)) mem.cap = 5;

  var mb = m.base || {};
  mem.base = {
    x: N(mb.x, N(obs.x, 0)),
    y: N(mb.y, N(obs.y, 0))
  };

  var sx = 400, sy = 400, sz = m.size;
  if (typeof sz === "number") {
    sx = sy = N(sz, 400);
  } else if (Array.isArray(sz)) {
    sx = N(sz[0], 400);
    sy = N(sz[1], sx);
  } else if (sz && typeof sz === "object") {
    sx = N(sz.x, N(sz.width, 400));
    sy = N(sz.y, N(sz.height, sx));
  }
  if (!(sx > 20)) sx = 400;
  if (!(sy > 20)) sy = 400;

  var hs = m.hints || [], i;
  mem.hints = [];
  var minx = mem.base.x, maxx = mem.base.x;
  var miny = mem.base.y, maxy = mem.base.y;

  for (i = 0; i < hs.length; i++) {
    var h = hs[i] || {};
    var hx = N(h.x, mem.base.x);
    var hy = N(h.y, mem.base.y);
    var est = N(h.estimate, 1);
    if (!(est > 0)) est = 1;
    mem.hints.push({ x: hx, y: hy, est: est, status: 0 });
    if (hx < minx) minx = hx;
    if (hx > maxx) maxx = hx;
    if (hy < miny) miny = hy;
    if (hy > maxy) maxy = hy;
  }

  var centered = minx < -5 || miny < -5 || maxx > sx + 5 || maxy > sy + 5;
  if (centered) {
    mem.wMinX = -sx / 2;
    mem.wMaxX = sx / 2;
    mem.wMinY = -sy / 2;
    mem.wMaxY = sy / 2;
  } else {
    mem.wMinX = 0;
    mem.wMaxX = sx;
    mem.wMinY = 0;
    mem.wMaxY = sy;
  }

  var vals = [];
  for (i = 0; i < mem.hints.length; i++) vals.push(mem.hints[i].est);
  vals.sort(function (a, b) { return a - b; });
  mem.medEst = vals.length ? vals[Math.floor(vals.length / 2)] : 1;

  mem.px = N(obs.x, mem.base.x);
  mem.py = N(obs.y, mem.base.y);
  mem.px = clamp(mem.px, mem.wMinX + 0.2, mem.wMaxX - 0.2);
  mem.py = clamp(mem.py, mem.wMinY + 0.2, mem.wMaxY - 0.2);
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastGx = mem.px;
  mem.lastGy = mem.py;
  mem.gpsStill = 0;

  mem.raw = norm(N(obs.heading, 0));
  mem.lastRaw = mem.raw;
  mem.jump = 0;
  mem.bias = 0;
  mem.biasN = 0;
  mem.hdg = mem.raw;

  mem.calX = mem.px;
  mem.calY = mem.py;
  mem.calRaw = norm(mem.raw + mem.jump);
  mem.calPhase = true;
  mem.calStartT = t;
  mem.calStartX = mem.px;
  mem.calStartY = mem.py;
  mem.calStartRaw = mem.raw;

  mem.lastWl = N(obs.wheelLeft, 0);
  mem.lastWr = N(obs.wheelRight, 0);
  mem.mL = { i: 0 };
  mem.mR = { i: 0 };
  mem.holdInit = false;
  mem.hIL = 0;
  mem.hIR = 0;

  mem.lastCarried = Math.round(N(obs.carried, 0));
  mem.samples = 0;
  mem.deliveredCount = 0;
  mem.returning = false;
  mem.task = null;
  mem.drill = null;
  mem.siteTrack = null;
  mem.ignoreSiteUntil = -1;
  mem.badSites = [];

  mem.lastBumpT = -99;
  mem.bumpCount = 0;
  mem.cautiousUntil = 0;
  mem.recoverUntil = -1;
  mem.recoverDir = 1;

  mem.chargeStart = null;
  mem.expPts = null;
  mem.sciCooldown = 0;

  mem.lastBattery = N(obs.battery, 1);
  mem.ePerM = 0.002;
  mem.eN = 0;
  mem.errCount = 0;
}

function updateState(obs, mem) {
  var t = N(obs.t, N(mem.lastT, 0) + 0.1);
  var dt = t - N(mem.lastT, t - 0.1);
  if (!(dt > 0) || dt > 0.5) dt = 0.1;
  mem.dt = dt;
  mem.t = t;

  var wl = N(obs.wheelLeft, 0);
  var wr = N(obs.wheelRight, 0);
  var avg = (wl + wr) / 2;
  var raw = norm(N(obs.heading, mem.lastRaw));

  var yaw = ((wr - wl) / 0.6) * R2D * dt;
  var draw = norm(raw - mem.lastRaw);
  if (Math.abs(draw) > 55 && Math.abs(yaw) < 18) {
    mem.jump = norm(mem.jump - draw);
  }
  var eff = norm(raw + mem.jump);

  var pred = norm(mem.hdg + yaw);
  var comp = norm(eff + mem.bias);
  var dh = norm(comp - pred);

  if (Math.abs(dh) < 60) {
    mem.hdg = norm(pred + dh * 0.48);
  } else if (Math.abs(avg) < 0.08 && Math.abs(dh) < 120) {
    mem.hdg = norm(mem.hdg + dh * 0.18);
  } else {
    mem.hdg = pred;
  }

  var gx = N(obs.x, mem.px);
  var gy = N(obs.y, mem.py);
  var gmove = dist(gx, gy, mem.lastGx, mem.lastGy);

  if (gmove < 0.004 && Math.abs(avg) > 0.08) mem.gpsStill += dt;
  else if (gmove > 0.02) mem.gpsStill = 0;
  else mem.gpsStill = Math.max(0, mem.gpsStill - dt * 1.2);

  var frozen = mem.gpsStill > 1.0;
  var oldpx = mem.px, oldpy = mem.py;

  if (frozen) {
    mem.px += avg * Math.cos(mem.hdg * D2R) * dt;
    mem.py += avg * Math.sin(mem.hdg * D2R) * dt;
  } else {
    mem.px = gx;
    mem.py = gy;
  }
  mem.px = clamp(mem.px, mem.wMinX + 0.2, mem.wMaxX - 0.2);
  mem.py = clamp(mem.py, mem.wMinY + 0.2, mem.wMaxY - 0.2);

  if (!frozen && gmove > 0.006) {
    var cd = dist(gx, gy, mem.calX, mem.calY);
    if (cd > 0.8 && Math.abs(wr - wl) < 0.75 && Math.abs(avg) > 0.15) {
      var ma = Math.atan2(gy - mem.calY, gx - mem.calX) * R2D;
      var ra = midAng(mem.calRaw, eff);
      var targetBias = norm(ma - ra);
      var bd = norm(targetBias - mem.bias);
      if (Math.abs(bd) < 85) {
        var alpha = mem.biasN < 6 ? 0.25 : 0.015;
        mem.bias = norm(mem.bias + bd * alpha);
        mem.biasN++;
        mem.hdg = norm(eff + mem.bias);
      }
      mem.calX = gx;
      mem.calY = gy;
      mem.calRaw = eff;
    } else if (cd > 2.5) {
      mem.calX = gx;
      mem.calY = gy;
      mem.calRaw = eff;
    }
  }

  var bat = N(obs.battery, mem.lastBattery);
  var moved = dist(mem.px, mem.py, oldpx, oldpy);
  if (moved > 0.08 && !mem.drill && mem.lastBattery != null) {
    var drop = mem.lastBattery - bat;
    if (drop > 0 && drop < 0.25) {
      var e = drop / moved;
      if (e > 0.00001 && e < 0.2) {
        if (mem.eN < 3) mem.ePerM = e;
        else mem.ePerM = mem.ePerM * 0.97 + e * 0.03;
        mem.eN++;
      }
    }
  }

  mem.lastRaw = raw;
  mem.lastWl = wl;
  mem.lastWr = wr;
  mem.lastGx = gx;
  mem.lastGy = gy;
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastBattery = bat;
  mem.lastT = t;
}

function wheelDrive(obs, mem, tl, tr, drillFlag) {
  var dt = mem.dt || 0.1;
  var wl = N(obs.wheelLeft, 0);
  var wr = N(obs.wheelRight, 0);

  function one(st, target, actual) {
    target = clamp(target, -2.8, 2.8);
    var err = target - actual;
    st.i = clamp(st.i + err * dt * 0.65, -1.6, 1.6);

    var ff = 0;
    if (target > 0.05) ff = 0.10 + 0.30 * target;
    else if (target < -0.05) ff = -0.10 + 0.30 * target;

    var u = ff + 0.50 * err + 0.18 * st.i;

    if (Math.abs(target) < 0.03 && Math.abs(actual) < 0.05) {
      st.i *= 0.85;
    }

    if (u > 1) {
      u = 1;
      if (err > 0) st.i = Math.min(st.i, 0.8);
    }
    if (u < -1) {
      u = -1;
      if (err < 0) st.i = Math.max(st.i, -0.8);
    }
    return clamp(u, -1, 1);
  }

  return {
    left: one(mem.mL, tl, wl),
    right: one(mem.mR, tr, wr),
    drill: !!drillFlag
  };
}

function holdControl(obs, mem, drillFlag) {
  var dt = mem.dt || 0.1;
  var wl = N(obs.wheelLeft, 0);
  var wr = N(obs.wheelRight, 0);

  if (!mem.holdInit) {
    mem.holdInit = true;
    mem.hIL = 0;
    mem.hIR = 0;
  }

  mem.hIL = clamp(mem.hIL - wl * dt * 0.50, -0.65, 0.65);
  mem.hIR = clamp(mem.hIR - wr * dt * 0.50, -0.65, 0.65);

  var p = clamp(N(obs.pitch, 0) * 0.006, -0.06, 0.06);
  var uL = p + mem.hIL - wl * 0.90;
  var uR = p + mem.hIR - wr * 0.90;

  return {
    left: clamp(uL, -1, 1),
    right: clamp(uR, -1, 1),
    drill: !!drillFlag
  };
}

function driveRel(obs, mem, err, v, avoid) {
  mem.holdInit = false;

  var rr = obs.rays || [];
  var front = 15, lc = 15, rc = 15;
  var steer = 0;
  var i, r, a, w;

  for (i = 0; i < 9 && i < rr.length; i++) {
    r = N(rr[i], 15);
    if (r < 0) r = 0;
    if (r > 15) r = 15;
    a = RA[i];

    if (a >= -30 && a <= 30) front = Math.min(front, r);
    if (a >= 20) lc = Math.min(lc, r);
    if (a <= -20) rc = Math.min(rc, r);

    if (avoid && r < 4.5) {
      w = (4.5 - r) / 4.5;
      w *= w;
      if (a > 10) steer -= w * 26;
      else if (a < -10) steer += w * 26;
    }
  }

  if (avoid) {
    var safe = (front - 0.85) * 0.80;
    if (!(safe > 0)) safe = 0;
    v = Math.min(v, safe);

    if (front < 0.8) v = 0;

    if (front < 2.2) {
      var side = lc >= rc ? 1 : -1;
      steer += side * (2.2 - front) * 10;
    }

    if (lc < 0.35 && rc < 0.35) v = 0;
  }

  var e = norm(err + clamp(steer, -75, 75));
  var ae = Math.abs(e);

  if (ae > 150) v = 0;
  else if (ae > 110) v = Math.min(v, 0.10);
  else if (ae > 70) v = Math.min(v, 0.40);
  else if (ae > 35) v *= 0.82;

  var omega = clamp(e * D2R * 1.8, -2.6, 2.6);
  if (ae < 2) omega = 0;

  var tl = v - omega * 0.3;
  var tr = v + omega * 0.3;

  if (v < 0.08 && ae > 18) {
    tl = -omega * 0.3;
    tr = omega * 0.3;
  }

  return wheelDrive(obs, mem, tl, tr, false);
}

function driveToPoint(obs, mem, x, y, speed, avoid) {
  var d = dist(mem.px, mem.py, x, y);
  if (d < 0.85) return holdControl(obs, mem, false);

  var ang = Math.atan2(y - mem.py, x - mem.px) * R2D;
  var err = norm(ang - mem.hdg);
  var sp = speed;

  if (d < 2.8) sp = Math.min(sp, 0.55);
  else if (d < 6.0) sp = Math.min(sp, 1.25);

  return driveRel(obs, mem, err, sp, avoid !== false);
}

function goHome(obs, mem) {
  var bd = dist(mem.px, mem.py, mem.base.x, mem.base.y);
  var battery = N(obs.battery, 1);

  if (obs.beacon) {
    var be = N(obs.beacon.distance, 99);
    if (be < 20) {
      if (be < 2.55 || obs.docked) return holdControl(obs, mem, false);
      var v = be > 8 ? 2.0 : (be > 4 ? 1.0 : 0.50);
      if (battery < 0.18) v = Math.min(v, 0.80);
      return driveRel(obs, mem, N(obs.beacon.bearing, 0), v, true);
    }
  }

  if (bd < 2.30 || obs.docked) return holdControl(obs, mem, false);

  var sp = 2.0;
  if (battery < 0.20) sp = 1.15;
  if (mem.cautiousUntil > mem.t) sp = Math.min(sp, 1.0);

  return driveToPoint(obs, mem, mem.base.x, mem.base.y, sp, true);
}

function addBad(mem, x, y, t) {
  if (!mem.badSites) mem.badSites = [];
  mem.badSites.push({ x: x, y: y, until: t + 90 });
  if (mem.badSites.length > 24) mem.badSites.shift();
}
function isBad(mem, x, y, t) {
  if (!mem.badSites) return false;
  for (var i = 0; i < mem.badSites.length; i++) {
    var b = mem.badSites[i];
    if (t < b.until && dist(x, y, b.x, b.y) < 4.0) return true;
  }
  return false;
}

function markSampleHints(mem, x, y) {
  var best = -1, bd = 1e9, i;
  for (i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.status === 0) {
      var d = dist(h.x, h.y, x, y);
      if (d < bd) {
        bd = d;
        best = i;
      }
    }
  }
  if (best >= 0 && bd < 34) mem.hints[best].status = 2;
  for (i = 0; i < mem.hints.length; i++) {
    if (mem.hints[i].status === 0 && dist(mem.hints[i].x, mem.hints[i].y, x, y) < 13) {
      mem.hints[i].status = 2;
    }
  }
}

function makeSpiral(mem, cx, cy, R, pitch) {
  var pts = [];
  pitch = Math.max(6, pitch || 12);
  var a = pitch / (2 * Math.PI);
  var thmax = R / Math.max(0.5, a);
  var lx = null, ly = null;

  for (var th = 0; th <= thmax + 0.2; th += 0.18) {
    var r = a * th;
    var x = cx + r * Math.cos(th);
    var y = cy + r * Math.sin(th);
    x = clamp(x, mem.wMinX + 1.6, mem.wMaxX - 1.6);
    y = clamp(y, mem.wMinY + 1.6, mem.wMaxY - 1.6);

    if (lx === null || dist(x, y, lx, ly) > 1.2) {
      pts.push({ x: x, y: y });
      lx = x;
      ly = y;
    }
  }
  if (!pts.length) {
    pts.push({
      x: clamp(cx, mem.wMinX + 1.6, mem.wMaxX - 1.6),
      y: clamp(cy, mem.wMinY + 1.6, mem.wMaxY - 1.6)
    });
  }
  return pts;
}

function chooseHint(obs, mem, carried, baseD, timeLeft, battery) {
  if (carried > 0) return null;

  var best = null;
  var bestScore = -1e18;
  var med = mem.medEst || 1;
  var t = mem.t || 0;

  for (var i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.status !== 0) continue;

    var d = dist(mem.px, mem.py, h.x, h.y);
    var db = dist(h.x, h.y, mem.base.x, mem.base.y);
    var val = Math.max(0.05, h.est);
    var high = val > med * 1.35;

    var R = high ? 26 : 21;
    var maxSearch = high ? 58 : 42;
    var searchT = maxSearch * 0.72;

    var need = d / 1.0 + searchT + db / 1.0 + 25;
    if (timeLeft < need) continue;
    if (battery < 0.07 && d > 15) continue;
    if (battery < 0.14 && d + db > 210) continue;

    var cost = d + db * 0.85 + 18 + searchT * 0.35;
    var score = val / Math.pow(Math.max(18, cost), 0.82);

    if (mem.deliveredCount === 0) score *= 1 / (1 + d / 140);
    if (d < 25) score *= 1.15;
    if (high) score *= 1.10;

    if (score > bestScore) {
      bestScore = score;
      best = {
        type: "hint",
        idx: i,
        phase: "travel",
        start: t,
        bestD: d,
        lastProg: t,
        searchPts: null,
        si: 0,
        searchStart: 0,
        ptStart: 0,
        R: R,
        maxSearch: maxSearch,
        high: high
      };
    }
  }
  return best;
}

function initExplore(mem) {
  var pts = [];
  var step = 55;
  var margin = 22;
  for (var y = mem.wMinY + margin; y <= mem.wMaxY - margin + 0.1; y += step) {
    for (var x = mem.wMinX + margin; x <= mem.wMaxX - margin + 0.1; x += step) {
      pts.push({ x: x, y: y, done: false });
    }
  }
  if (!pts.length) pts.push({ x: mem.base.x, y: mem.base.y, done: false });
  mem.expPts = pts;
}

function chooseExplore(obs, mem) {
  var t = mem.t || 0;
  var timeLeft = N(obs.timeLeft, 0);
  var battery = N(obs.battery, 1);
  if (timeLeft < 25 || battery < 0.06) return null;

  if (!mem.expPts) initExplore(mem);

  var bi = -1, bd = 1e9;
  for (var i = 0; i < mem.expPts.length; i++) {
    var p = mem.expPts[i];
    if (p.done) continue;
    var d = dist(mem.px, mem.py, p.x, p.y);
    if (d < 6.5) {
      p.done = true;
      continue;
    }
    if (d < bd) {
      bd = d;
      bi = i;
    }
  }

  if (bi >= 0) {
    var q = mem.expPts[bi];
    return {
      type: "explore",
      idx: bi,
      x: q.x,
      y: q.y,
      start: t,
      bestD: bd,
      lastProg: t
    };
  }

  return {
    type: "spiral",
    cx: mem.px,
    cy: mem.py,
    R: 21,
    maxSearch: 30,
    searchPts: null,
    si: 0,
    searchStart: t,
    ptStart: t,
    start: t
  };
}

function runTask(obs, mem, t, carried, baseD, battery, timeLeft) {
  var task = mem.task;
  if (!task) return null;

  if (task.type === "hint") {
    var h = mem.hints[task.idx];
    if (!h || h.status !== 0) {
      mem.task = null;
      return null;
    }

    if (task.phase === "travel") {
      var d = dist(mem.px, mem.py, h.x, h.y);
      if (d < task.bestD - 0.3) {
        task.bestD = d;
        task.lastProg = t;
      }

      if ((t - task.lastProg > 18 && d > 4.5) || t - task.start > 115) {
        h.status = 1;
        mem.task = null;
        return null;
      }

      if (timeLeft < 25) {
        h.status = 1;
        mem.task = null;
        return null;
      }

      if (d < 4.2) {
        task.phase = "search";
        task.searchPts = null;
        task.si = 0;
        task.searchStart = t;
        task.ptStart = t;
      } else {
        var sp = 2.0;
        if (battery < 0.25) sp = 1.20;
        if (mem.cautiousUntil > t) sp = Math.min(sp, 1.0);
        return driveToPoint(obs, mem, h.x, h.y, sp, true);
      }
    }

    if (task.phase === "search") {
      if (!task.searchPts) {
        task.searchPts = makeSpiral(mem, h.x, h.y, task.R || 22, 12);
        task.si = 0;
        task.searchStart = t;
        task.ptStart = t;
      }

      if (t - task.searchStart > task.maxSearch) {
        h.status = 1;
        mem.task = null;
        return null;
      }

      if (t - task.searchStart > 8 && N(obs.science, 0) < 0.12) {
        h.status = 1;
        mem.task = null;
        return null;
      }

      if (task.si >= task.searchPts.length) {
        h.status = 1;
        mem.task = null;
        return null;
      }

      var p = task.searchPts[task.si];
      var dp = dist(mem.px, mem.py, p.x, p.y);

      if (dp < 1.7 || t - task.ptStart > 7.0) {
        task.si++;
        task.ptStart = t;
        if (task.si >= task.searchPts.length) {
          h.status = 1;
          mem.task = null;
          return null;
        }
        p = task.searchPts[task.si];
      }

      if (timeLeft < 18) {
        h.status = 1;
        mem.task = null;
        return null;
      }

      var sp2 = 1.75;
      if (battery < 0.25) sp2 = 1.0;
      if (mem.cautiousUntil > t) sp2 = Math.min(sp2, 1.0);
      return driveToPoint(obs, mem, p.x, p.y, sp2, true);
    }
  }

  if (task.type === "explore") {
    var de = dist(mem.px, mem.py, task.x, task.y);

    if (de < task.bestD - 0.4) {
      task.bestD = de;
      task.lastProg = t;
    }

    if (de < 4.0 || t - task.start > 50 || (t - task.lastProg > 20 && de > 5)) {
      if (mem.expPts && mem.expPts[task.idx]) mem.expPts[task.idx].done = true;
      mem.task = null;
      return null;
    }

    var spe = 1.85;
    if (battery < 0.25) spe = 1.0;
    if (mem.cautiousUntil > t) spe = Math.min(spe, 1.0);
    return driveToPoint(obs, mem, task.x, task.y, spe, true);
  }

  if (task.type === "spiral") {
    if (!task.searchPts) {
      task.searchPts = makeSpiral(mem, task.cx, task.cy, task.R || 20, 13);
      task.si = 0;
      task.searchStart = t;
      task.ptStart = t;
    }

    if (t - task.searchStart > (task.maxSearch || 30) || task.si >= task.searchPts.length) {
      mem.task = null;
      return null;
    }

    var ps = task.searchPts[task.si];
    var ds = dist(mem.px, mem.py, ps.x, ps.y);

    if (ds < 1.7 || t - task.ptStart > 7.0) {
      task.si++;
      task.ptStart = t;
      if (task.si >= task.searchPts.length) {
        mem.task = null;
        return null;
      }
      ps = task.searchPts[task.si];
    }

    var sps = 1.70;
    if (battery < 0.25) sps = 1.0;
    return driveToPoint(obs, mem, ps.x, ps.y, sps, true);
  }

  mem.task = null;
  return null;
}

function act(obs, mem) {
  try {
    if (!mem.init) initMission(obs, mem);

    updateState(obs, mem);

    var t = mem.t;
    var dt = mem.dt || 0.1;
    var timeLeft = N(obs.timeLeft, mem.seconds - (t - mem.t0));
    if (!isFinite(timeLeft) || timeLeft < 0) timeLeft = 0;

    var battery = N(obs.battery, mem.lastBattery);
    var carried = Math.round(N(obs.carried, mem.lastCarried));
    var prevCarried = mem.lastCarried;

    var baseD = dist(mem.px, mem.py, mem.base.x, mem.base.y);
    var beaconD = obs.beacon ? N(obs.beacon.distance, 99) : 99;
    var atBase = !!obs.docked || (obs.beacon && beaconD < 2.9) || baseD < 2.6;

    if (carried > prevCarried) {
      mem.samples += carried - prevCarried;
      var sx = mem.px, sy = mem.py;
      if (mem.drill && mem.drill.x != null) {
        sx = mem.drill.x;
        sy = mem.drill.y;
      }
      markSampleHints(mem, sx, sy);
      mem.drill = null;
      mem.holdInit = false;
      mem.returning = true;
      mem.task = null;
      mem.siteTrack = null;
      mem.ignoreSiteUntil = -1;
    }

    if (carried < prevCarried) {
      mem.deliveredCount += prevCarried - carried;
      mem.returning = false;
      mem.task = null;
      mem.drill = null;
      mem.holdInit = false;
      mem.chargeStart = t;
    }

    mem.lastCarried = carried;

    if (carried > 0 && atBase) {
      mem.returning = true;
      mem.drill = null;
      return holdControl(obs, mem, false);
    }

    if (obs.bumped) {
      if (t - mem.lastBumpT > 0.45) {
        if (t - mem.lastBumpT < 4.0) mem.bumpCount++;
        else mem.bumpCount = 1;
        mem.lastBumpT = t;
        mem.recoverUntil = t + 1.0;
        mem.recoverDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
        mem.task = null;
        mem.drill = null;
        mem.holdInit = false;
        mem.siteTrack = null;
        if (mem.bumpCount >= 3) mem.cautiousUntil = t + 20;
      }
    }

    if (t < mem.recoverUntil) {
      var ph = t - (mem.recoverUntil - 1.0);
      mem.holdInit = false;
      if (ph < 0.42) return wheelDrive(obs, mem, -0.62, -0.62, false);
      var rd = mem.recoverDir || 1;
      return wheelDrive(obs, mem, -0.34 * rd, 0.34 * rd, false);
    }

    if (mem.calPhase) {
      var ff = frontMin(obs);

      if (!obs.site && ff > 1.2 && t - mem.calStartT < 0.9) {
        mem.holdInit = false;
        return wheelDrive(obs, mem, 0.90, 0.90, false);
      }

      var movedCal = dist(mem.px, mem.py, mem.calStartX, mem.calStartY);
      if (movedCal > 0.25 && !mem.gpsStill) {
        var ma = Math.atan2(mem.py - mem.calStartY, mem.px - mem.calStartX) * R2D;
        var effNow = norm(N(obs.heading, mem.raw) + mem.jump);
        var ra0 = midAng(mem.calStartRaw, effNow);
        var tb = norm(ma - ra0);
        mem.bias = norm(mem.bias + norm(tb - mem.bias) * 0.80);
        mem.hdg = norm(effNow + mem.bias);
        mem.biasN++;
      }

      mem.calPhase = false;
      mem.calX = mem.px;
      mem.calY = mem.py;
      mem.calRaw = norm(N(obs.heading, mem.raw) + mem.jump);
    }

    if (carried > 0) {
      mem.returning = true;
      mem.drill = null;
      mem.holdInit = false;
      return goHome(obs, mem);
    }

    if (mem.drill) {
      var sdD = obs.site ? N(obs.site.distance, 99) : 99;
      if (obs.site) {
        mem.drill.lastD = sdD;
        mem.drill.lost = 0;
      } else {
        mem.drill.lost = N(mem.drill.lost, 0) + dt;
      }

      if (t - mem.drill.start > 22 ||
          N(mem.drill.lost, 0) > 1.5 ||
          (obs.site && sdD > 1.75) ||
          timeLeft < 5 ||
          battery < 0.02) {
        var bx = mem.drill.x != null ? mem.drill.x : mem.px;
        var by = mem.drill.y != null ? mem.drill.y : mem.py;
        addBad(mem, bx, by, t);
        mem.drill = null;
        mem.holdInit = false;
        mem.ignoreSiteUntil = t + 5;
        mem.task = null;
        mem.siteTrack = null;
        mem.recoverUntil = t + 0.8;
        mem.recoverDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
        return wheelDrive(obs, mem, -0.45, -0.45, false);
      }

      return holdControl(obs, mem, true);
    }

    if (atBase && carried === 0) {
      mem.returning = false;
      mem.drill = null;
      mem.holdInit = false;

      if (mem.chargeStart == null) mem.chargeStart = t;

      var maxWait = 0;
      if (battery < 0.22) maxWait = 55;
      else if (battery < 0.50) maxWait = 20;
      else if (battery < 0.75) maxWait = 5;

      if (maxWait > 0 && timeLeft > maxWait + 30 &&
          t - mem.chargeStart < maxWait && battery < 0.95) {
        return holdControl(obs, mem, false);
      }

      mem.chargeStart = null;
    }

    if (!atBase && carried === 0) {
      if (!mem.returning) {
        if ((battery < 0.09 && baseD > 8) ||
            (timeLeft < baseD / 0.75 + 10)) {
          mem.returning = true;
        }
      }
      if (mem.returning) return goHome(obs, mem);
    }

    if (!mem.returning && carried === 0 && timeLeft > 8 && battery > 0.03) {
      var site = obs.site;
      if (site && t >= mem.ignoreSiteUntil) {
        var sd = N(site.distance, 99);
        var sb = N(site.bearing, 0);
        var ga = (mem.hdg + sb) * D2R;
        var estX = mem.px + sd * Math.cos(ga);
        var estY = mem.py + sd * Math.sin(ga);

        if (isBad(mem, estX, estY, t)) {
          site = null;
        } else {
          if (!mem.siteTrack ||
              dist(estX, estY, mem.siteTrack.x, mem.siteTrack.y) > 5 ||
              t - mem.siteTrack.lastSeen > 2) {
            mem.siteTrack = {
              x: estX,
              y: estY,
              start: t,
              best: sd,
              lastProg: t,
              lastSeen: t
            };
          } else {
            var st = mem.siteTrack;
            st.x = estX;
            st.y = estY;
            st.lastSeen = t;
            if (sd < st.best - 0.2) {
              st.best = sd;
              st.lastProg = t;
            }
          }

          var st2 = mem.siteTrack;

          if (sd > 1.55 && t - st2.start > 10 && t - st2.lastProg > 7) {
            addBad(mem, estX, estY, t);
            mem.ignoreSiteUntil = t + 7;
            mem.siteTrack = null;
            mem.task = null;
            mem.recoverUntil = t + 0.8;
            mem.recoverDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
            return wheelDrive(obs, mem, -0.50, -0.50, false);
          }

          if (sd <= 1.45) {
            mem.drill = {
              start: t,
              x: estX,
              y: estY,
              lastD: sd,
              lost: 0
            };
            mem.holdInit = false;
            mem.task = null;
            mem.siteTrack = null;
            return holdControl(obs, mem, true);
          }

          mem.task = null;

          var vv;
          if (sd > 5.5) vv = 1.70;
          else if (sd > 3.0) vv = 1.10;
          else if (sd > 2.1) vv = 0.60;
          else vv = 0.25;

          if (mem.cautiousUntil > t) vv = Math.min(vv, 1.0);
          return driveRel(obs, mem, sb, vv, true);
        }
      }
    }

    var ctl = null;

    for (var iter = 0; iter < 4; iter++) {
      if (!mem.task) {
        var chosen = chooseHint(obs, mem, carried, baseD, timeLeft, battery);

        if (!chosen && carried < mem.cap &&
            timeLeft > 45 && battery > 0.10 &&
            t > mem.sciCooldown && N(obs.science, 0) > 0.90) {
          chosen = {
            type: "spiral",
            cx: mem.px,
            cy: mem.py,
            R: 20,
            maxSearch: 30,
            searchPts: null,
            si: 0,
            searchStart: t,
            ptStart: t,
            start: t
          };
          mem.sciCooldown = t + 80;
        }

        if (!chosen && carried === 0) {
          chosen = chooseExplore(obs, mem);
        }

        if (!chosen) break;
        mem.task = chosen;
      }

      ctl = runTask(obs, mem, t, carried, baseD, battery, timeLeft);
      if (ctl) return ctl;

      if (mem.task) return holdControl(obs, mem, false);
    }

    if (!atBase && (mem.returning || timeLeft < baseD / 0.70 + 8)) {
      return goHome(obs, mem);
    }

    return holdControl(obs, mem, false);
  } catch (e) {
    mem.errCount = (mem.errCount || 0) + 1;
    mem.lastError = String(e);
    return { left: 0, right: 0, drill: false };
  }
}

var D2R = Math.PI / 180;
var R2D = 180 / Math.PI;
var RA = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
var GS = 2.0;
var DX = [1, 1, 0, -1, -1, -1, 0, 1];
var DY = [0, 1, 1, 1, 0, -1, -1, -1];

function N(v, d) {
  v = +v;
  return isFinite(v) ? v : d;
}
function clamp(v, a, b) {
  v = +v;
  if (!isFinite(v)) return a;
  return v < a ? a : (v > b ? b : v);
}
function norm(a) {
  a = +a;
  if (!isFinite(a)) return 0;
  return ((a + 180) % 360 + 360) % 360 - 180;
}
function dist(x1, y1, x2, y2) {
  var dx = x2 - x1, dy = y2 - y1;
  return Math.sqrt(dx * dx + dy * dy);
}
function midAng(a, b) {
  return norm(a + norm(b - a) / 2);
}
function rayAt(obs, i) {
  var rr = obs.rays || [];
  var r = N(rr[i], 15);
  if (r < 0) r = 0;
  if (r > 15) r = 15;
  return r;
}
function frontMin(obs) {
  var m = 15;
  for (var i = 0; i < 9; i++) {
    if (RA[i] >= -60 && RA[i] <= 60) {
      var r = rayAt(obs, i);
      if (r < m) m = r;
    }
  }
  return m;
}
function leftClear(obs) {
  var m = 15;
  for (var i = 0; i < 9; i++) {
    if (RA[i] >= 20) {
      var r = rayAt(obs, i);
      if (r < m) m = r;
    }
  }
  return m;
}
function rightClear(obs) {
  var m = 15;
  for (var i = 0; i < 9; i++) {
    if (RA[i] <= -20) {
      var r = rayAt(obs, i);
      if (r < m) m = r;
    }
  }
  return m;
}

function cellIndex(mem, x, y) {
  if (!mem.occ) return -1;
  var ix = Math.floor((x - mem.wMinX) / GS);
  var iy = Math.floor((y - mem.wMinY) / GS);
  if (ix < 0 || ix >= mem.gw || iy < 0 || iy >= mem.gh) return -1;
  return iy * mem.gw + ix;
}
function markFreePoint(mem, x, y) {
  var idx = cellIndex(mem, x, y);
  if (idx < 0) return;
  var o = mem.occ[idx];
  if (o > 0) mem.occ[idx] = Math.max(0, o - 2);
  else mem.occ[idx] = Math.max(-8, o - 1);
}
function markFreeCurrent(mem, x, y) {
  var idx = cellIndex(mem, x, y);
  if (idx < 0) return;
  if (mem.occ[idx] > 0) mem.occ[idx] = 0;
  else mem.occ[idx] = Math.max(-8, mem.occ[idx] - 1);
}
function markHitPoint(mem, x, y, amt) {
  if (!mem.occ) return;
  var ix = Math.floor((x - mem.wMinX) / GS);
  var iy = Math.floor((y - mem.wMinY) / GS);
  if (ix < 0 || ix >= mem.gw || iy < 0 || iy >= mem.gh) return;
  var idx = iy * mem.gw + ix;
  mem.occ[idx] = Math.min(60, mem.occ[idx] + (amt || 4));
  if (ix > 0) mem.occ[idx - 1] = Math.min(60, mem.occ[idx - 1] + 1);
  if (ix + 1 < mem.gw) mem.occ[idx + 1] = Math.min(60, mem.occ[idx + 1] + 1);
  if (iy > 0) mem.occ[idx - mem.gw] = Math.min(60, mem.occ[idx - mem.gw] + 1);
  if (iy + 1 < mem.gh) mem.occ[idx + mem.gw] = Math.min(60, mem.occ[idx + mem.gw] + 1);
}
function updateGrid(obs, mem) {
  if (!mem.occ) return;
  var t = mem.t;
  if (t - mem.lastGridT < 0.15) return;
  mem.lastGridT = t;

  markFreeCurrent(mem, mem.px, mem.py);

  for (var i = 0; i < 9; i++) {
    var r = rayAt(obs, i);
    var a = (mem.hdg + RA[i]) * D2R;
    var ca = Math.cos(a), sa = Math.sin(a);
    var lim = Math.min(r - 0.55, 14.5);
    if (lim > 0.5) {
      for (var d = 0.6; d <= lim; d += 0.8) {
        markFreePoint(mem, mem.px + ca * d, mem.py + sa * d);
      }
    }
    if (r > 0.10 && r < 14.6) {
      var rr = Math.min(r, 14.5);
      markHitPoint(mem, mem.px + ca * rr, mem.py + sa * rr, 4);
    }
  }
}

function cellHeur(idx, gw, gx, gy) {
  var cx = idx % gw;
  var cy = (idx / gw) | 0;
  var dx = Math.abs(cx - gx);
  var dy = Math.abs(cy - gy);
  return (dx + dy) + (1.41421356237 - 2) * Math.min(dx, dy);
}

function planPath(mem, tx, ty, t) {
  if (!mem.occ) return null;
  var gw = mem.gw, gh = mem.gh, Ncells = mem.gN, gs = GS;
  var sx = Math.floor((mem.px - mem.wMinX) / gs);
  var sy = Math.floor((mem.py - mem.wMinY) / gs);
  var gx = Math.floor((tx - mem.wMinX) / gs);
  var gy = Math.floor((ty - mem.wMinY) / gs);

  sx = clamp(sx, 0, gw - 1);
  sy = clamp(sy, 0, gh - 1);
  gx = clamp(gx, 0, gw - 1);
  gy = clamp(gy, 0, gh - 1);

  var start = sy * gw + sx;
  var goal = gy * gw + gx;
  if (start === goal) return [{ x: tx, y: ty, idx: goal }];

  var gScore = mem.planG;
  var fScore = mem.planF;
  var parent = mem.planP;
  var closed = mem.planC;

  for (var q = 0; q < Ncells; q++) {
    gScore[q] = 1e9;
    closed[q] = 0;
    parent[q] = -1;
  }

  var open = mem.heap;
  open.length = 0;
  var oh = 0;

  gScore[start] = 0;
  fScore[start] = cellHeur(start, gw, gx, gy);
  open[oh++] = start;

  var best = start;
  var bestH = fScore[start];
  var expansions = 0;

  while (oh > 0 && expansions < 7000) {
    var cur = open[0];
    oh--;
    if (oh > 0) {
      open[0] = open[oh];
      var hi = 0;
      while (true) {
        var l = hi * 2 + 1;
        var r = l + 1;
        var sm = hi;
        if (l < oh && fScore[open[l]] < fScore[open[sm]]) sm = l;
        if (r < oh && fScore[open[r]] < fScore[open[sm]]) sm = r;
        if (sm === hi) break;
        var tmp = open[hi];
        open[hi] = open[sm];
        open[sm] = tmp;
        hi = sm;
      }
    }

    if (closed[cur]) continue;
    closed[cur] = 1;
    expansions++;

    if (cur === goal) {
      best = cur;
      break;
    }

    var hh = cellHeur(cur, gw, gx, gy);
    if (hh < bestH) {
      bestH = hh;
      best = cur;
    }

    var cx = cur % gw;
    var cy = (cur / gw) | 0;

    for (var dir = 0; dir < 8; dir++) {
      var nx = cx + DX[dir];
      var ny = cy + DY[dir];
      if (nx < 0 || nx >= gw || ny < 0 || ny >= gh) continue;
      var nb = ny * gw + nx;
      if (closed[nb]) continue;

      var o = mem.occ[nb];
      var cost = 1;
      if (o >= 8) cost = 60;
      else if (o >= 4) cost = 8;
      else if (o >= 1) cost = 2.5;
      else if (o <= -1) cost = 1;
      else cost = 1.35;

      if (nx < 1 || nx >= gw - 1 || ny < 1 || ny >= gh - 1) cost += 30;

      var diag = DX[dir] !== 0 && DY[dir] !== 0;
      if (diag) {
        if (mem.occ[cy * gw + nx] >= 8 || mem.occ[ny * gw + cx] >= 8) continue;
      }

      var stepCost = (diag ? 1.41421356237 : 1) * cost;
      var ng = gScore[cur] + stepCost;
      if (ng < gScore[nb] - 1e-6) {
        gScore[nb] = ng;
        parent[nb] = cur;
        fScore[nb] = ng + cellHeur(nb, gw, gx, gy);

        var pos = oh++;
        open[pos] = nb;
        while (pos > 0) {
          var p = (pos - 1) >> 1;
          if (fScore[open[p]] <= fScore[open[pos]]) break;
          var tmp2 = open[p];
          open[p] = open[pos];
          open[pos] = tmp2;
          pos = p;
        }
      }
    }
  }

  if (best === start) return null;

  var arr = [];
  var c = best;
  var guard = 0;
  while (c !== -1 && c !== start && guard++ < 3000) {
    arr.push({
      x: mem.wMinX + ((c % gw) + 0.5) * gs,
      y: mem.wMinY + (((c / gw) | 0) + 0.5) * gs,
      idx: c
    });
    c = parent[c];
  }
  if (c === start) {
    arr.push({
      x: mem.wMinX + ((start % gw) + 0.5) * gs,
      y: mem.wMinY + (((start / gw) | 0) + 0.5) * gs,
      idx: start
    });
  }
  arr.reverse();
  if (arr.length && dist(arr[arr.length - 1].x, arr[arr.length - 1].y, tx, ty) < 6) {
    arr.push({ x: tx, y: ty, idx: goal });
  }
  return arr.length ? arr : null;
}

function initMission(obs, mem) {
  mem.init = true;
  var t = N(obs.t, 0);
  mem.t0 = t;
  mem.t = t;
  mem.lastT = t - 0.1;
  mem.dt = 0.1;

  var m = obs.mission || {};
  mem.seconds = N(m.seconds, 1200);
  mem.cap = Math.round(N(m.capacity, 5));
  if (!(mem.cap > 0)) mem.cap = 5;

  var b = m.base || {};
  mem.base = {
    x: N(b.x, N(obs.x, 0)),
    y: N(b.y, N(obs.y, 0))
  };

  var sx = 400, sy = 400;
  var sz = m.size;
  if (typeof sz === "number") {
    sx = sy = N(sz, 400);
  } else if (Array.isArray(sz)) {
    sx = N(sz[0], 400);
    sy = N(sz[1], sx);
  } else if (sz && typeof sz === "object") {
    sx = N(sz.x, N(sz.width, 400));
    sy = N(sz.y, N(sz.height, sx));
  }
  if (!(sx > 20)) sx = 400;
  if (!(sy > 20)) sy = 400;

  var hs = m.hints || [];
  mem.hints = [];
  var minx = mem.base.x, maxx = mem.base.x;
  var miny = mem.base.y, maxy = mem.base.y;
  var i;

  for (i = 0; i < hs.length; i++) {
    var h = hs[i] || {};
    var hx = N(h.x, mem.base.x);
    var hy = N(h.y, mem.base.y);
    var est = N(h.estimate, 1);
    if (!(est > 0)) est = 1;
    mem.hints.push({ x: hx, y: hy, est: est, status: 0 });
    if (hx < minx) minx = hx;
    if (hx > maxx) maxx = hx;
    if (hy < miny) miny = hy;
    if (hy > maxy) maxy = hy;
  }

  var vals = [];
  for (i = 0; i < mem.hints.length; i++) vals.push(mem.hints[i].est);
  vals.sort(function (a, b) { return a - b; });
  mem.medEst = vals.length ? vals[Math.floor(vals.length / 2)] : 1;

  var centered = minx < -5 || miny < -5 || maxx > sx + 5 || maxy > sy + 5;
  if (centered) {
    mem.wMinX = -sx / 2;
    mem.wMaxX = sx / 2;
    mem.wMinY = -sy / 2;
    mem.wMaxY = sy / 2;
  } else {
    mem.wMinX = 0;
    mem.wMaxX = sx;
    mem.wMinY = 0;
    mem.wMaxY = sy;
  }

  mem.gw = Math.max(4, Math.ceil((mem.wMaxX - mem.wMinX) / GS) + 1);
  mem.gh = Math.max(4, Math.ceil((mem.wMaxY - mem.wMinY) / GS) + 1);
  mem.gN = mem.gw * mem.gh;
  mem.occ = new Int16Array(mem.gN);
  mem.planG = new Float32Array(mem.gN);
  mem.planF = new Float32Array(mem.gN);
  mem.planP = new Int32Array(mem.gN);
  mem.planC = new Uint8Array(mem.gN);
  mem.heap = [];

  mem.px = clamp(N(obs.x, mem.base.x), mem.wMinX + 0.3, mem.wMaxX - 0.3);
  mem.py = clamp(N(obs.y, mem.base.y), mem.wMinY + 0.3, mem.wMaxY - 0.3);
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastGx = mem.px;
  mem.lastGy = mem.py;
  mem.gpsStill = 0;
  mem.bodySpeed = 0;

  mem.raw = norm(N(obs.heading, 0));
  mem.lastRaw = mem.raw;
  mem.jump = 0;
  mem.bias = 0;
  mem.biasN = 0;
  mem.hdg = mem.raw;

  mem.calX = mem.px;
  mem.calY = mem.py;
  mem.calRaw = mem.raw;
  mem.calPhase = true;
  mem.calStartT = t;
  mem.calStartX = mem.px;
  mem.calStartY = mem.py;
  mem.calStartRaw = mem.raw;

  mem.lastWl = N(obs.wheelLeft, 0);
  mem.lastWr = N(obs.wheelRight, 0);
  mem.mL = { i: 0 };
  mem.mR = { i: 0 };
  mem.holdInit = false;
  mem.hIL = 0;
  mem.hIR = 0;

  mem.lastBattery = N(obs.battery, 1);
  mem.ePerM = 0.0015;
  mem.eN = 0;

  mem.lastCarried = Math.round(N(obs.carried, 0));
  mem.samples = 0;
  mem.deliveredCount = Math.round(N(obs.delivered, 0));
  mem.returning = false;
  mem.task = null;
  mem.drill = null;
  mem.siteTrack = null;
  mem.ignoreSiteUntil = -1;
  mem.badSites = [];

  mem.lastBumpT = -99;
  mem.bumpCount = 0;
  mem.cautiousUntil = 0;
  mem.recoverUntil = -1;
  mem.recoverDir = 1;

  mem.avoidSide = 1;
  mem.avoidUntil = -1;

  mem.chargeStart = null;
  mem.expPts = null;
  mem.sciCooldown = 0;

  mem.path = null;
  mem.pathGoal = null;
  mem.pathIdx = 0;
  mem.lastPlan = -99;
  mem.lastGridT = t - 1;
  mem.wall = null;

  mem.errCount = 0;
  mem.lastError = "";
}

function updateState(obs, mem) {
  var t = N(obs.t, N(mem.lastT, 0) + 0.1);
  var dt = t - N(mem.lastT, t - 0.1);
  if (!(dt > 0) || dt > 0.5) dt = 0.1;
  mem.dt = dt;
  mem.t = t;

  var wl = N(obs.wheelLeft, 0);
  var wr = N(obs.wheelRight, 0);
  var avg = (wl + wr) / 2;
  var raw = norm(N(obs.heading, mem.lastRaw));

  var yaw = ((wr - wl) / 0.6) * R2D * dt;
  var draw = norm(raw - mem.lastRaw);
  if (Math.abs(draw) > 55 && Math.abs(yaw) < 18) {
    mem.jump = norm(mem.jump - draw);
  }
  var eff = norm(raw + mem.jump);

  var pred = norm(mem.hdg + yaw);
  var comp = norm(eff + mem.bias);
  var dh = norm(comp - pred);

  if (Math.abs(dh) < 60) {
    mem.hdg = norm(pred + dh * 0.48);
  } else if (Math.abs(avg) < 0.08 && Math.abs(dh) < 120) {
    mem.hdg = norm(mem.hdg + dh * 0.18);
  } else {
    mem.hdg = pred;
  }

  var gx = N(obs.x, mem.px);
  var gy = N(obs.y, mem.py);
  var gmove = dist(gx, gy, mem.lastGx, mem.lastGy);

  if (gmove < 0.004 && Math.abs(avg) > 0.08) mem.gpsStill += dt;
  else if (gmove > 0.02) mem.gpsStill = 0;
  else mem.gpsStill = Math.max(0, mem.gpsStill - dt * 1.2);

  var frozen = mem.gpsStill > 1.0;
  var oldpx = mem.px;
  var oldpy = mem.py;

  if (frozen) {
    mem.px += avg * Math.cos(mem.hdg * D2R) * dt;
    mem.py += avg * Math.sin(mem.hdg * D2R) * dt;
  } else {
    mem.px = gx;
    mem.py = gy;
  }

  mem.px = clamp(mem.px, mem.wMinX + 0.2, mem.wMaxX - 0.2);
  mem.py = clamp(mem.py, mem.wMinY + 0.2, mem.wMaxY - 0.2);

  var moved = dist(mem.px, mem.py, oldpx, oldpy);
  mem.bodySpeed = moved / dt;

  if (!frozen && gmove > 0.006) {
    var cd = dist(gx, gy, mem.calX, mem.calY);
    if (cd > 0.85 && Math.abs(wr - wl) < 0.75 && Math.abs(avg) > 0.15) {
      var ma = Math.atan2(gy - mem.calY, gx - mem.calX) * R2D;
      var ra = midAng(mem.calRaw, eff);
      var targetBias = norm(ma - ra);
      var bd = norm(targetBias - mem.bias);
      if (Math.abs(bd) < 85) {
        var alpha = mem.biasN < 8 ? 0.25 : 0.012;
        mem.bias = norm(mem.bias + bd * alpha);
        mem.biasN++;
        mem.hdg = norm(eff + mem.bias);
      }
      mem.calX = gx;
      mem.calY = gy;
      mem.calRaw = eff;
    } else if (cd > 2.5) {
      mem.calX = gx;
      mem.calY = gy;
      mem.calRaw = eff;
    }
  }

  var bat = N(obs.battery, mem.lastBattery);
  var eDist = dist(mem.px, mem.py, mem.lastPx, mem.lastPy);
  if (eDist > 0.10 && !mem.drill && mem.lastBattery != null) {
    var drop = mem.lastBattery - bat;
    if (drop > 0 && drop < 0.25) {
      var e = drop / eDist;
      if (e > 0.00001 && e < 0.2) {
        if (mem.eN < 3) mem.ePerM = e;
        else mem.ePerM = mem.ePerM * 0.97 + e * 0.03;
        mem.eN++;
      }
    }
  }

  mem.lastRaw = raw;
  mem.lastWl = wl;
  mem.lastWr = wr;
  mem.lastGx = gx;
  mem.lastGy = gy;
  mem.lastPx = mem.px;
  mem.lastPy = mem.py;
  mem.lastBattery = bat;
  mem.lastT = t;
}

function wheelDrive(obs, mem, tl, tr, drillFlag) {
  var dt = mem.dt || 0.1;
  var wl = N(obs.wheelLeft, 0);
  var wr = N(obs.wheelRight, 0);

  function one(st, target, actual) {
    target = clamp(target, -0.9, 0.9);
    var err = target - actual;

    st.i = clamp(st.i + err * dt * 1.1, -2.0, 2.0);

    var ff = 0;
    if (target > 0.02) ff = 0.06 + 0.28 * target;
    else if (target < -0.02) ff = -0.06 + 0.28 * target;

    var u = ff + 0.75 * err + 0.25 * st.i;

    if (Math.abs(target) < 0.03 && Math.abs(actual) < 0.05) {
      st.i *= 0.92;
    }

    if (u > 1) {
      u = 1;
      if (err > 0) st.i = Math.min(st.i, 1.0);
    }
    if (u < -1) {
      u = -1;
      if (err < 0) st.i = Math.max(st.i, -1.0);
    }
    return clamp(u, -1, 1);
  }

  return {
    left: one(mem.mL, tl, wl),
    right: one(mem.mR, tr, wr),
    drill: !!drillFlag
  };
}

function holdControl(obs, mem, drillFlag) {
  var dt = mem.dt || 0.1;
  var wl = N(obs.wheelLeft, 0);
  var wr = N(obs.wheelRight, 0);

  if (!mem.holdInit) {
    mem.holdInit = true;
    mem.hIL = 0;
    mem.hIR = 0;
  }

  mem.hIL = clamp(mem.hIL - wl * dt * 0.9, -1.2, 1.2);
  mem.hIR = clamp(mem.hIR - wr * dt * 0.9, -1.2, 1.2);

  var pitch = clamp(N(obs.pitch, 0), -45, 45);
  var ff = clamp(pitch * 0.015, -0.45, 0.45);

  var uL = ff + mem.hIL - wl * 1.2;
  var uR = ff + mem.hIR - wr * 1.2;

  return {
    left: clamp(uL, -1, 1),
    right: clamp(uR, -1, 1),
    drill: !!drillFlag
  };
}

function driveRel(obs, mem, errReq, vReq, avoid) {
  mem.holdInit = false;

  var rays = obs.rays || [];
  var fmin = 15, lc = 15, rc = 15;
  var steer = 0;
  var i, r, a, w;

  for (i = 0; i < 9; i++) {
    r = rayAt(obs, i);
    a = RA[i];

    if (a >= -60 && a <= 60 && r < fmin) fmin = r;
    if (a >= 20 && r < lc) lc = r;
    if (a <= -20 && r < rc) rc = r;

    if (avoid && r < 5.5) {
      w = (5.5 - r) / 5.5;
      w *= w;
      if (a > 8) steer -= w * 34;
      else if (a < -8) steer += w * 34;
    }
  }

  if (avoid) {
    if (fmin < 3.0) {
      var side;
      if (mem.t < mem.avoidUntil) {
        side = mem.avoidSide;
      } else {
        side = lc >= rc ? 1 : -1;
        var er0 = norm(errReq);
        if (Math.abs(er0) > 18) {
          if (er0 > 0 && lc > 0.9) side = 1;
          else if (er0 < 0 && rc > 0.9) side = -1;
        }
        mem.avoidSide = side;
        mem.avoidUntil = mem.t + 3.0;
      }
      steer += side * (3.0 - fmin) * 14;
    }

    if (lc < 0.7 && rc >= 0.7) steer -= (0.7 - lc) * 70;
    if (rc < 0.7 && lc >= 0.7) steer += (0.7 - rc) * 70;
    if (lc < 0.45 && rc < 0.45) vReq = Math.min(vReq, 0.10);
  }

  var e = norm(errReq + clamp(steer, -72, 72));
  var ae = Math.abs(e);

  var v = vReq;
  var capV = 0.82;
  if (mem.cautiousUntil > mem.t) capV = 0.55;

  if (avoid) {
    if (fmin < 0.95) v = 0;
    else if (fmin < 2.4) v = Math.min(v, Math.max(0.04, (fmin - 0.95) * 0.30));
    else if (fmin < 4.5) v = Math.min(v, 0.35);
    else if (fmin < 7.0) v = Math.min(v, 0.62);
    else v = Math.min(v, capV);

    if (lc < 0.50 || rc < 0.50) v = Math.min(v, 0.22);
  }
  if (v > capV) v = capV;

  if (ae > 120) v = Math.min(v, 0.10);
  else if (ae > 80) v = Math.min(v, 0.24);
  else if (ae > 50) v = Math.min(v, 0.52);

  var vmaxNow = Math.max(Math.abs(N(obs.wheelLeft, 0)), Math.abs(N(obs.wheelRight, 0)));
  if (vmaxNow > 0.98 && v > 0) v = 0;

  if (mem.bodySpeed > 0.98 && !mem.drill) {
    return wheelDrive(obs, mem, -0.12, -0.12, false);
  }

  var omega = clamp(e * D2R * 1.8, -2.2, 2.2);
  if (ae < 2.0) omega = 0;

  var tl = v - omega * 0.3;
  var tr = v + omega * 0.3;

  if (v < 0.08 && ae > 15) {
    var rot = clamp(ae * D2R * 1.2, 0.24, 0.55);
    var sgn = e > 0 ? 1 : -1;
    tl = -sgn * rot;
    tr = sgn * rot;
  }

  var maxW = 0.85;
  var mm = Math.max(Math.abs(tl), Math.abs(tr));
  if (mm > maxW) {
    tl *= maxW / mm;
    tr *= maxW / mm;
  }

  return wheelDrive(obs, mem, tl, tr, false);
}

function chooseWaypoint(obs, mem, tx, ty) {
  var d = dist(mem.px, mem.py, tx, ty);
  var tb = Math.atan2(ty - mem.py, tx - mem.px) * R2D;
  var err = norm(tb - mem.hdg);
  var fm = frontMin(obs);

  if (d < 1.5) return { x: tx, y: ty };
  if (d < 10 && fm > 3.0) return { x: tx, y: ty };
  if (fm > 6.5 && Math.abs(err) < 35) return { x: tx, y: ty };

  var needPlan = true;
  if (mem.path && mem.pathGoal && mem.path.length &&
      dist(tx, ty, mem.pathGoal.x, mem.pathGoal.y) < 4 &&
      mem.t - mem.lastPlan < 1.2) {
    needPlan = false;
  }

  if (needPlan) {
    var p = planPath(mem, tx, ty, mem.t);
    if (p && p.length > 0) {
      mem.path = p;
      mem.pathGoal = { x: tx, y: ty };
      mem.pathIdx = 0;
      mem.lastPlan = mem.t;
    } else {
      mem.path = null;
      mem.pathGoal = null;
    }
  }

  if (mem.path && mem.path.length) {
    var idx = mem.pathIdx || 0;
    while (idx < mem.path.length - 1 &&
           dist(mem.px, mem.py, mem.path[idx].x, mem.path[idx].y) < 2.0) {
      idx++;
    }
    mem.pathIdx = idx;
    var j = Math.min(mem.path.length - 1, idx + 2);
    return { x: mem.path[j].x, y: mem.path[j].y };
  }

  return { x: tx, y: ty };
}

function driveToPoint(obs, mem, tx, ty, speed, stopDist) {
  var d = dist(mem.px, mem.py, tx, ty);
  if (d <= stopDist) return holdControl(obs, mem, false);

  var wp = chooseWaypoint(obs, mem, tx, ty);
  var bearing = Math.atan2(wp.y - mem.py, wp.x - mem.px) * R2D;
  var err = norm(bearing - mem.hdg);

  var sp = speed;
  if (d < 2.0) sp = Math.min(sp, 0.15);
  else if (d < 4.0) sp = Math.min(sp, 0.28);
  else if (d < 7.0) sp = Math.min(sp, 0.45);
  else if (d < 12.0) sp = Math.min(sp, 0.65);
  if (Math.abs(err) > 100) sp = Math.min(sp, 0.15);
  if (mem.cautiousUntil > mem.t) sp = Math.min(sp, 0.50);

  return driveRel(obs, mem, err, sp, true);
}

function goHome(obs, mem) {
  var bd = dist(mem.px, mem.py, mem.base.x, mem.base.y);
  var bat = N(obs.battery, 1);

  if (obs.docked) return holdControl(obs, mem, false);

  if (obs.beacon) {
    var be = N(obs.beacon.distance, 99);
    if (be < 2.8) return holdControl(obs, mem, false);
    if (be < 20 && frontMin(obs) > 4.0) {
      var v = be > 8 ? 0.80 : (be > 5 ? 0.55 : 0.32);
      return driveRel(obs, mem, N(obs.beacon.bearing, 0), v, true);
    }
  }

  if (bd < 2.5) return holdControl(obs, mem, false);

  var sp = 0.80;
  if (bat < 0.18) sp = 0.55;
  if (mem.cautiousUntil > mem.t) sp = Math.min(sp, 0.50);

  return driveToPoint(obs, mem, mem.base.x, mem.base.y, sp, 0.7);
}

function makeSpiral(mem, cx, cy, R, pitch) {
  var pts = [];
  pitch = Math.max(6, pitch || 10);
  var a = pitch / (2 * Math.PI);
  var thmax = R / Math.max(0.5, a);
  var lx = null, ly = null;

  for (var th = 0; th <= thmax + 0.2; th += 0.15) {
    var rr = a * th;
    var x = cx + rr * Math.cos(th);
    var y = cy + rr * Math.sin(th);
    x = clamp(x, mem.wMinX + 1.5, mem.wMaxX - 1.5);
    y = clamp(y, mem.wMinY + 1.5, mem.wMaxY - 1.5);

    if (lx === null || dist(x, y, lx, ly) > 1.3) {
      pts.push({ x: x, y: y });
      lx = x;
      ly = y;
    }
  }

  if (!pts.length) {
    pts.push({
      x: clamp(cx, mem.wMinX + 1.5, mem.wMaxX - 1.5),
      y: clamp(cy, mem.wMinY + 1.5, mem.wMaxY - 1.5)
    });
  }
  return pts;
}

function addBad(mem, x, y, until) {
  if (!mem.badSites) mem.badSites = [];
  mem.badSites.push({ x: x, y: y, until: until });
  if (mem.badSites.length > 30) mem.badSites.shift();
}
function isBad(mem, x, y, t) {
  if (!mem.badSites) return false;
  for (var i = 0; i < mem.badSites.length; i++) {
    var b = mem.badSites[i];
    if (t < b.until && dist(x, y, b.x, b.y) < 5.0) return true;
  }
  return false;
}

function markSampledHints(mem, x, y) {
  var best = -1, bd = 1e9;
  for (var i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.status !== 0) continue;
    var d = dist(h.x, h.y, x, y);
    if (d < bd) {
      bd = d;
      best = i;
    }
  }
  if (best >= 0 && bd < 45) mem.hints[best].status = 2;
}

function startDrill(mem, obs, t, site, ex, ey) {
  mem.drill = {
    start: t,
    x: ex,
    y: ey,
    value: N(site.value, 0),
    lastDrill: N(obs.drilling, 0),
    resets: 0,
    lost: 0
  };
  mem.holdInit = false;
  mem.task = null;
  mem.path = null;
  mem.wall = null;
}

function shouldReturn(obs, mem, carried, timeLeft, battery, baseD) {
  if (carried >= mem.cap) return true;
  var e = Math.max(0.0012, mem.ePerM || 0.0015) * 1.6;
  var reserve = 0.08 + baseD * e * (1 + 0.35 * carried) + 0.025 * carried;
  if (battery < reserve) return true;
  if (timeLeft < baseD / 0.55 + 25 + 6 * carried) return true;
  if (battery < 0.12 && baseD > 12) return true;
  if (timeLeft < 45) return true;
  return false;
}

function initExplore(mem) {
  var pts = [];
  var step = 60;
  var margin = 24;
  for (var y = mem.wMinY + margin; y <= mem.wMaxY - margin + 0.1; y += step) {
    for (var x = mem.wMinX + margin; x <= mem.wMaxX - margin + 0.1; x += step) {
      pts.push({ x: x, y: y, done: false });
    }
  }
  if (!pts.length) pts.push({ x: mem.base.x, y: mem.base.y, done: false });
  mem.expPts = pts;
}

function chooseTask(obs, mem, carried, baseD, timeLeft, battery) {
  if (carried > 0) return null;

  var best = null;
  var bestScore = -1e18;
  var med = mem.medEst || 1;
  var t = mem.t || 0;

  for (var i = 0; i < mem.hints.length; i++) {
    var h = mem.hints[i];
    if (h.status !== 0) continue;

    var d = dist(mem.px, mem.py, h.x, h.y);
    var db = dist(h.x, h.y, mem.base.x, mem.base.y);
    var val = Math.max(0.05, h.est);
    var high = val > med * 1.35;
    var R = high ? 30 : 23;
    var maxSearch = high ? 55 : 40;

    var need = (d + db) / 0.55 + maxSearch + 25;
    if (timeLeft < need) continue;

    var e = Math.max(0.0012, mem.ePerM || 0.0015) * 1.6;
    var reserve = 0.05 + (d + db) * e * 2.0 + 0.02;
    if (battery < reserve && d + db > 18) continue;

    var cost = d + db * 0.9 + R * 0.7 + 22;
    var score = val / Math.pow(Math.max(10, cost), 0.85);

    if (mem.deliveredCount === 0) {
      score *= 1 / (1 + d / 160);
      score *= 1.20;
    }
    if (d < 30) score *= 1.12;
    if (high) score *= 1.08;
    if (isBad(mem, h.x, h.y, t)) score *= 0.55;

    if (score > bestScore) {
      bestScore = score;
      best = {
        type: "hint",
        idx: i,
        phase: "travel",
        start: t,
        bestD: d,
        lastProg: t,
        searchPts: null,
        si: 0,
        searchStart: 0,
        ptStart: 0,
        R: R,
        maxSearch: maxSearch
      };
    }
  }

  return best;
}

function chooseExplore(obs, mem, timeLeft, battery) {
  if (timeLeft < 35 || battery < 0.07) return null;

  if (N(obs.science, 0) > 0.90 && mem.t > mem.sciCooldown) {
    mem.sciCooldown = mem.t + 75;
    return {
      type: "spiral",
      cx: mem.px,
      cy: mem.py,
      R: 20,
      maxSearch: 28,
      searchPts: null,
      si: 0,
      searchStart: mem.t,
      ptStart: mem.t,
      start: mem.t
    };
  }

  if (!mem.expPts) initExplore(mem);

  var bi = -1;
  var bd = 1e9;
  for (var i = 0; i < mem.expPts.length; i++) {
    var p = mem.expPts[i];
    if (p.done) continue;
    var d = dist(mem.px, mem.py, p.x, p.y);
    if (d < 8) {
      p.done = true;
      continue;
    }
    if (d < bd) {
      bd = d;
      bi = i;
    }
  }

  if (bi >= 0) {
    var q = mem.expPts[bi];
    return {
      type: "point",
      idx: bi,
      x: q.x,
      y: q.y,
      start: mem.t
    };
  }

  return {
    type: "spiral",
    cx: mem.px,
    cy: mem.py,
    R: 18,
    maxSearch: 24,
    searchPts: null,
    si: 0,
    searchStart: mem.t,
    ptStart: mem.t,
    start: mem.t
  };
}

function runTask(obs, mem, t, carried, baseD, battery, timeLeft) {
  var task = mem.task;
  if (!task) return null;

  if (task.type === "hint") {
    var h = mem.hints[task.idx];
    if (!h || h.status !== 0) {
      mem.task = null;
      return null;
    }

    if (task.phase === "travel") {
      var d = dist(mem.px, mem.py, h.x, h.y);

      if (d < 5.0) {
        task.phase = "search";
        task.searchPts = null;
        task.si = 0;
        task.searchStart = t;
        task.ptStart = t;
      } else {
        if (d < task.bestD - 0.3) {
          task.bestD = d;
          task.lastProg = t;
        }

        if (t - task.lastProg > 35 && d > 6 && t - task.start > 80) {
          h.status = 1;
          mem.task = null;
          mem.path = null;
          return null;
        }

        if (timeLeft < (d + dist(h.x, h.y, mem.base.x, mem.base.y)) / 0.45 + 20) {
          mem.task = null;
          return null;
        }

        var sp = 0.80;
        if (battery < 0.25) sp = 0.55;
        if (mem.cautiousUntil > t) sp = Math.min(sp, 0.50);
        return driveToPoint(obs, mem, h.x, h.y, sp, 1.2);
      }
    }

    if (task.phase === "search") {
      if (!task.searchPts) {
        task.searchPts = makeSpiral(mem, h.x, h.y, task.R || 24, 10);
        task.si = 0;
        task.searchStart = t;
        task.ptStart = t;
      }

      if (t - task.searchStart > (task.maxSearch || 45) ||
          task.si >= task.searchPts.length) {
        h.status = 1;
        mem.task = null;
        mem.path = null;
        return null;
      }

      var p = task.searchPts[task.si];
      var dp = dist(mem.px, mem.py, p.x, p.y);

      if (dp < 2.1 || t - task.ptStart > 10.0) {
        task.si++;
        task.ptStart = t;
        if (task.si >= task.searchPts.length) {
          h.status = 1;
          mem.task = null;
          mem.path = null;
          return null;
        }
        p = task.searchPts[task.si];
      }

      if (timeLeft < 15) {
        mem.task = null;
        return null;
      }

      var sp2 = 0.70;
      if (mem.cautiousUntil > t) sp2 = Math.min(sp2, 0.45);
      return driveToPoint(obs, mem, p.x, p.y, sp2, 0.8);
    }
  }

  if (task.type === "point") {
    var de = dist(mem.px, mem.py, task.x, task.y);

    if (de < 4.0 || t - task.start > 60) {
      if (mem.expPts && mem.expPts[task.idx]) mem.expPts[task.idx].done = true;
      mem.task = null;
      return null;
    }

    var spe = 0.78;
    if (battery < 0.25) spe = 0.52;
    if (mem.cautiousUntil > t) spe = Math.min(spe, 0.48);
    return driveToPoint(obs, mem, task.x, task.y, spe, 0.8);
  }

  if (task.type === "spiral") {
    if (!task.searchPts) {
      task.searchPts = makeSpiral(mem, task.cx, task.cy, task.R || 20, 10);
      task.si = 0;
      task.searchStart = t;
      task.ptStart = t;
    }

    if (t - task.searchStart > (task.maxSearch || 26) ||
        task.si >= task.searchPts.length) {
      mem.task = null;
      mem.path = null;
      return null;
    }

    var ps = task.searchPts[task.si];
    var ds = dist(mem.px, mem.py, ps.x, ps.y);

    if (ds < 2.1 || t - task.ptStart > 9.0) {
      task.si++;
      task.ptStart = t;
      if (task.si >= task.searchPts.length) {
        mem.task = null;
        mem.path = null;
        return null;
      }
      ps = task.searchPts[task.si];
    }

    var sps = 0.68;
    if (battery < 0.25) sps = 0.48;
    return driveToPoint(obs, mem, ps.x, ps.y, sps, 0.8);
  }

  mem.task = null;
  return null;
}

function act(obs, mem) {
  try {
    if (!mem.init) initMission(obs, mem);

    updateState(obs, mem);
    updateGrid(obs, mem);

    var t = mem.t;
    var dt = mem.dt || 0.1;
    var timeLeft = N(obs.timeLeft, mem.seconds - (t - mem.t0));
    if (!isFinite(timeLeft) || timeLeft < 0) timeLeft = 0;

    var battery = N(obs.battery, mem.lastBattery);
    var carried = Math.max(0, Math.round(N(obs.carried, mem.lastCarried)));
    var prevCarried = mem.lastCarried;

    var baseD = dist(mem.px, mem.py, mem.base.x, mem.base.y);
    var beaconD = obs.beacon ? N(obs.beacon.distance, 99) : 99;
    var atBase = !!obs.docked || (obs.beacon && beaconD < 3.2) || baseD < 3.2;

    if (carried > prevCarried) {
      mem.samples += carried - prevCarried;
      var sx = mem.px, sy = mem.py;
      if (mem.drill && mem.drill.x != null) {
        sx = mem.drill.x;
        sy = mem.drill.y;
      }
      markSampledHints(mem, sx, sy);

      mem.drill = null;
      mem.holdInit = false;
      mem.task = null;
      mem.path = null;
      mem.wall = null;
      mem.returning = true;
      mem.ignoreSiteUntil = t + 1;
    }

    if (carried < prevCarried) {
      mem.deliveredCount += prevCarried - carried;
      mem.returning = false;
      mem.task = null;
      mem.drill = null;
      mem.holdInit = false;
      mem.path = null;
      mem.wall = null;
      mem.chargeStart = t;
    }

    mem.lastCarried = carried;

    if (obs.bumped) {
      if (t - mem.lastBumpT > 0.5) {
        if (t - mem.lastBumpT < 5.0) mem.bumpCount++;
        else mem.bumpCount = 1;
        mem.lastBumpT = t;
        mem.recoverUntil = t + 1.2;
        mem.recoverDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
        mem.task = null;
        mem.drill = null;
        mem.holdInit = false;
        mem.path = null;
        mem.wall = null;

        mem.cautiousUntil = Math.max(mem.cautiousUntil, t + 6);
        if (mem.bumpCount >= 3) mem.cautiousUntil = t + 20;

        var ax = mem.px + Math.cos(mem.hdg * D2R) * 1.2;
        var ay = mem.py + Math.sin(mem.hdg * D2R) * 1.2;
        markHitPoint(mem, ax, ay, 20);
      }
    }

    if (t < mem.recoverUntil) {
      var ph = t - (mem.recoverUntil - 1.2);
      if (ph < 0.45) return wheelDrive(obs, mem, -0.35, -0.35, false);
      var rd = mem.recoverDir || 1;
      return wheelDrive(obs, mem, -rd * 0.35, rd * 0.35, false);
    }

    if (mem.calPhase) {
      if (t - mem.calStartT < 0.8 && !obs.site && frontMin(obs) > 2.0) {
        return wheelDrive(obs, mem, 0.50, 0.50, false);
      }

      var md = dist(mem.px, mem.py, mem.calStartX, mem.calStartY);
      if (md > 0.25 && mem.gpsStill < 1.0) {
        var ma = Math.atan2(mem.py - mem.calStartY, mem.px - mem.calStartX) * R2D;
        var ra = midAng(mem.calStartRaw, norm(N(obs.heading, 0) + mem.jump));
        var tbias = norm(ma - ra);
        var bd = norm(tbias - mem.bias);
        if (Math.abs(bd) < 80) {
          mem.bias = norm(mem.bias + bd * 0.60);
          mem.hdg = norm(N(obs.heading, 0) + mem.jump + mem.bias);
        }
      }

      mem.calPhase = false;
      mem.calX = mem.px;
      mem.calY = mem.py;
      mem.calRaw = norm(N(obs.heading, 0) + mem.jump);
    }

    if (mem.drill) {
      var dr = N(obs.drilling, 0);
      if (dr < mem.drill.lastDrill - 0.30) mem.drill.resets++;
      mem.drill.lastDrill = dr;

      var siteNow = obs.site;
      if (siteNow && N(siteNow.distance, 99) > 2.2 && t - mem.drill.start > 1.5) {
        mem.drill.lost += dt;
      } else {
        mem.drill.lost = 0;
      }

      if (mem.drill.resets > 4 || mem.drill.lost > 1.5 ||
          t - mem.drill.start > 15 || battery < 0.02 || timeLeft < 3) {
        var bxs = mem.drill.x != null ? mem.drill.x : mem.px;
        var bys = mem.drill.y != null ? mem.drill.y : mem.py;
        addBad(mem, bxs, bys, t + 35);
        mem.drill = null;
        mem.holdInit = false;
        mem.task = null;
        mem.path = null;
        mem.ignoreSiteUntil = t + 8;
        mem.recoverUntil = t + 0.8;
        mem.recoverDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
        return wheelDrive(obs, mem, -0.35, -0.35, false);
      }

      return holdControl(obs, mem, true);
    }

    if (carried > 0 && atBase) {
      if (obs.docked || (!obs.beacon && baseD < 2.7) ||
          (obs.beacon && beaconD < 2.8) || baseD < 2.7) {
        mem.returning = true;
        return holdControl(obs, mem, false);
      }
    }

    if (carried === 0 && atBase) {
      mem.returning = false;
      mem.drill = null;
      mem.holdInit = false;

      if (mem.chargeStart == null) mem.chargeStart = t;

      var maxWait = 0;
      if (battery < 0.25) maxWait = 45;
      else if (battery < 0.50) maxWait = 18;
      else if (battery < 0.75) maxWait = 6;

      if (maxWait > 0 && timeLeft > maxWait + 60 &&
          t - mem.chargeStart < maxWait && battery < 0.92) {
        return holdControl(obs, mem, false);
      }

      if (battery >= 0.88 || t - mem.chargeStart > 24) mem.chargeStart = null;
    } else if (!atBase) {
      mem.chargeStart = null;
    }

    if (carried === 0) {
      if (!mem.returning) {
        if ((battery < 0.07 && baseD > 15) ||
            (timeLeft < baseD / 0.55 + 12)) {
          mem.returning = true;
        }
      }
    } else {
      if (!mem.returning && shouldReturn(obs, mem, carried, timeLeft, battery, baseD)) {
        mem.returning = true;
      }
      if (timeLeft < baseD / 0.55 + 15) mem.returning = true;
    }

    if (mem.returning) {
      if (carried > 0 && carried < mem.cap && obs.site && t >= mem.ignoreSiteUntil) {
        var osite = obs.site;
        var osd = N(osite.distance, 99);
        var oang = (mem.hdg + N(osite.bearing, 0)) * D2R;
        var oex = mem.px + osd * Math.cos(oang);
        var oey = mem.py + osd * Math.sin(oang);

        var reserve2 = Math.max(0.12, baseD * Math.max(0.0012, mem.ePerM || 0.0015) * 2.0 + 0.06);
        if (osd < 4.5 && !isBad(mem, oex, oey, t) &&
            timeLeft > baseD / 0.55 + 18 + 6 &&
            battery > reserve2) {
          if (osd <= 1.45) {
            startDrill(mem, obs, t, osite, oex, oey);
            return holdControl(obs, mem, true);
          }
          var osp = osd > 3.0 ? 0.35 : 0.18;
          return driveToPoint(obs, mem, oex, oey, osp, 0.8);
        }
      }

      if (carried > 0 && (obs.docked ||
          (obs.beacon && beaconD < 2.8) ||
          baseD < 2.6)) {
        return holdControl(obs, mem, false);
      }

      return goHome(obs, mem);
    }

    if (obs.site && carried < mem.cap && timeLeft > 8 &&
        battery > 0.03 && t >= mem.ignoreSiteUntil) {
      var site = obs.site;
      var sd = N(site.distance, 99);
      var sb = N(site.bearing, 0);
      var ga = (mem.hdg + sb) * D2R;
      var ex = mem.px + sd * Math.cos(ga);
      var ey = mem.py + sd * Math.sin(ga);

      var allow = true;
      if (carried > 0) {
        if (N(site.value, 0) < 0.15) allow = false;
        if (timeLeft < baseD / 0.55 + 28) allow = false;
        var reserve3 = baseD * Math.max(0.0012, mem.ePerM || 0.0015) * (1 + 0.5 * carried) * 2.0 + 0.10;
        if (battery < reserve3) allow = false;
      }

      if (allow && !isBad(mem, ex, ey, t)) {
        if (!mem.siteTrack ||
            dist(ex, ey, mem.siteTrack.x, mem.siteTrack.y) > 5 ||
            t - mem.siteTrack.lastSeen > 2) {
          mem.siteTrack = {
            x: ex,
            y: ey,
            start: t,
            best: sd,
            lastProg: t,
            lastSeen: t
          };
        } else {
          var stt = mem.siteTrack;
          stt.x = ex;
          stt.y = ey;
          stt.lastSeen = t;
          if (sd < stt.best - 0.2) {
            stt.best = sd;
            stt.lastProg = t;
          }
        }

        var st2 = mem.siteTrack;

        if (sd > 1.8 && t - st2.start > 50 && t - st2.lastProg > 35) {
          addBad(mem, ex, ey, t + 55);
          mem.ignoreSiteUntil = t + 15;
          mem.siteTrack = null;
          mem.task = null;
          mem.path = null;
          mem.recoverUntil = t + 0.8;
          mem.recoverDir = leftClear(obs) >= rightClear(obs) ? 1 : -1;
          return wheelDrive(obs, mem, -0.35, -0.35, false);
        }

        if (sd <= 1.45) {
          startDrill(mem, obs, t, site, ex, ey);
          return holdControl(obs, mem, true);
        }

        mem.task = null;

        var vv;
        if (sd > 6.0) vv = 0.74;
        else if (sd > 3.5) vv = 0.52;
        else if (sd > 2.2) vv = 0.32;
        else vv = 0.16;

        if (mem.cautiousUntil > t) vv = Math.min(vv, 0.32);
        return driveToPoint(obs, mem, ex, ey, vv, 0.8);
      }
    } else if (!obs.site) {
      if (mem.siteTrack && t - mem.siteTrack.lastSeen > 3) mem.siteTrack = null;
    }

    if (!mem.task) {
      var chosen = chooseTask(obs, mem, carried, baseD, timeLeft, battery);
      if (chosen) mem.task = chosen;
    }

    if (!mem.task) {
      if (carried > 0) return goHome(obs, mem);
      var ex2 = chooseExplore(obs, mem, timeLeft, battery);
      if (ex2) mem.task = ex2;
    }

    if (mem.task) {
      var ctl = runTask(obs, mem, t, carried, baseD, battery, timeLeft);
      if (ctl) return ctl;
      if (mem.task) return holdControl(obs, mem, false);
    }

    if (carried > 0) return goHome(obs, mem);
    return holdControl(obs, mem, false);
  } catch (e) {
    mem.errCount = (mem.errCount || 0) + 1;
    mem.lastError = String(e);
    return { left: 0, right: 0, drill: false };
  }
}

const D2R = Math.PI / 180;
const TRACK = 0.6;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) / D2R; }
function nCarried(obs) {
  const c = obs.carried;
  if (Array.isArray(c)) return c.length;
  return typeof c === 'number' ? c : 0;
}
function logEv(mem, t, msg) {
  if (!mem.log) mem.log = [];
  if (mem.log.length < 200) mem.log.push([Math.round(t), msg]);
}
function setMode(mem, name, t) { mem.mode = name; mem.modeT = t; mem.arrT = undefined; }

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  mem.base = (m.base && typeof m.base.x === 'number') ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = m.capacity > 0 ? m.capacity : 5;
  mem.seconds = m.seconds > 0 ? m.seconds : 1200;
  mem.sites = [];
  const hints = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hints) {
    if (h && typeof h.x === 'number' && typeof h.y === 'number') {
      mem.sites.push({ x: h.x, y: h.y, est: typeof h.estimate === 'number' ? h.estimate : 1, status: 'open', stuck: 0, tries: 0, kind: 'hint' });
    }
  }
  mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  mem.hEst = typeof obs.heading === 'number' ? obs.heading : 0;
  mem.off = 0; mem.hold = 0; mem.bal = 1;
  mem.mode = 'choose'; mem.modeT = obs.t || 0; mem.arrT = undefined;
  mem.hist = []; mem.lastCmd = { l: 0, r: 0 };
  mem.unstickUntil = -1; mem.uL = 0; mem.uR = 0;
  mem.moving = false; mem.log = [];
  mem.Lc = 15; mem.Rc = 15; mem.goLimit = 200;
}

// learn relative motor gain from straight driving; lastCmd holds the commands actually sent
function balanceLearn(obs, mem) {
  const c = mem.lastCmd;
  if (!c || !mem.bal) return;
  const wL = +obs.wheelLeft || 0, wR = +obs.wheelRight || 0;
  if (Math.abs(c.l) > 0.4 && Math.abs(c.r) > 0.4 && Math.sign(c.l) === Math.sign(c.r) &&
      Math.abs(c.l - c.r) < 0.08 && Math.abs(wL) > 0.2 && Math.abs(wR) > 0.2 &&
      Math.sign(wL) === Math.sign(wR)) {
    const ratio = (wL / c.l) / (wR / c.r);
    if (isFinite(ratio)) mem.bal = clamp(mem.bal + 0.03 * (ratio - mem.bal), 0.6, 1.6);
  }
}

function triggerUnstick(mem, t, dur) {
  const s = mem.Lc > mem.Rc ? 1 : -1;
  mem.uL = -0.55 - 0.2 * s;
  mem.uR = -0.55 + 0.2 * s;
  mem.unstickUntil = t + dur;
  logEv(mem, t, 'unstick in ' + mem.mode);
  if ((mem.mode === 'go' || mem.mode === 'search') && mem.tgt) {
    mem.tgt.stuck = (mem.tgt.stuck || 0) + 1;
    if (mem.tgt.stuck >= 3) { mem.tgt.status = 'fail'; setMode(mem, 'choose', t); }
  }
}

function hold(mem, sp) {
  mem.hold = clamp(mem.hold - 0.06 * sp, -0.9, 0.9);
  const u = clamp(mem.hold - 0.4 * sp, -0.9, 0.9);
  return { l: u, r: u, drill: false };
}

// e: bearing error in degrees (positive = target to the left), f: forward fraction, av: obstacle steer
function driveTo(e, f, av) {
  const c = Math.cos(e * D2R);
  let fw = f * Math.max(0, c);
  if (Math.abs(e) > 55) fw = 0;
  let tu = clamp(e * 0.006 + av, -0.7, 0.7);
  if (fw === 0) tu = clamp(tu, -0.3, 0.3);
  return { l: clamp(fw - tu, -1, 1), r: clamp(fw + tu, -1, 1), drill: false };
}

function chooseMode(obs, mem, t) {
  const cap = mem.cap, nC = nCarried(obs);
  const bat = typeof obs.battery === 'number' ? obs.battery : 1;
  const tl = typeof obs.timeLeft === 'number' ? obs.timeLeft : (mem.seconds - t);
  const px = mem.px, py = mem.py, base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  if (nC > 0 && (nC >= cap || bat < 0.3 || tl < dB / 1.0 + 60)) { setMode(mem, 'dock', t); return 'dock'; }
  if (bat < 0.18) { setMode(mem, 'dock', t); return 'dock'; }
  let best = null, bs = -1, bd = 0;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const d = hyp(px, py, s.x, s.y), db = hyp(s.x, s.y, base.x, base.y);
    if (d / 1.2 + db / 1.2 + 40 > tl - 5) continue;
    const sc = s.est / (d + 0.7 * db + 30);
    if (sc > bs) { bs = sc; best = s; bd = d; }
  }
  if (best) {
    mem.tgt = best;
    mem.goLimit = 60 + 0.8 * bd;
    setMode(mem, 'go', t);
    logEv(mem, t, 'target ' + best.x.toFixed(0) + ',' + best.y.toFixed(0));
    return 'go';
  }
  setMode(mem, 'dock', t);
  return 'dock';
}

function finishSample(mem, t) {
  const tg = mem.tgt;
  if (tg && tg.status === 'open' && hyp(tg.x, tg.y, mem.px, mem.py) < 25) tg.status = 'done';
  for (const s of mem.sites) {
    if (s.status === 'open' && hyp(s.x, s.y, mem.px, mem.py) < 8) s.status = 'done';
  }
  mem.doneRecent = { x: mem.px, y: mem.py, t };
  mem.samples = (mem.samples || 0) + 1;
  logEv(mem, t, 'drilled');
}

function step(obs, mem) {
  const t = typeof obs.t === 'number' ? obs.t : 0;
  if (!mem.init) initMem(obs, mem);
  const dt = mem.lastT === undefined ? 0.1 : clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;
  const cap = mem.cap;
  const nC = nCarried(obs);
  const wL = +obs.wheelLeft || 0, wR = +obs.wheelRight || 0;
  const sp = (wL + wR) / 2;
  const bat = typeof obs.battery === 'number' ? obs.battery : 1;
  const sci = +obs.science || 0;
  const site = obs.site || null;

  // ---- localisation: GPS when it changes, otherwise dead reckoning
  if (obs.x !== mem.gx || obs.y !== mem.gy) {
    mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  } else {
    mem.px += sp * Math.cos(mem.hEst * D2R) * dt;
    mem.py += sp * Math.sin(mem.hEst * D2R) * dt;
  }

  // ---- heading: wheel-speed gyro fused with compass (+ learned offset)
  const comp = wrap(obs.heading + mem.off);
  mem.hEst = wrap(mem.hEst + ((wR - wL) / TRACK) * dt / D2R + 0.03 * wrap(comp - mem.hEst));

  // compass offset learning from GPS displacement on straight runs
  const H = mem.hist;
  if (!H.length || t - H[H.length - 1].t >= 1.0) {
    H.push({ t: t, x: mem.px, y: mem.py, s: Math.abs(wL - wR) < 0.15 && sp > 0.5 });
    if (H.length > 4) H.shift();
  }
  if (H.length >= 4 && H.every(e => e.s)) {
    const a = H[0], b = H[H.length - 1];
    if (hyp(a.x, a.y, b.x, b.y) > 2.5) {
      const gh = brg(a.x, a.y, b.x, b.y);
      const diff = wrap(gh - obs.heading);
      mem.off = wrap(mem.off + 0.2 * wrap(diff - mem.off));
      mem.hist = [b];
    }
  }

  // ---- range sensing
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  let Lc = 15, Rc = 15, Fc = 15;
  for (let i = 0; i < 9; i++) {
    const v = rays[i];
    let d = (typeof v === 'number' && isFinite(v)) ? v : 15;
    d = clamp(d, 0, 15);
    const a = ANG[i];
    if (a > 0) Lc = Math.min(Lc, d); else if (a < 0) Rc = Math.min(Rc, d);
    if (Math.abs(a) <= 20) Fc = Math.min(Fc, d);
  }
  mem.Lc = Lc; mem.Rc = Rc;
  const fCap = clamp((Fc - 1) / 3, 0.15, 1);
  const wl = clamp((3 - Lc) / 3, 0, 1), wr = clamp((3 - Rc) / 3, 0, 1), wf = clamp((4.5 - Fc) / 4.5, 0, 1);
  const av = (wr - wl) * 0.6 + wf * clamp((Lc - Rc) / 5, -1, 1) * 0.5;

  // ---- bump / stuck handling
  if (obs.bumped && t >= mem.unstickUntil) triggerUnstick(mem, t, 1.6);
  if (!mem.ref) mem.ref = { x: mem.px, y: mem.py, t: t };
  if (hyp(mem.px, mem.py, mem.ref.x, mem.ref.y) > 1.0) {
    mem.ref = { x: mem.px, y: mem.py, t: t };
  } else if (t - mem.ref.t > 4) {
    if (mem.moving && t >= mem.unstickUntil) triggerUnstick(mem, t, 1.8);
    mem.ref = { x: mem.px, y: mem.py, t: t };
  }
  mem.moving = false;
  if (t < mem.unstickUntil) return { l: mem.uL, r: mem.uR, drill: false };

  // ---- mode management
  const px = mem.px, py = mem.py, H_ = mem.hEst, base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  const ignore = mem.doneRecent && (t - mem.doneRecent.t < 12) &&
    hyp(px, py, mem.doneRecent.x, mem.doneRecent.y) < 4;
  let mode = mem.mode;
  if (site && !ignore && nC < cap && (mode === 'go' || mode === 'search' || mode === 'choose')) {
    setMode(mem, 'approach', t);
    mode = 'approach';
  }
  if (mode === 'approach' && !site) {
    if (mem.tgt && mem.tgt.status === 'open') setMode(mem, 'go', t);
    else setMode(mem, 'choose', t);
    mode = mem.mode;
  }
  if (mode === 'choose') mode = chooseMode(obs, mem, t);

  let out = { l: 0, r: 0, drill: false };

  if (mode === 'drill') {
    const dr = +obs.drilling || 0;
    if (dr >= 6.0) {
      finishSample(mem, t);
      setMode(mem, 'choose', t);
      out = hold(mem, sp);
    } else if (t - mem.modeT > 25) {
      logEv(mem, t, 'drill timeout');
      if (mem.tgt) {
        mem.tgt.tries = (mem.tgt.tries || 0) + 1;
        if (mem.tgt.tries >= 2) mem.tgt.status = 'fail';
      }
      setMode(mem, 'choose', t);
      out = hold(mem, sp);
    } else {
      out = hold(mem, sp);
      out.drill = true;
    }
  } else if (mode === 'approach') {
    const d = site && typeof site.distance === 'number' ? site.distance : 5;
    const e = site && typeof site.bearing === 'number' ? site.bearing : 0;
    if (d <= 1.2) {
      setMode(mem, 'drill', t);
      out = hold(mem, sp);
      out.drill = true;
    } else {
      out = driveTo(e, clamp((d - 1.0) * 0.8, 0.15, 0.7) * fCap, 0);
      mem.moving = true;
    }
  } else if (mode === 'go') {
    const tg = mem.tgt;
    if (!tg) {
      setMode(mem, 'choose', t);
      out = hold(mem, sp);
    } else {
      const d = hyp(px, py, tg.x, tg.y);
      if (d < 2.2) {
        if (tg.kind === 'hint' && sci <= 0) {
          tg.status = 'fail';
          logEv(mem, t, 'hint empty');
          setMode(mem, 'choose', t);
        } else {
          setMode(mem, 'search', t);
          mem.sp = { th: 0, wpT: t };
        }
        out = hold(mem, sp);
      } else if (t - mem.modeT > mem.goLimit) {
        tg.status = 'fail';
        logEv(mem, t, 'go timeout');
        setMode(mem, 'choose', t);
        out = hold(mem, sp);
      } else {
        const e = wrap(brg(px, py, tg.x, tg.y) - H_);
        const f = (d > 6 ? 0.95 : clamp((d - 1.5) * 0.3 + 0.35, 0.3, 0.95)) * fCap;
        out = driveTo(e, f, av);
        mem.moving = true;
      }
    }
  } else if (mode === 'search') {
    const tg = mem.tgt, S = mem.sp;
    if (!tg || !S) {
      setMode(mem, 'choose', t);
      out = hold(mem, sp);
    } else {
      const a = 1.9, th = S.th, r = a * th;
      const wx = tg.x + r * Math.cos(th), wy = tg.y + r * Math.sin(th);
      const dw = hyp(px, py, wx, wy);
      if (dw < 2.0 || t - S.wpT > 12) {
        S.th += 2.5 / Math.max(r, 2.5);
        S.wpT = t;
        if (S.th > 8.5) {
          tg.status = 'fail';
          logEv(mem, t, 'search failed');
          setMode(mem, 'choose', t);
        }
        out = hold(mem, sp);
      } else {
        const e = wrap(brg(px, py, wx, wy) - H_);
        const f = clamp(dw * 0.5, 0.3, 0.7) * fCap;
        out = driveTo(e, f, av);
        mem.moving = true;
      }
    }
  } else if (mode === 'dock') {
    const bc = obs.beacon;
    let d, e;
    if (bc && typeof bc.distance === 'number') {
      d = bc.distance; e = typeof bc.bearing === 'number' ? bc.bearing : 0;
    } else {
      d = dB; e = wrap(brg(px, py, base.x, base.y) - H_);
    }
    if (d > 1.5) {
      out = driveTo(e, clamp((d - 1.2) * 0.6, 0.25, 0.8) * fCap, av);
      mem.moving = true;
      if (t - mem.modeT > 240) setMode(mem, 'choose', t);
    } else {
      out = hold(mem, sp);
      if (mem.arrT === undefined) mem.arrT = t;
      const waited = t - mem.arrT;
      if (nC > 0 && waited > 12) {
        mem.arrT = t;
        logEv(mem, t, 'no delivery yet');
      }
      if (nC === 0 && (bat > 0.9 || waited > 10)) {
        if (mem.deliveries === undefined) mem.deliveries = 0;
        mem.deliveries++;
        setMode(mem, 'choose', t);
      }
    }
  } else {
    out = hold(mem, sp);
    setMode(mem, 'choose', t);
  }
  return out;
}

function act(obs, mem) {
  let o = { l: 0, r: 0, drill: false };
  try {
    if (!mem.init) initMem(obs, mem);
    balanceLearn(obs, mem);
    o = step(obs, mem) || o;
  } catch (e) {
    mem.errs = (mem.errs || 0) + 1;
    o = { l: 0, r: 0, drill: false };
  }
  let l = clamp(+o.l || 0, -1, 1), r = clamp(+o.r || 0, -1, 1);
  if (mem.bal) {
    const s = Math.sqrt(mem.bal);
    l = clamp(l / s, -1, 1);
    r = clamp(r * s, -1, 1);
  }
  mem.lastCmd = { l: l, r: r };
  return { left: l, right: r, drill: !!o.drill };
}

const D2R = Math.PI / 180;
const TRACK = 0.6;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const MAXF = 0.7;

function isNum(v) { return typeof v === 'number' && isFinite(v); }
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) / D2R; }
function nCarried(obs) {
  const c = obs.carried;
  if (Array.isArray(c)) return c.length;
  return isNum(c) ? c : 0;
}
function logEv(mem, t, msg) {
  if (!mem.log) mem.log = [];
  if (mem.log.length < 150) mem.log.push([Math.round(t), msg]);
}
function setMode(mem, name, t) { mem.mode = name; mem.modeT = t; }

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  const t = isNum(obs.t) ? obs.t : 0;
  mem.base = (m.base && isNum(m.base.x) && isNum(m.base.y)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = (isNum(m.capacity) && m.capacity > 0) ? m.capacity : 5;
  mem.seconds = (isNum(m.seconds) && m.seconds > 0) ? m.seconds : 1200;
  mem.sites = [];
  const hints = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hints) {
    if (h && isNum(h.x) && isNum(h.y)) {
      mem.sites.push({ x: h.x, y: h.y, est: isNum(h.estimate) ? h.estimate : 1, status: 'open' });
    }
  }
  mem.grid = [];
  for (let gx = 30; gx <= 370; gx += 55) {
    for (let gy = 30; gy <= 370; gy += 55) mem.grid.push({ x: gx, y: gy, vis: false });
  }
  mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  mem.hEst = isNum(obs.heading) ? obs.heading : 0;
  mem.off = 0; mem.bal = 1; mem.I = 0; mem.hist = [];
  mem.lastCmd = { l: 0, r: 0 };
  mem.uUntil = -1; mem.uL = 0; mem.uR = 0; mem.slowT = 0; mem.wantMove = false;
  mem.tgt = null; mem.spiral = null; mem.exT = null; mem.goLimit = 100;
  mem.ignoreUntil = -1; mem.samples = 0; mem.delivered = 0; mem.nUnstick = 0; mem.sciT = -99;
  mem.log = [];
  setMode(mem, 'choose', t);
}

// learn relative motor gain from straight driving
function balanceLearn(obs, mem) {
  const c = mem.lastCmd;
  if (!c || !mem.bal) return;
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  if (Math.abs(c.l) > 0.4 && Math.abs(c.r) > 0.4 && Math.sign(c.l) === Math.sign(c.r) &&
      Math.abs(c.l - c.r) < 0.08 && Math.abs(wL) > 0.2 && Math.abs(wR) > 0.2 &&
      Math.sign(wL) === Math.sign(wR)) {
    const ratio = (wL / c.l) / (wR / c.r);
    if (isFinite(ratio)) mem.bal = clamp(mem.bal + 0.03 * (ratio - mem.bal), 0.6, 1.6);
  }
}

function triggerUnstick(mem, t, Lc, Rc) {
  const s = Lc >= Rc ? 1 : -1;
  mem.uL = -0.4 - 0.2 * s;
  mem.uR = -0.4 + 0.2 * s;
  mem.uUntil = t + 1.6;
  mem.slowT = 0;
  mem.nUnstick++;
  logEv(mem, t, 'unstick in ' + mem.mode);
  if ((mem.mode === 'go' || mem.mode === 'search') && mem.tgt) {
    mem.tgt.stuck = (mem.tgt.stuck || 0) + 1;
    if (mem.tgt.stuck >= 3) {
      mem.tgt.status = 'fail';
      mem.spiral = null;
      setMode(mem, 'choose', t);
    }
  }
}

// still-hold: cancels motion, compensates slope with pitch feedforward and an integrator
function holdStill(obs, mem, sp, pitch, dt, drill) {
  mem.I = clamp(mem.I - 1.0 * sp * dt, -0.6, 0.6);
  const u = clamp(mem.I - 0.8 * sp + 0.02 * pitch, -0.6, 0.6);
  return { l: u, r: u, drill: !!drill };
}

// e: bearing error in degrees (positive = target to the left), f: desired forward fraction
function drive(e, f, rays) {
  if (rays.Fc < 1.4) {
    const s = rays.Lc >= rays.Rc ? 1 : -1;
    const back = rays.Fc < 0.9 ? -0.25 : 0;
    return { l: clamp(back - 0.35 * s, -1, 1), r: clamp(back + 0.35 * s, -1, 1), drill: false };
  }
  const fCap = clamp((rays.Fw - 1.2) / 4.5, 0, 1);
  const wl = clamp((4 - rays.Lc) / 4, 0, 1);
  const wr = clamp((4 - rays.Rc) / 4, 0, 1);
  const av = 0.6 * (wr - wl);
  const c = Math.cos(e * D2R);
  let fw = clamp(f, 0, MAXF) * fCap * Math.max(0, c);
  if (Math.abs(e) > 60) fw = 0;
  let tu = clamp(0.012 * e + av, -0.8, 0.8);
  if (fw < 0.08) tu = clamp(tu, -0.5, 0.5);
  return { l: clamp(fw - tu, -1, 1), r: clamp(fw + tu, -1, 1), drill: false };
}

function newSpiral(cx, cy, rMax, t, tgt) {
  return { cx: cx, cy: cy, a: 1.2, th: 0, wpT: t, rMax: rMax, tgt: tgt };
}

function finishSample(mem, px, py, t) {
  mem.samples = (mem.samples || 0) + 1;
  let best = null, bd = 25;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const d = hyp(s.x, s.y, px, py);
    if (d < bd) { bd = d; best = s; }
  }
  if (best) best.status = 'done';
  mem.ignoreUntil = t + 3;
  logEv(mem, t, 'drilled');
}

function choose(mem, t, px, py, nC, tl, bat) {
  const cap = mem.cap, base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  if (nC > 0 && (nC >= cap || bat < 0.2 || tl < dB / 1.2 + 70)) return 'dock';
  let best = null, bs = 0;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const d = hyp(px, py, s.x, s.y), db = hyp(s.x, s.y, base.x, base.y);
    if ((d + db) / 1.0 + 50 > tl) continue;
    const sc = s.est / (d + 0.6 * db + 25);
    if (sc > bs) { bs = sc; best = s; }
  }
  if (best) {
    mem.tgt = best;
    mem.goLimit = 40 + 1.6 * hyp(px, py, best.x, best.y);
    logEv(mem, t, 'target ' + best.x.toFixed(0) + ',' + best.y.toFixed(0));
    return 'go';
  }
  let g = null, gd = 1e9;
  for (const q of mem.grid) {
    if (q.vis) continue;
    const d = hyp(px, py, q.x, q.y);
    if (d < gd) { gd = d; g = q; }
  }
  if (g && tl > dB / 1.0 + gd / 1.0 + (nC > 0 ? 200 : 60)) {
    mem.exT = g;
    return 'explore';
  }
  if (nC > 0) return 'dock';
  return 'idle';
}

function step(obs, mem) {
  const t = isNum(obs.t) ? obs.t : 0;
  if (!mem.init) initMem(obs, mem);
  const dt = mem.lastT === undefined ? 0.1 : clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;
  const wm = mem.wantMove;
  mem.wantMove = false;
  if (wm) mem.I = 0;
  const cap = mem.cap, nC = nCarried(obs);
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  const sp = (wL + wR) / 2;
  const bat = isNum(obs.battery) ? obs.battery : 1;
  const tl = isNum(obs.timeLeft) ? obs.timeLeft : (mem.seconds - t);
  const sci = isNum(obs.science) ? obs.science : 0;
  const site = obs.site || null;
  const pitch = isNum(obs.pitch) ? obs.pitch : 0;

  // ---- localisation: GPS when it changes, otherwise dead reckoning
  if (obs.x !== mem.gx || obs.y !== mem.gy) {
    mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  } else {
    mem.px += sp * Math.cos(mem.hEst * D2R) * dt;
    mem.py += sp * Math.sin(mem.hEst * D2R) * dt;
  }
  const px = mem.px, py = mem.py;

  // ---- heading: wheel-speed gyro fused with compass + learned offset
  const comp = wrap((isNum(obs.heading) ? obs.heading : mem.hEst) + mem.off);
  mem.hEst = wrap(mem.hEst + ((wR - wL) / TRACK) * dt / D2R + 0.03 * wrap(comp - mem.hEst));
  const H = mem.hEst;

  // compass offset learning on straight GPS runs
  const hist = mem.hist;
  if (!hist.length || t - hist[hist.length - 1].t >= 1.0) {
    hist.push({ t: t, x: px, y: py, s: Math.abs(wL - wR) < 0.15 && sp > 0.5 });
    if (hist.length > 4) hist.shift();
  }
  if (hist.length >= 4 && hist.every(e => e.s)) {
    const a = hist[0], b = hist[hist.length - 1];
    if (hyp(a.x, a.y, b.x, b.y) > 2.5 && isNum(obs.heading)) {
      const gh = brg(a.x, a.y, b.x, b.y);
      const diff = wrap(gh - obs.heading);
      mem.off = wrap(mem.off + 0.2 * wrap(diff - mem.off));
      mem.hist = [b];
    }
  }

  // ---- range sensing
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  let Lc = 15, Rc = 15, Fc = 15, Fw = 15;
  for (let i = 0; i < 9; i++) {
    const v = rays[i];
    const d = clamp((isNum(v) ? v : 15), 0, 15);
    const a = ANG[i];
    if (a > 0) Lc = Math.min(Lc, d);
    if (a < 0) Rc = Math.min(Rc, d);
    if (Math.abs(a) <= 20) Fc = Math.min(Fc, d);
    if (Math.abs(a) <= 40) Fw = Math.min(Fw, d);
  }
  const R = { Lc: Lc, Rc: Rc, Fc: Fc, Fw: Fw };

  // ---- stuck / bump handling
  if (wm && Math.abs(mem.lastCmd.l) + Math.abs(mem.lastCmd.r) > 0.3 && Math.abs(wL) + Math.abs(wR) < 0.2) {
    mem.slowT += dt;
  } else {
    mem.slowT = 0;
  }
  if (t >= mem.uUntil && (obs.bumped || mem.slowT > 2.5)) triggerUnstick(mem, t, Lc, Rc);
  if (t < mem.uUntil) return { l: mem.uL, r: mem.uR, drill: false };

  const base = mem.base;
  const bc = obs.beacon;
  const bD = (bc && isNum(bc.distance)) ? bc.distance : hyp(px, py, base.x, base.y);
  const bB = (bc && isNum(bc.bearing)) ? bc.bearing : wrap(brg(px, py, base.x, base.y) - H);

  let mode = mem.mode;

  // ---- drilling in progress
  if (mode === 'drill') {
    const dr = isNum(obs.drilling) ? obs.drilling : 0;
    if (dr >= 6.0) {
      finishSample(mem, px, py, t);
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (!site || site.distance > 1.7) {
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (t - mem.modeT > 30) {
      logEv(mem, t, 'drill timeout');
      mem.ignoreUntil = t + 15;
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    return holdStill(obs, mem, sp, pitch, dt, true);
  }

  // ---- opportunistic site approach
  const sitePossible = site && nC < cap && t >= mem.ignoreUntil && mode !== 'dock';
  if (sitePossible) {
    if (site.distance <= 1.4) {
      setMode(mem, 'drill', t);
      return holdStill(obs, mem, sp, pitch, dt, true);
    }
    if (mode !== 'approach') setMode(mem, 'approach', t);
    const f = clamp((site.distance - 0.6) * 0.5, 0.12, 0.45);
    mem.wantMove = true;
    return drive(isNum(site.bearing) ? site.bearing : 0, f, R);
  }
  if (mode === 'approach') { setMode(mem, 'choose', t); mode = 'choose'; }

  if (mode === 'choose') {
    mode = choose(mem, t, px, py, nC, tl, bat);
    setMode(mem, mode, t);
  }

  // ---- dock: deliver samples at base
  if (mode === 'dock') {
    if (nC === 0) {
      mem.delivered++;
      logEv(mem, t, 'delivered');
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (bD > 1.6) {
      if (t - mem.modeT > 240) { setMode(mem, 'choose', t); return holdStill(obs, mem, sp, pitch, dt, false); }
      const f = clamp((bD - 1.0) * 0.4, 0.2, 0.7);
      mem.wantMove = true;
      return drive(bB, f, R);
    }
    if (t - mem.modeT > 40) {
      logEv(mem, t, 'dock wait long');
      setMode(mem, 'choose', t);
    }
    return holdStill(obs, mem, sp, pitch, dt, false);
  }

  // ---- go to a hinted site
  if (mode === 'go') {
    const tg = mem.tgt;
    if (!tg || tg.status !== 'open') { setMode(mem, 'choose', t); return holdStill(obs, mem, sp, pitch, dt, false); }
    const d = hyp(px, py, tg.x, tg.y);
    if (d < 4) {
      mem.spiral = newSpiral(tg.x, tg.y, 16, t, tg);
      setMode(mem, 'search', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (t - mem.modeT > mem.goLimit) {
      tg.status = 'fail';
      logEv(mem, t, 'go timeout');
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    const e = wrap(brg(px, py, tg.x, tg.y) - H);
    const f = clamp(0.3 + d * 0.05, 0.3, MAXF);
    mem.wantMove = true;
    return drive(e, f, R);
  }

  // ---- spiral search around a point
  if (mode === 'search') {
    const S = mem.spiral;
    if (!S) { setMode(mem, 'choose', t); return holdStill(obs, mem, sp, pitch, dt, false); }
    let r = S.a * S.th;
    let wx = S.cx + r * Math.cos(S.th), wy = S.cy + r * Math.sin(S.th);
    let dw = hyp(px, py, wx, wy);
    if (dw < 2.0 || t - S.wpT > 10) {
      S.th += 2.5 / Math.max(r, 2.5);
      S.wpT = t;
      r = S.a * S.th;
      if (r > S.rMax) {
        if (S.tgt && S.tgt.status === 'open') {
          S.tgt.status = 'fail';
          logEv(mem, t, 'search failed');
        }
        mem.spiral = null;
        setMode(mem, 'choose', t);
        return holdStill(obs, mem, sp, pitch, dt, false);
      }
      wx = S.cx + r * Math.cos(S.th); wy = S.cy + r * Math.sin(S.th);
      dw = hyp(px, py, wx, wy);
    }
    const e = wrap(brg(px, py, wx, wy) - H);
    const f = clamp(dw * 0.3, 0.25, 0.5);
    mem.wantMove = true;
    return drive(e, f, R);
  }

  // ---- explore unvisited grid points
  if (mode === 'explore') {
    const g = mem.exT;
    if (!g) { setMode(mem, 'choose', t); return holdStill(obs, mem, sp, pitch, dt, false); }
    const d = hyp(px, py, g.x, g.y);
    if (d < 10 || t - mem.modeT > 90) {
      g.vis = true;
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (sci > 2.0 && t - mem.sciT > 40 && nC < cap) {
      mem.sciT = t;
      mem.spiral = newSpiral(px, py, 12, t, null);
      setMode(mem, 'search', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    const e = wrap(brg(px, py, g.x, g.y) - H);
    mem.wantMove = true;
    return drive(e, MAXF, R);
  }

  // ---- idle: wait and re-plan
  if (t - mem.modeT > 5) setMode(mem, 'choose', t);
  return holdStill(obs, mem, sp, pitch, dt, false);
}

function act(obs, mem) {
  let o = { l: 0, r: 0, drill: false };
  try {
    if (!mem.init) initMem(obs, mem);
    balanceLearn(obs, mem);
    o = step(obs, mem) || o;
  } catch (e) {
    mem.errs = (mem.errs || 0) + 1;
    o = { l: 0, r: 0, drill: false };
  }
  let l = clamp(+o.l || 0, -1, 1), r = clamp(+o.r || 0, -1, 1);
  if (mem.bal) {
    const s = Math.sqrt(mem.bal);
    l = clamp(l / s, -1, 1);
    r = clamp(r * s, -1, 1);
  }
  mem.lastCmd = { l: l, r: r };
  return { left: l, right: r, drill: !!o.drill };
}

const D2R = Math.PI / 180;
const TRACK = 0.6;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function isNum(v) { return typeof v === 'number' && isFinite(v); }
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) / D2R; }
function nCarried(obs) {
  const c = obs.carried;
  if (Array.isArray(c)) return c.length;
  return isNum(c) ? c : 0;
}
function logEv(mem, t, msg) {
  if (!mem.log) mem.log = [];
  if (mem.log.length < 150) mem.log.push([Math.round(t), msg]);
}
function setMode(mem, name, t) { mem.mode = name; mem.modeT = t; }

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  const t = isNum(obs.t) ? obs.t : 0;
  mem.base = (m.base && isNum(m.base.x) && isNum(m.base.y)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = (isNum(m.capacity) && m.capacity > 0) ? m.capacity : 5;
  mem.seconds = (isNum(m.seconds) && m.seconds > 0) ? m.seconds : 1200;
  mem.sites = [];
  const hints = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hints) {
    if (h && isNum(h.x) && isNum(h.y)) {
      mem.sites.push({ x: h.x, y: h.y, est: isNum(h.estimate) ? Math.max(0.1, h.estimate) : 1, status: 'open', fails: 0 });
    }
  }
  mem.grid = [];
  for (let gx = 30; gx <= 370; gx += 55) {
    for (let gy = 30; gy <= 370; gy += 55) mem.grid.push({ x: gx, y: gy, vis: false });
  }
  mem.px = isNum(obs.x) ? obs.x : 0; mem.py = isNum(obs.y) ? obs.y : 0;
  mem.gx = obs.x; mem.gy = obs.y;
  mem.hEst = isNum(obs.heading) ? obs.heading : 0;
  mem.off = 0; mem.bal = 1; mem.I = 0; mem.hist = [];
  mem.lastCmd = { l: 0, r: 0 };
  mem.escUntil = -1; mem.escL = 0; mem.escR = 0; mem.escHist = [];
  mem.stkX = mem.px; mem.stkY = mem.py; mem.stkT = t;
  mem.wantMove = false; mem.wallOff = -1;
  mem.tgt = null; mem.spiral = null; mem.exT = null; mem.goLimit = 100;
  mem.ignoreUntil = -1; mem.samples = 0; mem.delivered = 0;
  mem.sciT = -99; mem.sciZeroT = t; mem.log = [];
  setMode(mem, 'choose', t);
}

// learn relative motor gain from straight driving
function balanceLearn(obs, mem) {
  const c = mem.lastCmd;
  if (!c || !mem.bal) return;
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  if (Math.abs(c.l) > 0.3 && Math.abs(c.r) > 0.3 && Math.sign(c.l) === Math.sign(c.r) &&
      Math.abs(c.l - c.r) < 0.08 && Math.abs(wL) > 0.15 && Math.abs(wR) > 0.15 &&
      Math.sign(wL) === Math.sign(wR)) {
    const ratio = (wL / c.l) / (wR / c.r);
    if (isFinite(ratio)) mem.bal = clamp(mem.bal + 0.03 * (ratio - mem.bal), 0.6, 1.6);
  }
}

function rayInfo(obs, mem, t) {
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  let Lw = 15, Rw = 15, Fc = 15, Fs = 15;
  for (let i = 0; i < 9; i++) {
    const v = rays[i];
    const d = clamp(isNum(v) ? v : 15, 0, 15);
    const a = ANG[i];
    if (a > 0) Lw = Math.min(Lw, d);
    if (a < 0) Rw = Math.min(Rw, d);
    if (Math.abs(a) <= 20) Fc = Math.min(Fc, d);
    if (Math.abs(a) <= 40) Fs = Math.min(Fs, d);
  }
  if (t < mem.wallOff) Fs = Math.max(Fs, 1.5);
  return { Lw: Lw, Rw: Rw, Fc: Fc, Fs: Fs };
}

function triggerEsc(mem, t, R, dur, why) {
  const dir = R.Lw >= R.Rw ? 1 : -1;
  mem.escL = -0.5 - 0.2 * dir;
  mem.escR = -0.5 + 0.2 * dir;
  mem.escUntil = t + dur;
  mem.stkT = t; mem.stkX = mem.px; mem.stkY = mem.py;
  mem.escHist.push(t);
  mem.escHist = mem.escHist.filter(x => t - x < 90);
  logEv(mem, t, 'esc ' + why + ' in ' + mem.mode);
  if (mem.escHist.length >= 8 && t >= mem.wallOff) {
    mem.wallOff = t + 60;
    mem.escHist = [];
    logEv(mem, t, 'wall escapes suppressed');
  }
  if (mem.tgt && (mem.mode === 'go' || mem.mode === 'search')) {
    mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    if (mem.tgt.fails >= 3) {
      mem.tgt.status = 'fail';
      mem.spiral = null;
      setMode(mem, 'choose', t);
    }
  }
}

// still-hold: cancels motion, slope feedforward from pitch plus slow integrator on rolling
function holdStill(obs, mem, sp, pitch, dt, drill) {
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  mem.I = clamp(mem.I - 0.5 * sp * dt, -0.5, 0.5);
  const ff = clamp(0.015 * pitch, -0.3, 0.3);
  const ul = clamp(mem.I + ff - 0.3 * wL, -0.5, 0.5);
  const ur = clamp(mem.I + ff - 0.3 * wR, -0.5, 0.5);
  return { l: ul, r: ur, drill: !!drill };
}

// e: bearing error in degrees (positive = target to the left), f: forward fraction
function drive(e, f, R) {
  const wl = clamp((2.5 - R.Lw) / 2.0, 0, 1);
  const wr = clamp((2.5 - R.Rw) / 2.0, 0, 1);
  const wf = clamp((3.5 - R.Fc) / 2.5, 0, 1);
  const av = 0.7 * (wr - wl) + 0.5 * wf * (R.Lw >= R.Rw ? 1 : -1);
  const vf = clamp((R.Fs - 1.2) / 4.0, 0, 1);
  const c = Math.cos(e * D2R);
  let fw = clamp(f, 0, 0.6) * vf * Math.max(0, c);
  if (Math.abs(e) > 60) fw = 0;
  let tu = clamp(0.015 * e + av, -0.8, 0.8);
  if (fw < 0.05) tu = clamp(tu, -0.6, 0.6);
  return { l: clamp(fw - tu, -1, 1), r: clamp(fw + tu, -1, 1), drill: false };
}

function finishSample(mem, px, py, t) {
  mem.samples = (mem.samples || 0) + 1;
  let best = null, bd = 12;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const d = hyp(s.x, s.y, px, py);
    if (d < bd) { bd = d; best = s; }
  }
  if (best) best.status = 'done';
  const tg = mem.tgt;
  if (tg && tg.status === 'open' && hyp(tg.x, tg.y, px, py) < 25) tg.status = 'done';
  mem.ignoreUntil = t + 3;
  logEv(mem, t, 'drilled');
}

function choose(mem, t, px, py, nC, tl, bat) {
  const cap = mem.cap, base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  if (nC > 0 && (nC >= cap || bat < 0.25 || tl < dB / 0.8 + 90)) return 'dock';
  let best = null, bs = 0, bd = 0;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const d = hyp(px, py, s.x, s.y), db = hyp(s.x, s.y, base.x, base.y);
    if ((d + db) / 0.8 + 90 > tl) continue;
    const sc = s.est / (d + 0.6 * db + 25);
    if (sc > bs) { bs = sc; best = s; bd = d; }
  }
  if (best) {
    mem.tgt = best;
    mem.goLimit = 30 + 2.5 * bd;
    logEv(mem, t, 'target ' + best.x.toFixed(0) + ',' + best.y.toFixed(0));
    return 'go';
  }
  let g = null, gd = 1e9;
  for (const q of mem.grid) {
    if (q.vis) continue;
    const d = hyp(px, py, q.x, q.y);
    if (d < gd) { gd = d; g = q; }
  }
  if (g && tl > (dB + gd) / 0.8 + (nC > 0 ? 150 : 80)) {
    mem.exT = g;
    return 'explore';
  }
  if (nC > 0) return 'dock';
  return 'idle';
}

function step(obs, mem) {
  const t = isNum(obs.t) ? obs.t : 0;
  if (!mem.init) initMem(obs, mem);
  const dt = mem.lastT === undefined ? 0.1 : clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;
  const wasMove = mem.wantMove;
  mem.wantMove = false;
  const cap = mem.cap, nC = nCarried(obs);
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  const sp = (wL + wR) / 2;
  const bat = isNum(obs.battery) ? obs.battery : 1;
  const tl = isNum(obs.timeLeft) ? obs.timeLeft : (mem.seconds - t);
  const sci = isNum(obs.science) ? obs.science : 0;
  const site = obs.site || null;
  const pitch = isNum(obs.pitch) ? obs.pitch : 0;

  // ---- localisation: GPS when it changes, otherwise dead reckoning
  if (isNum(obs.x) && isNum(obs.y) && (obs.x !== mem.gx || obs.y !== mem.gy)) {
    mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  } else {
    mem.px += sp * Math.cos(mem.hEst * D2R) * dt;
    mem.py += sp * Math.sin(mem.hEst * D2R) * dt;
  }
  const px = mem.px, py = mem.py;

  // ---- heading: wheel-speed gyro fused with compass + learned offset
  const comp = wrap((isNum(obs.heading) ? obs.heading : mem.hEst) + mem.off);
  mem.hEst = wrap(mem.hEst + ((wR - wL) / TRACK) * dt / D2R + 0.03 * wrap(comp - mem.hEst));
  const H = mem.hEst;

  // compass offset learning on straight GPS runs
  const hist = mem.hist;
  if (!hist.length || t - hist[hist.length - 1].t >= 1.0) {
    hist.push({ t: t, x: px, y: py, s: Math.abs(wL - wR) < 0.15 && sp > 0.5 });
    if (hist.length > 4) hist.shift();
  }
  if (hist.length >= 4 && hist.every(e => e.s)) {
    const a = hist[0], b = hist[hist.length - 1];
    if (hyp(a.x, a.y, b.x, b.y) > 2.5 && isNum(obs.heading)) {
      const gh = brg(a.x, a.y, b.x, b.y);
      const diff = wrap(gh - obs.heading);
      mem.off = wrap(mem.off + 0.2 * wrap(diff - mem.off));
      mem.hist = [b];
    }
  }

  const R = rayInfo(obs, mem, t);

  // ---- stuck / bump / wall handling
  if (wasMove) {
    if (hyp(px, py, mem.stkX, mem.stkY) > 0.8) {
      mem.stkX = px; mem.stkY = py; mem.stkT = t;
    } else if (t - mem.stkT > 8) {
      triggerEsc(mem, t, R, 1.8, 'stuck');
    }
  } else {
    mem.stkX = px; mem.stkY = py; mem.stkT = t;
  }
  if (obs.bumped && t >= mem.escUntil) triggerEsc(mem, t, R, 1.5, 'bump');
  if (wasMove && R.Fc < 0.8 && t >= mem.escUntil && t >= mem.wallOff) triggerEsc(mem, t, R, 1.2, 'wall');
  if (t < mem.escUntil) return { l: mem.escL, r: mem.escR, drill: false };

  const base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  const bc = obs.beacon;
  let mode = mem.mode;

  // ---- drilling in progress
  if (mode === 'drill') {
    const dr = isNum(obs.drilling) ? obs.drilling : 0;
    if (dr >= 6.0) {
      finishSample(mem, px, py, t);
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (!site || !isNum(site.distance) || site.distance > 2.2) {
      logEv(mem, t, 'drill lost site');
      mem.ignoreUntil = t + 4;
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (t - mem.modeT > 35) {
      logEv(mem, t, 'drill timeout');
      mem.ignoreUntil = t + 20;
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    return holdStill(obs, mem, sp, pitch, dt, true);
  }

  // ---- opportunistic site approach (any unsampled site within 8 m)
  if (site && nC < cap && t >= mem.ignoreUntil && mode !== 'dock') {
    const d = isNum(site.distance) ? site.distance : 5;
    if (d <= 1.4) {
      setMode(mem, 'drill', t);
      return holdStill(obs, mem, sp, pitch, dt, true);
    }
    if (mode !== 'approach') setMode(mem, 'approach', t);
    mem.wantMove = true;
    return drive(isNum(site.bearing) ? site.bearing : 0, clamp((d - 0.6) * 0.5, 0.15, 0.4), R);
  }
  if (mode === 'approach') {
    mode = (mem.tgt && mem.tgt.status === 'open') ? 'go' : 'choose';
    setMode(mem, mode, t);
  }

  if (mode === 'choose') {
    mode = choose(mem, t, px, py, nC, tl, bat);
    setMode(mem, mode, t);
  }

  // ---- dock: deliver samples at base
  if (mode === 'dock') {
    if (nC === 0) {
      mem.delivered++;
      logEv(mem, t, 'delivered');
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    let d, e;
    if (bc && isNum(bc.distance)) {
      d = bc.distance; e = isNum(bc.bearing) ? bc.bearing : 0;
    } else {
      d = dB; e = wrap(brg(px, py, base.x, base.y) - H);
    }
    if (d > 1.6) {
      if (t - mem.modeT > 200) {
        logEv(mem, t, 'dock timeout');
        setMode(mem, 'choose', t);
        return holdStill(obs, mem, sp, pitch, dt, false);
      }
      const f = clamp((d - 1.0) * 0.3, 0.2, 0.5);
      mem.wantMove = true;
      return drive(e, f, R);
    }
    if (t - mem.modeT > 60) {
      logEv(mem, t, 'dock wait long');
      setMode(mem, 'choose', t);
    }
    return holdStill(obs, mem, sp, pitch, dt, false);
  }

  // ---- go to a hinted site
  if (mode === 'go') {
    const tg = mem.tgt;
    if (!tg || tg.status !== 'open') {
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    const d = hyp(px, py, tg.x, tg.y);
    if (d < 4) {
      if (sci < 0.03) {
        tg.status = 'fail';
        logEv(mem, t, 'hint empty');
        setMode(mem, 'choose', t);
      } else {
        mem.spiral = { cx: tg.x, cy: tg.y, a: 2.0, th: 0, wpT: t, rMax: 12, tgt: tg };
        mem.sciZeroT = t;
        setMode(mem, 'search', t);
      }
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (t - mem.modeT > mem.goLimit) {
      tg.status = 'fail';
      logEv(mem, t, 'go timeout');
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    const e = wrap(brg(px, py, tg.x, tg.y) - H);
    const f = d > 6 ? 0.5 : clamp(0.2 + d * 0.05, 0.2, 0.5);
    mem.wantMove = true;
    return drive(e, f, R);
  }

  // ---- spiral search around a point
  if (mode === 'search') {
    const S = mem.spiral;
    if (!S) {
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (sci > 0.05) mem.sciZeroT = t;
    if (t - mem.sciZeroT > 12) {
      if (S.tgt && S.tgt.status === 'open') {
        S.tgt.status = 'fail';
        logEv(mem, t, 'search: no science');
      }
      mem.spiral = null;
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    let r = S.a * S.th;
    let wx = S.cx + r * Math.cos(S.th), wy = S.cy + r * Math.sin(S.th);
    let dw = hyp(px, py, wx, wy);
    if (dw < 1.8 || t - S.wpT > 10) {
      S.th += 2.5 / Math.max(r, 2.5);
      S.wpT = t;
      r = S.a * S.th;
      if (r > S.rMax) {
        if (S.tgt && S.tgt.status === 'open') {
          S.tgt.status = 'fail';
          logEv(mem, t, 'search failed');
        }
        mem.spiral = null;
        setMode(mem, 'choose', t);
        return holdStill(obs, mem, sp, pitch, dt, false);
      }
      wx = S.cx + r * Math.cos(S.th); wy = S.cy + r * Math.sin(S.th);
      dw = hyp(px, py, wx, wy);
    }
    const e = wrap(brg(px, py, wx, wy) - H);
    const f = clamp(dw * 0.3, 0.2, 0.35);
    mem.wantMove = true;
    return drive(e, f, R);
  }

  // ---- explore unvisited grid points
  if (mode === 'explore') {
    const g = mem.exT;
    if (!g) {
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    const d = hyp(px, py, g.x, g.y);
    if (d < 10 || t - mem.modeT > 120) {
      g.vis = true;
      setMode(mem, 'choose', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    if (sci > 1.5 && t - mem.sciT > 40 && nC < cap) {
      mem.sciT = t;
      mem.tgt = null;
      mem.spiral = { cx: px, cy: py, a: 2.0, th: 0, wpT: t, rMax: 10, tgt: null };
      mem.sciZeroT = t;
      setMode(mem, 'search', t);
      return holdStill(obs, mem, sp, pitch, dt, false);
    }
    const e = wrap(brg(px, py, g.x, g.y) - H);
    mem.wantMove = true;
    return drive(e, 0.5, R);
  }

  // ---- idle: wait and re-plan
  if (t - mem.modeT > 5) setMode(mem, 'choose', t);
  return holdStill(obs, mem, sp, pitch, dt, false);
}

function act(obs, mem) {
  let o = { l: 0, r: 0, drill: false };
  try {
    if (!mem.init) initMem(obs, mem);
    balanceLearn(obs, mem);
    o = step(obs, mem) || o;
  } catch (e) {
    mem.errs = (mem.errs || 0) + 1;
    o = { l: 0, r: 0, drill: false };
  }
  let l = clamp(+o.l || 0, -1, 1), r = clamp(+o.r || 0, -1, 1);
  if (mem.bal) {
    const s = Math.sqrt(mem.bal);
    l = clamp(l / s, -1, 1);
    r = clamp(r * s, -1, 1);
  }
  mem.lastCmd = { l: l, r: r };
  return { left: l, right: r, drill: !!o.drill };
}

const D2R = Math.PI / 180;
const TRACK = 0.6;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function isNum(v) { return typeof v === 'number' && isFinite(v); }
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) / D2R; }
function nCarried(obs) {
  const c = obs.carried;
  if (Array.isArray(c)) return c.length;
  return isNum(c) ? c : 0;
}
function logEv(mem, t, msg) {
  if (!mem.log) mem.log = [];
  if (mem.log.length < 150) mem.log.push([Math.round(t), msg]);
}
function setMode(mem, name, t) { mem.mode = name; mem.modeT = t; }
function newSpiral(cx, cy, rMax, t, tgt) {
  return { cx: cx, cy: cy, a: 1.6, th: 0, wpT: t, t0: t, rMax: rMax, tgt: tgt };
}

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  const t = isNum(obs.t) ? obs.t : 0;
  mem.base = (m.base && isNum(m.base.x) && isNum(m.base.y)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = (isNum(m.capacity) && m.capacity > 0) ? m.capacity : 5;
  mem.seconds = (isNum(m.seconds) && m.seconds > 0) ? m.seconds : 1200;
  mem.sites = [];
  const hints = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hints) {
    if (h && isNum(h.x) && isNum(h.y)) {
      mem.sites.push({ x: h.x, y: h.y, est: isNum(h.estimate) ? Math.max(0.1, h.estimate) : 1, status: 'open', fails: 0 });
    }
  }
  mem.grid = [];
  for (let gx = 30; gx <= 370; gx += 60) {
    for (let gy = 30; gy <= 370; gy += 60) mem.grid.push({ x: gx, y: gy, vis: false });
  }
  mem.px = isNum(obs.x) ? obs.x : 0; mem.py = isNum(obs.y) ? obs.y : 0;
  mem.gx = obs.x; mem.gy = obs.y;
  mem.hEst = isNum(obs.heading) ? obs.heading : 0;
  mem.off = 0; mem.bal = 1; mem.I = 0; mem.hist = [];
  mem.lastCmd = { l: 0, r: 0 };
  mem.mv = false;
  mem.escUntil = -1; mem.escL = 0; mem.escR = 0;
  mem.anX = mem.px; mem.anY = mem.py; mem.anT = t;
  mem.tgt = null; mem.spiral = null; mem.exT = null; mem.goLimit = 100;
  mem.ignoreUntil = -1; mem.samples = 0; mem.delivered = 0;
  mem.sciT = -99; mem.sciSeen = false;
  mem.log = [];
  setMode(mem, 'choose', t);
}

// learn relative motor gain from straight driving
function balanceLearn(obs, mem) {
  const c = mem.lastCmd;
  if (!c || !mem.bal) return;
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  if (Math.abs(c.l) > 0.3 && Math.abs(c.r) > 0.3 && Math.sign(c.l) === Math.sign(c.r) &&
      Math.abs(c.l - c.r) < 0.05 && Math.abs(wL) > 0.2 && Math.abs(wR) > 0.2 &&
      Math.sign(wL) === Math.sign(wR)) {
    const ratio = (wL / c.l) / (wR / c.r);
    if (isFinite(ratio)) mem.bal = clamp(mem.bal + 0.02 * (ratio - mem.bal), 0.7, 1.4);
  }
}

// still-hold with per-wheel damping, pitch feedforward and slow integrator
function hold(obs, mem, sp, pitch, dt, drill) {
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  mem.I = clamp(mem.I - 0.5 * sp * dt, -0.5, 0.5);
  const ff = clamp(0.015 * pitch, -0.3, 0.3);
  return {
    l: clamp(mem.I + ff - 0.3 * wL, -0.5, 0.5),
    r: clamp(mem.I + ff - 0.3 * wR, -0.5, 0.5),
    drill: !!drill, mv: false
  };
}

// choose a steering angle (deg, relative to heading, + = left) that is clear
function steerAngle(e, d, T) {
  const idx = (a) => clamp(Math.round((a + 80) / 20), 0, 8);
  if (Math.abs(e) <= 80) {
    const ok = d[idx(e - 8)] >= T && d[idx(e)] >= T && d[idx(e + 8)] >= T;
    if (ok) return e;
  }
  let best = null, bc = 1e9;
  for (let i = 0; i < 9; i++) {
    if (d[i] >= T) {
      const c = Math.abs(ANG[i] - e);
      if (c < bc) { bc = c; best = ANG[i]; }
    }
  }
  return best;
}

function clearance(s, d) {
  let c = 15;
  for (let i = 0; i < 9; i++) {
    if (Math.abs(ANG[i] - s) <= 25) c = Math.min(c, d[i]);
  }
  return c;
}

function escCmd(d) {
  const Lm = Math.min(d[5], d[6], d[7], d[8]);
  const Rm = Math.min(d[0], d[1], d[2], d[3]);
  const s = Lm >= Rm ? 1 : -1;
  const back = d[4] < 1.0 ? -0.2 : 0;
  return { l: clamp(back - 0.3 * s, -1, 1), r: clamp(back + 0.3 * s, -1, 1), drill: false, mv: true };
}

// e: bearing error to target (deg, + = left); fmax: max forward command; d: rays; T: clear threshold
function drive(e, fmax, d, T) {
  const s = steerAngle(e, d, T);
  if (s === null) return escCmd(d);
  const C = clearance(s, d);
  const vf = clamp((C - 1.5) / 3.5, 0, 1);
  const cf = Math.max(0, Math.cos(s * D2R));
  let f = fmax * vf * cf;
  if (Math.abs(s) > 60) f = 0;
  if (f < 0.05) f = 0;
  let tu = clamp(0.0035 * s, -0.25, 0.25);
  if (Math.abs(s) > 8 && Math.abs(tu) < 0.12) tu = (s > 0 ? 0.12 : -0.12);
  return { l: clamp(f - tu, -1, 1), r: clamp(f + tu, -1, 1), drill: false, mv: true };
}

function startEsc(mem, t, d, dur, why) {
  const Lm = Math.min(d[5], d[6], d[7], d[8]);
  const Rm = Math.min(d[0], d[1], d[2], d[3]);
  const s = Lm >= Rm ? 1 : -1;
  mem.escL = -0.35 - 0.2 * s;
  mem.escR = -0.35 + 0.2 * s;
  mem.escUntil = t + dur;
  mem.anX = mem.px; mem.anY = mem.py; mem.anT = t + dur;
  logEv(mem, t, 'esc ' + why + ' in ' + mem.mode);
  if (mem.mode === 'approach') mem.ignoreUntil = t + 8;
  if (mem.tgt && mem.tgt.status === 'open' && (mem.mode === 'go' || mem.mode === 'search' || mem.mode === 'approach')) {
    mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    if (mem.tgt.fails >= 3) {
      mem.tgt.status = 'fail';
      mem.spiral = null;
      logEv(mem, t, 'target dropped after escapes');
      setMode(mem, 'choose', t);
    }
  }
}

function finishSample(mem, px, py, t) {
  mem.samples = (mem.samples || 0) + 1;
  let best = null, bd = 25;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(s.x, s.y, px, py);
    if (dd < bd) { bd = dd; best = s; }
  }
  if (best) best.status = 'done';
  mem.ignoreUntil = t + 2;
  logEv(mem, t, 'drilled');
}

function choose(mem, t, px, py, nC, tl, bat) {
  const base = mem.base, cap = mem.cap;
  const dB = hyp(px, py, base.x, base.y);
  if (nC > 0 && (nC >= 3 || nC >= cap || dB < 40 || bat < 0.2 || tl < dB / 0.5 + 60)) return 'dock';
  let best = null, bs = 0, bdist = 0;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(px, py, s.x, s.y), db = hyp(s.x, s.y, base.x, base.y);
    if ((dd + db) / 0.5 + 60 > tl) continue;
    const sc = s.est / (dd + 0.6 * db + 25);
    if (sc > bs) { bs = sc; best = s; bdist = dd; }
  }
  if (best) {
    mem.tgt = best;
    mem.goLimit = 30 + 1.8 * bdist;
    logEv(mem, t, 'target ' + best.x.toFixed(0) + ',' + best.y.toFixed(0));
    return 'go';
  }
  if (nC > 0) return 'dock';
  let g = null, gd = 1e9;
  for (const q of mem.grid) {
    if (q.vis) continue;
    const dd = hyp(px, py, q.x, q.y);
    if (dd < gd) { gd = dd; g = q; }
  }
  if (g && tl > (dB + gd) / 0.5 + 80) {
    mem.exT = g;
    return 'explore';
  }
  return 'idle';
}

function step(obs, mem) {
  const t = isNum(obs.t) ? obs.t : 0;
  if (!mem.init) initMem(obs, mem);
  const dt = mem.lastT === undefined ? 0.1 : clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;
  const cap = mem.cap, nC = nCarried(obs);
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  const sp = (wL + wR) / 2;
  const bat = isNum(obs.battery) ? obs.battery : 1;
  const tl = isNum(obs.timeLeft) ? obs.timeLeft : (mem.seconds - t);
  const sci = isNum(obs.science) ? obs.science : 0;
  if (sci > 0.05) mem.sciSeen = true;
  const site = (obs.site && isNum(obs.site.distance)) ? obs.site : null;
  const pitch = isNum(obs.pitch) ? obs.pitch : 0;
  const bc = (obs.beacon && isNum(obs.beacon.distance)) ? obs.beacon : null;

  // ---- localisation: GPS when it changes, dead reckoning otherwise
  if (isNum(obs.x) && isNum(obs.y) && (obs.x !== mem.gx || obs.y !== mem.gy)) {
    mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  } else {
    mem.px += sp * Math.cos(mem.hEst * D2R) * dt;
    mem.py += sp * Math.sin(mem.hEst * D2R) * dt;
  }
  const px = mem.px, py = mem.py;

  // ---- heading: wheel gyro fused with compass + learned offset
  const comp = wrap((isNum(obs.heading) ? obs.heading : mem.hEst) + mem.off);
  mem.hEst = wrap(mem.hEst + ((wR - wL) / TRACK) * dt / D2R + 0.03 * wrap(comp - mem.hEst));
  const H = mem.hEst;

  // compass offset learning on straight GPS runs
  const hist = mem.hist;
  if (!hist.length || t - hist[hist.length - 1].t >= 1.0) {
    hist.push({ t: t, x: px, y: py, s: Math.abs(wL - wR) < 0.15 && sp > 0.5 });
    if (hist.length > 4) hist.shift();
  }
  if (hist.length >= 4 && hist.every(e => e.s)) {
    const a = hist[0], b = hist[hist.length - 1];
    if (hyp(a.x, a.y, b.x, b.y) > 2.5 && isNum(obs.heading)) {
      const gh = brg(a.x, a.y, b.x, b.y);
      const diff = wrap(gh - obs.heading);
      mem.off = wrap(mem.off + 0.2 * wrap(diff - mem.off));
      mem.hist = [b];
    }
  }

  // ---- range rays
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const d = [];
  for (let i = 0; i < 9; i++) d.push(clamp(isNum(rays[i]) ? rays[i] : 15, 0, 15));

  // ---- stuck / bump handling
  if (mem.mv && t >= mem.escUntil) {
    if (hyp(px, py, mem.anX, mem.anY) > 0.6) {
      mem.anX = px; mem.anY = py; mem.anT = t;
    } else if (t - mem.anT > 6) {
      startEsc(mem, t, d, 2.0, 'stuck');
    }
  } else if (!mem.mv) {
    mem.anX = px; mem.anY = py; mem.anT = t;
  }
  if (obs.bumped && t >= mem.escUntil) startEsc(mem, t, d, 1.5, 'bump');
  if (t < mem.escUntil) return { l: mem.escL, r: mem.escR, drill: false, mv: true };

  const base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  const bD = bc ? bc.distance : dB;
  const bB = (bc && isNum(bc.bearing)) ? bc.bearing : wrap(brg(px, py, base.x, base.y) - H);

  let mode = mem.mode;

  // ---- drilling in progress
  if (mode === 'drill') {
    const dr = isNum(obs.drilling) ? obs.drilling : 0;
    if (dr >= 6.0) {
      finishSample(mem, px, py, t);
      setMode(mem, 'choose', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    if (!site || site.distance > 2.2) {
      logEv(mem, t, 'drill lost site');
      mem.ignoreUntil = t + 2;
      setMode(mem, 'choose', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    if (t - mem.modeT > 25) {
      logEv(mem, t, 'drill timeout');
      mem.ignoreUntil = t + 15;
      setMode(mem, 'choose', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    return hold(obs, mem, sp, pitch, dt, true);
  }

  // ---- any unsampled site within 8 m: approach and drill
  const siteOK = !!site && nC < cap && t >= mem.ignoreUntil && mode !== 'dock';
  if (siteOK) {
    if (site.distance <= 1.3) {
      setMode(mem, 'drill', t);
      return hold(obs, mem, sp, pitch, dt, true);
    }
    if (mode !== 'approach') setMode(mem, 'approach', t);
    if (t - mem.modeT > 40) {
      logEv(mem, t, 'approach timeout');
      mem.ignoreUntil = t + 20;
      setMode(mem, 'choose', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    const f = clamp((site.distance - 0.6) * 0.5, 0.12, 0.4);
    const T = site.distance < 3 ? 1.2 : 2.0;
    return drive(isNum(site.bearing) ? site.bearing : 0, f, d, T);
  }
  if (mode === 'approach') { setMode(mem, 'choose', t); mode = 'choose'; }

  if (mode === 'choose') {
    mode = choose(mem, t, px, py, nC, tl, bat);
    setMode(mem, mode, t);
  }

  // ---- deliver at base
  if (mode === 'dock') {
    if (nC === 0) {
      mem.delivered++;
      logEv(mem, t, 'delivered');
      setMode(mem, 'choose', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    if (bD > 1.6) {
      if (t - mem.modeT > 240) {
        logEv(mem, t, 'dock timeout');
        setMode(mem, 'choose', t);
        return hold(obs, mem, sp, pitch, dt, false);
      }
      const f = clamp((bD - 1.0) * 0.4, 0.2, 0.5);
      return drive(bB, f, d, bD < 6 ? 1.2 : 2.0);
    }
    return hold(obs, mem, sp, pitch, dt, false);
  }

  // ---- go to a hinted site
  if (mode === 'go') {
    const tg = mem.tgt;
    if (!tg || tg.status !== 'open') {
      setMode(mem, 'choose', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    const dd = hyp(px, py, tg.x, tg.y);
    if (dd < 6) {
      if (mem.sciSeen && sci < 0.02) {
        tg.status = 'fail';
        logEv(mem, t, 'hint empty (no science)');
        setMode(mem, 'choose', t);
        return hold(obs, mem, sp, pitch, dt, false);
      }
      mem.spiral = newSpiral(tg.x, tg.y, 13, t, tg);
      setMode(mem, 'search', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    if (t - mem.modeT > mem.goLimit) {
      tg.status = 'fail';
      logEv(mem, t, 'go timeout');
      setMode(mem, 'choose', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    const e = wrap(brg(px, py, tg.x, tg.y) - H);
    const f = clamp(0.25 + dd * 0.02, 0.25, 0.4);
    return drive(e, f, d, 2.0);
  }

  // ---- spiral search around a point (hint or current spot)
  if (mode === 'search') {
    const S = mem.spiral;
    if (!S || t - S.t0 > 150) {
      if (S && S.tgt && S.tgt.status === 'open') { S.tgt.status = 'fail'; logEv(mem, t, 'search time out'); }
      mem.spiral = null;
      setMode(mem, 'choose', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    let r = S.a * S.th;
    let wx = S.cx + r * Math.cos(S.th), wy = S.cy + r * Math.sin(S.th);
    let dw = hyp(px, py, wx, wy);
    if (dw < 2.0 || t - S.wpT > 12) {
      S.th += clamp(2.5 / Math.max(r, 2.5), 0.12, 0.8);
      S.wpT = t;
      r = S.a * S.th;
      if (r > S.rMax) {
        if (S.tgt && S.tgt.status === 'open') {
          S.tgt.status = 'fail';
          logEv(mem, t, 'search failed');
        }
        mem.spiral = null;
        setMode(mem, 'choose', t);
        return hold(obs, mem, sp, pitch, dt, false);
      }
      wx = S.cx + r * Math.cos(S.th); wy = S.cy + r * Math.sin(S.th);
      dw = hyp(px, py, wx, wy);
    }
    const e = wrap(brg(px, py, wx, wy) - H);
    return drive(e, clamp(dw * 0.25, 0.2, 0.4), d, 2.0);
  }

  // ---- explore unvisited grid points (fallback for unhinted sites)
  if (mode === 'explore') {
    const g = mem.exT;
    if (!g || hyp(px, py, g.x, g.y) < 10 || t - mem.modeT > 120) {
      if (g) g.vis = true;
      setMode(mem, 'choose', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    if (sci > 1.0 && t - mem.sciT > 60 && nC < cap) {
      mem.sciT = t;
      mem.spiral = newSpiral(px, py, 12, t, null);
      setMode(mem, 'search', t);
      return hold(obs, mem, sp, pitch, dt, false);
    }
    const e = wrap(brg(px, py, g.x, g.y) - H);
    return drive(e, 0.35, d, 2.0);
  }

  // ---- idle: wait and re-plan
  if (t - mem.modeT > 5) setMode(mem, 'choose', t);
  return hold(obs, mem, sp, pitch, dt, false);
}

function act(obs, mem) {
  let o = { l: 0, r: 0, drill: false, mv: false };
  try {
    if (!mem.init) initMem(obs, mem);
    balanceLearn(obs, mem);
    o = step(obs, mem) || o;
  } catch (e) {
    mem.errs = (mem.errs || 0) + 1;
    o = { l: 0, r: 0, drill: false, mv: false };
  }
  let l = clamp(+o.l || 0, -1, 1), r = clamp(+o.r || 0, -1, 1);
  if (mem.bal) {
    const s = Math.sqrt(mem.bal);
    l = clamp(l / s, -1, 1);
    r = clamp(r * s, -1, 1);
  }
  mem.lastCmd = { l: l, r: r };
  mem.mv = !!o.mv;
  return { left: l, right: r, drill: !!o.drill };
}

const D2R = Math.PI / 180;
const TRACK = 0.6;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function isNum(v) { return typeof v === 'number' && isFinite(v); }
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) / D2R; }
function nCarried(obs) {
  const c = obs.carried;
  if (Array.isArray(c)) return c.length;
  return isNum(c) ? c : 0;
}
function logEv(mem, t, msg) {
  if (!mem.log) mem.log = [];
  if (mem.log.length < 150) mem.log.push([Math.round(t), msg]);
}
function setMode(mem, name, t) { mem.mode = name; mem.modeT = t; }
function newSpiral(cx, cy, rMax, t, tgt) {
  return { cx: cx, cy: cy, a: 1.5, th: 0, wpT: t, t0: t, rMax: rMax, tgt: tgt };
}

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  const t = isNum(obs.t) ? obs.t : 0;
  mem.base = (m.base && isNum(m.base.x) && isNum(m.base.y)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = (isNum(m.capacity) && m.capacity > 0) ? m.capacity : 5;
  mem.seconds = (isNum(m.seconds) && m.seconds > 0) ? m.seconds : 1200;
  mem.sites = [];
  const hints = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hints) {
    if (h && isNum(h.x) && isNum(h.y)) {
      mem.sites.push({ x: h.x, y: h.y, est: isNum(h.estimate) ? Math.max(0.1, h.estimate) : 1, status: 'open', fails: 0 });
    }
  }
  mem.grid = [];
  for (let gx = 30; gx <= 370; gx += 60) {
    for (let gy = 30; gy <= 370; gy += 60) mem.grid.push({ x: gx, y: gy, vis: false });
  }
  mem.px = isNum(obs.x) ? obs.x : 0; mem.py = isNum(obs.y) ? obs.y : 0;
  mem.gx = obs.x; mem.gy = obs.y;
  mem.hEst = isNum(obs.heading) ? obs.heading : 0;
  mem.off = 0; mem.bal = 1; mem.IL = 0; mem.IR = 0; mem.hist = [];
  mem.lastCmd = { l: 0, r: 0 };
  mem.mv = false;
  mem.esc = null; mem.escHist = [];
  mem.stallT = null; mem.ancX = mem.px; mem.ancY = mem.py; mem.ancT = t;
  mem.ignoreBumpUntil = -1;
  mem.tgt = null; mem.spiral = null; mem.exT = null; mem.goLimit = 100;
  mem.ignoreUntil = -1; mem.samples = 0; mem.delivered = 0;
  mem.sciT = -99; mem.sciSeen = false;
  mem.log = [];
  setMode(mem, 'choose', t);
}

// learn relative motor gain from straight driving
function balanceLearn(obs, mem) {
  const c = mem.lastCmd;
  if (!c || !mem.bal) return;
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  if (Math.abs(c.l) > 0.3 && Math.abs(c.r) > 0.3 && Math.sign(c.l) === Math.sign(c.r) &&
      Math.abs(c.l - c.r) < 0.05 && Math.abs(wL) > 0.2 && Math.abs(wR) > 0.2 &&
      Math.sign(wL) === Math.sign(wR)) {
    const ratio = (wL / c.l) / (wR / c.r);
    if (isFinite(ratio)) mem.bal = clamp(mem.bal + 0.02 * (ratio - mem.bal), 0.7, 1.4);
  }
}

// still-hold: wheel-speed integrator plus pitch feedforward
function hold(obs, mem, pitch, dt, drill) {
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  mem.IL = clamp((mem.IL || 0) - 0.8 * wL * dt, -0.35, 0.35);
  mem.IR = clamp((mem.IR || 0) - 0.8 * wR * dt, -0.35, 0.35);
  const ff = clamp(0.02 * pitch, -0.35, 0.35);
  return { l: clamp(ff + mem.IL, -0.4, 0.4), r: clamp(ff + mem.IR, -0.4, 0.4), drill: !!drill, mv: false };
}

// choose steering angle (deg, relative to heading, + = left) that is clear
function steerAngle(e, d, T) {
  const idx = (a) => clamp(Math.round((a + 80) / 20), 0, 8);
  if (Math.abs(e) <= 80) {
    const ok = d[idx(e - 8)] >= T && d[idx(e)] >= T && d[idx(e + 8)] >= T;
    if (ok) return e;
  }
  let best = null, bc = 1e9;
  for (let i = 0; i < 9; i++) {
    if (d[i] >= T) {
      const c = Math.abs(ANG[i] - e);
      if (c < bc) { bc = c; best = ANG[i]; }
    }
  }
  return best;
}

function clearance(s, d) {
  let c = 15;
  for (let i = 0; i < 9; i++) {
    if (Math.abs(ANG[i] - s) <= 25) c = Math.min(c, d[i]);
  }
  return c;
}

// e: bearing error (deg, + = target left); fmax: max forward command; d: rays; T: clear threshold
function drive(e, fmax, d, T) {
  const s = steerAngle(e, d, T);
  if (s === null) {
    const Lm = Math.min(d[5], d[6], d[7], d[8]);
    const Rm = Math.min(d[0], d[1], d[2], d[3]);
    const k = Lm >= Rm ? 1 : -1;
    return { l: -0.4 * k, r: 0.4 * k, drill: false, mv: true };
  }
  const C = clearance(s, d);
  const vf = clamp((C - 1.5) / 3.5, 0, 1);
  const cf = Math.max(0, Math.cos(s * D2R));
  let f = fmax * vf * cf;
  if (Math.abs(s) > 60) f = 0;
  if (f < 0.2) f = 0; else if (f < 0.25) f = 0.25;
  const mn = f > 0 ? 0.15 : 0.25;
  let tu = clamp(0.012 * s, -0.45, 0.45);
  if (Math.abs(s) > 8 && Math.abs(tu) < mn) tu = s > 0 ? mn : -mn;
  return { l: clamp(f - tu, -1, 1), r: clamp(f + tu, -1, 1), drill: false, mv: true };
}

function startEsc(mem, t, d, why) {
  const Lm = Math.min(d[5], d[6], d[7], d[8]);
  const Rm = Math.min(d[0], d[1], d[2], d[3]);
  let dir = Lm >= Rm ? 1 : -1;
  mem.escHist = mem.escHist.filter(x => t - x < 60);
  mem.escHist.push(t);
  if (mem.escHist.length % 2 === 0) dir = -dir;
  mem.esc = { ph: 0, until: t + 1.2, dir: dir };
  mem.stallT = null;
  logEv(mem, t, 'esc ' + why + ' in ' + mem.mode);
  if (mem.tgt && mem.tgt.status === 'open' && (mem.mode === 'go' || mem.mode === 'search' || mem.mode === 'approach')) {
    mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    if (mem.tgt.fails >= 2) {
      mem.tgt.status = 'fail';
      mem.spiral = null;
      logEv(mem, t, 'target dropped after escapes');
      setMode(mem, 'choose', t);
    }
  }
  if (mem.escHist.length >= 5) {
    mem.escHist = [];
    if (mem.tgt && mem.tgt.status === 'open') mem.tgt.status = 'fail';
    mem.spiral = null;
    logEv(mem, t, 'too many escapes, replanning');
    setMode(mem, 'choose', t);
  }
}

function runEsc(mem, t) {
  const E = mem.esc;
  if (E.ph === 0) {
    if (t < E.until) return { l: -0.45, r: -0.45, drill: false, mv: false };
    E.ph = 1; E.until = t + 1.0;
  }
  if (t < E.until) return { l: -0.45 * E.dir, r: 0.45 * E.dir, drill: false, mv: false };
  mem.esc = null;
  mem.ignoreBumpUntil = t + 1.5;
  mem.ancX = mem.px; mem.ancY = mem.py; mem.ancT = t;
  return null;
}

function finishSample(mem, px, py, t) {
  mem.samples = (mem.samples || 0) + 1;
  let best = null, bd = 20;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(s.x, s.y, px, py);
    if (dd < bd) { bd = dd; best = s; }
  }
  if (best) best.status = 'done';
  if (mem.tgt && mem.tgt.status === 'open' && hyp(mem.tgt.x, mem.tgt.y, px, py) < 20) mem.tgt.status = 'done';
  mem.ignoreUntil = t + 2;
  logEv(mem, t, 'drilled');
}

function choose(mem, t, px, py, nC, tl, bat) {
  const base = mem.base, cap = mem.cap;
  const dB = hyp(px, py, base.x, base.y);
  let best = null, bs = 0, bdist = 0;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(px, py, s.x, s.y), db = hyp(s.x, s.y, base.x, base.y);
    if ((dd + db) / 0.4 + 60 > tl) continue;
    const sc = s.est / (dd + 0.6 * db + 25);
    if (sc > bs) { bs = sc; best = s; bdist = dd; }
  }
  if (nC > 0 && (nC >= cap || bat < 0.2 || tl < dB / 0.4 + 60 || !best || (nC >= 2 && dB < 50))) return 'dock';
  if (best) {
    mem.tgt = best;
    mem.goLimit = 40 + 3 * bdist;
    logEv(mem, t, 'target ' + best.x.toFixed(0) + ',' + best.y.toFixed(0));
    return 'go';
  }
  let g = null, gd = 1e9;
  for (const q of mem.grid) {
    if (q.vis) continue;
    const dd = hyp(px, py, q.x, q.y);
    if (dd < gd) { gd = dd; g = q; }
  }
  if (g && tl > (dB + gd) / 0.4 + 80) {
    mem.exT = g;
    return 'explore';
  }
  return 'idle';
}

function step(obs, mem) {
  const t = isNum(obs.t) ? obs.t : 0;
  if (!mem.init) initMem(obs, mem);
  const dt = mem.lastT === undefined ? 0.1 : clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;
  const cap = mem.cap, nC = nCarried(obs);
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  const sp = (wL + wR) / 2;
  const wAvg = (Math.abs(wL) + Math.abs(wR)) / 2;
  const bat = isNum(obs.battery) ? obs.battery : 1;
  const tl = isNum(obs.timeLeft) ? obs.timeLeft : (mem.seconds - t);
  const sci = isNum(obs.science) ? obs.science : 0;
  if (sci > 0.05) mem.sciSeen = true;
  const site = (obs.site && isNum(obs.site.distance)) ? obs.site : null;
  const pitch = isNum(obs.pitch) ? obs.pitch : 0;
  const bc = (obs.beacon && isNum(obs.beacon.distance)) ? obs.beacon : null;

  // localisation: GPS when it changes, dead reckoning otherwise
  if (isNum(obs.x) && isNum(obs.y) && (obs.x !== mem.gx || obs.y !== mem.gy)) {
    mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  } else {
    mem.px += sp * Math.cos(mem.hEst * D2R) * dt;
    mem.py += sp * Math.sin(mem.hEst * D2R) * dt;
  }
  const px = mem.px, py = mem.py;

  // heading: wheel gyro fused with compass + learned offset
  const comp = wrap((isNum(obs.heading) ? obs.heading : mem.hEst) + mem.off);
  mem.hEst = wrap(mem.hEst + ((wR - wL) / TRACK) * dt / D2R + 0.03 * wrap(comp - mem.hEst));
  const H = mem.hEst;

  // compass offset learning on straight GPS runs
  const hist = mem.hist;
  if (!hist.length || t - hist[hist.length - 1].t >= 1.0) {
    hist.push({ t: t, x: px, y: py, s: Math.abs(wL - wR) < 0.15 && sp > 0.5 });
    if (hist.length > 4) hist.shift();
  }
  if (hist.length >= 4 && hist.every(e => e.s)) {
    const a = hist[0], b = hist[hist.length - 1];
    if (hyp(a.x, a.y, b.x, b.y) > 2.5 && isNum(obs.heading)) {
      const gh = brg(a.x, a.y, b.x, b.y);
      const diff = wrap(gh - obs.heading);
      mem.off = wrap(mem.off + 0.2 * wrap(diff - mem.off));
      mem.hist = [b];
    }
  }

  // range rays
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const d = [];
  for (let i = 0; i < 9; i++) d.push(clamp(isNum(rays[i]) ? rays[i] : 15, 0, 15));

  // escape sequence in progress
  if (mem.esc) {
    const o = runEsc(mem, t);
    if (o) return o;
  }
  // bump or stall while moving -> escape
  if (mem.mv) {
    if (obs.bumped === true && t >= mem.ignoreBumpUntil) {
      startEsc(mem, t, d, 'bump');
      const o = runEsc(mem, t); if (o) return o;
    }
    if (wAvg < 0.08) {
      if (mem.stallT === null || mem.stallT === undefined) mem.stallT = t;
      else if (t - mem.stallT > 2.5 && t >= mem.ignoreBumpUntil) {
        startEsc(mem, t, d, 'stall');
        const o = runEsc(mem, t); if (o) return o;
      }
    } else {
      mem.stallT = null;
    }
    if (hyp(px, py, mem.ancX, mem.ancY) > 0.5) {
      mem.ancX = px; mem.ancY = py; mem.ancT = t;
    } else if (t - mem.ancT > 8 && t >= mem.ignoreBumpUntil) {
      startEsc(mem, t, d, 'noprog');
      mem.ancT = t;
      const o = runEsc(mem, t); if (o) return o;
    }
  } else {
    mem.stallT = null; mem.ancX = px; mem.ancY = py; mem.ancT = t;
  }

  const base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  let mode = mem.mode;

  // drilling in progress
  if (mode === 'drill') {
    const dr = isNum(obs.drilling) ? obs.drilling : 0;
    if (dr >= 6.0) {
      finishSample(mem, px, py, t);
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (!site || site.distance > 2.2) {
      logEv(mem, t, 'drill lost site');
      mem.ignoreUntil = t + 2;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (t - mem.modeT > 25) {
      logEv(mem, t, 'drill timeout');
      mem.ignoreUntil = t + 15;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    return hold(obs, mem, pitch, dt, true);
  }

  // any unsampled site within 8 m: approach and drill
  const siteOK = !!site && nC < cap && t >= mem.ignoreUntil && mode !== 'dock';
  if (siteOK) {
    if (site.distance <= 1.3) {
      setMode(mem, 'drill', t);
      return hold(obs, mem, pitch, dt, true);
    }
    if (mode !== 'approach') setMode(mem, 'approach', t);
    if (t - mem.modeT > 40) {
      logEv(mem, t, 'approach timeout');
      mem.ignoreUntil = t + 20;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const f = clamp((site.distance - 0.6) * 0.5, 0.2, 0.4);
    const T = site.distance < 3 ? 1.2 : 2.0;
    return drive(isNum(site.bearing) ? site.bearing : 0, f, d, T);
  }
  if (mode === 'approach') {
    mode = (mem.tgt && mem.tgt.status === 'open') ? 'go' : 'choose';
    setMode(mem, mode, t);
  }

  if (mode === 'choose') {
    mode = choose(mem, t, px, py, nC, tl, bat);
    setMode(mem, mode, t);
  }

  // deliver at base
  if (mode === 'dock') {
    if (nC === 0) {
      mem.delivered++;
      logEv(mem, t, 'delivered');
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    let bD, bB;
    if (bc) { bD = bc.distance; bB = isNum(bc.bearing) ? bc.bearing : 0; }
    else { bD = dB; bB = wrap(brg(px, py, base.x, base.y) - H); }
    if (bD > 1.8) {
      if (t - mem.modeT > 240) {
        logEv(mem, t, 'dock timeout');
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      const f = clamp((bD - 1.0) * 0.4, 0.25, 0.5);
      return drive(bB, f, d, bD < 6 ? 1.2 : 2.0);
    }
    if (t - mem.modeT > 60) {
      logEv(mem, t, 'dock wait long');
      setMode(mem, 'choose', t);
    }
    return hold(obs, mem, pitch, dt, false);
  }

  // go to a hinted site
  if (mode === 'go') {
    const tg = mem.tgt;
    if (!tg || tg.status !== 'open') {
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const dd = hyp(px, py, tg.x, tg.y);
    if (dd < 6) {
      if (mem.sciSeen && sci < 0.02) {
        tg.status = 'fail';
        logEv(mem, t, 'hint empty (no science)');
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      mem.spiral = newSpiral(tg.x, tg.y, 13, t, tg);
      setMode(mem, 'search', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (t - mem.modeT > mem.goLimit) {
      tg.status = 'fail';
      logEv(mem, t, 'go timeout');
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const e = wrap(brg(px, py, tg.x, tg.y) - H);
    const f = clamp(0.3 + dd * 0.02, 0.3, 0.5);
    return drive(e, f, d, 2.0);
  }

  // spiral search around a point
  if (mode === 'search') {
    const S = mem.spiral;
    if (!S || t - S.t0 > 100) {
      if (S && S.tgt && S.tgt.status === 'open') { S.tgt.status = 'fail'; logEv(mem, t, 'search time out'); }
      mem.spiral = null;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    let r = S.a * S.th;
    let wx = S.cx + r * Math.cos(S.th), wy = S.cy + r * Math.sin(S.th);
    let dw = hyp(px, py, wx, wy);
    if (dw < 2.0 || t - S.wpT > 12) {
      S.th += clamp(2.5 / Math.max(r, 2.5), 0.12, 0.8);
      S.wpT = t;
      r = S.a * S.th;
      if (r > S.rMax) {
        if (S.tgt && S.tgt.status === 'open') { S.tgt.status = 'fail'; logEv(mem, t, 'search failed'); }
        mem.spiral = null;
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      wx = S.cx + r * Math.cos(S.th); wy = S.cy + r * Math.sin(S.th);
      dw = hyp(px, py, wx, wy);
    }
    const e = wrap(brg(px, py, wx, wy) - H);
    return drive(e, clamp(dw * 0.3, 0.25, 0.4), d, 2.0);
  }

  // explore unvisited grid points
  if (mode === 'explore') {
    const g = mem.exT;
    if (!g || hyp(px, py, g.x, g.y) < 10 || t - mem.modeT > 120) {
      if (g) g.vis = true;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (sci > 1.0 && t - mem.sciT > 60 && nC < cap) {
      mem.sciT = t;
      mem.spiral = newSpiral(px, py, 12, t, null);
      setMode(mem, 'search', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const e = wrap(brg(px, py, g.x, g.y) - H);
    return drive(e, 0.4, d, 2.0);
  }

  // idle: wait and re-plan
  if (t - mem.modeT > 5) setMode(mem, 'choose', t);
  return hold(obs, mem, pitch, dt, false);
}

function act(obs, mem) {
  let o = { l: 0, r: 0, drill: false, mv: false };
  try {
    if (!mem.init) initMem(obs, mem);
    balanceLearn(obs, mem);
    o = step(obs, mem) || o;
  } catch (e) {
    mem.errs = (mem.errs || 0) + 1;
    o = { l: 0, r: 0, drill: false, mv: false };
  }
  let l = clamp(+o.l || 0, -1, 1), r = clamp(+o.r || 0, -1, 1);
  if (mem.bal) {
    const s = Math.sqrt(mem.bal);
    l = clamp(l / s, -1, 1);
    r = clamp(r * s, -1, 1);
  }
  mem.lastCmd = { l: l, r: r };
  mem.mv = !!o.mv;
  return { left: l, right: r, drill: !!o.drill };
}

const D2R = Math.PI / 180;
const TRACK = 0.6;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];

function isNum(v) { return typeof v === 'number' && isFinite(v); }
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) / D2R; }
function nCarried(obs) {
  const c = obs.carried;
  if (Array.isArray(c)) return c.length;
  return isNum(c) ? c : 0;
}
function logEv(mem, t, msg) {
  if (!mem.log) mem.log = [];
  if (mem.log.length < 150) mem.log.push([Math.round(t), msg]);
}
function setMode(mem, name, t) { mem.mode = name; mem.modeT = t; }
function newSpiral(cx, cy, rMax, t, tgt) {
  return { cx: cx, cy: cy, a: 1.5, th: 0, wpT: t, t0: t, rMax: rMax, tgt: tgt };
}

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  const t = isNum(obs.t) ? obs.t : 0;
  mem.base = (m.base && isNum(m.base.x) && isNum(m.base.y)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = (isNum(m.capacity) && m.capacity > 0) ? m.capacity : 5;
  mem.seconds = (isNum(m.seconds) && m.seconds > 0) ? m.seconds : 1200;
  mem.sites = [];
  const hints = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hints) {
    if (h && isNum(h.x) && isNum(h.y)) {
      mem.sites.push({ x: h.x, y: h.y, est: isNum(h.estimate) ? Math.max(0.1, h.estimate) : 1, status: 'open', fails: 0 });
    }
  }
  mem.grid = [];
  for (let gx = 30; gx <= 370; gx += 60) {
    for (let gy = 30; gy <= 370; gy += 60) mem.grid.push({ x: gx, y: gy, vis: false });
  }
  mem.px = isNum(obs.x) ? obs.x : 0; mem.py = isNum(obs.y) ? obs.y : 0;
  mem.gx = obs.x; mem.gy = obs.y;
  mem.hEst = isNum(obs.heading) ? obs.heading : 0;
  mem.off = 0; mem.bal = 1; mem.IL = 0; mem.IR = 0; mem.hist = [];
  mem.lastCmd = { l: 0, r: 0 };
  mem.mv = false;
  mem.esc = null; mem.escHist = [];
  mem.stallT = null; mem.ancX = mem.px; mem.ancY = mem.py; mem.ancT = t;
  mem.ignoreBumpUntil = -1;
  mem.tgt = null; mem.spiral = null; mem.exT = null; mem.goLimit = 100;
  mem.ignoreUntil = -1; mem.samples = 0; mem.delivered = 0;
  mem.sciT = -99; mem.sciSeen = false;
  mem.log = [];
  setMode(mem, 'choose', t);
}

// learn relative motor gain from straight driving
function balanceLearn(obs, mem) {
  const c = mem.lastCmd;
  if (!c || !mem.bal) return;
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  if (Math.abs(c.l) > 0.3 && Math.abs(c.r) > 0.3 && Math.sign(c.l) === Math.sign(c.r) &&
      Math.abs(c.l - c.r) < 0.05 && Math.abs(wL) > 0.2 && Math.abs(wR) > 0.2 &&
      Math.sign(wL) === Math.sign(wR)) {
    const ratio = (wL / c.l) / (wR / c.r);
    if (isFinite(ratio)) mem.bal = clamp(mem.bal + 0.02 * (ratio - mem.bal), 0.7, 1.4);
  }
}

// still-hold: wheel-speed integrator plus pitch feedforward
function hold(obs, mem, pitch, dt, drill) {
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  mem.IL = clamp((mem.IL || 0) - 0.8 * wL * dt, -0.35, 0.35);
  mem.IR = clamp((mem.IR || 0) - 0.8 * wR * dt, -0.35, 0.35);
  const ff = clamp(0.02 * pitch, -0.35, 0.35);
  return { l: clamp(ff + mem.IL, -0.4, 0.4), r: clamp(ff + mem.IR, -0.4, 0.4), drill: !!drill, mv: false };
}

// choose steering angle (deg, relative to heading, + = left) that is clear
function steerAngle(e, d, T) {
  const idx = (a) => clamp(Math.round((a + 80) / 20), 0, 8);
  if (Math.abs(e) <= 80) {
    const ok = d[idx(e - 8)] >= T && d[idx(e)] >= T && d[idx(e + 8)] >= T;
    if (ok) return e;
  }
  let best = null, bc = 1e9;
  for (let i = 0; i < 9; i++) {
    if (d[i] >= T) {
      const c = Math.abs(ANG[i] - e);
      if (c < bc) { bc = c; best = ANG[i]; }
    }
  }
  return best;
}

function clearance(s, d) {
  let c = 15;
  for (let i = 0; i < 9; i++) {
    if (Math.abs(ANG[i] - s) <= 25) c = Math.min(c, d[i]);
  }
  return c;
}

// e: bearing error (deg, + = target left); fmax: max forward command; d: rays; T: clear threshold
function drive(e, fmax, d, T) {
  const s = steerAngle(e, d, T);
  if (s === null) {
    const Lm = Math.min(d[5], d[6], d[7], d[8]);
    const Rm = Math.min(d[0], d[1], d[2], d[3]);
    const k = Lm >= Rm ? 1 : -1;
    return { l: -0.4 * k, r: 0.4 * k, drill: false, mv: true };
  }
  const C = clearance(s, d);
  // speed scales with clear distance ahead: full speed only when >= 7.5 m is clear
  const vf = clamp((C - 2.5) / 5, 0, 1);
  const cf = Math.max(0, Math.cos(s * D2R));
  let f = fmax * vf * cf;
  if (Math.abs(s) > 60) f = 0;
  if (f < 0.2) f = 0; else if (f < 0.25) f = 0.25;
  const mn = f > 0 ? 0.15 : 0.25;
  let tu = clamp(0.012 * s, -0.45, 0.45);
  if (Math.abs(s) > 8 && Math.abs(tu) < mn) tu = s > 0 ? mn : -mn;
  return { l: clamp(f - tu, -1, 1), r: clamp(f + tu, -1, 1), drill: false, mv: true };
}

function startEsc(mem, t, d, why) {
  const Lm = Math.min(d[5], d[6], d[7], d[8]);
  const Rm = Math.min(d[0], d[1], d[2], d[3]);
  let dir = Lm >= Rm ? 1 : -1;
  mem.escHist = mem.escHist.filter(x => t - x < 60);
  mem.escHist.push(t);
  if (mem.escHist.length % 2 === 0) dir = -dir;
  mem.esc = { ph: 0, until: t + 1.2, dir: dir };
  mem.stallT = null;
  logEv(mem, t, 'esc ' + why + ' in ' + mem.mode);
  if (mem.tgt && mem.tgt.status === 'open' && (mem.mode === 'go' || mem.mode === 'search' || mem.mode === 'approach')) {
    mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    if (mem.tgt.fails >= 2) {
      mem.tgt.status = 'fail';
      mem.spiral = null;
      logEv(mem, t, 'target dropped after escapes');
      setMode(mem, 'choose', t);
    }
  }
  if (mem.escHist.length >= 5) {
    mem.escHist = [];
    if (mem.tgt && mem.tgt.status === 'open') mem.tgt.status = 'fail';
    mem.spiral = null;
    logEv(mem, t, 'too many escapes, replanning');
    setMode(mem, 'choose', t);
  }
}

function runEsc(mem, t) {
  const E = mem.esc;
  if (E.ph === 0) {
    if (t < E.until) return { l: -0.45, r: -0.45, drill: false, mv: false };
    E.ph = 1; E.until = t + 1.0;
  }
  if (t < E.until) return { l: -0.45 * E.dir, r: 0.45 * E.dir, drill: false, mv: false };
  mem.esc = null;
  mem.ignoreBumpUntil = t + 1.5;
  mem.ancX = mem.px; mem.ancY = mem.py; mem.ancT = t;
  return null;
}

function finishSample(mem, px, py, t) {
  mem.samples = (mem.samples || 0) + 1;
  let best = null, bd = 20;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(s.x, s.y, px, py);
    if (dd < bd) { bd = dd; best = s; }
  }
  if (best) best.status = 'done';
  if (mem.tgt && mem.tgt.status === 'open' && hyp(mem.tgt.x, mem.tgt.y, px, py) < 20) mem.tgt.status = 'done';
  mem.ignoreUntil = t + 2;
  logEv(mem, t, 'drilled');
}

function choose(mem, t, px, py, nC, tl, bat) {
  const base = mem.base, cap = mem.cap;
  const dB = hyp(px, py, base.x, base.y);
  let best = null, bs = 0, bdist = 0;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(px, py, s.x, s.y), db = hyp(s.x, s.y, base.x, base.y);
    if ((dd + db) / 0.6 + 60 > tl) continue;
    const sc = s.est / (dd + 0.6 * db + 25);
    if (sc > bs) { bs = sc; best = s; bdist = dd; }
  }
  if (nC > 0 && (nC >= cap || bat < 0.2 || tl < dB / 0.6 + 60 || !best || (nC >= 2 && dB < 50))) return 'dock';
  if (best) {
    mem.tgt = best;
    mem.goLimit = 40 + 2.5 * bdist;
    logEv(mem, t, 'target ' + best.x.toFixed(0) + ',' + best.y.toFixed(0));
    return 'go';
  }
  let g = null, gd = 1e9;
  for (const q of mem.grid) {
    if (q.vis) continue;
    const dd = hyp(px, py, q.x, q.y);
    if (dd < gd) { gd = dd; g = q; }
  }
  if (g && tl > (dB + gd) / 0.6 + 80) {
    mem.exT = g;
    return 'explore';
  }
  return 'idle';
}

function step(obs, mem) {
  const t = isNum(obs.t) ? obs.t : 0;
  if (!mem.init) initMem(obs, mem);
  const dt = mem.lastT === undefined ? 0.1 : clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;
  const cap = mem.cap, nC = nCarried(obs);
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  const sp = (wL + wR) / 2;
  const wAvg = (Math.abs(wL) + Math.abs(wR)) / 2;
  const bat = isNum(obs.battery) ? obs.battery : 1;
  const tl = isNum(obs.timeLeft) ? obs.timeLeft : (mem.seconds - t);
  const sci = isNum(obs.science) ? obs.science : 0;
  if (sci > 0.05) mem.sciSeen = true;
  const site = (obs.site && isNum(obs.site.distance)) ? obs.site : null;
  const pitch = isNum(obs.pitch) ? obs.pitch : 0;
  const bc = (obs.beacon && isNum(obs.beacon.distance)) ? obs.beacon : null;

  // localisation: GPS when it changes, dead reckoning otherwise (covers GPS freezes)
  if (isNum(obs.x) && isNum(obs.y) && (obs.x !== mem.gx || obs.y !== mem.gy)) {
    mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  } else {
    mem.px += sp * Math.cos(mem.hEst * D2R) * dt;
    mem.py += sp * Math.sin(mem.hEst * D2R) * dt;
  }
  const px = mem.px, py = mem.py;

  // heading: wheel gyro fused with compass + learned offset
  const comp = wrap((isNum(obs.heading) ? obs.heading : mem.hEst) + mem.off);
  mem.hEst = wrap(mem.hEst + ((wR - wL) / TRACK) * dt / D2R + 0.03 * wrap(comp - mem.hEst));
  const H = mem.hEst;

  // compass offset learning on straight GPS runs
  const hist = mem.hist;
  if (!hist.length || t - hist[hist.length - 1].t >= 1.0) {
    hist.push({ t: t, x: px, y: py, s: Math.abs(wL - wR) < 0.15 && sp > 0.5 });
    if (hist.length > 4) hist.shift();
  }
  if (hist.length >= 4 && hist.every(e => e.s)) {
    const a = hist[0], b = hist[hist.length - 1];
    if (hyp(a.x, a.y, b.x, b.y) > 2.5 && isNum(obs.heading)) {
      const gh = brg(a.x, a.y, b.x, b.y);
      const diff = wrap(gh - obs.heading);
      mem.off = wrap(mem.off + 0.2 * wrap(diff - mem.off));
      mem.hist = [b];
    }
  }

  // range rays
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const d = [];
  for (let i = 0; i < 9; i++) d.push(clamp(isNum(rays[i]) ? rays[i] : 15, 0, 15));

  // escape sequence in progress
  if (mem.esc) {
    const o = runEsc(mem, t);
    if (o) return o;
  }
  // bump or stall while moving -> escape
  if (mem.mv) {
    if (obs.bumped === true && t >= mem.ignoreBumpUntil) {
      startEsc(mem, t, d, 'bump');
      const o = runEsc(mem, t); if (o) return o;
    }
    if (wAvg < 0.08) {
      if (mem.stallT === null || mem.stallT === undefined) mem.stallT = t;
      else if (t - mem.stallT > 2.5 && t >= mem.ignoreBumpUntil) {
        startEsc(mem, t, d, 'stall');
        const o = runEsc(mem, t); if (o) return o;
      }
    } else {
      mem.stallT = null;
    }
    if (hyp(px, py, mem.ancX, mem.ancY) > 0.5) {
      mem.ancX = px; mem.ancY = py; mem.ancT = t;
    } else if (t - mem.ancT > 8 && t >= mem.ignoreBumpUntil) {
      startEsc(mem, t, d, 'noprog');
      mem.ancT = t;
      const o = runEsc(mem, t); if (o) return o;
    }
  } else {
    mem.stallT = null; mem.ancX = px; mem.ancY = py; mem.ancT = t;
  }

  const base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  let mode = mem.mode;

  // drilling in progress
  if (mode === 'drill') {
    const dr = isNum(obs.drilling) ? obs.drilling : 0;
    if (dr >= 6.0) {
      finishSample(mem, px, py, t);
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (!site || site.distance > 2.2) {
      logEv(mem, t, 'drill lost site');
      mem.ignoreUntil = t + 2;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (t - mem.modeT > 25) {
      logEv(mem, t, 'drill timeout');
      mem.ignoreUntil = t + 15;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    return hold(obs, mem, pitch, dt, true);
  }

  // any unsampled site within 8 m: approach and drill
  const siteOK = !!site && nC < cap && t >= mem.ignoreUntil && mode !== 'dock';
  if (siteOK) {
    if (site.distance <= 1.3) {
      setMode(mem, 'drill', t);
      return hold(obs, mem, pitch, dt, true);
    }
    if (mode !== 'approach') setMode(mem, 'approach', t);
    if (t - mem.modeT > 40) {
      logEv(mem, t, 'approach timeout');
      mem.ignoreUntil = t + 20;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const f = clamp((site.distance - 0.6) * 0.5, 0.25, 0.45);
    const T = site.distance < 3 ? 1.2 : 2.0;
    return drive(isNum(site.bearing) ? site.bearing : 0, f, d, T);
  }
  if (mode === 'approach') {
    mode = (mem.tgt && mem.tgt.status === 'open') ? 'go' : 'choose';
    setMode(mem, mode, t);
  }

  if (mode === 'choose') {
    mode = choose(mem, t, px, py, nC, tl, bat);
    setMode(mem, mode, t);
  }

  // deliver at base
  if (mode === 'dock') {
    if (nC === 0) {
      mem.delivered++;
      logEv(mem, t, 'delivered');
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    let bD, bB;
    if (bc) { bD = bc.distance; bB = isNum(bc.bearing) ? bc.bearing : 0; }
    else { bD = dB; bB = wrap(brg(px, py, base.x, base.y) - H); }
    if (bD > 1.8) {
      if (t - mem.modeT > 240) {
        logEv(mem, t, 'dock timeout');
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      const f = clamp((bD - 1.0) * 0.4, 0.3, 0.55);
      return drive(bB, f, d, bD < 6 ? 1.2 : 2.0);
    }
    if (t - mem.modeT > 60) {
      logEv(mem, t, 'dock wait long');
      setMode(mem, 'choose', t);
    }
    return hold(obs, mem, pitch, dt, false);
  }

  // go to a hinted site
  if (mode === 'go') {
    const tg = mem.tgt;
    if (!tg || tg.status !== 'open') {
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const dd = hyp(px, py, tg.x, tg.y);
    if (dd < 6) {
      if (mem.sciSeen && sci < 0.02) {
        tg.status = 'fail';
        logEv(mem, t, 'hint empty (no science)');
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      mem.spiral = newSpiral(tg.x, tg.y, 13, t, tg);
      setMode(mem, 'search', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (t - mem.modeT > mem.goLimit) {
      tg.status = 'fail';
      logEv(mem, t, 'go timeout');
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const e = wrap(brg(px, py, tg.x, tg.y) - H);
    const f = clamp(0.4 + dd * 0.02, 0.4, 0.6);
    return drive(e, f, d, 2.0);
  }

  // spiral search around a point
  if (mode === 'search') {
    const S = mem.spiral;
    if (!S || t - S.t0 > 100) {
      if (S && S.tgt && S.tgt.status === 'open') { S.tgt.status = 'fail'; logEv(mem, t, 'search time out'); }
      mem.spiral = null;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    let r = S.a * S.th;
    let wx = S.cx + r * Math.cos(S.th), wy = S.cy + r * Math.sin(S.th);
    let dw = hyp(px, py, wx, wy);
    if (dw < 2.0 || t - S.wpT > 12) {
      S.th += clamp(2.5 / Math.max(r, 2.5), 0.12, 0.8);
      S.wpT = t;
      r = S.a * S.th;
      if (r > S.rMax) {
        if (S.tgt && S.tgt.status === 'open') { S.tgt.status = 'fail'; logEv(mem, t, 'search failed'); }
        mem.spiral = null;
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      wx = S.cx + r * Math.cos(S.th); wy = S.cy + r * Math.sin(S.th);
      dw = hyp(px, py, wx, wy);
    }
    const e = wrap(brg(px, py, wx, wy) - H);
    return drive(e, clamp(dw * 0.3, 0.25, 0.4), d, 2.0);
  }

  // explore unvisited grid points
  if (mode === 'explore') {
    const g = mem.exT;
    if (!g || hyp(px, py, g.x, g.y) < 10 || t - mem.modeT > 120) {
      if (g) g.vis = true;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (sci > 1.0 && t - mem.sciT > 60 && nC < cap) {
      mem.sciT = t;
      mem.spiral = newSpiral(px, py, 12, t, null);
      setMode(mem, 'search', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const e = wrap(brg(px, py, g.x, g.y) - H);
    return drive(e, 0.5, d, 2.0);
  }

  // idle: wait and re-plan
  if (t - mem.modeT > 5) setMode(mem, 'choose', t);
  return hold(obs, mem, pitch, dt, false);
}

function act(obs, mem) {
  let o = { l: 0, r: 0, drill: false, mv: false };
  try {
    if (!mem.init) initMem(obs, mem);
    balanceLearn(obs, mem);
    o = step(obs, mem) || o;
  } catch (e) {
    mem.errs = (mem.errs || 0) + 1;
    o = { l: 0, r: 0, drill: false, mv: false };
  }
  let l = clamp(+o.l || 0, -1, 1), r = clamp(+o.r || 0, -1, 1);
  if (mem.bal) {
    const s = Math.sqrt(mem.bal);
    l = clamp(l / s, -1, 1);
    r = clamp(r * s, -1, 1);
  }
  mem.lastCmd = { l: l, r: r };
  mem.mv = !!o.mv;
  return { left: l, right: r, drill: !!o.drill };
}

const D2R = Math.PI / 180;
const TRACK = 0.6;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
const GS = 2.5, GO = -20, GN = 176;

function isNum(v) { return typeof v === 'number' && isFinite(v); }
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) / D2R; }
function nCarried(obs) {
  const c = obs.carried;
  if (Array.isArray(c)) return c.length;
  return isNum(c) ? c : 0;
}
function logEv(mem, t, msg) {
  if (!mem.log) mem.log = [];
  if (mem.log.length < 150) mem.log.push([Math.round(t), msg]);
}
function setMode(mem, name, t) { mem.mode = name; mem.modeT = t; }
function newSpiral(cx, cy, rMax, t, tgt) {
  return { cx: cx, cy: cy, a: 1.5, th: 0, wpT: t, t0: t, rMax: rMax, tgt: tgt };
}

// ---------- occupancy grid and planner ----------
function cellI(v) {
  const i = Math.floor((v - GO) / GS);
  return i < 0 ? 0 : (i >= GN ? GN - 1 : i);
}

function mapUpdate(mem, px, py, H, d) {
  const occ = mem.occ;
  if (!occ) return;
  for (let i = 0; i < 9; i++) {
    const r = d[i];
    const a = (H + ANG[i]) * D2R;
    const ca = Math.cos(a), sa = Math.sin(a);
    const hit = r < 14.5;
    const lim = hit ? r - 0.5 : r;
    for (let s = 1.0; s < lim; s += 1.0) {
      const k = cellI(py + sa * s) * GN + cellI(px + ca * s);
      occ[k] = Math.max(-2, occ[k] - 0.2);
    }
    if (hit) {
      const k = cellI(py + sa * r) * GN + cellI(px + ca * r);
      occ[k] = Math.min(4, occ[k] + 1);
    }
  }
}

function octH(i, j, gi, gj) {
  const dx = Math.abs(i - gi), dy = Math.abs(j - gj);
  return Math.max(dx, dy) + 0.414 * Math.min(dx, dy);
}

function nearOcc(occ, i, j) {
  for (let a = -1; a <= 1; a++) {
    for (let b = -1; b <= 1; b++) {
      const ii = i + a, jj = j + b;
      if (ii < 0 || jj < 0 || ii >= GN || jj >= GN) continue;
      if (occ[jj * GN + ii] >= 0.5) return true;
    }
  }
  return false;
}

function hPush(hf, hk, f, k) {
  hf.push(f); hk.push(k);
  let i = hf.length - 1;
  while (i > 0) {
    const p = (i - 1) >> 1;
    if (hf[p] <= hf[i]) break;
    const tf = hf[p]; hf[p] = hf[i]; hf[i] = tf;
    const tk = hk[p]; hk[p] = hk[i]; hk[i] = tk;
    i = p;
  }
}

function hPop(hf, hk) {
  const top = hk[0];
  const lf = hf.pop(), lk = hk.pop();
  const n = hf.length;
  if (n > 0) {
    hf[0] = lf; hk[0] = lk;
    let i = 0;
    for (;;) {
      const l = 2 * i + 1, r = l + 1;
      let m = i;
      if (l < n && hf[l] < hf[m]) m = l;
      if (r < n && hf[r] < hf[m]) m = r;
      if (m === i) break;
      const tf = hf[m]; hf[m] = hf[i]; hf[i] = tf;
      const tk = hk[m]; hk[m] = hk[i]; hk[i] = tk;
      i = m;
    }
  }
  return top;
}

function astar(mem, sx, sy, gx, gy) {
  const occ = mem.occ;
  const si = cellI(sx), sj = cellI(sy), gi = cellI(gx), gj = cellI(gy);
  const N = GN * GN;
  const s = sj * GN + si, g = gj * GN + gi;
  const gc = new Float32Array(N).fill(1e9);
  const par = new Int32Array(N).fill(-1);
  const cl = new Uint8Array(N);
  const hf = [], hk = [];
  gc[s] = 0;
  hPush(hf, hk, octH(si, sj, gi, gj), s);
  let exp = 0;
  while (hf.length > 0 && exp < 6000) {
    const k = hPop(hf, hk);
    if (cl[k]) continue;
    cl[k] = 1; exp++;
    if (k === g) break;
    const i = k % GN, j = (k - i) / GN;
    for (let di = -1; di <= 1; di++) {
      for (let dj = -1; dj <= 1; dj++) {
        if (di === 0 && dj === 0) continue;
        const ni = i + di, nj = j + dj;
        if (ni < 0 || nj < 0 || ni >= GN || nj >= GN) continue;
        const nk = nj * GN + ni;
        if (cl[nk]) continue;
        if (nk !== g && occ[nk] >= 0.5) continue;
        let c = (di !== 0 && dj !== 0) ? 1.414 : 1;
        if (nearOcc(occ, ni, nj)) c += 1.5;
        const ng = gc[k] + c;
        if (ng < gc[nk]) {
          gc[nk] = ng; par[nk] = k;
          hPush(hf, hk, ng + octH(ni, nj, gi, gj), nk);
        }
      }
    }
  }
  if (!cl[g]) return null;
  const pts = [];
  let k = g, guard = 0;
  while (k !== -1 && guard++ < 5000) {
    const i = k % GN, j = (k - i) / GN;
    pts.push([GO + (i + 0.5) * GS, GO + (j + 0.5) * GS]);
    if (k === s) break;
    k = par[k];
  }
  pts.reverse();
  return pts;
}

function losFree(occ, x0, y0, x1, y1) {
  const L = hyp(x0, y0, x1, y1);
  const n = Math.max(1, Math.ceil(L / 1.2));
  for (let q = 1; q < n; q++) {
    const f = q / n;
    const k = cellI(y0 + (y1 - y0) * f) * GN + cellI(x0 + (x1 - x0) * f);
    if (occ[k] >= 0.5) return false;
  }
  return true;
}

function pickWp(mem, px, py) {
  const P = mem.path;
  let best = null;
  for (let q = 0; q < P.length; q++) {
    const dd = hyp(px, py, P[q][0], P[q][1]);
    if (dd > 12) break;
    if (dd < 1.5) continue;
    if (losFree(mem.occ, px, py, P[q][0], P[q][1])) best = P[q];
  }
  return best;
}

// route toward (tx,ty) via the remembered map, steer with the local ray driver
function navDrive(mem, t, px, py, H, tx, ty, fmax, d, T) {
  let need = (t - mem.planT) > 2.5 || hyp(mem.pgx, mem.pgy, tx, ty) > 3;
  if (!need && mem.path && mem.path.length) {
    let md = 1e9;
    for (let q = 0; q < mem.path.length; q++) {
      const p = mem.path[q];
      const dd = hyp(p[0], p[1], px, py);
      if (dd < md) md = dd;
    }
    if (md > 3.5) need = true;
  }
  if (need) {
    mem.path = astar(mem, px, py, tx, ty);
    mem.planT = t; mem.pgx = tx; mem.pgy = ty;
    if (mem.path) {
      mem.path.push([tx, ty]);
    } else {
      mem.planFails = (mem.planFails || 0) + 1;
    }
  }
  let wp = null;
  if (mem.path && mem.path.length) wp = pickWp(mem, px, py);
  if (!wp) wp = [tx, ty];
  const e = wrap(brg(px, py, wp[0], wp[1]) - H);
  return drive(e, fmax, d, T);
}

// ---------- original controller pieces ----------
function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  const t = isNum(obs.t) ? obs.t : 0;
  mem.base = (m.base && isNum(m.base.x) && isNum(m.base.y)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = (isNum(m.capacity) && m.capacity > 0) ? m.capacity : 5;
  mem.seconds = (isNum(m.seconds) && m.seconds > 0) ? m.seconds : 1200;
  mem.sites = [];
  const hints = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hints) {
    if (h && isNum(h.x) && isNum(h.y)) {
      mem.sites.push({ x: h.x, y: h.y, est: isNum(h.estimate) ? Math.max(0.1, h.estimate) : 1, status: 'open', fails: 0 });
    }
  }
  mem.grid = [];
  for (let gx = 30; gx <= 370; gx += 60) {
    for (let gy = 30; gy <= 370; gy += 60) mem.grid.push({ x: gx, y: gy, vis: false });
  }
  mem.occ = new Float32Array(GN * GN);
  mem.path = null; mem.planT = -99; mem.pgx = -1e9; mem.pgy = -1e9; mem.planFails = 0;
  mem.px = isNum(obs.x) ? obs.x : 0; mem.py = isNum(obs.y) ? obs.y : 0;
  mem.gx = obs.x; mem.gy = obs.y;
  mem.hEst = isNum(obs.heading) ? obs.heading : 0;
  mem.off = 0; mem.bal = 1; mem.IL = 0; mem.IR = 0; mem.hist = [];
  mem.lastCmd = { l: 0, r: 0 };
  mem.mv = false;
  mem.esc = null; mem.escHist = [];
  mem.stallT = null; mem.ancX = mem.px; mem.ancY = mem.py; mem.ancT = t;
  mem.ignoreBumpUntil = -1;
  mem.tgt = null; mem.spiral = null; mem.exT = null; mem.goLimit = 100;
  mem.ignoreUntil = -1; mem.samples = 0; mem.delivered = 0;
  mem.sciT = -99; mem.sciSeen = false;
  mem.log = [];
  setMode(mem, 'choose', t);
}

function balanceLearn(obs, mem) {
  const c = mem.lastCmd;
  if (!c || !mem.bal) return;
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  if (Math.abs(c.l) > 0.3 && Math.abs(c.r) > 0.3 && Math.sign(c.l) === Math.sign(c.r) &&
      Math.abs(c.l - c.r) < 0.05 && Math.abs(wL) > 0.2 && Math.abs(wR) > 0.2 &&
      Math.sign(wL) === Math.sign(wR)) {
    const ratio = (wL / c.l) / (wR / c.r);
    if (isFinite(ratio)) mem.bal = clamp(mem.bal + 0.02 * (ratio - mem.bal), 0.7, 1.4);
  }
}

function hold(obs, mem, pitch, dt, drill) {
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  mem.IL = clamp((mem.IL || 0) - 0.8 * wL * dt, -0.35, 0.35);
  mem.IR = clamp((mem.IR || 0) - 0.8 * wR * dt, -0.35, 0.35);
  const ff = clamp(0.02 * pitch, -0.35, 0.35);
  return { l: clamp(ff + mem.IL, -0.4, 0.4), r: clamp(ff + mem.IR, -0.4, 0.4), drill: !!drill, mv: false };
}

function steerAngle(e, d, T) {
  const idx = (a) => clamp(Math.round((a + 80) / 20), 0, 8);
  if (Math.abs(e) <= 80) {
    const ok = d[idx(e - 8)] >= T && d[idx(e)] >= T && d[idx(e + 8)] >= T;
    if (ok) return e;
  }
  let best = null, bc = 1e9;
  for (let i = 0; i < 9; i++) {
    if (d[i] >= T) {
      const c = Math.abs(ANG[i] - e);
      if (c < bc) { bc = c; best = ANG[i]; }
    }
  }
  return best;
}

function clearance(s, d) {
  let c = 15;
  for (let i = 0; i < 9; i++) {
    if (Math.abs(ANG[i] - s) <= 25) c = Math.min(c, d[i]);
  }
  return c;
}

function drive(e, fmax, d, T) {
  const s = steerAngle(e, d, T);
  if (s === null) {
    const Lm = Math.min(d[5], d[6], d[7], d[8]);
    const Rm = Math.min(d[0], d[1], d[2], d[3]);
    const k = Lm >= Rm ? 1 : -1;
    return { l: -0.4 * k, r: 0.4 * k, drill: false, mv: true };
  }
  const C = clearance(s, d);
  const vf = clamp((C - 2.5) / 5, 0, 1);
  const cf = Math.max(0, Math.cos(s * D2R));
  let f = fmax * vf * cf;
  if (Math.abs(s) > 60) f = 0;
  if (f < 0.2) f = 0; else if (f < 0.25) f = 0.25;
  const mn = f > 0 ? 0.15 : 0.25;
  let tu = clamp(0.012 * s, -0.45, 0.45);
  if (Math.abs(s) > 8 && Math.abs(tu) < mn) tu = s > 0 ? mn : -mn;
  return { l: clamp(f - tu, -1, 1), r: clamp(f + tu, -1, 1), drill: false, mv: true };
}

function startEsc(mem, t, d, why) {
  const Lm = Math.min(d[5], d[6], d[7], d[8]);
  const Rm = Math.min(d[0], d[1], d[2], d[3]);
  let dir = Lm >= Rm ? 1 : -1;
  mem.escHist = mem.escHist.filter(x => t - x < 60);
  mem.escHist.push(t);
  if (mem.escHist.length % 2 === 0) dir = -dir;
  mem.esc = { ph: 0, until: t + 1.2, dir: dir };
  mem.stallT = null;
  logEv(mem, t, 'esc ' + why + ' in ' + mem.mode);
  if (mem.tgt && mem.tgt.status === 'open' && (mem.mode === 'go' || mem.mode === 'search' || mem.mode === 'approach')) {
    mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    if (mem.tgt.fails >= 2) {
      mem.tgt.status = 'fail';
      mem.spiral = null;
      logEv(mem, t, 'target dropped after escapes');
      setMode(mem, 'choose', t);
    }
  }
  if (mem.escHist.length >= 5) {
    mem.escHist = [];
    if (mem.tgt && mem.tgt.status === 'open') mem.tgt.status = 'fail';
    mem.spiral = null;
    logEv(mem, t, 'too many escapes, replanning');
    setMode(mem, 'choose', t);
  }
}

function runEsc(mem, t) {
  const E = mem.esc;
  if (E.ph === 0) {
    if (t < E.until) return { l: -0.45, r: -0.45, drill: false, mv: false };
    E.ph = 1; E.until = t + 1.0;
  }
  if (t < E.until) return { l: -0.45 * E.dir, r: 0.45 * E.dir, drill: false, mv: false };
  mem.esc = null;
  mem.ignoreBumpUntil = t + 1.5;
  mem.ancX = mem.px; mem.ancY = mem.py; mem.ancT = t;
  return null;
}

function finishSample(mem, px, py, t) {
  mem.samples = (mem.samples || 0) + 1;
  let best = null, bd = 20;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(s.x, s.y, px, py);
    if (dd < bd) { bd = dd; best = s; }
  }
  if (best) best.status = 'done';
  if (mem.tgt && mem.tgt.status === 'open' && hyp(mem.tgt.x, mem.tgt.y, px, py) < 20) mem.tgt.status = 'done';
  mem.ignoreUntil = t + 2;
  logEv(mem, t, 'drilled');
}

function choose(mem, t, px, py, nC, tl, bat) {
  const base = mem.base, cap = mem.cap;
  const dB = hyp(px, py, base.x, base.y);
  let best = null, bs = 0, bdist = 0;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(px, py, s.x, s.y), db = hyp(s.x, s.y, base.x, base.y);
    if ((dd + db) / 0.6 + 60 > tl) continue;
    const sc = s.est / (dd + 0.6 * db + 25);
    if (sc > bs) { bs = sc; best = s; bdist = dd; }
  }
  if (nC > 0 && (nC >= cap || bat < 0.2 || tl < dB / 0.6 + 60 || !best || (nC >= 2 && dB < 50))) return 'dock';
  if (best) {
    mem.tgt = best;
    mem.goLimit = 40 + 2.5 * bdist;
    logEv(mem, t, 'target ' + best.x.toFixed(0) + ',' + best.y.toFixed(0));
    return 'go';
  }
  let g = null, gd = 1e9;
  for (const q of mem.grid) {
    if (q.vis) continue;
    const dd = hyp(px, py, q.x, q.y);
    if (dd < gd) { gd = dd; g = q; }
  }
  if (g && tl > (dB + gd) / 0.6 + 80) {
    mem.exT = g;
    return 'explore';
  }
  return 'idle';
}

function step(obs, mem) {
  const t = isNum(obs.t) ? obs.t : 0;
  if (!mem.init) initMem(obs, mem);
  const dt = mem.lastT === undefined ? 0.1 : clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;
  const cap = mem.cap, nC = nCarried(obs);
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  const sp = (wL + wR) / 2;
  const wAvg = (Math.abs(wL) + Math.abs(wR)) / 2;
  const bat = isNum(obs.battery) ? obs.battery : 1;
  const tl = isNum(obs.timeLeft) ? obs.timeLeft : (mem.seconds - t);
  const sci = isNum(obs.science) ? obs.science : 0;
  if (sci > 0.05) mem.sciSeen = true;
  const site = (obs.site && isNum(obs.site.distance)) ? obs.site : null;
  const pitch = isNum(obs.pitch) ? obs.pitch : 0;
  const bc = (obs.beacon && isNum(obs.beacon.distance)) ? obs.beacon : null;

  // localisation: GPS when it changes, dead reckoning otherwise
  if (isNum(obs.x) && isNum(obs.y) && (obs.x !== mem.gx || obs.y !== mem.gy)) {
    mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  } else {
    mem.px += sp * Math.cos(mem.hEst * D2R) * dt;
    mem.py += sp * Math.sin(mem.hEst * D2R) * dt;
  }
  const px = mem.px, py = mem.py;

  // heading: wheel gyro fused with compass + learned offset
  const comp = wrap((isNum(obs.heading) ? obs.heading : mem.hEst) + mem.off);
  mem.hEst = wrap(mem.hEst + ((wR - wL) / TRACK) * dt / D2R + 0.03 * wrap(comp - mem.hEst));
  const H = mem.hEst;

  // compass offset learning on straight GPS runs
  const hist = mem.hist;
  if (!hist.length || t - hist[hist.length - 1].t >= 1.0) {
    hist.push({ t: t, x: px, y: py, s: Math.abs(wL - wR) < 0.15 && sp > 0.5 });
    if (hist.length > 4) hist.shift();
  }
  if (hist.length >= 4 && hist.every(e => e.s)) {
    const a = hist[0], b = hist[hist.length - 1];
    if (hyp(a.x, a.y, b.x, b.y) > 2.5 && isNum(obs.heading)) {
      const gh = brg(a.x, a.y, b.x, b.y);
      const diff = wrap(gh - obs.heading);
      mem.off = wrap(mem.off + 0.2 * wrap(diff - mem.off));
      mem.hist = [b];
    }
  }

  // range rays
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const d = [];
  for (let i = 0; i < 9; i++) d.push(clamp(isNum(rays[i]) ? rays[i] : 15, 0, 15));
  mapUpdate(mem, px, py, H, d);

  // escape sequence in progress
  if (mem.esc) {
    const o = runEsc(mem, t);
    if (o) return o;
  }
  // bump or stall while moving -> escape
  if (mem.mv) {
    if (obs.bumped === true && t >= mem.ignoreBumpUntil) {
      startEsc(mem, t, d, 'bump');
      const o = runEsc(mem, t); if (o) return o;
    }
    if (wAvg < 0.08) {
      if (mem.stallT === null || mem.stallT === undefined) mem.stallT = t;
      else if (t - mem.stallT > 2.5 && t >= mem.ignoreBumpUntil) {
        startEsc(mem, t, d, 'stall');
        const o = runEsc(mem, t); if (o) return o;
      }
    } else {
      mem.stallT = null;
    }
    if (hyp(px, py, mem.ancX, mem.ancY) > 0.5) {
      mem.ancX = px; mem.ancY = py; mem.ancT = t;
    } else if (t - mem.ancT > 8 && t >= mem.ignoreBumpUntil) {
      startEsc(mem, t, d, 'noprog');
      mem.ancT = t;
      const o = runEsc(mem, t); if (o) return o;
    }
  } else {
    mem.stallT = null; mem.ancX = px; mem.ancY = py; mem.ancT = t;
  }

  const base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  let mode = mem.mode;

  // drilling in progress
  if (mode === 'drill') {
    const dr = isNum(obs.drilling) ? obs.drilling : 0;
    if (dr >= 6.0) {
      finishSample(mem, px, py, t);
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (!site || site.distance > 2.2) {
      logEv(mem, t, 'drill lost site');
      mem.ignoreUntil = t + 2;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (t - mem.modeT > 25) {
      logEv(mem, t, 'drill timeout');
      mem.ignoreUntil = t + 15;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    return hold(obs, mem, pitch, dt, true);
  }

  // any unsampled site within 8 m: approach and drill
  const siteOK = !!site && nC < cap && t >= mem.ignoreUntil && mode !== 'dock';
  if (siteOK) {
    if (site.distance <= 1.3) {
      setMode(mem, 'drill', t);
      return hold(obs, mem, pitch, dt, true);
    }
    if (mode !== 'approach') setMode(mem, 'approach', t);
    if (t - mem.modeT > 40) {
      logEv(mem, t, 'approach timeout');
      mem.ignoreUntil = t + 20;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const f = clamp((site.distance - 0.6) * 0.5, 0.25, 0.45);
    const T = site.distance < 3 ? 1.2 : 2.0;
    return drive(isNum(site.bearing) ? site.bearing : 0, f, d, T);
  }
  if (mode === 'approach') {
    mode = (mem.tgt && mem.tgt.status === 'open') ? 'go' : 'choose';
    setMode(mem, mode, t);
  }

  if (mode === 'choose') {
    mode = choose(mem, t, px, py, nC, tl, bat);
    setMode(mem, mode, t);
  }

  // deliver at base
  if (mode === 'dock') {
    if (nC === 0) {
      mem.delivered++;
      logEv(mem, t, 'delivered');
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    let bD, bB;
    if (bc) { bD = bc.distance; bB = isNum(bc.bearing) ? bc.bearing : 0; }
    else { bD = dB; bB = wrap(brg(px, py, base.x, base.y) - H); }
    if (bD > 1.8) {
      if (t - mem.modeT > 240) {
        logEv(mem, t, 'dock timeout');
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      const f = clamp((bD - 1.0) * 0.4, 0.3, 0.55);
      if (dB > 8) return navDrive(mem, t, px, py, H, base.x, base.y, f, d, 2.0);
      return drive(bB, f, d, bD < 6 ? 1.2 : 2.0);
    }
    if (t - mem.modeT > 60) {
      logEv(mem, t, 'dock wait long');
      setMode(mem, 'choose', t);
    }
    return hold(obs, mem, pitch, dt, false);
  }

  // go to a hinted site
  if (mode === 'go') {
    const tg = mem.tgt;
    if (!tg || tg.status !== 'open') {
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const dd = hyp(px, py, tg.x, tg.y);
    if (dd < 6) {
      if (mem.sciSeen && sci < 0.02) {
        tg.status = 'fail';
        logEv(mem, t, 'hint empty (no science)');
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      mem.spiral = newSpiral(tg.x, tg.y, 13, t, tg);
      setMode(mem, 'search', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (t - mem.modeT > mem.goLimit) {
      tg.status = 'fail';
      logEv(mem, t, 'go timeout');
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const f = clamp(0.4 + dd * 0.02, 0.4, 0.6);
    return navDrive(mem, t, px, py, H, tg.x, tg.y, f, d, 2.0);
  }

  // spiral search around a point
  if (mode === 'search') {
    const S = mem.spiral;
    if (!S || t - S.t0 > 100) {
      if (S && S.tgt && S.tgt.status === 'open') { S.tgt.status = 'fail'; logEv(mem, t, 'search time out'); }
      mem.spiral = null;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    let r = S.a * S.th;
    let wx = S.cx + r * Math.cos(S.th), wy = S.cy + r * Math.sin(S.th);
    let dw = hyp(px, py, wx, wy);
    if (dw < 2.0 || t - S.wpT > 12) {
      S.th += clamp(2.5 / Math.max(r, 2.5), 0.12, 0.8);
      S.wpT = t;
      r = S.a * S.th;
      if (r > S.rMax) {
        if (S.tgt && S.tgt.status === 'open') { S.tgt.status = 'fail'; logEv(mem, t, 'search failed'); }
        mem.spiral = null;
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      wx = S.cx + r * Math.cos(S.th); wy = S.cy + r * Math.sin(S.th);
      dw = hyp(px, py, wx, wy);
    }
    const e = wrap(brg(px, py, wx, wy) - H);
    return drive(e, clamp(dw * 0.3, 0.25, 0.4), d, 2.0);
  }

  // explore unvisited grid points
  if (mode === 'explore') {
    const g = mem.exT;
    if (!g || hyp(px, py, g.x, g.y) < 10 || t - mem.modeT > 120) {
      if (g) g.vis = true;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (sci > 1.0 && t - mem.sciT > 60 && nC < cap) {
      mem.sciT = t;
      mem.spiral = newSpiral(px, py, 12, t, null);
      setMode(mem, 'search', t);
      return hold(obs, mem, pitch, dt, false);
    }
    return navDrive(mem, t, px, py, H, g.x, g.y, 0.5, d, 2.0);
  }

  // idle: wait and re-plan
  if (t - mem.modeT > 5) setMode(mem, 'choose', t);
  return hold(obs, mem, pitch, dt, false);
}

function act(obs, mem) {
  let o = { l: 0, r: 0, drill: false, mv: false };
  try {
    if (!mem.init) initMem(obs, mem);
    balanceLearn(obs, mem);
    o = step(obs, mem) || o;
  } catch (e) {
    mem.errs = (mem.errs || 0) + 1;
    o = { l: 0, r: 0, drill: false, mv: false };
  }
  let l = clamp(+o.l || 0, -1, 1), r = clamp(+o.r || 0, -1, 1);
  if (mem.bal) {
    const s = Math.sqrt(mem.bal);
    l = clamp(l / s, -1, 1);
    r = clamp(r * s, -1, 1);
  }
  mem.lastCmd = { l: l, r: r };
  mem.mv = !!o.mv;
  return { left: l, right: r, drill: !!o.drill };
}

const D2R = Math.PI / 180;
const TRACK = 0.6;
const ANG = [-80, -60, -40, -20, 0, 20, 40, 60, 80];
let CUR_SP = 0;

function isNum(v) { return typeof v === 'number' && isFinite(v); }
function wrap(a) { return ((a + 180) % 360 + 360) % 360 - 180; }
function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }
function hyp(ax, ay, bx, by) { return Math.hypot(ax - bx, ay - by); }
function brg(ax, ay, bx, by) { return Math.atan2(by - ay, bx - ax) / D2R; }
function nCarried(obs) {
  const c = obs.carried;
  if (Array.isArray(c)) return c.length;
  return isNum(c) ? c : 0;
}
function logEv(mem, t, msg) {
  if (!mem.log) mem.log = [];
  if (mem.log.length < 150) mem.log.push([Math.round(t), msg]);
}
function setMode(mem, name, t) { mem.mode = name; mem.modeT = t; }
function newSpiral(cx, cy, rMax, t, tgt) {
  return { cx: cx, cy: cy, a: 1.5, th: 0, wpT: t, t0: t, rMax: rMax, tgt: tgt };
}

function initMem(obs, mem) {
  mem.init = true;
  const m = obs.mission || {};
  const t = isNum(obs.t) ? obs.t : 0;
  mem.base = (m.base && isNum(m.base.x) && isNum(m.base.y)) ? { x: m.base.x, y: m.base.y } : { x: obs.x, y: obs.y };
  mem.cap = (isNum(m.capacity) && m.capacity > 0) ? m.capacity : 5;
  mem.seconds = (isNum(m.seconds) && m.seconds > 0) ? m.seconds : 1200;
  mem.sites = [];
  const hints = Array.isArray(m.hints) ? m.hints : [];
  for (const h of hints) {
    if (h && isNum(h.x) && isNum(h.y)) {
      mem.sites.push({ x: h.x, y: h.y, est: isNum(h.estimate) ? Math.max(0.1, h.estimate) : 1, status: 'open', fails: 0 });
    }
  }
  mem.grid = [];
  for (let gx = 30; gx <= 370; gx += 60) {
    for (let gy = 30; gy <= 370; gy += 60) mem.grid.push({ x: gx, y: gy, vis: false });
  }
  mem.px = isNum(obs.x) ? obs.x : 0; mem.py = isNum(obs.y) ? obs.y : 0;
  mem.gx = obs.x; mem.gy = obs.y;
  mem.hEst = isNum(obs.heading) ? obs.heading : 0;
  mem.off = 0; mem.bal = 1; mem.IL = 0; mem.IR = 0; mem.hist = [];
  mem.lastCmd = { l: 0, r: 0 };
  mem.mv = false;
  mem.esc = null; mem.escHist = [];
  mem.stallT = null; mem.ancX = mem.px; mem.ancY = mem.py; mem.ancT = t;
  mem.ignoreBumpUntil = -1;
  mem.tgt = null; mem.spiral = null; mem.exT = null; mem.goLimit = 100;
  mem.ignoreUntil = -1; mem.samples = 0; mem.delivered = 0;
  mem.sciT = -99; mem.sciSeen = false;
  mem.log = [];
  setMode(mem, 'choose', t);
}

function balanceLearn(obs, mem) {
  const c = mem.lastCmd;
  if (!c || !mem.bal) return;
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  if (Math.abs(c.l) > 0.3 && Math.abs(c.r) > 0.3 && Math.sign(c.l) === Math.sign(c.r) &&
      Math.abs(c.l - c.r) < 0.05 && Math.abs(wL) > 0.2 && Math.abs(wR) > 0.2 &&
      Math.sign(wL) === Math.sign(wR)) {
    const ratio = (wL / c.l) / (wR / c.r);
    if (isFinite(ratio)) mem.bal = clamp(mem.bal + 0.02 * (ratio - mem.bal), 0.7, 1.4);
  }
}

function hold(obs, mem, pitch, dt, drill) {
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  mem.IL = clamp((mem.IL || 0) - 0.8 * wL * dt, -0.35, 0.35);
  mem.IR = clamp((mem.IR || 0) - 0.8 * wR * dt, -0.35, 0.35);
  const ff = clamp(0.02 * pitch, -0.35, 0.35);
  return { l: clamp(ff + mem.IL, -0.4, 0.4), r: clamp(ff + mem.IR, -0.4, 0.4), drill: !!drill, mv: false };
}

function steerAngle(e, d, T) {
  const idx = (a) => clamp(Math.round((a + 80) / 20), 0, 8);
  if (Math.abs(e) <= 80) {
    const ok = d[idx(e - 8)] >= T && d[idx(e)] >= T && d[idx(e + 8)] >= T;
    if (ok) return e;
  }
  let best = null, bc = 1e9;
  for (let i = 0; i < 9; i++) {
    if (d[i] >= T) {
      const c = Math.abs(ANG[i] - e);
      if (c < bc) { bc = c; best = ANG[i]; }
    }
  }
  return best;
}

function clearance(s, d) {
  let c = 15;
  for (let i = 0; i < 9; i++) {
    if (Math.abs(ANG[i] - s) <= 25) c = Math.min(c, d[i]);
  }
  return c;
}

// e: bearing error (deg, + = target left); fmax: max forward command; d: rays; T: clear threshold
function drive(e, fmax, d, T) {
  // front brake: moving fast with something close ahead -> back off
  if (CUR_SP > 0.6 && Math.min(d[3], d[4], d[5]) < 2.0) {
    return { l: -0.25, r: -0.25, drill: false, mv: true };
  }
  const s = steerAngle(e, d, T);
  if (s === null) {
    const Lm = Math.min(d[5], d[6], d[7], d[8]);
    const Rm = Math.min(d[0], d[1], d[2], d[3]);
    const k = Lm >= Rm ? 1 : -1;
    return { l: -0.4 * k, r: 0.4 * k, drill: false, mv: true };
  }
  const C = clearance(s, d);
  // speed scales with clear distance ahead: full only when about 8.5 m is clear
  const vf = clamp((C - 2.5) / 6, 0, 1);
  const cf = Math.max(0, Math.cos(s * D2R));
  let f = Math.min(fmax, 0.45) * vf * cf;
  if (Math.abs(s) > 60) f = 0;
  else if (Math.abs(s) > 30) f *= 0.5;
  if (f < 0.2) f = 0; else if (f < 0.25) f = 0.25;
  const mn = f > 0 ? 0.15 : 0.25;
  let tu = clamp(0.012 * s, -0.45, 0.45);
  if (Math.abs(s) > 8 && Math.abs(tu) < mn) tu = s > 0 ? mn : -mn;
  return { l: clamp(f - tu, -1, 1), r: clamp(f + tu, -1, 1), drill: false, mv: true };
}

function startEsc(mem, t, d, why) {
  const Lm = Math.min(d[5], d[6], d[7], d[8]);
  const Rm = Math.min(d[0], d[1], d[2], d[3]);
  let dir = Lm >= Rm ? 1 : -1;
  mem.escHist = mem.escHist.filter(x => t - x < 60);
  mem.escHist.push(t);
  if (mem.escHist.length % 2 === 0) dir = -dir;
  mem.esc = { ph: 0, until: t + 1.2, dir: dir };
  mem.stallT = null;
  logEv(mem, t, 'esc ' + why + ' in ' + mem.mode);
  if (mem.tgt && mem.tgt.status === 'open' && (mem.mode === 'go' || mem.mode === 'search' || mem.mode === 'approach')) {
    mem.tgt.fails = (mem.tgt.fails || 0) + 1;
    if (mem.tgt.fails >= 2) {
      mem.tgt.status = 'fail';
      mem.spiral = null;
      logEv(mem, t, 'target dropped after escapes');
      setMode(mem, 'choose', t);
    }
  }
  if (mem.escHist.length >= 5) {
    mem.escHist = [];
    if (mem.tgt && mem.tgt.status === 'open') mem.tgt.status = 'fail';
    mem.spiral = null;
    logEv(mem, t, 'too many escapes, replanning');
    setMode(mem, 'choose', t);
  }
}

function runEsc(mem, t) {
  const E = mem.esc;
  if (E.ph === 0) {
    if (t < E.until) return { l: -0.45, r: -0.45, drill: false, mv: false };
    E.ph = 1; E.until = t + 1.0;
  }
  if (t < E.until) return { l: -0.45 * E.dir, r: 0.45 * E.dir, drill: false, mv: false };
  mem.esc = null;
  mem.ignoreBumpUntil = t + 1.5;
  mem.ancX = mem.px; mem.ancY = mem.py; mem.ancT = t;
  return null;
}

function finishSample(mem, px, py, t) {
  mem.samples = (mem.samples || 0) + 1;
  let best = null, bd = 20;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(s.x, s.y, px, py);
    if (dd < bd) { bd = dd; best = s; }
  }
  if (best) best.status = 'done';
  if (mem.tgt && mem.tgt.status === 'open' && hyp(mem.tgt.x, mem.tgt.y, px, py) < 20) mem.tgt.status = 'done';
  mem.ignoreUntil = t + 2;
  logEv(mem, t, 'drilled');
}

function choose(mem, t, px, py, nC, tl, bat) {
  const base = mem.base, cap = mem.cap;
  const dB = hyp(px, py, base.x, base.y);
  let best = null, bs = 0, bdist = 0;
  for (const s of mem.sites) {
    if (s.status !== 'open') continue;
    const dd = hyp(px, py, s.x, s.y), db = hyp(s.x, s.y, base.x, base.y);
    if ((dd + db) / 0.6 + 60 > tl) continue;
    const sc = s.est / (dd + 0.6 * db + 25);
    if (sc > bs) { bs = sc; best = s; bdist = dd; }
  }
  if (nC > 0 && (nC >= cap || bat < 0.2 || tl < dB / 0.6 + 60 || !best || (nC >= 2 && dB < 50))) return 'dock';
  if (best) {
    mem.tgt = best;
    mem.goLimit = 40 + 2.5 * bdist;
    logEv(mem, t, 'target ' + best.x.toFixed(0) + ',' + best.y.toFixed(0));
    return 'go';
  }
  let g = null, gd = 1e9;
  for (const q of mem.grid) {
    if (q.vis) continue;
    const dd = hyp(px, py, q.x, q.y);
    if (dd < gd) { gd = dd; g = q; }
  }
  if (g && tl > (dB + gd) / 0.6 + 80) {
    mem.exT = g;
    return 'explore';
  }
  return 'idle';
}

function step(obs, mem) {
  const t = isNum(obs.t) ? obs.t : 0;
  if (!mem.init) initMem(obs, mem);
  const dt = mem.lastT === undefined ? 0.1 : clamp(t - mem.lastT, 0.01, 0.5);
  mem.lastT = t;
  const cap = mem.cap, nC = nCarried(obs);
  const wL = isNum(obs.wheelLeft) ? obs.wheelLeft : 0;
  const wR = isNum(obs.wheelRight) ? obs.wheelRight : 0;
  const sp = (wL + wR) / 2;
  CUR_SP = sp;
  const wAvg = (Math.abs(wL) + Math.abs(wR)) / 2;
  const bat = isNum(obs.battery) ? obs.battery : 1;
  const tl = isNum(obs.timeLeft) ? obs.timeLeft : (mem.seconds - t);
  const sci = isNum(obs.science) ? obs.science : 0;
  if (sci > 0.05) mem.sciSeen = true;
  const site = (obs.site && isNum(obs.site.distance)) ? obs.site : null;
  const pitch = isNum(obs.pitch) ? obs.pitch : 0;
  const bc = (obs.beacon && isNum(obs.beacon.distance)) ? obs.beacon : null;

  // localisation: GPS when it changes, dead reckoning otherwise (covers GPS freezes)
  if (isNum(obs.x) && isNum(obs.y) && (obs.x !== mem.gx || obs.y !== mem.gy)) {
    mem.px = obs.x; mem.py = obs.y; mem.gx = obs.x; mem.gy = obs.y;
  } else {
    mem.px += sp * Math.cos(mem.hEst * D2R) * dt;
    mem.py += sp * Math.sin(mem.hEst * D2R) * dt;
  }
  const px = mem.px, py = mem.py;

  // heading: wheel gyro fused with compass + learned offset
  const comp = wrap((isNum(obs.heading) ? obs.heading : mem.hEst) + mem.off);
  mem.hEst = wrap(mem.hEst + ((wR - wL) / TRACK) * dt / D2R + 0.03 * wrap(comp - mem.hEst));
  const H = mem.hEst;

  // compass offset learning on straight GPS runs
  const hist = mem.hist;
  if (!hist.length || t - hist[hist.length - 1].t >= 1.0) {
    hist.push({ t: t, x: px, y: py, s: Math.abs(wL - wR) < 0.15 && sp > 0.5 });
    if (hist.length > 4) hist.shift();
  }
  if (hist.length >= 4 && hist.every(e => e.s)) {
    const a = hist[0], b = hist[hist.length - 1];
    if (hyp(a.x, a.y, b.x, b.y) > 2.5 && isNum(obs.heading)) {
      const gh = brg(a.x, a.y, b.x, b.y);
      const diff = wrap(gh - obs.heading);
      mem.off = wrap(mem.off + 0.2 * wrap(diff - mem.off));
      mem.hist = [b];
    }
  }

  // range rays
  const rays = Array.isArray(obs.rays) ? obs.rays : [];
  const d = [];
  for (let i = 0; i < 9; i++) d.push(clamp(isNum(rays[i]) ? rays[i] : 15, 0, 15));

  // escape sequence in progress
  if (mem.esc) {
    const o = runEsc(mem, t);
    if (o) return o;
  }
  // bump or stall while moving -> escape
  if (mem.mv) {
    if (obs.bumped === true && t >= mem.ignoreBumpUntil) {
      startEsc(mem, t, d, 'bump');
      const o = runEsc(mem, t); if (o) return o;
    }
    if (wAvg < 0.08) {
      if (mem.stallT === null || mem.stallT === undefined) mem.stallT = t;
      else if (t - mem.stallT > 2.5 && t >= mem.ignoreBumpUntil) {
        startEsc(mem, t, d, 'stall');
        const o = runEsc(mem, t); if (o) return o;
      }
    } else {
      mem.stallT = null;
    }
    if (hyp(px, py, mem.ancX, mem.ancY) > 0.5) {
      mem.ancX = px; mem.ancY = py; mem.ancT = t;
    } else if (t - mem.ancT > 8 && t >= mem.ignoreBumpUntil) {
      startEsc(mem, t, d, 'noprog');
      mem.ancT = t;
      const o = runEsc(mem, t); if (o) return o;
    }
  } else {
    mem.stallT = null; mem.ancX = px; mem.ancY = py; mem.ancT = t;
  }

  const base = mem.base;
  const dB = hyp(px, py, base.x, base.y);
  let mode = mem.mode;

  // drilling in progress
  if (mode === 'drill') {
    const dr = isNum(obs.drilling) ? obs.drilling : 0;
    if (dr >= 6.0) {
      finishSample(mem, px, py, t);
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (!site || site.distance > 2.2) {
      logEv(mem, t, 'drill lost site');
      mem.ignoreUntil = t + 2;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (t - mem.modeT > 25) {
      logEv(mem, t, 'drill timeout');
      mem.ignoreUntil = t + 15;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    return hold(obs, mem, pitch, dt, true);
  }

  // any unsampled site within 8 m: approach and drill
  const siteOK = !!site && nC < cap && t >= mem.ignoreUntil && mode !== 'dock';
  if (siteOK) {
    if (site.distance <= 1.3) {
      setMode(mem, 'drill', t);
      return hold(obs, mem, pitch, dt, true);
    }
    if (mode !== 'approach') setMode(mem, 'approach', t);
    if (t - mem.modeT > 40) {
      logEv(mem, t, 'approach timeout');
      mem.ignoreUntil = t + 20;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const f = clamp((site.distance - 0.6) * 0.5, 0.25, 0.45);
    const T = site.distance < 3 ? 1.2 : 2.0;
    return drive(isNum(site.bearing) ? site.bearing : 0, f, d, T);
  }
  if (mode === 'approach') {
    mode = (mem.tgt && mem.tgt.status === 'open') ? 'go' : 'choose';
    setMode(mem, mode, t);
  }

  if (mode === 'choose') {
    mode = choose(mem, t, px, py, nC, tl, bat);
    setMode(mem, mode, t);
  }

  // deliver at base
  if (mode === 'dock') {
    if (nC === 0) {
      mem.delivered++;
      logEv(mem, t, 'delivered');
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    let bD, bB;
    if (bc) { bD = bc.distance; bB = isNum(bc.bearing) ? bc.bearing : 0; }
    else { bD = dB; bB = wrap(brg(px, py, base.x, base.y) - H); }
    if (bD > 1.8) {
      if (t - mem.modeT > 240) {
        logEv(mem, t, 'dock timeout');
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      const f = clamp((bD - 1.0) * 0.4, 0.3, 0.55);
      return drive(bB, f, d, bD < 6 ? 1.2 : 2.0);
    }
    if (t - mem.modeT > 60) {
      logEv(mem, t, 'dock wait long');
      setMode(mem, 'choose', t);
    }
    return hold(obs, mem, pitch, dt, false);
  }

  // go to a hinted site
  if (mode === 'go') {
    const tg = mem.tgt;
    if (!tg || tg.status !== 'open') {
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const dd = hyp(px, py, tg.x, tg.y);
    if (dd < 6) {
      if (mem.sciSeen && sci < 0.02) {
        tg.status = 'fail';
        logEv(mem, t, 'hint empty (no science)');
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      mem.spiral = newSpiral(tg.x, tg.y, 13, t, tg);
      setMode(mem, 'search', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (t - mem.modeT > mem.goLimit) {
      tg.status = 'fail';
      logEv(mem, t, 'go timeout');
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const e = wrap(brg(px, py, tg.x, tg.y) - H);
    const f = clamp(0.4 + dd * 0.02, 0.4, 0.5);
    return drive(e, f, d, 2.0);
  }

  // spiral search around a point
  if (mode === 'search') {
    const S = mem.spiral;
    if (!S || t - S.t0 > 100) {
      if (S && S.tgt && S.tgt.status === 'open') { S.tgt.status = 'fail'; logEv(mem, t, 'search time out'); }
      mem.spiral = null;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    let r = S.a * S.th;
    let wx = S.cx + r * Math.cos(S.th), wy = S.cy + r * Math.sin(S.th);
    let dw = hyp(px, py, wx, wy);
    if (dw < 2.0 || t - S.wpT > 12) {
      S.th += clamp(2.5 / Math.max(r, 2.5), 0.12, 0.8);
      S.wpT = t;
      r = S.a * S.th;
      if (r > S.rMax) {
        if (S.tgt && S.tgt.status === 'open') { S.tgt.status = 'fail'; logEv(mem, t, 'search failed'); }
        mem.spiral = null;
        setMode(mem, 'choose', t);
        return hold(obs, mem, pitch, dt, false);
      }
      wx = S.cx + r * Math.cos(S.th); wy = S.cy + r * Math.sin(S.th);
      dw = hyp(px, py, wx, wy);
    }
    const e = wrap(brg(px, py, wx, wy) - H);
    return drive(e, clamp(dw * 0.3, 0.25, 0.35), d, 2.0);
  }

  // explore unvisited grid points
  if (mode === 'explore') {
    const g = mem.exT;
    if (!g || hyp(px, py, g.x, g.y) < 10 || t - mem.modeT > 120) {
      if (g) g.vis = true;
      setMode(mem, 'choose', t);
      return hold(obs, mem, pitch, dt, false);
    }
    if (sci > 1.0 && t - mem.sciT > 60 && nC < cap) {
      mem.sciT = t;
      mem.spiral = newSpiral(px, py, 12, t, null);
      setMode(mem, 'search', t);
      return hold(obs, mem, pitch, dt, false);
    }
    const e = wrap(brg(px, py, g.x, g.y) - H);
    return drive(e, 0.4, d, 2.0);
  }

  // idle: wait and re-plan
  if (t - mem.modeT > 5) setMode(mem, 'choose', t);
  return hold(obs, mem, pitch, dt, false);
}

function act(obs, mem) {
  let o = { l: 0, r: 0, drill: false, mv: false };
  try {
    if (!mem.init) initMem(obs, mem);
    balanceLearn(obs, mem);
    o = step(obs, mem) || o;
  } catch (e) {
    mem.errs = (mem.errs || 0) + 1;
    o = { l: 0, r: 0, drill: false, mv: false };
  }
  let l = clamp(+o.l || 0, -1, 1), r = clamp(+o.r || 0, -1, 1);
  if (mem.bal) {
    const s = Math.sqrt(mem.bal);
    l = clamp(l / s, -1, 1);
    r = clamp(r * s, -1, 1);
  }
  mem.lastCmd = { l: l, r: r };
  mem.mv = !!o.mv;
  return { left: l, right: r, drill: !!o.drill };
}
